function resetDocHelperResultsPanel() {
  const resultsEl = document.querySelector("#docHelperResults");
  const outputEl = document.querySelector("#docHelperOutput");
  const postSave = document.querySelector("#docHelperPostSavePanel");
  const editBtn = document.querySelector("#docHelperEditBtn");
  const saveBtn = document.querySelector("#docHelperSaveBtn");
  const hint = document.querySelector("#docHelperNextStepHint");
  const note = document.querySelector("#docHelperNote");
  if (resultsEl) resultsEl.hidden = true;
  if (postSave) postSave.hidden = true;
  if (outputEl) {
    outputEl.innerHTML = "";
    delete outputEl.dataset.rawMarkdown;
    outputEl.contentEditable = "false";
  }
  if (editBtn) editBtn.textContent = "Edit Generated Content";
  if (saveBtn) {
    saveBtn.textContent = "Save to Child Profile";
    saveBtn.disabled = false;
  }
  if (hint) {
    hint.textContent = "Review the draft, edit if needed, then save it to the child profile or copy it for parents.";
  }
  if (note) {
    note.value = "";
    note.focus();
  }
  docHelperDraftState.originalNote = "";
  docHelperDraftState.lastOutput = "";
  docHelperDraftState.lastData = null;
  docHelperDraftState.toolId = "";
  docHelperDraftState.docType = "";
  setDocHelperDraftActionsVisible(false);
  document.querySelector("#docHelperDebugPanel")?.setAttribute("hidden", "hidden");
  const typeSelect = document.querySelector("#docHelperType");
  if (typeSelect?.value) selectDocHelperType(typeSelect.value, { focusNote: true, scroll: true });
}

function updateDocHelperComposeHint() {
  const hint = document.querySelector("#docHelperComposeHint");
  if (!hint) return;
  const childSelect = document.querySelector("#docHelperChild");
  const childId = childSelect?.value || "";
  const childName = childSelect?.selectedOptions?.[0]?.textContent?.trim() || "";
  const remaining = typeof aiUsageRemaining === "function" ? aiUsageRemaining() : null;
  const limit = typeof aiMonthlyLimit === "function" ? aiMonthlyLimit() : freeAiMonthlyLimit;
  const usageLine = !isProUser() && remaining != null
    ? ` Free plan: ${remaining} of ${limit} document creations left this month.`
    : "";
  if (childId && childName && childName !== "No child selected") {
    hint.textContent = `Selected child: ${childName}. Add a quick note, generate a draft, then review before saving.${usageLine}`;
    return;
  }
  hint.textContent = `No child selected. Add a quick note, generate a draft, then choose a child explicitly before saving to a profile.${usageLine}`;
}

function syncDocHelperAgeField() {
  const compose = document.querySelector("#docHelperCompose");
  const form = document.querySelector("#docHelperForm");
  if (!compose || !form) return;
  const childSelect = document.querySelector("#docHelperChild");
  const childId = childSelect?.value || "";
  const child = childId ? childRecords().children.find((item) => item.id === childId) : null;
  const childAge = child ? (normalizeAgeGroup(child.ageGroup) || "") : "";
  let ageWrap = form.querySelector("[data-doc-helper-age-wrap]");
  const needsAge = !childAge && ["lesson-plan", "activity-idea", "behavior-note", "daily-log"].includes(selectedDocHelperType || form.querySelector("#docHelperType")?.value || "");
  if (!needsAge) {
    if (ageWrap) ageWrap.hidden = true;
    return;
  }
  if (!ageWrap) {
    ageWrap = document.createElement("label");
    ageWrap.dataset.docHelperAgeWrap = "1";
    ageWrap.className = "doc-helpers-age-label";
    ageWrap.innerHTML = `Age group (required when no child age is on file)
      <select name="docHelperAge" id="docHelperAge">
        <option value="">Select age group</option>
        ${aiAgeGroupOptions.map((option) => `<option value="${option}">${option}</option>`).join("")}
      </select>`;
    const noteLabel = form.querySelector("#docHelperNote")?.closest("label");
    if (noteLabel) noteLabel.before(ageWrap);
    else form.appendChild(ageWrap);
  }
  ageWrap.hidden = false;
}

function selectDocHelperType(docType, options = {}) {
  const resolvedType = docHelperToolMap[docType] ? docType : "observation";
  selectedDocHelperType = resolvedType;
  const typeSelect = document.querySelector("#docHelperType");
  const compose = document.querySelector("#docHelperCompose");
  const title = document.querySelector("#docHelperComposeTitle");
  const label = docTypeLabels[resolvedType] || "Documentation";
  if (typeSelect) typeSelect.value = resolvedType;
  document.querySelectorAll(".doc-helper-card[data-quick-doc-type]").forEach((card) => {
    card.classList.toggle("is-selected", card.dataset.quickDocType === resolvedType);
  });
  if (compose) compose.hidden = false;
  if (title) title.textContent = label;
  updateDocHelperComposeHint();
  syncDocHelperAgeField();
  if (options.scroll !== false) {
    compose?.scrollIntoView({ behavior: "smooth", block: "start" });
  }
  if (options.focusNote !== false) {
    requestAnimationFrame(() => document.querySelector("#docHelperNote")?.focus());
  }
}

function clearDocHelperSelection() {
  selectedDocHelperType = "";
  document.querySelectorAll(".doc-helper-card.is-selected").forEach((card) => card.classList.remove("is-selected"));
  const compose = document.querySelector("#docHelperCompose");
  if (compose) compose.hidden = true;
}

function openDocHelperSavedChild(childId, childTab = "overview") {
  if (childId) {
    selectedChildId = childId;
    localStorage.setItem("llhSelectedChild", selectedChildId);
    childManagementMode = "profile";
    childProfileTab = normalizeChildProfileTab(childTab || "overview");
  }
  setView("children");
}
