function structuredCurriculumLessonPlanHtml(resource, options = {}) {
  const plan = normalizeCurriculumLessonPlanForRender(resource?._curriculumLessonPlan);
  if (!plan?.id && !plan?.title) return "";
  const api = curriculumViewerRenderApi();
  if (!api) return "";
  return api.renderCurriculumLessonPlanHtml(plan, {
    ...options,
    accessLabel: options.accessLabel || authoritativeLessonPlanAccessLabel(resource),
    showAdminStatus: hasAdminFullAccess(),
    resolveActivityId: resolvePublishedCurriculumActivityId,
  });
}

function structuredCurriculumActivityHtml(resource) {
  const activity = resource?._curriculumActivity || effectiveCurriculumLibrary().activities.find((item) => item.id === resource.id) || null;
  const api = curriculumViewerRenderApi();
  if (!api || !activity) return "";
  const body = api.renderCurriculumActivityHtml(activity, {
    parentTitle: resource._curriculumParentTitle || activity.parentTitle || "",
    parentAge: resource.age || activity.parentAge || "",
    lessonPlanId: resource.lessonPlanId || resource._curriculumLessonPlanId || activity.lessonPlanId || "",
  });
  return `${body}${activityViewerFeedbackHtml(resource)}`;
}

function resourceSearchHaystack(resource) {
  const parts = [
    resource.title,
    resource.category,
    resource.age,
    resource.plan,
    resource.description,
    resource.theme,
    resource.weeklyOverview,
    resource.keywords,
    resource.month,
    resource.holiday,
    resource.activityFocus,
    ...(Array.isArray(resource.tags) ? resource.tags : []),
  ];
  if (resource._curriculumManaged && resource.category === "Lesson Plans" && resource._curriculumLessonPlan) {
    const plan = resource._curriculumLessonPlan;
    parts.push(
      plan.theme,
      plan.weeklyOverview,
      plan.objectives,
      plan.weeklyMaterials,
      plan.vocabularyWords,
      plan.familyConnection,
      plan.adaptations,
      plan.observationOpportunities,
      ...(Array.isArray(plan.learningDomains) ? plan.learningDomains : []),
      ...(Array.isArray(plan.books) ? plan.books.flatMap((book) => [book.title, book.author, book.notes]) : []),
      ...(Array.isArray(plan.songs) ? plan.songs.flatMap((song) => [song.title, song.notes]) : []),
    );
    CURRICULUM_WEEKDAYS.forEach((day) => {
      const items = Array.isArray(plan.dailyPlans?.[day]?.items) ? plan.dailyPlans[day].items : [];
      items.forEach((item) => {
        parts.push(
          item.title,
          item.activityCategory,
          item.materials,
          item.setup,
          item.steps,
          ...(Array.isArray(item.learningGoals) ? item.learningGoals : []),
        );
      });
    });
  }
  if (resource._curriculumManaged && resource.category === "Activity Center") {
    const activity = resource._curriculumActivity || null;
    parts.push(
      resource.materials,
      resource.setup,
      resource.steps,
      resource._curriculumParentTitle,
      resource.lessonPlanId,
      activity?.dayOfWeek,
      activity?.description,
      ...(Array.isArray(resource.learningGoals) ? resource.learningGoals : []),
      ...(Array.isArray(activity?.learningGoals) ? activity.learningGoals : []),
    );
  }
  return parts.filter(Boolean).join(" ").toLowerCase();
}

function effectiveCurriculumLibrary() {
  const content = effectiveSiteContent();
  const fromPublic = content.curriculumLibrary;
  const publicPlans = Array.isArray(fromPublic?.lessonPlans) ? fromPublic.lessonPlans : [];
  const hasLoadedPublicLibrary = Boolean(fromPublic?.updatedAt) || publicPlans.length > 0;
  if (fromPublic && typeof fromPublic === "object" && hasLoadedPublicLibrary) {
    return {
      lessonPlans: publicPlans,
      activities: Array.isArray(fromPublic.activities) ? fromPublic.activities : [],
      resources: Array.isArray(fromPublic.resources) ? fromPublic.resources : [],
      series: Array.isArray(fromPublic.series) ? fromPublic.series : [],
      updatedAt: fromPublic.updatedAt || "",
    };
  }
  // Admin sessions and fresh saves use full curriculum; derive the published library view.
  const curriculum = effectiveCurriculum();
  const lessonPlans = curriculum.lessonPlans
    .filter((plan) => plan.status === "published" || plan.status === "featured")
    .slice()
    .sort((a, b) => {
      const featuredDelta = (b.status === "featured" ? 1 : 0) - (a.status === "featured" ? 1 : 0);
      if (featuredDelta) return featuredDelta;
      return String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""));
    });
  const publicLessonIds = new Set(lessonPlans.map((plan) => plan.id));
  const activities = curriculum.activities.filter((activity) => (
    activity.status === "published" && publicLessonIds.has(activity.lessonPlanId)
  ));
  const resources = curriculum.resources
    .filter((resource) => resource.status === "published")
    .filter((resource) => (resource.lessonPlanIds || []).some((id) => publicLessonIds.has(id)))
    .map((resource) => ({
      id: resource.id,
      title: resource.title,
      resourceCategory: resource.resourceCategory,
      mimeType: resource.mimeType,
      fileName: resource.fileName,
      lessonPlanIds: resource.lessonPlanIds || [],
      status: resource.status,
      hasFile: Boolean(resource.fileData || resource.hasFile),
      updatedAt: resource.updatedAt || "",
    }));
  const series = (curriculum.series || []).filter((entry) => (
    entry && ["published", "featured"].includes(String(entry.status || ""))
  ));
  return {
    lessonPlans,
    activities: activities.map((activity) => {
      const parent = lessonPlans.find((plan) => plan.id === activity.lessonPlanId);
      return {
        ...activity,
        parentTitle: parent?.title || "",
        parentAge: parent?.age || "Preschool",
        parentTheme: parent?.theme || "",
        parentPlan: parent?.plan || "Free",
        parentStatus: parent?.status || "",
      };
    }),
    resources,
    series,
    updatedAt: curriculum.updatedAt || "",
  };
}

function curriculumLibraryResourceById(id) {
  const targetId = String(id || "").trim();
  if (!targetId) return null;
  return effectiveCurriculumLibrary().resources.find((item) => item.id === targetId) || null;
}

function buildLessonPlanTextFromCurriculum(plan) {
  return formatCurriculumLessonPlanImportText(plan);
}

function buildActivityTextFromCurriculum(activity) {
  const entry = activity && typeof activity === "object" ? activity : {};
  const dayLabel = entry.dayOfWeek
    ? String(entry.dayOfWeek).charAt(0).toUpperCase() + String(entry.dayOfWeek).slice(1)
    : "Monday";
  return [
    `Parent Lesson: ${entry.parentTitle || entry.lessonPlanId || ""}`,
    `Day: ${dayLabel}`,
    "",
    `Activity: ${entry.title || ""}`,
    `Category: ${entry.activityCategory || ""}`,
    "",
    `Objective:\n${entry.objective || ""}`,
    "",
    `Description:\n${entry.description || ""}`,
    "",
    `Materials:\n${entry.materials || ""}`,
    "",
    `Setup:\n${entry.setup || ""}`,
    "",
    `Directions:\n${entry.steps || ""}`,
    "",
    `Teacher Role:\n${entry.teacherRole || ""}`,
    "",
    `Learning Goals:\n${(Array.isArray(entry.learningGoals) ? entry.learningGoals : []).join("\n")}`,
    "",
    `Observation Opportunities:\n${entry.observationOpportunities || ""}`,
  ].join("\n");
}

function loadCurriculumManagedLessonPlans() {
  const sourcePlans = hasAdminFullAccess()
    ? effectiveCurriculum().lessonPlans
    : effectiveCurriculumLibrary().lessonPlans;
  const plans = Array.isArray(sourcePlans) ? sourcePlans : [];
  const mapped = [];
  plans.forEach((item) => {
    try {
      if (!item || !item.id || !item.title) return;
      const plan = normalizeCurriculumLessonPlanForRender(item);
      if (!plan?.id || !plan?.title) return;
      mapped.push({
      id: plan.id,
      category: "Lesson Plans",
      title: plan.title,
      age: plan.age || "Preschool",
      plan: plan.plan || "Free",
      month: "",
      tags: [
        ...curriculumAsStringArray(plan.learningDomains),
        plan.theme,
      ].filter(Boolean),
      format: "Play-Based Lesson",
      description: plan.weeklyOverview || plan.theme || "",
      theme: plan.theme || "",
      developmentalArea: curriculumAsStringArray(plan.learningDomains)[0] || "Approaches to Learning",
      holiday: "",
      activityFocus: "",
      weeklyOverview: plan.weeklyOverview || "",
      materials: plan.weeklyMaterials || "",
      previewData: sanitizedImageSource(plan.coverImageUrl || "") || (lessonPlanCoversApi()?.resolveLessonPlanCover?.(plan)?.url || ""),
      thumbnailUrl: sanitizedImageSource(plan.coverImageUrl || "") || (lessonPlanCoversApi()?.resolveLessonPlanCover?.(plan)?.url || ""),
      coverImageUrl: plan.coverImageUrl || "",
      coverImageAlt: plan.coverImageAlt || "",
      coverImageSource: plan.coverImageSource || "",
      coverImagePosition: plan.coverImagePosition || "center",
      visible: true,
      archived: false,
      featured: plan.status === "featured",
      customContent: buildLessonPlanTextFromCurriculum(plan),
      _curriculumManaged: true,
      _curriculumResourceIds: curriculumAsStringArray(plan.resourceIds),
      _curriculumLessonPlan: plan,
    });
    } catch (error) {
      console.warn("Skipping malformed curriculum lesson plan", item?.id || "(unknown)", error);
    }
  });
  return mapped;
}

function loadCurriculumManagedActivities() {
  // Admin full access must use the private curriculum activities, not public locked teasers.
  // Otherwise Pro activity how-to fields stay empty and appear "locked" for the owner.
  const sourceActivities = hasAdminFullAccess()
    ? (() => {
      const curriculum = effectiveCurriculum();
      const plansById = new Map((curriculum.lessonPlans || []).map((plan) => [plan.id, plan]));
      return (curriculum.activities || []).map((activity) => {
        const parent = plansById.get(activity.lessonPlanId);
        return {
          ...activity,
          parentTitle: parent?.title || activity.parentTitle || "",
          parentAge: parent?.age || activity.parentAge || "Preschool",
          parentTheme: parent?.theme || activity.parentTheme || "",
          parentPlan: parent?.plan || activity.parentPlan || "Free",
          locked: false,
        };
      });
    })()
    : effectiveCurriculumLibrary().activities;
  return sourceActivities
    .filter((item) => item && item.id && item.title && item.lessonPlanId)
    .map((item) => {
      try {
      // Paid members must never see Pro activities as empty locked teasers.
      const lockedTeaser = !hasAdminFullAccess()
        && !isProUser()
        && (item.locked === true || item.parentPlan === "Pro");
      return {
      id: item.id,
      category: "Activity Center",
      title: item.title,
      age: item.parentAge || "All Ages",
      plan: item.parentPlan || "Free",
      // Locked Pro teasers never carry activity how-to copy into the library card.
      description: lockedTeaser ? "" : (item.description || ""),
      theme: item.parentTheme || item.activityCategory || "",
      tags: [item.activityCategory, item.dayOfWeek, item.parentTitle, item.parentTheme].filter(Boolean),
      previewData: "",
      fileData: "",
      customContent: lockedTeaser ? "" : buildActivityTextFromCurriculum(item),
      downloadUrl: "",
      format: "Play-Based Activity",
      visible: true,
      archived: false,
      updatedAt: item.updatedAt || "",
      activityCategory: item.activityCategory || "Open-Ended Exploration",
      lessonPlanId: item.lessonPlanId,
      objective: lockedTeaser ? "" : (item.objective || ""),
      materials: lockedTeaser ? "" : (item.materials || ""),
      setup: lockedTeaser ? "" : (item.setup || ""),
      steps: lockedTeaser ? "" : (item.steps || ""),
      learningGoals: lockedTeaser ? [] : (Array.isArray(item.learningGoals) ? item.learningGoals : []),
      learningDomains: Array.isArray(item.learningDomains) ? item.learningDomains : [],
      teacherRole: lockedTeaser ? "" : (item.teacherRole || ""),
      teacherLanguage: lockedTeaser ? "" : (item.teacherLanguage || ""),
      observationOpportunities: lockedTeaser ? "" : (item.observationOpportunities || ""),
      vocabulary: lockedTeaser ? "" : (item.vocabulary || ""),
      extensions: lockedTeaser ? "" : (item.extensions || ""),
      adaptations: lockedTeaser ? "" : (item.adaptations || ""),
      safetyNotes: lockedTeaser ? "" : (item.safetyNotes || ""),
      ageModifications: lockedTeaser ? "" : (item.ageModifications || ""),
      _curriculumManaged: true,
      _curriculumLessonPlanId: item.lessonPlanId,
      _curriculumParentTitle: item.parentTitle || "",
      _curriculumParentTheme: item.parentTheme || "",
      _curriculumActivity: item,
    };
      } catch (error) {
        console.warn("Skipping malformed curriculum activity", item?.id || "(unknown)", error);
        return null;
      }
    })
    .filter(Boolean);
}

const CURRICULUM_WEEKDAYS = Object.freeze(["monday", "tuesday", "wednesday", "thursday", "friday"]);
const CURRICULUM_LESSON_STATUSES = Object.freeze(["draft", "published", "featured", "archived"]);

function generateCurriculumItemIdClient() {
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return `item-${Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
}

function curriculumLessonPlanStatusLabel(status) {
  const labels = {
    draft: "🟡 Draft",
    published: "🟢 Published",
    featured: "⭐ Featured",
    archived: "📦 Archived",
  };
  return labels[status] || status;
}

function emptyCurriculumDailyPlans() {
  const api = curriculumImportApi();
  if (api?.emptyCurriculumDailyPlans) return api.emptyCurriculumDailyPlans();
  return Object.fromEntries(CURRICULUM_WEEKDAYS.map((day) => [day, { items: [] }]));
}

function emptyCurriculumDailyPlanDay() {
  const api = curriculumImportApi();
  if (api?.emptyCurriculumDailyPlanDay) return api.emptyCurriculumDailyPlanDay();
  return { items: [] };
}

function curriculumLessonPlansForAdmin() {
  return effectiveCurriculum().lessonPlans.slice().sort((a, b) => (
    String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""))
  ));
}

function curriculumActivityStatusLabel(status) {
  const labels = {
    draft: "🟡 Draft",
    published: "🟢 Published",
    archived: "📦 Archived",
  };
  return labels[status] || status || "draft";
}

function curriculumActivitiesForAdmin() {
  return effectiveCurriculum().activities.slice().sort((a, b) => (
    String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""))
    || String(a.title || "").localeCompare(String(b.title || ""))
  ));
}

function curriculumActivityParentLesson(activity) {
  const lessonPlanId = String(activity?.lessonPlanId || "").trim();
  if (!lessonPlanId) return null;
  return curriculumLessonPlanById(lessonPlanId);
}

function filteredCurriculumActivitiesForAdmin() {
  const filters = adminCurriculumActivityFilters || {};
  const query = String(filters.query || "").trim().toLowerCase();
  return curriculumActivitiesForAdmin().filter((activity) => {
    const parent = curriculumActivityParentLesson(activity);
    if (filters.category && activity.activityCategory !== filters.category) return false;
    if (filters.status && (activity.status || "draft") !== filters.status) return false;
    if (filters.age && (parent?.age || "") !== filters.age) return false;
    if (filters.lessonPlanId && activity.lessonPlanId !== filters.lessonPlanId) return false;
    if (!query) return true;
    const haystack = [
      activity.title,
      activity.activityCategory,
      activity.dayOfWeek,
      activity.status,
      activity.lessonPlanId,
      parent?.title,
      parent?.age,
      parent?.theme,
    ].map((value) => String(value || "").toLowerCase()).join(" ");
    return haystack.includes(query);
  });
}

