function applyAdminCurriculumCoverSelection(url, { source = "mapped", alt = "" } = {}) {
  const form = document.querySelector("#adminCurriculumLessonPlanForm");
  if (!form) return;
  const safeUrl = sanitizedImageSource(url || "");
  const urlField = form.querySelector("[data-curriculum-cover-url]");
  const sourceField = form.querySelector("[data-curriculum-cover-source]");
  const urlInput = form.querySelector("[data-curriculum-cover-url-input]");
  const preview = form.querySelector("[data-curriculum-cover-preview]");
  const altField = form.querySelector('[name="coverImageAlt"]');
  const removeButton = form.querySelector("[data-curriculum-cover-remove]");
  if (urlField) urlField.value = safeUrl;
  if (sourceField) sourceField.value = safeUrl ? source : "";
  if (urlInput && !String(safeUrl).startsWith("data:")) urlInput.value = safeUrl;
  if (urlInput && !safeUrl) urlInput.value = "";
  if (preview) {
    preview.src = safeUrl
      || resolveLessonPlanCoverForResource({
        title: form.querySelector('[name="title"]')?.value || "",
        theme: form.querySelector('[name="theme"]')?.value || "",
        age: form.querySelector('[name="age"]')?.value || "",
      }).url
      || "/images/lesson-covers/default.svg";
    preview.style.objectPosition = form.querySelector('[name="coverImagePosition"]')?.value || "center";
  }
  if (alt && altField && !String(altField.value || "").trim()) {
    altField.value = alt;
  }
  if (removeButton) removeButton.disabled = !safeUrl;
  form.querySelectorAll("[data-curriculum-cover-pick]").forEach((button) => {
    button.classList.toggle("is-selected", button.dataset.curriculumCoverPick === safeUrl);
  });
}

async function uploadAdminCurriculumLessonCover(file) {
  const token = adminSession()?.token || "";
  if (!token || !canUseLaunchBackend()) {
    throw new Error("Backend server and admin login are required to upload a cover.");
  }
  if (!file || file.size > 2 * 1024 * 1024) {
    throw new Error("Use a PNG, JPG, or WebP image no larger than 2 MB.");
  }
  if (!["image/png", "image/jpeg", "image/webp"].includes(file.type)) {
    throw new Error("Use a PNG, JPG, or WebP image.");
  }
  const fileData = await fileToImageDataUrlSafe(file, { maxMb: 2 });
  if (!fileData) throw new Error("Could not read that image.");
  const response = await fetch("/api/admin/curriculum/lesson-covers/upload", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({
      fileName: file.name || "lesson-cover",
      fileData,
    }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data.persistent || !sanitizedImageSource(data.url || "")) {
    throw new Error(data.error || "The cover could not be saved to persistent storage.");
  }
  return data;
}

function filterAdminCurriculumCoverLibrary() {
  const form = document.querySelector("#adminCurriculumLessonPlanForm");
  if (!form) return;
  const query = String(form.querySelector("[data-curriculum-cover-search]")?.value || "").trim().toLowerCase();
  const activeCategory = form.querySelector("[data-curriculum-cover-category].active-filter")?.dataset.curriculumCoverCategory || "All";
  form.querySelectorAll("[data-curriculum-cover-pick]").forEach((button) => {
    const label = String(button.dataset.coverLabel || button.textContent || "").toLowerCase();
    const category = String(button.dataset.coverCategory || "");
    const matchesQuery = !query || label.includes(query) || category.toLowerCase().includes(query);
    const matchesCategory = activeCategory === "All" || category === activeCategory;
    button.hidden = !(matchesQuery && matchesCategory);
  });
}

function adminCurriculumLessonJumpNavHtml() {
  const dayLinks = CURRICULUM_WEEKDAYS.map((day) => {
    const label = day.charAt(0).toUpperCase() + day.slice(1);
    return `<a class="lesson-editor-jump-link" href="#admin-lesson-day-${day}" data-admin-lesson-jump="${day}">${escapeHtml(label)}</a>`;
  }).join("");
  const binderLinks = typeof isTeachingKitAuthoringEnabled === "function" && isTeachingKitAuthoringEnabled()
    && typeof LLHTeachingKitAuthoring !== "undefined"
    ? LLHTeachingKitAuthoring.binderJumpLinkHtml()
    : "";
  return `
    <nav class="lesson-editor-jump admin-lesson-jump" aria-label="Jump to lesson plan sections">
      <a class="lesson-editor-jump-link" href="#admin-lesson-basics" data-admin-lesson-jump="basics">Basics</a>
      <a class="lesson-editor-jump-link" href="#admin-lesson-cover" data-admin-lesson-jump="cover">Cover</a>
      <a class="lesson-editor-jump-link" href="#admin-lesson-weekly" data-admin-lesson-jump="weekly">Weekly</a>
      ${binderLinks}
      ${dayLinks}
      <a class="lesson-editor-jump-link" href="#admin-lesson-resources" data-admin-lesson-jump="resources">Resources</a>
    </nav>
  `;
}

