function countCurriculumDailyPlanItems(dailyPlans) {
  return CURRICULUM_WEEKDAYS.reduce((count, day) => (
    count + (Array.isArray(dailyPlans?.[day]?.items) ? dailyPlans[day].items.length : 0)
  ), 0);
}

function setAdminCurriculumLessonSaveBanner(text, isSuccess = false) {
  adminCurriculumLessonSaveBanner = {
    text: String(text || ""),
    isSuccess: Boolean(isSuccess),
  };
}

function collectCurriculumBooksFromEditor(root) {
  if (!root) return [];
  return [...root.querySelectorAll("[data-curriculum-book-row]")].map((row) => ({
    title: normalizedShortText(row.querySelector("[data-curriculum-book-title]")?.value),
    author: normalizedShortText(row.querySelector("[data-curriculum-book-author]")?.value),
    notes: normalizedMultilineText(row.querySelector("[data-curriculum-book-notes]")?.value),
  })).filter((book) => book.title);
}

function collectCurriculumSongsFromEditor(root) {
  if (!root) return [];
  return [...root.querySelectorAll("[data-curriculum-song-row]")].map((row) => ({
    title: normalizedShortText(row.querySelector("[data-curriculum-song-title]")?.value),
    notes: normalizedMultilineText(row.querySelector("[data-curriculum-song-notes]")?.value),
  })).filter((song) => song.title);
}

function collectCurriculumTextListFromEditor(root) {
  if (!root) return [];
  return [...root.querySelectorAll("[data-curriculum-text-list-row]")].map((row) => (
    normalizedMultilineText(row.querySelector("[data-curriculum-text-list-value]")?.value)
  )).filter(Boolean);
}

function collectCurriculumDomainChecks(root) {
  if (!root) return [];
  return [...root.querySelectorAll("input[data-curriculum-domain-option]:checked")]
    .map((input) => normalizedShortText(input.value))
    .filter(Boolean);
}

function collectCurriculumLessonPlanFromForm(form, existingOverride = null) {
  const formData = new FormData(form);
  const id = normalizedShortText(formData.get("id"));
  const existing = existingOverride
    || (id ? curriculumLessonEditorRecord() : null)
    || (id ? normalizeCurriculumLessonPlanForRender(resources.find((item) => item.id === id)?._curriculumLessonPlan || null) : null);
  const preservedDaily = existing?.dailyPlans || {};
  const weeklyBooksEditor = form.querySelector('[data-curriculum-books-editor="weekly"]');
  const weeklySongsEditor = form.querySelector('[data-curriculum-songs-editor="weekly"]');
  const dailyPlans = emptyCurriculumDailyPlans();
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const preservedDay = preservedDaily[day] && typeof preservedDaily[day] === "object"
      ? preservedDaily[day]
      : emptyCurriculumDailyPlanDay();
    const preservedItemsById = new Map(
      (Array.isArray(preservedDay.items) ? preservedDay.items : [])
        .filter((item) => item?.itemId)
        .map((item) => [item.itemId, item]),
    );
    const dayPanel = form.querySelector(`[data-curriculum-day-panel="${day}"]`);
    const rows = form.querySelectorAll(`.curriculum-daily-item-row[data-curriculum-day="${day}"]`);
    const items = [];
    rows.forEach((row) => {
      const title = normalizedShortText(row.querySelector("[data-curriculum-title]")?.value);
      if (!title) return;
      const itemId = normalizedShortText(row.querySelector("[data-curriculum-item-id]")?.value) || generateCurriculumItemIdClient();
      const preservedItem = preservedItemsById.get(itemId) || {};
      const learningGoals = normalizedMultilineText(row.querySelector("[data-curriculum-learning-goals]")?.value)
        .split(/\r?\n/)
        .map((goal) => goal.trim())
        .filter(Boolean);
      const domainsRoot = row.querySelector("[data-curriculum-activity-domains]");
      const binderFields = typeof isTeachingKitAuthoringEnabled === "function"
        && isTeachingKitAuthoringEnabled()
        && typeof LLHTeachingKitAuthoring !== "undefined"
        ? LLHTeachingKitAuthoring.collectActivityBinderFields(row)
        : {};
      items.push({
        ...preservedItem,
        itemId,
        activityCategory: normalizedShortText(row.querySelector("[data-curriculum-category]")?.value) || preservedItem.activityCategory || PLAY_ACTIVITY_CATEGORIES[0],
        title,
        objective: normalizedMultilineText(row.querySelector("[data-curriculum-objective]")?.value),
        description: normalizedMultilineText(row.querySelector("[data-curriculum-description]")?.value),
        learningDomains: collectCurriculumDomainChecks(domainsRoot),
        materials: normalizedMultilineText(row.querySelector("[data-curriculum-materials]")?.value),
        setup: normalizedMultilineText(row.querySelector("[data-curriculum-setup]")?.value),
        steps: normalizedMultilineText(row.querySelector("[data-curriculum-steps]")?.value),
        teacherRole: normalizedMultilineText(row.querySelector("[data-curriculum-teacher-role]")?.value),
        teacherLanguage: normalizedMultilineText(row.querySelector("[data-curriculum-teacher-language]")?.value),
        learningGoals,
        observationOpportunities: normalizedMultilineText(row.querySelector("[data-curriculum-observation-opportunities]")?.value),
        vocabulary: normalizedMultilineText(row.querySelector("[data-curriculum-vocabulary]")?.value),
        extensions: normalizedMultilineText(row.querySelector("[data-curriculum-extensions]")?.value),
        adaptations: normalizedMultilineText(row.querySelector("[data-curriculum-adaptations]")?.value),
        safetyNotes: normalizedMultilineText(row.querySelector("[data-curriculum-safety-notes]")?.value),
        ageModifications: normalizedMultilineText(row.querySelector("[data-curriculum-age-modifications]")?.value),
        ...binderFields,
      });
    });
    // If a weekday panel was removed from the DOM, preserve existing day content instead of wiping it.
    const preservedItems = Array.isArray(preservedDay.items) ? preservedDay.items : [];
    const resolvedItems = (!dayPanel && !rows.length && preservedItems.length)
      ? preservedItems
      : items;
    const dayBooksEditor = dayPanel?.querySelector(`[data-curriculum-books-editor="day:${day}"]`);
    const daySongsEditor = dayPanel?.querySelector(`[data-curriculum-songs-editor="day:${day}"]`);
    dailyPlans[day] = dayPanel ? {
      theme: normalizedShortText(dayPanel.querySelector("[data-curriculum-day-theme]")?.value),
      objectives: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-objectives]")?.value),
      learningDomains: collectCurriculumDomainChecks(dayPanel.querySelector("[data-curriculum-day-domains]")),
      materials: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-materials]")?.value),
      vocabulary: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-vocabulary]")?.value),
      books: collectCurriculumBooksFromEditor(dayBooksEditor),
      songs: collectCurriculumSongsFromEditor(daySongsEditor),
      circleTime: collectCurriculumTextListFromEditor(dayPanel.querySelector(`[data-curriculum-text-list-editor="day:${day}:circleTime"]`)),
      transitions: collectCurriculumTextListFromEditor(dayPanel.querySelector(`[data-curriculum-text-list-editor="day:${day}:transitions"]`)),
      outdoorPlay: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-outdoor]")?.value),
      familyConnection: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-family]")?.value),
      observations: collectCurriculumTextListFromEditor(dayPanel.querySelector(`[data-curriculum-text-list-editor="day:${day}:observations"]`)),
      adaptations: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-adaptations]")?.value),
      safetyNotes: normalizedMultilineText(dayPanel.querySelector("[data-curriculum-day-safety]")?.value),
      items: resolvedItems,
    } : {
      ...preservedDay,
      items: resolvedItems,
    };
  });
  // Prefer the live store plan for enrichment-bearing fields so classic Save cannot
  // drop drafts/history/media even if the form normalize path omitted them.
  const storedPlan = id ? curriculumLessonPlanById(id) : null;
  const enrichmentSource = storedPlan || existing || {};
  const collected = {
    ...(existing || {}),
    id,
    title: normalizedShortText(formData.get("title")) || "Untitled Lesson Plan",
    age: normalizedShortText(formData.get("age")) || "Preschool",
    theme: normalizedShortText(formData.get("theme")),
    plan: normalizedShortText(formData.get("plan")) === "Pro" ? "Pro" : "Free",
    status: CURRICULUM_LESSON_STATUSES.includes(formData.get("status")) ? formData.get("status") : "draft",
    learningDomains: formData.getAll("learningDomains").map((item) => normalizedShortText(item)).filter(Boolean),
    weeklyOverview: normalizedMultilineText(formData.get("weeklyOverview")),
    objectives: normalizedMultilineText(formData.get("objectives")),
    weeklyMaterials: normalizedMultilineText(formData.get("weeklyMaterials")),
    vocabularyWords: normalizedMultilineText(formData.get("vocabularyWords")),
    observationOpportunities: normalizedMultilineText(formData.get("observationOpportunities")),
    adaptations: normalizedMultilineText(formData.get("adaptations")),
    familyConnection: normalizedMultilineText(formData.get("familyConnection")),
    books: collectCurriculumBooksFromEditor(weeklyBooksEditor),
    songs: collectCurriculumSongsFromEditor(weeklySongsEditor),
    dailyPlans,
    resourceIds: existing?.resourceIds || enrichmentSource.resourceIds || [],
    activityIds: existing?.activityIds || enrichmentSource.activityIds || [],
    coverImageUrl: (() => {
      const rawCoverUrl = formData.get("coverImageUrl");
      if (rawCoverUrl === null) return sanitizedImageSource(existing?.coverImageUrl || "");
      return sanitizedImageSource(rawCoverUrl || "");
    })(),
    coverImageAlt: (() => {
      const rawAlt = formData.get("coverImageAlt");
      if (rawAlt === null) return existing?.coverImageAlt || "";
      return normalizedShortText(rawAlt) || "";
    })(),
    coverImageSource: (() => {
      const rawSource = formData.get("coverImageSource");
      if (rawSource === null) return existing?.coverImageSource || "";
      return normalizedShortText(rawSource) || "";
    })(),
    coverImagePosition: (() => {
      const rawPosition = formData.get("coverImagePosition");
      if (rawPosition === null) return existing?.coverImagePosition || "center";
      return normalizedShortText(rawPosition) || "center";
    })(),
    createdAt: existing?.createdAt || "",
    updatedAt: existing?.updatedAt || "",
  };
  if (Object.prototype.hasOwnProperty.call(enrichmentSource, "enrichmentDraft")) {
    collected.enrichmentDraft = enrichmentSource.enrichmentDraft;
  }
  if (Array.isArray(enrichmentSource.enrichmentPublishHistory)) {
    collected.enrichmentPublishHistory = enrichmentSource.enrichmentPublishHistory;
  }
  if (enrichmentSource.teachingKit && typeof enrichmentSource.teachingKit === "object") {
    collected.teachingKit = enrichmentSource.teachingKit;
  }
  if (typeof isTeachingKitAuthoringEnabled === "function"
    && isTeachingKitAuthoringEnabled()
    && typeof LLHTeachingKitAuthoring !== "undefined") {
    const toolkit = LLHTeachingKitAuthoring.collectTeacherToolkitFromForm(form);
    if (toolkit) {
      collected.teachingKit = {
        ...(collected.teachingKit && typeof collected.teachingKit === "object" ? collected.teachingKit : { schemaVersion: 1 }),
        schemaVersion: 1,
        teacherToolkit: toolkit,
        updatedAt: new Date().toISOString(),
      };
      const completeness = LLHTeachingKitAuthoring.buildBinderCompleteness(
        collected,
        typeof curriculumActivitiesForLesson === "function" ? curriculumActivitiesForLesson(id) : [],
      );
      collected.teachingKit.completionPercent = completeness.percent;
      collected.teachingKit.completeness = completeness.percent >= 90
        ? "complete"
        : completeness.percent >= 50
          ? "enriched"
          : "legacy_mapped";
    }
  }
  return collected;
}

async function saveAdminCurriculumLessonPlanForm(form) {
  if (adminCurriculumLessonSaving) {
    setAdminCurriculumLessonSaveBanner("Already saving — please wait. If this persists, refresh the page and try again.", false);
    renderAdminCurriculumLessonPlanManager();
    document.querySelector("#adminCurriculumLessonPlanBanner")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    return;
  }
  const token = adminSession()?.token || "";
  if (!curriculumLessonPlanConfig.endpoint || !canUseLaunchBackend() || !token) {
    setAdminCurriculumLessonSaveBanner("Backend server and admin login are required.", false);
    renderAdminCurriculumLessonPlanManager();
    return;
  }

  // Collect from the live submitted form BEFORE any re-render. Re-rendering first
  // detaches the form and can produce an empty payload (silent no-op saves).
  let lessonPlan;
  try {
    lessonPlan = collectCurriculumLessonPlanFromForm(form);
  } catch (error) {
    setAdminCurriculumLessonSaveBanner(`❌ Could not read lesson form: ${error.message || "unknown error"}`, false);
    renderAdminCurriculumLessonPlanManager();
    return;
  }
  if (!lessonPlan.id) {
    lessonPlan.id = adminCurriculumLessonEditorId || `cur-lp-${Date.now().toString(16)}${Math.random().toString(16).slice(2, 10)}`;
  }
  adminCurriculumLessonEditorId = lessonPlan.id;
  const activityCount = countCurriculumDailyPlanItems(lessonPlan.dailyPlans);
  if (!activityCount) {
    setAdminCurriculumLessonSaveBanner("❌ No activities found in the form. Click Parse Lesson Plan again, then Save.", false);
    renderAdminCurriculumLessonPlanManager();
    document.querySelector("#adminCurriculumLessonPlanBanner")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    return;
  }
  const emptyWeekdays = CURRICULUM_WEEKDAYS.filter((day) => {
    const items = Array.isArray(lessonPlan.dailyPlans?.[day]?.items) ? lessonPlan.dailyPlans[day].items : [];
    return !items.some((item) => String(item?.title || "").trim());
  });
  const publishing = ["published", "featured"].includes(String(lessonPlan.status || "").toLowerCase());
  if (publishing && emptyWeekdays.length) {
    const labels = emptyWeekdays.map((day) => day.charAt(0).toUpperCase() + day.slice(1)).join(", ");
    setAdminCurriculumLessonSaveBanner(
      `❌ Published lesson plans need activities on every weekday. Add activities for: ${labels}.`,
      false,
    );
    renderAdminCurriculumLessonPlanManager();
    document.querySelector("#adminCurriculumLessonPlanBanner")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    return;
  }

  adminCurriculumLessonSaving = true;
  setAdminCurriculumLessonSaveBanner(`Saving “${lessonPlan.title}” with ${activityCount} activities…`, true);
  // Update banner/button in place — do not destroy the form while the request is in flight.
  const liveBanner = document.querySelector("#adminCurriculumLessonPlanBanner");
  if (liveBanner) {
    liveBanner.className = `form-message ${adminCurriculumLessonSaveBanner.isSuccess ? "success" : ""}`;
    liveBanner.textContent = adminCurriculumLessonSaveBanner.text;
  }
  const liveSubmit = form.querySelector("button[type='submit']");
  if (liveSubmit) {
    liveSubmit.disabled = true;
    liveSubmit.textContent = "Saving…";
  }

  const SAVE_TIMEOUT_MS = 30000;
  let successMessage = "";
  let errorMessage = "";
  let abortController = null;
  try {
    console.log("[curriculum-lesson-save] start", {
      id: lessonPlan.id,
      title: lessonPlan.title,
      activities: activityCount,
      expectedUpdatedAt: curriculumExpectedUpdatedAt() || "(empty)",
    });
    if (!curriculumExpectedUpdatedAt()) {
      try {
        await Promise.race([
          loadAdminSiteContent(),
          new Promise((_, reject) => setTimeout(() => reject(new Error("Timed out refreshing admin content.")), 15000)),
        ]);
      } catch (error) {
        console.warn("[curriculum-lesson-save] updatedAt refresh skipped", error.message || error);
      }
    }

    abortController = new AbortController();
    const timeoutId = setTimeout(() => abortController.abort(), SAVE_TIMEOUT_MS);
    let response;
    let data = null;
    let rawText = "";
    try {
      response = await fetch(curriculumLessonPlanConfig.endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          expectedUpdatedAt: curriculumExpectedUpdatedAt(),
          lessonPlan,
        }),
        signal: abortController.signal,
      });
      rawText = await response.text();
      try {
        data = rawText ? JSON.parse(rawText) : null;
      } catch {
        data = null;
      }
    } finally {
      clearTimeout(timeoutId);
    }

    console.log("[curriculum-lesson-save] response", {
      status: response.status,
      ok: response.ok,
      hasLesson: Boolean(data?.lessonPlan?.id),
      activities: Array.isArray(data?.activities) ? data.activities.length : 0,
      error: data?.error || null,
    });

    // On conflict: refresh the stamp from the response and ask the user to click Save
    // again. Do not auto-retry (avoids masking failures / duplicate blind posts).
    if (response.status === 409) {
      await handleCurriculumSaveConflict(data || {});
      const detail = data?.error || "Content was updated elsewhere.";
      throw new Error(`HTTP ${response.status}: ${detail} Stamp refreshed — click Save again.`);
    }
    if (!response.ok) {
      const detail = Array.isArray(data?.details) && data.details.length
        ? ` ${data.details.slice(0, 3).join(" ")}`
        : "";
      const serverError = data?.error || (rawText ? rawText.slice(0, 300) : "Save failed.");
      throw new Error(`HTTP ${response.status}: ${serverError}${detail}`);
    }
    if (!data?.lessonPlan?.id) {
      throw new Error(`HTTP ${response.status}: Save returned an empty lesson plan. Please refresh and try again.`);
    }
    applyCurriculumState(data.curriculum || effectiveCurriculum(), {
      siteContentUpdatedAt: data.siteContentUpdatedAt,
    });
    adminCurriculumLessonEditorId = data.lessonPlan.id;
    adminCurriculumLessonImportDraft = null;
    const syncedCount = (data.activities || []).filter((item) => item.status !== "archived").length;
    successMessage = `✅ Saved “${data.lessonPlan.title || lessonPlan.title}”. ${syncedCount} linked activities synced.`;
  } catch (error) {
    console.error("[curriculum-lesson-save] failed", error);
    if (error?.name === "AbortError") {
      errorMessage = `❌ Save timed out after ${SAVE_TIMEOUT_MS / 1000}s. The request was aborted — check Network for the POST status, then try again.`;
    } else {
      errorMessage = `❌ ${error.message || "Save failed."}`;
    }
  } finally {
    if (abortController) {
      try { abortController.abort(); } catch { /* ignore */ }
    }
    adminCurriculumLessonSaving = false;
    setAdminCurriculumLessonSaveBanner(successMessage || errorMessage || "❌ Save ended without a result. Check the browser console.", Boolean(successMessage));
    try {
      renderAdminCurriculumLessonPlanManager();
    } catch (renderError) {
      console.error("[curriculum-lesson-save] render failed after save", renderError);
      const fallbackBanner = document.querySelector("#adminCurriculumLessonPlanBanner");
      if (fallbackBanner) {
        fallbackBanner.className = `form-message ${successMessage ? "success" : ""}`;
        fallbackBanner.textContent = successMessage || errorMessage || "Save finished but the panel could not refresh. Reload the page.";
      }
    }
    const bannerEl = document.querySelector("#adminCurriculumLessonPlanBanner");
    bannerEl?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    // Keep the in-form message in sync when the editor is open.
    if (successMessage) setFormMessage("#adminCurriculumLessonPlanMessage", successMessage, true);
    if (errorMessage) setFormMessage("#adminCurriculumLessonPlanMessage", errorMessage, false);
  }
}

function ensureCurriculumListRowsContainer(container, emptyText) {
  if (!container) return null;
  const empty = container.querySelector(".curriculum-list-empty, .curriculum-daily-empty");
  if (empty) empty.remove();
  return container;
}

function moveCurriculumListRow(row, direction) {
  if (!row) return;
  const parent = row.parentElement;
  if (!parent) return;
  if (direction === "up") {
    const previous = row.previousElementSibling;
    if (previous) parent.insertBefore(row, previous);
    return;
  }
  const next = row.nextElementSibling;
  if (next) parent.insertBefore(next, row);
}

function removeCurriculumListRow(row, emptyHtml) {
  const container = row?.parentElement;
  row?.remove();
  if (container && !container.querySelector("[data-curriculum-book-row], [data-curriculum-song-row], [data-curriculum-text-list-row], .curriculum-daily-item-row")) {
    container.innerHTML = emptyHtml;
  }
}

function addCurriculumBookRow(scope) {
  const root = activeCurriculumLessonEditorRoot();
  const editor = root.querySelector(`[data-curriculum-books-editor="${scope}"]`);
  const container = ensureCurriculumListRowsContainer(editor?.querySelector("[data-curriculum-books-rows]"));
  if (!container) return;
  container.insertAdjacentHTML("beforeend", curriculumBookRowHtml({}, { scope }));
}

function addCurriculumSongRow(scope) {
  const root = activeCurriculumLessonEditorRoot();
  const editor = root.querySelector(`[data-curriculum-songs-editor="${scope}"]`);
  const container = ensureCurriculumListRowsContainer(editor?.querySelector("[data-curriculum-songs-rows]"));
  if (!container) return;
  container.insertAdjacentHTML("beforeend", curriculumSongRowHtml({}, { scope }));
}

function addCurriculumTextListRow(field) {
  const root = activeCurriculumLessonEditorRoot();
  const editor = root.querySelector(`[data-curriculum-text-list-editor="${field}"]`);
  const container = ensureCurriculumListRowsContainer(editor?.querySelector("[data-curriculum-text-list-rows]"));
  if (!container) return;
  container.insertAdjacentHTML("beforeend", curriculumTextListRowHtml("", { field }));
}

function activeCurriculumLessonEditorRoot() {
  return document.querySelector("#view-lesson-editor.active-view #userLessonPlanEditorForm")
    || document.querySelector("#adminCurriculumLessonPlanForm")
    || document;
}

function addCurriculumDailyPlanRow(day) {
  const root = activeCurriculumLessonEditorRoot();
  const container = root.querySelector(`[data-curriculum-day-items="${day}"]`);
  if (!container) return;
  const empty = container.querySelector(".curriculum-daily-empty");
  if (empty) empty.remove();
  container.insertAdjacentHTML("beforeend", curriculumDailyItemRowHtml(day, { itemId: generateCurriculumItemIdClient() }));
  const panel = root.querySelector(`[data-curriculum-day-panel="${day}"]`);
  if (panel && "open" in panel) panel.open = true;
}

async function removeCurriculumDailyPlanRow(button) {
  const confirmed = await confirmAction({
    title: "Remove from lesson plan?",
    message: "This removes the activity from this lesson plan only. When you save, the linked Activity Library entry is archived — not deleted permanently. The lesson plan itself is not deleted.",
    confirmLabel: "Remove From Lesson Plan",
  });
  if (!confirmed) return;
  const row = button.closest(".curriculum-daily-item-row");
  const container = row?.closest("[data-curriculum-day-items]");
  row?.remove();
  if (container && !container.querySelector(".curriculum-daily-item-row")) {
    const heading = container.querySelector("h5");
    container.innerHTML = `${heading ? heading.outerHTML : ""}<p class="muted-copy curriculum-daily-empty">No activities yet.</p>`;
  }
}

function duplicateCurriculumDailyPlanRow(button) {
  const row = button.closest(".curriculum-daily-item-row");
  if (!row) return;
  const day = row.getAttribute("data-curriculum-day") || "";
  const clone = row.cloneNode(true);
  const idInput = clone.querySelector("[data-curriculum-item-id]");
  if (idInput) idInput.value = generateCurriculumItemIdClient();
  const titleInput = clone.querySelector("[data-curriculum-title]");
  if (titleInput && titleInput.value) titleInput.value = `${titleInput.value} (copy)`;
  row.insertAdjacentElement("afterend", clone);
  if (day) {
    const panel = document.querySelector(`[data-curriculum-day-panel="${day}"]`);
    if (panel && "open" in panel) panel.open = true;
  }
}

function moveCurriculumDailyPlanRow(button, direction) {
  const row = button.closest(".curriculum-daily-item-row");
  if (!row) return;
  const siblings = [...(row.parentElement?.querySelectorAll(".curriculum-daily-item-row") || [])];
  const index = siblings.indexOf(row);
  if (index < 0) return;
  if (direction === "up") {
    if (index === 0) return;
    const previous = siblings[index - 1];
    row.parentElement.insertBefore(row, previous);
    return;
  }
  if (index >= siblings.length - 1) return;
  const next = siblings[index + 1];
  row.parentElement.insertBefore(next, row);
}

function moveCurriculumDailyPlanRowToDay(row, targetDay) {
  if (!row || !CURRICULUM_WEEKDAYS.includes(targetDay)) return;
  const currentDay = row.getAttribute("data-curriculum-day");
  if (currentDay === targetDay) return;
  const sourceContainer = row.closest("[data-curriculum-day-items]");
  const targetContainer = document.querySelector(`[data-curriculum-day-items="${targetDay}"]`);
  if (!targetContainer) return;
  const empty = targetContainer.querySelector(".curriculum-daily-empty");
  if (empty) empty.remove();
  row.setAttribute("data-curriculum-day", targetDay);
  const moveSelect = row.querySelector("[data-curriculum-activity-move-day]");
  if (moveSelect) moveSelect.value = targetDay;
  targetContainer.appendChild(row);
  if (sourceContainer && !sourceContainer.querySelector(".curriculum-daily-item-row")) {
    const heading = sourceContainer.querySelector("h5");
    sourceContainer.innerHTML = `${heading ? heading.outerHTML : ""}<p class="muted-copy curriculum-daily-empty">No activities yet.</p>`;
  }
  const panel = document.querySelector(`[data-curriculum-day-panel="${targetDay}"]`);
  if (panel && "open" in panel) panel.open = true;
}

function curriculumResourcesForAdmin({ includeArchived = false } = {}) {
  return effectiveCurriculum().resources
    .filter((item) => includeArchived || item.status !== "archived")
    .slice()
    .sort((a, b) => String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")));
}

function curriculumResourceStatusLabel(status) {
  const labels = {
    draft: "🟡 Draft",
    published: "🟢 Published",
    archived: "📦 Archived",
  };
  return labels[status] || status;
}

function curriculumResourceFileHref(resource) {
  const mediaUrl = String(resource?.mediaUrl || "").trim();
  if (mediaUrl) {
    if (mediaUrl.startsWith("/")) return mediaUrl;
    if (/^https:\/\//i.test(mediaUrl)) return mediaUrl;
  }
  const fileData = String(resource?.fileData || resource?.fileUrl || "").trim();
  if (!fileData) return "";
  // Data URLs and HTTPS URLs open directly (same pattern as Forms / Printables / legacy Uploads).
  if (fileData.startsWith("data:") || /^https:\/\//i.test(fileData)) return fileData;
  return "";
}

function curriculumResourceHasFile(resource) {
  if (!resource) return false;
  if (resource.hasFile === true) return true;
  return Boolean(curriculumResourceFileHref(resource));
}

function applyCurriculumState(curriculum, { siteContentUpdatedAt } = {}) {
  const next = {
    ...effectiveSiteContent(),
    curriculum: curriculum || effectiveCurriculum(),
    ...(siteContentUpdatedAt ? { updatedAt: siteContentUpdatedAt } : {}),
  };
  // Drop stale public-library cache so user-facing views derive from the saved curriculum.
  delete next.curriculumLibrary;
  siteContentState = next;
  syncSiteManagedResources();
}

function curriculumExpectedUpdatedAt() {
  return normalizedShortText(effectiveSiteContent().updatedAt || "");
}

async function handleCurriculumSaveConflict(data) {
  if (!data?.conflict) return false;
  if (data.siteContentUpdatedAt || data.curriculum) {
    applyCurriculumState(data.curriculum || effectiveCurriculum(), {
      siteContentUpdatedAt: data.siteContentUpdatedAt,
    });
  }
  // Curriculum conflict payloads already include siteContentUpdatedAt. Avoid a full admin
  // site-content reload here — it can be huge (embedded fileData) and block save retries.
  if (!data?.siteContentUpdatedAt) {
    try {
      await loadAdminSiteContent();
    } catch {
      // Keep conflict payload if reload fails.
    }
  }
  return true;
}

const CURRICULUM_UPLOAD_MAX_MB = 5;

async function fetchCurriculumResourceFile(resourceId) {
  const token = adminSession()?.token || "";
  if (!token || !resourceId) throw new Error("Admin login and resource id are required.");
  const params = new URLSearchParams({
    id: resourceId,
  });
  const response = await fetch(`${curriculumResourceConfig.fileEndpoint}?${params.toString()}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error || "Could not open resource file.");
  const href = curriculumResourceFileHref(data.resource);
  if (!href) throw new Error("Resource file data is not available.");
  return href;
}

async function openCurriculumResourceFile(resourceId) {
  const href = await fetchCurriculumResourceFile(resourceId);
  window.open(href, "_blank", "noopener");
}

async function uploadCurriculumResourceFile({ resourceId, file }) {
  const token = adminSession()?.token || "";
  if (!token || !file) throw new Error("Admin login and a file are required.");
  const fileData = await fileToDataUrlSafe(file, { maxMb: CURRICULUM_UPLOAD_MAX_MB });
  if (!fileData) throw new Error("Could not read the selected file.");
  const response = await fetch(curriculumResourceConfig.uploadEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({
      resourceId: resourceId || "",
      fileName: file.name || "upload",
      fileData,
    }),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error || "Upload failed.");
  return data;
}

function curriculumResourceAdminCardHtml(resource) {
  const linkedCount = Array.isArray(resource.lessonPlanIds) ? resource.lessonPlanIds.length : 0;
  const canOpen = curriculumResourceHasFile(resource);
  return `
    <article class="admin-content-card is-${escapeHtml(resource.status || "draft")}">
      <div class="admin-mobile-card-body">
        <div>
          <strong>${escapeHtml(resource.title || "Untitled Resource")}</strong>
          <div class="tag-row" style="margin:2px 0 4px">
            <span class="tag">${curriculumResourceStatusLabel(resource.status || "draft")}</span>
            <span class="tag">${escapeHtml(resource.resourceCategory || "Classroom Resources")}</span>
          </div>
          <small>${escapeHtml(resource.fileName || "No file")}</small>
          <small>${linkedCount} linked ${linkedCount === 1 ? "lesson plan" : "lesson plans"}</small>
          <small>Updated: ${escapeHtml(adminLessonUpdatedLabel(resource.updatedAt))}</small>
        </div>
      </div>
      <div class="form-actions">
        <button class="ghost-button" type="button" data-curriculum-resource-edit="${escapeHtml(resource.id)}">Edit</button>
        ${canOpen ? `<button class="ghost-button" type="button" data-curriculum-resource-open="${escapeHtml(resource.id)}">Open file</button>` : ""}
        ${resource.status !== "archived"
          ? `<button class="ghost-button" type="button" data-curriculum-resource-archive="${escapeHtml(resource.id)}">📦 Archive</button>`
          : ""
        }
      </div>
    </article>
  `;
}

function renderAdminCurriculumResourceForm(resource) {
  const record = resource || {
    id: adminCurriculumResourceEditorId || "",
    title: "",
    resourceCategory: "Classroom Resources",
    fileData: "",
    fileName: "",
    mimeType: "",
    status: "draft",
  };
  const openHref = curriculumResourceHasFile(record);
  const httpsValue = record.fileData?.startsWith("https://") ? record.fileData : "";
  return `
    <form id="adminCurriculumResourceForm" class="panel-form admin-stacked-form">
      <input type="hidden" name="id" value="${escapeHtml(record.id || "")}" />
      <h4>${record.id ? `Editing: ${escapeHtml(record.title || "Resource")}` : "New curriculum resource"}</h4>
      <p class="muted-copy">PDF or image up to ${CURRICULUM_UPLOAD_MAX_MB} MB. In production, files are stored in Postgres media storage (not inside the main store blob).</p>
      <div class="form-grid-two">
        <label>Title<input name="title" value="${escapeHtml(record.title || "")}" required /></label>
        <label>Category
          <select name="resourceCategory">
            ${CURRICULUM_RESOURCE_CATEGORIES.map((category) => `<option${record.resourceCategory === category ? " selected" : ""}>${escapeHtml(category)}</option>`).join("")}
          </select>
        </label>
      </div>
      <label>Status
        <select name="status">
          ${["draft", "published"].map((status) => `<option value="${status}"${record.status === status ? " selected" : ""}>${curriculumResourceStatusLabel(status)}</option>`).join("")}
        </select>
      </label>
      <label>Upload file (PDF or image, max ${CURRICULUM_UPLOAD_MAX_MB} MB)<input name="file" type="file" accept=".pdf,image/*" /></label>
      <label>Or external HTTPS URL<input name="fileUrl" value="${escapeHtml(httpsValue)}" placeholder="https://..." /></label>
      ${openHref ? `<p class="muted-copy">Current file: <button class="ghost-button" type="button" data-curriculum-resource-open="${escapeHtml(record.id)}">${escapeHtml(record.fileName || "Open file")}</button></p>` : ""}
      <div class="form-actions">
        <button class="primary-button" type="submit" ${adminCurriculumResourceSaving ? "disabled" : ""}>${adminCurriculumResourceSaving ? "Saving…" : "💾 Save resource"}</button>
        <button class="ghost-button" type="button" data-curriculum-resource-back>Back to list</button>
      </div>
      <span class="form-message" id="adminCurriculumResourceMessage"></span>
    </form>
  `;
}

function renderAdminCurriculumResourceManager() {
  const target = document.querySelector("#adminCurriculumResourceApp");
  if (!target) return;
  const resources = curriculumResourcesForAdmin();
  const editingId = adminCurriculumResourceEditorId;
  const editingResource = editingId
    ? (curriculumResourceById(editingId) || {
      id: editingId,
      title: "",
      resourceCategory: "Classroom Resources",
      fileData: "",
      fileName: "",
      status: "draft",
    })
    : null;
  target.innerHTML = `
    <div class="section-heading">
      <div>
        <p class="eyebrow">Play-Based Curriculum (Beta)</p>
        <h3>Curriculum resources</h3>
        <p class="muted-copy">Files are stored in Postgres media storage when available. Max ${CURRICULUM_UPLOAD_MAX_MB} MB per file.</p>
      </div>
      <button class="ghost-button" type="button" id="adminCreateCurriculumResourceButton">+ Upload resource</button>
    </div>
    <div class="admin-mobile-list">
      ${resources.map(curriculumResourceAdminCardHtml).join("") || `<div class="empty-state">No curriculum resources yet.</div>`}
    </div>
    ${editingResource ? renderAdminCurriculumResourceForm(editingResource) : ""}
  `;
}

function renderCurriculumLessonLinkedResourcesSection(plan) {
  const lessonPlanId = plan?.id || "";
  if (!lessonPlanId) return "";
  const linked = curriculumResourcesForLesson(lessonPlanId).filter((item) => item.status !== "archived");
  const available = curriculumResourcesForAdmin().filter((item) => !linked.some((linkedItem) => linkedItem.id === item.id));
  return `
    <fieldset class="admin-fieldset curriculum-linked-resources">
      <legend>Linked resources</legend>
      <p class="muted-copy">Resources link to this lesson plan only (not individual activities).</p>
      <div class="curriculum-linked-resource-list">
        ${linked.length
          ? linked.map((resource) => {
            const canOpen = curriculumResourceHasFile(resource);
            return `
            <div class="curriculum-linked-resource-row">
              <div>
                <strong>${escapeHtml(resource.title || "Resource")}</strong>
                <small>${escapeHtml(resource.resourceCategory || "Classroom Resources")} · ${escapeHtml(resource.fileName || "")}</small>
              </div>
              <div class="form-actions">
                ${canOpen ? `<button class="ghost-button" type="button" data-curriculum-resource-open="${escapeHtml(resource.id)}">Open</button>` : ""}
                <button class="ghost-button" type="button" data-curriculum-resource-unlink="${escapeHtml(resource.id)}" data-curriculum-lesson-id="${escapeHtml(lessonPlanId)}">Unlink</button>
              </div>
            </div>
          `;
          }).join("")
          : `<p class="muted-copy">No resources linked yet.</p>`
        }
      </div>
      ${available.length ? `
        <div class="form-grid-two curriculum-link-resource-row">
          <label>Link existing resource
            <select id="adminCurriculumLinkResourceSelect">
              <option value="">Select a resource…</option>
              ${available.map((resource) => `<option value="${escapeHtml(resource.id)}">${escapeHtml(resource.title || resource.id)}</option>`).join("")}
            </select>
          </label>
          <div class="form-actions">
            <button class="ghost-button" type="button" id="adminCurriculumLinkResourceButton" data-curriculum-lesson-id="${escapeHtml(lessonPlanId)}">Link resource</button>
          </div>
        </div>
      ` : `<p class="muted-copy">Upload resources in Curriculum Resources (Beta) to link them here.</p>`}
    </fieldset>
  `;
}

async function saveAdminCurriculumResourceForm(form) {
  if (adminCurriculumResourceSaving) return;
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !token) {
    setFormMessage("#adminCurriculumResourceMessage", "Backend server and admin login are required.", false);
    return;
  }
  adminCurriculumResourceSaving = true;
  renderAdminCurriculumResourceManager();
  applyAdminSectionVisibility();
  let successMessage = "";
  let errorMessage = "";
  try {
    if (!curriculumExpectedUpdatedAt()) {
      try {
        await loadAdminSiteContent();
      } catch {
        // Continue; server will return 409 if a stamp already exists.
      }
    }
    const formData = new FormData(form);
    const id = normalizedShortText(formData.get("id")) || `cur-res-${Date.now().toString(16)}${Math.random().toString(16).slice(2, 10)}`;
    const existing = curriculumResourceById(id);
    let fileData = "";
    let mediaAssetId = existing?.mediaAssetId || "";
    let mediaUrl = existing?.mediaUrl || "";
    let fileName = existing?.fileName || "";
    let mimeType = existing?.mimeType || "";
    const httpsUrl = sanitizedUrl(formData.get("fileUrl"));
    if (httpsUrl && /^https:\/\//i.test(httpsUrl)) {
      fileData = httpsUrl;
      fileName = fileName || httpsUrl.split("/").pop() || "link";
      mediaAssetId = "";
      mediaUrl = "";
    }
    const file = formData.get("file");
    if (file && file.size) {
      const uploaded = await uploadCurriculumResourceFile({ resourceId: id, file });
      fileData = uploaded.fileData || fileData;
      mediaAssetId = uploaded.mediaAssetId || mediaAssetId;
      mediaUrl = uploaded.mediaUrl || mediaUrl;
      fileName = uploaded.fileName || file.name || fileName;
      mimeType = uploaded.mimeType || mimeType;
    }
    if (!fileData && !mediaAssetId && !curriculumResourceHasFile(existing)) {
      throw new Error(`Upload a PDF/image (max ${CURRICULUM_UPLOAD_MAX_MB} MB) or provide an HTTPS URL.`);
    }
    const postResource = async () => {
      const response = await fetch(curriculumResourceConfig.saveEndpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          expectedUpdatedAt: curriculumExpectedUpdatedAt(),
          resource: {
            id,
            title: normalizedShortText(formData.get("title")) || "Resource",
            resourceCategory: normalizedShortText(formData.get("resourceCategory")) || "Classroom Resources",
            ...(fileData ? { fileData } : {}),
            ...(mediaAssetId ? { mediaAssetId, mediaUrl } : {}),
            fileName,
            mimeType,
            status: ["draft", "published"].includes(formData.get("status")) ? formData.get("status") : "draft",
            lessonPlanIds: existing?.lessonPlanIds || [],
          },
        }),
      });
      let data = null;
      try {
        data = await response.json();
      } catch {
        data = null;
      }
      return { response, data };
    };
    let { response, data } = await postResource();
    if (response.status === 409) {
      await handleCurriculumSaveConflict(data || {});
      ({ response, data } = await postResource());
    }
    if (response.status === 409) {
      throw new Error(data?.error || "Content was updated elsewhere. Reload admin content and try again.");
    }
    if (!response.ok) {
      const detail = Array.isArray(data?.details) && data.details.length
        ? ` ${data.details.slice(0, 3).join(" ")}`
        : "";
      throw new Error(`${data?.error || `Could not save resource (${response.status}).`}${detail}`);
    }
    applyCurriculumState(data.curriculum, { siteContentUpdatedAt: data.siteContentUpdatedAt });
    adminCurriculumResourceEditorId = data.resource?.id || id;
    successMessage = "✅ Resource saved.";
  } catch (error) {
    errorMessage = `❌ ${error.message || "Save failed."}`;
  } finally {
    adminCurriculumResourceSaving = false;
    renderAdminCurriculumResourceManager();
    applyAdminSectionVisibility();
    if (successMessage) setFormMessage("#adminCurriculumResourceMessage", successMessage, true);
    if (errorMessage) setFormMessage("#adminCurriculumResourceMessage", errorMessage, false);
  }
}

async function archiveAdminCurriculumResource(id) {
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !token) return;
  await runAdminAction({
    messageSelector: "#adminCurriculumResourceMessage",
    actionFn: async () => {
      const response = await fetch(curriculumResourceConfig.archiveEndpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          expectedUpdatedAt: curriculumExpectedUpdatedAt(),
          id,
        }),
      });
      const data = await response.json();
      if (response.status === 409 && await handleCurriculumSaveConflict(data)) {
        throw new Error(data?.error || "Content was updated elsewhere. Reload and try again.");
      }
      if (!response.ok) throw new Error(data?.error || "Could not archive resource.");
      applyCurriculumState(data.curriculum, { siteContentUpdatedAt: data.siteContentUpdatedAt });
    },
    successMsg: "✅ Resource archived.",
    onComplete: () => {
      renderAdminCurriculumResourceManager();
      if (adminCurriculumLessonEditorId) {
        renderAdminCurriculumLessonPlanManager();
      }
    },
  });
}

async function linkCurriculumResourceToLesson(resourceId, lessonPlanId) {
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !token || !resourceId || !lessonPlanId) return;
  const response = await fetch(curriculumResourceConfig.linkEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({
      expectedUpdatedAt: curriculumExpectedUpdatedAt(),
      resourceId,
      lessonPlanId,
    }),
  });
  const data = await response.json();
  if (response.status === 409 && await handleCurriculumSaveConflict(data)) {
    throw new Error(data?.error || "Content was updated elsewhere. Reload and try again.");
  }
  if (!response.ok) throw new Error(data?.error || "Could not link resource.");
  applyCurriculumState(data.curriculum, { siteContentUpdatedAt: data.siteContentUpdatedAt });
  return data;
}

async function unlinkCurriculumResourceFromLesson(resourceId, lessonPlanId) {
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !token || !resourceId || !lessonPlanId) return;
  const response = await fetch(curriculumResourceConfig.unlinkEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({
      expectedUpdatedAt: curriculumExpectedUpdatedAt(),
      resourceId,
      lessonPlanId,
    }),
  });
  const data = await response.json();
  if (response.status === 409 && await handleCurriculumSaveConflict(data)) {
    throw new Error(data?.error || "Content was updated elsewhere. Reload and try again.");
  }
  if (!response.ok) throw new Error(data?.error || "Could not unlink resource.");
  applyCurriculumState(data.curriculum, { siteContentUpdatedAt: data.siteContentUpdatedAt });
  return data;
}

