// ─── Account Type + User Role (mirrors scripts/account-access.js) ───────────
// Account Type (home_daycare | center) is separate from User Role
// (owner | director | teacher | assistant). Subscription/plan checks stay separate.
const ACCOUNT_TYPES = Object.freeze({
  HOME_DAYCARE: "home_daycare",
  CENTER: "center",
  SINGLE_PROVIDER: "single_provider",
});

/** Reserved — see docs/FUTURE_ONBOARDING_PRICING.md (not active yet). */
const FUTURE_ACCOUNT_TYPES = Object.freeze({
  CURRICULUM_ONLY: "curriculum_only",
});

const USER_ROLES = Object.freeze({
  OWNER: "owner",
  DIRECTOR: "director",
  TEACHER: "teacher",
  ASSISTANT: "assistant",
});

const PLATFORM_CAPABILITIES = Object.freeze([
  "calendar",
  "lesson_plans",
  "daily_logs",
  "child_profiles",
  "activity_library",
  "documentation_helpers",
  "forms",
  "reports",
  "resources",
  "settings",
  "staff_management",
  "billing",
  "permissions",
  "classrooms",
  "families",
  "enrollment",
]);

const ACCOUNT_TYPE_ALIASES = Object.freeze({
  home_daycare: ACCOUNT_TYPES.HOME_DAYCARE,
  "home daycare": ACCOUNT_TYPES.HOME_DAYCARE,
  homedaycare: ACCOUNT_TYPES.HOME_DAYCARE,
  "family childcare": ACCOUNT_TYPES.HOME_DAYCARE,
  "family child care": ACCOUNT_TYPES.HOME_DAYCARE,
  family_childcare: ACCOUNT_TYPES.HOME_DAYCARE,
  center: ACCOUNT_TYPES.CENTER,
  "childcare center": ACCOUNT_TYPES.CENTER,
  "child care center": ACCOUNT_TYPES.CENTER,
  childcare_center: ACCOUNT_TYPES.CENTER,
  preschool: ACCOUNT_TYPES.CENTER,
  "preschool classroom": ACCOUNT_TYPES.CENTER,
  "after school program": ACCOUNT_TYPES.CENTER,
  after_school: ACCOUNT_TYPES.CENTER,
  single_provider: ACCOUNT_TYPES.SINGLE_PROVIDER,
  "single provider": ACCOUNT_TYPES.SINGLE_PROVIDER,
  individual: ACCOUNT_TYPES.SINGLE_PROVIDER,
  other: ACCOUNT_TYPES.HOME_DAYCARE,
});

const USER_ROLE_ALIASES = Object.freeze({
  owner: USER_ROLES.OWNER,
  "director / owner": USER_ROLES.OWNER,
  "director/owner": USER_ROLES.OWNER,
  director: USER_ROLES.DIRECTOR,
  teacher: USER_ROLES.TEACHER,
  "lead teacher": USER_ROLES.TEACHER,
  lead_teacher: USER_ROLES.TEACHER,
  assistant: USER_ROLES.ASSISTANT,
  "assistant / staff": USER_ROLES.ASSISTANT,
  staff: USER_ROLES.ASSISTANT,
  "co-teacher": USER_ROLES.TEACHER,
  coteacher: USER_ROLES.TEACHER,
  "family helper": USER_ROLES.ASSISTANT,
  substitute: USER_ROLES.ASSISTANT,
});

function normalizeAccountType(value, fallback = ACCOUNT_TYPES.HOME_DAYCARE) {
  const key = String(value || "").trim().toLowerCase();
  if (!key) return fallback;
  return ACCOUNT_TYPE_ALIASES[key] || fallback;
}

function normalizeUserRole(value, fallback = USER_ROLES.OWNER) {
  const key = String(value || "").trim().toLowerCase();
  if (!key) return fallback;
  return USER_ROLE_ALIASES[key] || fallback;
}

function mapProgramTypeToAccountType(programType) {
  return normalizeAccountType(programType, ACCOUNT_TYPES.HOME_DAYCARE);
}

function resolveAccountType(account = {}) {
  if (account?.accountType) return normalizeAccountType(account.accountType);
  const programType = account?.programSettings?.programType;
  if (programType) return mapProgramTypeToAccountType(programType);
  return ACCOUNT_TYPES.HOME_DAYCARE;
}

function resolveUserRole(account = {}) {
  const email = String(account?.email || currentUser || "").trim().toLowerCase();
  const linkedOwner = String(account?.linkedProgramOwnerEmail || "").trim().toLowerCase();
  const isLinkedMember = Boolean(linkedOwner && email && linkedOwner !== email);
  if (account?.role) {
    const role = normalizeUserRole(account.role, isLinkedMember ? USER_ROLES.DIRECTOR : USER_ROLES.OWNER);
    if (isLinkedMember && role === USER_ROLES.OWNER) return USER_ROLES.DIRECTOR;
    return role;
  }
  if (account?.userRole) {
    const role = normalizeUserRole(account.userRole, isLinkedMember ? USER_ROLES.DIRECTOR : USER_ROLES.OWNER);
    if (isLinkedMember && role === USER_ROLES.OWNER) return USER_ROLES.DIRECTOR;
    return role;
  }
  if (isLinkedMember) return USER_ROLES.DIRECTOR;
  return USER_ROLES.OWNER;
}

function roleAllowsCapability(role, capability) {
  const r = normalizeUserRole(role);
  switch (capability) {
    case "calendar":
    case "lesson_plans":
    case "daily_logs":
    case "child_profiles":
    case "activity_library":
    case "documentation_helpers":
    case "reports":
    case "resources":
    case "settings":
      return true;
    case "forms":
    case "staff_management":
    case "permissions":
      return r === USER_ROLES.OWNER || r === USER_ROLES.DIRECTOR;
    case "billing":
      return r === USER_ROLES.OWNER;
    case "classrooms":
    case "families":
    case "enrollment":
      return r === USER_ROLES.OWNER || r === USER_ROLES.DIRECTOR;
    default:
      return false;
  }
}

function accountTypeAllowsCapability(accountType, capability) {
  const type = normalizeAccountType(accountType);
  if (capability === "classrooms" || capability === "families" || capability === "enrollment") {
    // Work-mode nav (testing) surfaces Families/Classrooms/Enrollment for home daycares too.
    try {
      if (typeof isWorkModeNavEnabled === "function" && isWorkModeNavEnabled()) return true;
    } catch (_error) { /* boot race */ }
    return type === ACCOUNT_TYPES.CENTER;
  }
  return true;
}

function canAccessCapability(account, capability, options = {}) {
  if (!capability || !PLATFORM_CAPABILITIES.includes(capability)) return false;
  if (options.adminOverride === true) return true;
  if (!account) return false;
  const accountType = resolveAccountType(account);
  // Prefer getUserRole so Admin View As (Owner/Director/Teacher/Assistant) updates nav/permissions instantly.
  const role = typeof getUserRole === "function" ? getUserRole(account) : resolveUserRole(account);
  if (!accountTypeAllowsCapability(accountType, capability)) return false;
  if (!roleAllowsCapability(role, capability)) return false;
  return true;
}

function migrateAccountAccessFields(account = {}) {
  const accountType = resolveAccountType(account);
  const role = resolveUserRole(account);
  const changed = account.accountType !== accountType || account.role !== role;
  return {
    accountType,
    role,
    changed,
    updates: changed ? { accountType, role } : {},
  };
}

function defaultAccountAccessFields() {
  return {
    accountType: ACCOUNT_TYPES.HOME_DAYCARE,
    role: USER_ROLES.OWNER,
  };
}

/** Current session account type. Guests default to home_daycare. */
function getAccountType(account = currentAccount()) {
  if (!account) return ACCOUNT_TYPES.HOME_DAYCARE;
  return resolveAccountType(account);
}

/** Current session user role. Guests default to owner for read-only marketing paths. */
function getUserRole(account = currentAccount()) {
  const previewRole = typeof adminPreviewUserRole === "function" ? adminPreviewUserRole() : "";
  if (previewRole) return previewRole;
  if (!account) return USER_ROLES.OWNER;
  return resolveUserRole(account);
}

function accountTypeDisplayLabel(accountOrType) {
  const type = typeof accountOrType === "string"
    ? normalizeAccountType(accountOrType)
    : getAccountType(accountOrType);
  if (type === ACCOUNT_TYPES.CENTER) return "Childcare Center";
  if (type === ACCOUNT_TYPES.SINGLE_PROVIDER) return "Single Provider";
  return "Home Daycare";
}

function roleDisplayLabel(accountOrRole) {
  const role = typeof accountOrRole === "string"
    ? normalizeUserRole(accountOrRole)
    : getUserRole(accountOrRole);
  if (role === USER_ROLES.DIRECTOR) return "Director";
  if (role === USER_ROLES.TEACHER) return "Lead Teacher";
  if (role === USER_ROLES.ASSISTANT) return "Assistant / Staff";
  return "Director / Owner";
}

async function syncAccountProfileToBackend(email, profile = {}, options = {}) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail || !canUseLaunchBackend()) return null;
  try {
    const metaIds = metaBrowserIds();
    const response = await fetch("/api/account/profile", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email: cleanEmail,
        firstName: profile.firstName || "",
        lastName: profile.lastName || "",
        businessName: profile.businessName || profile.daycareName || profile.programName || "",
        accountType: profile.accountType || "",
        role: profile.role || "",
        phone: profile.phone || "",
        centerAssociation: profile.centerAssociation || "",
        centerInviteCode: profile.centerInviteCode || "",
        signup: Boolean(options.signup),
        lastLogin: Boolean(options.lastLogin),
        metaEventId: options.metaEventId || "",
        eventId: options.metaEventId || "",
        fbp: metaIds.fbp,
        fbc: metaIds.fbc,
        eventSourceUrl: window.location.href,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error || "Could not sync account profile.");
    return data.user || null;
  } catch (error) {
    console.warn("Account profile sync failed", error);
    return null;
  }
}

/**
 * Platform feature gate (roles + account type).
 * Distinct from canAccess(resource) which gates Free vs Pro library content.
 */
function canAccessPlatformFeature(capability, account = currentAccount()) {
  return canAccessCapability(account, capability, {
    adminOverride: typeof hasAdminFullAccess === "function" && hasAdminFullAccess(),
  });
}

function ensureAccountAccessMigrated(email = currentUser) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) return null;
  const account = ensureAccount(cleanEmail);
  if (!account) return null;
  const migration = migrateAccountAccessFields(account);
  if (migration.changed) {
    return updateAccount(cleanEmail, migration.updates);
  }
  return account;
}

function ensureAccount(email) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) return null;
  const allAccounts = accounts();
  if (!allAccounts[cleanEmail]) {
    allAccounts[cleanEmail] = {
      email: cleanEmail,
      plan: "Free",
      subscriptionCadence: "",
      subscriptionStatus: "Free Plan",
      foundingMember: false,
      foundingMemberNumber: null,
      priceLock: "",
      monthlyPrice: "$0/month",
      stripeCustomerId: "",
      stripeSubscriptionId: "",
      paymentMethod: "No payment method on file",
      billingHistory: [],
      favorites: [],
      downloads: [],
      phone: "",
      authProvider: authProviderName,
      emailVerified: !firebaseAuthEnabled,
      passwordHash: "",
      ...defaultAccountAccessFields(),
      createdAt: new Date().toISOString(),
    };
    saveAccounts(allAccounts);
  }
  return allAccounts[cleanEmail];
}

function updateAccount(email, updates) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) return null;
  const allAccounts = accounts();
  const account = allAccounts[cleanEmail] || ensureAccount(cleanEmail);
  allAccounts[cleanEmail] = repairFoundingMemberPricing({
    ...account,
    ...updates,
    updatedAt: new Date().toISOString(),
  });
  saveAccounts(allAccounts);
  return allAccounts[cleanEmail];
}

function getProgramSettings() {
  if (!currentUser) return {};
  return currentAccount()?.programSettings || {};
}

function saveProgramSettings(data) {
  if (!currentUser) return;
  const account = currentAccount() || ensureAccount(currentUser);
  const nextSettings = data && typeof data === "object" ? data : {};
  const updates = { programSettings: nextSettings };
  // Keep accountType in sync with Program Settings programType when present.
  // Explicit accountType already set to center/home_daycare still follows programType on save
  // so providers who update Program Type get the matching account type.
  if (nextSettings.programType) {
    updates.accountType = mapProgramTypeToAccountType(nextSettings.programType);
  }
  const migration = migrateAccountAccessFields({ ...account, ...updates });
  if (!updates.accountType) updates.accountType = migration.accountType;
  if (!account?.role) updates.role = migration.role;
  updateAccount(currentUser, updates);
  syncAccountProfileToBackend(currentUser, {
    firstName: account?.firstName || "",
    lastName: account?.lastName || "",
    businessName: nextSettings.programName || account?.businessName || "",
    accountType: updates.accountType || account?.accountType || "",
    role: updates.role || account?.role || "",
    phone: account?.phone || "",
  }).catch(() => {});
}

function loadAccountState(email) {
  const account = ensureAccount(email);
  if (!account) return;
  currentUser = account.email;
  // Backfill accountType + role for existing accounts (defaults: home_daycare / owner).
  ensureAccountAccessMigrated(account.email);
  // Refresh curriculum so grandfathered Free users receive their legacy Free library payload.
  refreshPublicCurriculumLibrary().catch(() => {});
  // Repair stale $19.99 on continuously active founding members.
  const repaired = repairFoundingMemberPricing(account);
  if (repaired && (repaired.monthlyPrice !== account.monthlyPrice || repaired.plan !== account.plan)) {
    updateAccount(account.email, repaired);
  }
  currentPlan = normalizeBillingPlan((repaired || account).plan || (account.foundingMember ? "Founding" : "Free"), repaired || account);
  if (currentPlan === "Free" && (account.plan !== "Free" || account.monthlyPrice !== "$0/month")) {
    updateAccount(account.email, {
      plan: "Free",
      subscriptionCadence: "",
      monthlyPrice: "$0/month",
      priceLock: "",
    });
  }
  const refreshed = accounts()[account.email] || repaired || account;
  favorites = refreshed.favorites || [];
  savedDownloads = refreshed.downloads || [];
  localStorage.setItem("llhGeneratedOutputs", JSON.stringify(refreshed.generatedOutputs || []));
  localStorage.setItem("llhUser", currentUser);
  localStorage.setItem("llhPlan", currentPlan);
  localStorage.setItem("llhFavorites", JSON.stringify(favorites));
  localStorage.setItem("llhDownloads", JSON.stringify(savedDownloads));
  updateAuthButtons();
  updatePlanLabel();
}

function markAccountLogin(email) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) return;
  updateAccount(cleanEmail, {
    lastLoginAt: new Date().toISOString(),
    lastSeenAt: new Date().toISOString(),
    lastPlanSeen: currentPlan,
  });
}

function saveCurrentAccountState() {
  if (!currentUser) return;
  const allAccounts = accounts();
  const account = allAccounts[currentUser] || ensureAccount(currentUser);
  const normalizedPlan = normalizeBillingPlan(currentPlan, account);
  const paidBilling = accountHasPaidBilling({ ...account, plan: normalizedPlan });
  allAccounts[currentUser] = {
    ...account,
    plan: normalizedPlan,
    subscriptionStatus: paidBilling
      ? account?.subscriptionStatus || `${billingPlanLabel(normalizedPlan)} Subscription Active`
      : "Free Plan",
    subscriptionCadence: paidBilling ? account?.subscriptionCadence || "" : "",
    monthlyPrice: paidBilling ? billingPriceLabel({ ...account, plan: normalizedPlan }) : "$0/month",
    priceLock: paidBilling
      ? (normalizedPlan === "Founding" || account?.foundingMemberActive ? "Lifetime" : (account?.priceLock || ""))
      : "",
    favorites,
    downloads: savedDownloads,
    generatedOutputs: generatedOutputs(),
    updatedAt: new Date().toISOString(),
  };
  saveAccounts(allAccounts);
}

function setAuthMode(mode) {
  currentAuthMode = mode;
  const title = document.querySelector("#authTitle");
  const nameFields = document.querySelector("#authNameFields");
  const businessFields = document.querySelector("#authBusinessFields");
  const phoneField = document.querySelector("#authPhoneField");
  const passwordField = document.querySelector("#passwordInput");
  const submitButton = document.querySelector("#authSubmitButton");
  const forgotButton = document.querySelector("#forgotPasswordButton");
  const switchButton = document.querySelector("#switchAuthModeButton");
  setFormMessage("#authMessage", "");
  if (!title || !phoneField || !passwordField || !submitButton || !forgotButton || !switchButton) return;
  const isSignup = mode === "signup";
  if (!isSignup) {
    signupWizardStep = 1;
    signupPersonaChoice = "";
    signupCenterPathway = "";
  }
  // Step 1 signup: name + email + password only (no business/role yet).
  if (nameFields) {
    nameFields.classList.toggle("hidden-field", !isSignup);
    nameFields.setAttribute("aria-hidden", isSignup ? "false" : "true");
    const fullNameInput = nameFields.querySelector("#fullNameInput");
    if (fullNameInput) fullNameInput.required = isSignup;
  }
  if (businessFields) {
    businessFields.classList.add("hidden-field");
    businessFields.setAttribute("aria-hidden", "true");
    businessFields.querySelectorAll("input, select").forEach((input) => {
      input.required = false;
    });
  }
  phoneField.classList.add("hidden-field");
  phoneField.setAttribute("aria-hidden", "true");
  passwordField.required = mode !== "forgot";
  passwordField.autocomplete = mode === "signup" ? "new-password" : "current-password";
  passwordField.closest("label")?.classList.toggle("hidden-field", mode === "forgot");
  submitButton.hidden = false;
  if (mode === "signup") {
    applySignupIntentCopyToAuthModal();
    submitButton.textContent = "Continue";
    forgotButton.style.display = "none";
    switchButton.textContent = "Already have an account? Log in";
    renderSignupWizardStep();
  } else if (mode === "forgot") {
    const intentNote = document.querySelector("#authFoundingContinueNote");
    if (intentNote) intentNote.hidden = true;
    title.textContent = "Reset your password";
    submitButton.textContent = "Send Reset Email";
    forgotButton.style.display = "none";
    switchButton.textContent = "Back to login";
    renderSignupWizardStep();
  } else {
    const intentNote = document.querySelector("#authFoundingContinueNote");
    if (intentNote) intentNote.hidden = true;
    title.textContent = "Log in to Little Learner Hub";
    submitButton.textContent = "Log In";
    forgotButton.style.display = "inline-flex";
    switchButton.textContent = "Create account";
    renderSignupWizardStep();
  }
}

async function signUpWithProvider(email, password, phone, firstName, lastName) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) throw new Error("Please enter your email address.");
  if (String(password || "").length < 8) throw new Error("Please use a password with at least 8 characters.");
  const cleanFirst = String(firstName || "").trim();
  const cleanLast  = String(lastName || "").trim();
  const fullName   = [cleanFirst, cleanLast].filter(Boolean).join(" ");
  if (firebaseAuthEnabled) {
    const client = await getFirebaseAuthClient();
    const credential = await client.createUserWithEmailAndPassword(client.auth, cleanEmail, password);
    await client.sendEmailVerification(credential.user);
    ensureAccount(cleanEmail);
    updateAccount(cleanEmail, {
      authProvider: "Firebase Authentication",
      emailVerified: credential.user.emailVerified,
      firebaseUid: credential.user.uid,
      phone: String(phone || "").trim(),
      firstName: cleanFirst,
      lastName: cleanLast,
      name: fullName || undefined,
    });
    return { email: cleanEmail, verified: credential.user.emailVerified, message: "Account created. Please check your email to verify your address." };
  }
  ensureAccount(cleanEmail);
  updateAccount(cleanEmail, {
    authProvider: "Email & password",
    emailVerified: false,
    phone: String(phone || "").trim(),
    firstName: cleanFirst,
    lastName: cleanLast,
    name: fullName || undefined,
    passwordHash: await localPasswordHash(password),
  });
  return { email: cleanEmail, verified: false, message: "Welcome! Your account is ready — you can start exploring right away." };
}

async function loginWithServerPassword(email, password) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  const response = await fetch("/api/auth/password-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: cleanEmail, password }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || "The email or password did not match. Please try again.");
  }
  ensureAccount(cleanEmail);
  updateAccount(cleanEmail, {
    mustChangePassword: Boolean(data.mustChangePassword),
    serverPasswordAuth: Boolean(data.serverPasswordAuth),
    tempPasswordExpiresAt: data.tempPasswordExpiresAt || "",
    authProvider: "Email & password",
  });
  writeMemberSessionToken(data.memberSessionToken || "", { persist: memberWantsPersistentSession() });
  return {
    email: cleanEmail,
    verified: true,
    mustChangePassword: Boolean(data.mustChangePassword),
    memberSessionToken: data.memberSessionToken || "",
  };
}

async function syncPasswordAfterFirebaseAuth(password, source = "firebase_login", emailHint = "") {
  try {
    const headers = { "Content-Type": "application/json" };
    const body = {
      newPassword: password || undefined,
      source,
      email: String(emailHint || currentUser || "").trim().toLowerCase() || undefined,
    };
    if (firebaseAuthEnabled) {
      const client = await getFirebaseAuthClient();
      const token = await client.auth.currentUser?.getIdToken?.();
      if (!token) return null;
      headers.Authorization = `Bearer ${token}`;
    }
    const response = await fetch("/api/auth/sync-password-after-firebase", {
      method: "POST",
      headers,
      body: JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      console.warn("[auth] firebase password sync failed", data.error || response.status);
      return null;
    }
    const email = data.email || emailHint || currentUser;
    if (email) {
      updateAccount(email, {
        mustChangePassword: false,
        serverPasswordAuth: true,
        passwordHash: password ? await localPasswordHash(password) : accounts()[email]?.passwordHash,
        tempPasswordExpiresAt: "",
      });
    }
    return data;
  } catch (error) {
    console.warn("[auth] firebase password sync error", error);
    return null;
  }
}

async function loginWithProvider(email, password) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) throw new Error("Please enter your email address.");
  if (firebaseAuthEnabled) {
    try {
      // Re-resolve client so Keep me signed in applies the right Firebase persistence.
      firebaseAuthClient = null;
      const client = await getFirebaseAuthClient();
      const credential = await client.signInWithEmailAndPassword(client.auth, cleanEmail, password);
      clearMemberSessionToken();
      ensureAccount(cleanEmail);
      // Firebase password is authoritative — never leave a sticky mustChangePassword
      // gate that requires a member session the Firebase path just cleared.
      updateAccount(cleanEmail, {
        authProvider: "Firebase Authentication",
        emailVerified: credential.user.emailVerified,
        firebaseUid: credential.user.uid,
        mustChangePassword: false,
        tempPasswordExpiresAt: "",
      });
      await syncPasswordAfterFirebaseAuth(password, "firebase_login");
      return { email: cleanEmail, verified: credential.user.emailVerified, mustChangePassword: false };
    } catch (firebaseError) {
      // Always attempt server temp/recovery password login when Firebase rejects the
      // password. Do not depend on a narrow set of error codes — Firebase has changed
      // these across releases (wrong-password vs invalid-credential, etc.).
      try {
        return await loginWithServerPassword(cleanEmail, password);
      } catch (serverError) {
        const serverMsg = String(serverError?.message || "");
        if (/method not allowed|failed to fetch|network|offline/i.test(serverMsg)) {
          throw new Error("Sign-in is taking longer than usual. Wait a moment and try again, or Message Support if it keeps happening.");
        }
        throw serverError?.message ? serverError : firebaseError;
      }
    }
  }
  try {
    return await loginWithServerPassword(cleanEmail, password);
  } catch (serverError) {
    const account = accounts()[cleanEmail];
    if (!account) throw serverError;
    if (account.passwordHash) {
      const hash = await localPasswordHash(password);
      if (hash !== account.passwordHash) throw serverError;
    }
    return { email: cleanEmail, verified: account.emailVerified, mustChangePassword: accountRequiresPasswordChange(account) };
  }
}

async function completeForcedPasswordChange(newPassword, confirmPassword) {
  if (!currentUser) throw new Error("Please log in before changing your password.");
  if (String(newPassword || "").length < 8) throw new Error("Please use a new password with at least 8 characters.");
  if (String(newPassword || "") !== String(confirmPassword || "")) {
    throw new Error("The new passwords did not match.");
  }
  const token = readMemberSessionToken();
  if (!token) throw new Error("Please log in again with your temporary password, then create a new password.");
  const response = await fetch("/api/auth/complete-forced-password-change", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ newPassword, confirmPassword }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Could not update your password.");
  writeMemberSessionToken(data.memberSessionToken || "", { persist: memberWantsPersistentSession() });
  updateAccount(currentUser, {
    mustChangePassword: false,
    serverPasswordAuth: true,
    passwordHash: await localPasswordHash(newPassword),
    tempPasswordExpiresAt: "",
  });
  // If Firebase session exists, keep it aligned with the new password.
  if (firebaseAuthEnabled) {
    try {
      const client = await getFirebaseAuthClient();
      if (client.auth.currentUser) {
        await client.updatePassword(client.auth.currentUser, newPassword);
      }
    } catch (error) {
      console.warn("Firebase password sync after forced change did not complete", error);
    }
  }
  return "Password updated. You can continue into your account.";
}

async function sendPasswordReset(email) {
  const cleanEmail = String(email || "").trim().toLowerCase();
  if (!cleanEmail) throw new Error("Please enter your email address.");
  console.info("[auth] password_reset_request", { email: cleanEmail, firebase: firebaseAuthEnabled });
  if (firebaseAuthEnabled) {
    const client = await getFirebaseAuthClient();
    const resetUrl = window.location.origin && window.location.origin !== "null"
      ? `${window.location.origin}${window.location.pathname}`
      : window.location.href.split("?")[0];
    try {
      await client.sendPasswordResetEmail(client.auth, cleanEmail, {
        url: resetUrl,
        handleCodeInApp: false,
      });
      console.info("[auth] password_reset_email_sent", { email: cleanEmail });
      return "Password reset email sent. Please check your inbox (and spam folder). The link usually stays valid for about an hour — request another if it expires.";
    } catch (error) {
      console.error("[auth] password_reset_email_failed", { email: cleanEmail, code: error?.code, message: error?.message });
      throw error;
    }
  }
  // Gated server Resend path — only used when Firebase is off and Resend+DNS are ready.
  try {
    const response = await fetch("/api/auth/request-password-reset", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: cleanEmail }),
    });
    const data = await response.json().catch(() => ({}));
    if (response.ok && data.delivery === "sent") {
      return data.message || "If that email is in Little Learner Hub, a password reset link has been sent.";
    }
  } catch (error) {
    console.warn("[auth] server_password_reset_unavailable", error);
  }
  const token = `demo-reset-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  localStorage.setItem("llhDemoResetToken", JSON.stringify({
    email: cleanEmail,
    token,
    createdAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
  }));
  console.info("[auth] password_reset_demo_token_created", { email: cleanEmail });
  return "If that email is on file, you can continue with a reset link. Check your inbox and spam folder, or Message Support if nothing arrives.";
}

async function resendVerificationEmail() {
  if (!currentUser) throw new Error("Please log in before requesting a verification email.");
  if (firebaseAuthEnabled) {
    const client = await getFirebaseAuthClient();
    if (!client.auth.currentUser) throw new Error("Please log in again before requesting verification.");
    await client.sendEmailVerification(client.auth.currentUser);
    return "Verification email sent. Please check your inbox.";
  }
  try {
    const response = await fetch("/api/auth/send-verification-email", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: currentUser }),
    });
    const data = await response.json().catch(() => ({}));
    if (response.ok && data.delivery === "sent") {
      return data.message || "Verification email sent. Please check your inbox.";
    }
  } catch (error) {
    console.warn("[auth] server_verification_email_unavailable", error);
  }
  updateAccount(currentUser, { emailVerified: false });
  return "We couldn’t send a verification email right now. Try again in a minute, or Message Support and we’ll help.";
}

async function changePassword(currentPassword, newPassword) {
  if (!currentUser) throw new Error("Please log in before changing your password.");
  if (String(newPassword || "").length < 8) throw new Error("Please use a new password with at least 8 characters.");
  if (firebaseAuthEnabled) {
    const client = await getFirebaseAuthClient();
    const user = client.auth.currentUser;
    if (!user?.email) throw new Error("Please log in again before changing your password.");
    const credential = client.EmailAuthProvider.credential(user.email, currentPassword);
    await client.reauthenticateWithCredential(user, credential);
    await client.updatePassword(user, newPassword);
    updateAccount(currentUser, {
      passwordHash: await localPasswordHash(newPassword),
      mustChangePassword: false,
      serverPasswordAuth: true,
      tempPasswordExpiresAt: "",
    });
    await syncPasswordAfterFirebaseAuth(newPassword, "settings_change_password");
    return "Password updated.";
  }
  const account = currentAccount();
  if (account?.passwordHash) {
    const currentHash = await localPasswordHash(currentPassword);
    if (currentHash !== account.passwordHash) throw new Error("The current password did not match.");
  }
  updateAccount(currentUser, {
    passwordHash: await localPasswordHash(newPassword),
    mustChangePassword: false,
    serverPasswordAuth: true,
  });
  // Keep server store aligned in demo/local modes so login after change works.
  try {
    const token = readMemberSessionToken();
    if (token) {
      await fetch("/api/auth/complete-forced-password-change", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ newPassword, confirmPassword: newPassword }),
      });
    }
  } catch { /* best-effort */ }
  return "Password updated. You’re all set — keep using your email and new password to sign in.";
}

async function confirmPasswordResetFromLink(newPassword) {
  if (String(newPassword || "").length < 8) throw new Error("Please use a password with at least 8 characters.");
  const params = new URLSearchParams(window.location.search);
  const resetToken = params.get("resetToken") || consumePendingUrlSecret("resetToken");
  if (resetToken) {
    const response = await fetch("/api/auth/password-reset/complete", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token: resetToken, newPassword, confirmPassword: newPassword }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Could not complete the password reset.");
    const email = String(data.email || "").trim().toLowerCase();
    if (email) {
      ensureAccount(email);
      updateAccount(email, {
        passwordHash: await localPasswordHash(newPassword),
        serverPasswordAuth: true,
        mustChangePassword: false,
        tempPasswordExpiresAt: "",
        emailVerified: true,
      });
    }
    return data.message || "Password reset complete. You can now log in.";
  }
  const oobCode = params.get("oobCode");
  console.info("[auth] password_reset_confirm_attempt", { hasOobCode: Boolean(oobCode), firebase: firebaseAuthEnabled });
  if (firebaseAuthEnabled && oobCode) {
    const client = await getFirebaseAuthClient();
    let resetEmail = "";
    try {
      resetEmail = String(await client.verifyPasswordResetCode(client.auth, oobCode) || "").trim().toLowerCase();
    } catch (error) {
      console.error("[auth] password_reset_link_invalid", { code: error?.code, message: error?.message });
      throw error;
    }
    await client.confirmPasswordReset(client.auth, oobCode, newPassword);
    // Sign in immediately so the new password is usable and server recovery flags clear.
    try {
      firebaseAuthClient = null;
      const liveClient = await getFirebaseAuthClient();
      await liveClient.signInWithEmailAndPassword(liveClient.auth, resetEmail, newPassword);
      ensureAccount(resetEmail);
      updateAccount(resetEmail, {
        authProvider: "Firebase Authentication",
        mustChangePassword: false,
        serverPasswordAuth: true,
        passwordHash: await localPasswordHash(newPassword),
        tempPasswordExpiresAt: "",
      });
      await syncPasswordAfterFirebaseAuth(newPassword, "firebase_password_reset");
      clearMemberSessionToken();
      console.info("[auth] password_reset_confirm_success", { email: resetEmail, synced: true });
    } catch (syncError) {
      console.warn("[auth] password_reset_post_login_sync_failed", syncError);
      // Password was still reset in Firebase — user can log in manually.
    }
    return "Password reset complete. You can now log in with your new password.";
  }
  const demoReset = readSavedJson("llhDemoResetToken", null);
  if (demoReset?.email) {
    const expiresAt = Date.parse(demoReset.expiresAt || "");
    if (Number.isFinite(expiresAt) && expiresAt < Date.now()) {
      localStorage.removeItem("llhDemoResetToken");
      throw new Error("This reset link has expired. Please request a new password reset email.");
    }
    const cleanEmail = String(demoReset.email).trim().toLowerCase();
    const passwordHash = await localPasswordHash(newPassword);
    updateAccount(cleanEmail, {
      passwordHash,
      mustChangePassword: false,
      serverPasswordAuth: true,
      tempPasswordExpiresAt: "",
    });
    localStorage.removeItem("llhDemoResetToken");
    // Persist into server JSON store so password-login works after demo reset.
    await syncPasswordAfterFirebaseAuth(newPassword, "demo_password_reset", cleanEmail);
    console.info("[auth] password_reset_demo_success", { email: cleanEmail });
    return "Password reset complete. You can now log in with your new password.";
  }
  throw new Error("This reset link is missing or expired. Please request a new password reset email.");
}

function updateAuthButtons() {
  const signIn = document.querySelector("#signinButton");
  const signUp = document.querySelector("#signupButton");
  if (!signIn || !signUp) return;
  if (currentUser || isAdminUnlocked()) {
    signIn.textContent = "Account";
    signIn.dataset.view = "settings";
    if (isAdminPreviewSimulating()) {
      signUp.textContent = `${previewAwarePlanLabel()} Preview`;
      signUp.dataset.view = isProUser() ? "billing" : "plans";
    } else if (currentUser) {
      if (isProUser()) {
        signUp.textContent = `${billingPlanLabel()} Active`;
        signUp.dataset.view = "billing";
        delete signUp.dataset.checkoutPlan;
      } else if (typeof canSeePaidUpgradeOffer === "function" && canSeePaidUpgradeOffer()) {
        const primary = freePlanUpgradePrimaryCta();
        signUp.textContent = primary.label || "Upgrade";
        if (primary.checkout) {
          signUp.dataset.checkoutPlan = primary.checkout;
          delete signUp.dataset.view;
        } else {
          delete signUp.dataset.checkoutPlan;
          signUp.dataset.view = primary.view || "plans";
        }
      } else {
        signUp.textContent = "Upgrade";
        signUp.dataset.view = "plans";
        delete signUp.dataset.checkoutPlan;
      }
    } else {
      signUp.textContent = "Sign Up";
      delete signUp.dataset.view;
    }
  } else {
    signIn.textContent = "Log in";
    delete signIn.dataset.view;
    signUp.textContent = foundingOpenForAcquisition()
      ? "Get Started — $9.99/month"
      : "Get Started — $19.99/month";
    delete signUp.dataset.view;
  }
  updateAdminNavVisibility();
  syncPlatformNavVisibility();
  updateBodyAuthClass();
  refreshAdminPreviewBadge();
  refreshFreePlanUpgradeChrome();
  // Auth state just changed (login, logout, or boot restore) — keep the
  // notification bell in sync either way (it also hides itself when logged out).
  if (typeof refreshNotificationBell === "function") {
    refreshNotificationBell();
    if (currentUser) startNotificationBellPolling();
    else if (notificationBellPollTimer) { clearInterval(notificationBellPollTimer); notificationBellPollTimer = null; }
  }
}

/** Map SPA views to platform capabilities for role/account-type guards. */
const viewCapabilityRequirements = Object.freeze({
  staff: "staff_management",
  classrooms: "classrooms",
  families: "families",
  enrollment: "enrollment",
  billing: "billing",
  subscription: "billing",
  "billing-history": "billing",
  "cancel-subscription": "billing",
});

function capabilityRequiredForView(view) {
  return viewCapabilityRequirements[resolveSidebarView(view)] || viewCapabilityRequirements[view] || "";
}

function canOpenViewForCurrentAccess(view) {
  const capability = capabilityRequiredForView(view);
  if (!capability) return true;
  return canAccessPlatformFeature(capability);
}

/**
 * Show/hide sidebar items from accountType + role capabilities.
 * No separate Director Tools section — items appear only when allowed.
 */
let whatsNewNavSyncPromise = null;
window.whatsNewNavHasNotes = null;

function setWhatsNewNavVisible(show) {
  const link = document.querySelector("#whatsNewNavLink");
  if (!link) return;
  const visible = Boolean(show) && isLoggedIn();
  link.hidden = !visible;
  link.setAttribute("aria-hidden", visible ? "false" : "true");
  if (visible) link.removeAttribute("tabindex");
  else link.setAttribute("tabindex", "-1");
}
window.setWhatsNewNavVisible = setWhatsNewNavVisible;

function syncWhatsNewNavVisibility() {
  const link = document.querySelector("#whatsNewNavLink");
  if (!link) return;
  if (!isLoggedIn()) {
    setWhatsNewNavVisible(false);
    return;
  }
  if (window.whatsNewNavHasNotes != null) {
    setWhatsNewNavVisible(window.whatsNewNavHasNotes);
    return;
  }
  setWhatsNewNavVisible(false);
  if (whatsNewNavSyncPromise) return;
  whatsNewNavSyncPromise = fetch("/api/release-notes", { cache: "no-store" })
    .then((res) => (res.ok ? res.json() : {}))
    .then((data) => {
      const notes = Array.isArray(data.releaseNotes) ? data.releaseNotes : [];
      window.whatsNewNavHasNotes = notes.length > 0;
      setWhatsNewNavVisible(window.whatsNewNavHasNotes);
    })
    .catch(() => {
      window.whatsNewNavHasNotes = false;
      setWhatsNewNavVisible(false);
    })
    .finally(() => {
      whatsNewNavSyncPromise = null;
    });
}

function syncPlatformNavVisibility() {
  const account = currentAccount();
  document.querySelectorAll("[data-nav-capability]").forEach((button) => {
    const capability = button.getAttribute("data-nav-capability");
    const permanentlyHidden = button.hasAttribute("data-nav-hidden");
    const allowed = !permanentlyHidden && (!capability || canAccessCapability(account, capability, {
      adminOverride: typeof hasAdminFullAccess === "function" && hasAdminFullAccess(),
    }));
    button.hidden = !allowed;
    button.setAttribute("aria-hidden", allowed ? "false" : "true");
    if (allowed) button.removeAttribute("tabindex");
    else button.setAttribute("tabindex", "-1");
  });
  document.querySelectorAll("#platformNav [data-nav-hidden='true']").forEach((button) => {
    button.hidden = true;
    button.setAttribute("aria-hidden", "true");
    button.setAttribute("tabindex", "-1");
  });
  syncHomeDaycareHubNavVisibility();
  syncAiGuideNavVisibility();
  syncWhatsNewNavVisibility();
  document.querySelectorAll("[data-nav-section]").forEach((section) => {
    if (section.hasAttribute("data-work-nav-root")) return;
    const hasVisibleLink = Array.from(section.querySelectorAll(".nav-link")).some((link) => !link.hidden);
    section.hidden = !hasVisibleLink;
  });
  syncCurriculumPlannerNavVisibility();
  syncWorkModeNav();
  syncUniversalQuickAdd();
  syncHdhTesterSwitcherChrome();
}

/** Testing-site work-mode nav: role-specific homes (not a shared feature dump). */
function isWorkModeNavEnabled() {
  try {
    return Boolean(
      isHomeDaycareHubTestingEnabled()
      && isLoggedIn()
      && !isFamilyHubParentMode()
    );
  } catch (_error) {
    return false;
  }
}

function workModeRole() {
  const role = typeof getUserRole === "function" ? getUserRole() : "owner";
  if (role === USER_ROLES.DIRECTOR) return "director";
  if (role === USER_ROLES.TEACHER) return "teacher";
  if (role === USER_ROLES.ASSISTANT) return "assistant";
  return "owner";
}

function workModeLandingView(role = workModeRole()) {
  if (role === "teacher" || role === "assistant") return "today";
  return "home";
}

function syncWorkModeNav() {
  const enabled = isWorkModeNavEnabled();
  const role = workModeRole();
  document.body.classList.toggle("work-mode-nav", enabled);
  document.body.dataset.workRole = enabled ? role : "";

  const workRoot = document.querySelector("[data-work-nav-root]");
  if (workRoot) workRoot.hidden = !enabled;

  document.querySelectorAll("[data-legacy-nav='true']").forEach((section) => {
    section.hidden = enabled;
    section.setAttribute("aria-hidden", enabled ? "true" : "false");
  });

  document.querySelectorAll("[data-work-nav]").forEach((button) => {
    const roles = String(button.getAttribute("data-work-roles") || "")
      .split(",")
      .map((r) => r.trim())
      .filter(Boolean);
    const show = enabled && roles.includes(role);
    button.hidden = !show;
    button.setAttribute("aria-hidden", show ? "false" : "true");
    if (show) button.removeAttribute("tabindex");
    else button.setAttribute("tabindex", "-1");
  });

  // Role-specific Children label (Owner vs Teacher vs Assistant — intentionally not symmetrical).
  document.querySelectorAll("[data-work-label-owner]").forEach((el) => {
    el.hidden = !(role === "owner" || role === "director");
  });
  document.querySelectorAll("[data-work-label-teacher]").forEach((el) => {
    el.hidden = role !== "teacher";
  });
  document.querySelectorAll("[data-work-label-assistant]").forEach((el) => {
    el.hidden = role !== "assistant";
  });

  // Testing Pro: never show upgrade CTA on testing work-mode.
  const upgradeCard = document.querySelector("#sidebarFreeUpgradeCard");
  if (upgradeCard && typeof hasTestingProEntitlement === "function" && hasTestingProEntitlement()) {
    upgradeCard.hidden = true;
  }
}

function workHubTile(options = {}) {
  const {
    view = "",
    title = "",
    detail = "",
    primary = false,
    attrs = "",
  } = options;
  const viewAttr = view ? `data-view="${escapeHtml(view)}"` : "";
  return `
    <button class="work-hub-tile${primary ? " is-primary" : ""}" type="button" ${viewAttr} ${attrs}>
      <strong>${escapeHtml(title)}</strong>
      ${detail ? `<span>${escapeHtml(detail)}</span>` : ""}
    </button>
  `;
}

function workHubShell({ eyebrow = "", title = "", subtitle = "", body = "" } = {}) {
  return `
    <section class="work-hub-page">
      <header class="work-hub-header">
        <p class="eyebrow">${escapeHtml(eyebrow)}</p>
        <h2>${escapeHtml(title)}</h2>
        ${subtitle ? `<p class="muted-copy">${escapeHtml(subtitle)}</p>` : ""}
      </header>
      <div class="work-hub-body">${body}</div>
    </section>
  `;
}

function renderOwnerHomeDashboard() {
  const homeSection = document.querySelector("#view-home");
  if (!homeSection) return;
  homeSection.classList.remove("landing-home");
  homeSection.classList.add("user-dashboard-view", "work-owner-home");

  const records = childRecords();
  const today = typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10);
  const children = records.children || [];
  const attendance = (records.attendance || []).filter((a) => a.date === today);
  const checkedIn = attendance.filter((a) => {
    const status = String(a.status || "").toLowerCase();
    return status !== "absent" && (a.dropoff || status === "present") && !a.pickup;
  }).length;
  const present = attendance.filter((a) => String(a.status || "").toLowerCase() !== "absent").length;
  const mealsToday = (records.meals || []).filter((m) => m.date === today).length;
  const obsRecent = [...(records.observations || [])]
    .filter((obs) => String(obs.date || "") === today || !obs.date)
    .sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")))
    .slice(0, 4);
  const docsPending = (records.documents || []).filter((d) => {
    const status = String(d.status || d.statusLabel || "").toLowerCase();
    return d.shareWithFamily && !d.signedAt && /need|notif|assign|action|draft|request/.test(status);
  }).length;
  const ratio = typeof classroomRatioSnapshot === "function" ? classroomRatioSnapshot(records, today) : { checkedIn, roster: children.length, byRoom: {} };
  const roomRatioText = Object.keys(ratio.byRoom || {}).length
    ? Object.entries(ratio.byRoom).map(([room, count]) => `${room}: ${count}`).slice(0, 3).join(" · ")
    : "No rooms checked in yet";
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
  const name = accountDisplayFirstName(currentAccount());
  const program = getProgramSettings()?.programName || "your program";
  const childById = Object.fromEntries(children.map((c) => [c.id, c]));
  const attention = typeof buildActionOnlyAttentionCards === "function" ? buildActionOnlyAttentionCards() : [];
  const attentionHtml = attention.length
    ? `<section class="work-hub-section">
        <h3>Needs attention</h3>
        <div class="work-hub-grid">
          ${attention.map((card) => workHubTile(card)).join("")}
        </div>
      </section>`
    : "";
  const lessonHtml = typeof todayAssignedLessonCardHtml === "function" ? todayAssignedLessonCardHtml() : "";

  homeSection.innerHTML = workHubShell({
    eyebrow: "Home",
    title: `${greeting}, ${name}`,
    subtitle: `${program} · ${new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })}`,
    body: `
      <div class="work-pulse-grid" aria-label="Today at a glance">
        <article class="work-pulse-card"><em>Checked in</em><strong>${checkedIn}</strong><span>of ${children.length} children</span></article>
        <article class="work-pulse-card"><em>Classroom count</em><strong>${ratio.checkedIn}</strong><span>${escapeHtml(roomRatioText)}</span></article>
        <article class="work-pulse-card"><em>Meals logged</em><strong>${mealsToday}</strong><span>entries today</span></article>
        ${docsPending ? `<article class="work-pulse-card"><em>Forms awaiting parent</em><strong>${docsPending}</strong><span>follow up</span></article>` : `<article class="work-pulse-card"><em>Attendance logged</em><strong>${present}</strong><span>present / recorded</span></article>`}
      </div>

      <section class="work-hub-section">
        <h3>Next actions</h3>
        <div class="work-hub-grid">
          ${workHubTile({ view: "child-tools-daily-logs", title: "Daily Logs", detail: checkedIn ? "Continue the care day" : "Check children in", primary: true })}
          ${workHubTile({ view: "classroom", title: "Classroom", detail: "Lessons, meals, schedule" })}
          ${workHubTile({ view: "children", title: "Children", detail: "Profiles & files" })}
          ${workHubTile({ view: "families", title: "Families", detail: "Messages & Family Hub" })}
        </div>
      </section>

      ${attentionHtml}
      ${lessonHtml}

      ${obsRecent.length ? `<section class="work-hub-section">
        <div class="work-hub-section-head">
          <h3>Recent observations</h3>
          <button class="ghost-button" type="button" data-view="children">Open Children</button>
        </div>
        <ul class="work-simple-list">${obsRecent.map((obs) => {
            const child = childById[obs.childId];
            return `<li><strong>${escapeHtml(child?.name || "Child")}</strong><span>${escapeHtml((obs.text || obs.note || obs.summary || "Observation").slice(0, 100))}</span><small>${escapeHtml(obs.date || "")}</small></li>`;
          }).join("")}</ul>
      </section>` : ""}
    `,
  });
}

