function toggleUniversalQuickAdd(force) {
  const sheet = document.querySelector("[data-work-quick-sheet]");
  const toggle = document.querySelector("[data-work-quick-toggle]");
  if (!sheet || !toggle) return;
  const open = typeof force === "boolean" ? force : sheet.hasAttribute("hidden");
  if (open) {
    sheet.removeAttribute("hidden");
    toggle.setAttribute("aria-expanded", "true");
    document.body.classList.add("work-quick-add-open");
  } else {
    sheet.setAttribute("hidden", "");
    toggle.setAttribute("aria-expanded", "false");
    document.body.classList.remove("work-quick-add-open");
  }
}

function syncHomeDaycareHubNavVisibility() {
  const enabled = isHomeDaycareHubTestingEnabled() && isLoggedIn() && staffMaySeeHdhView("home-daycare-hub");
  document.body.classList.toggle("hdh-testing", isHomeDaycareHubTestingEnabled());
  document.querySelectorAll("[data-nav-hdh-testing='true']").forEach((button) => {
    button.hidden = !enabled;
    button.setAttribute("aria-hidden", enabled ? "false" : "true");
    if (enabled) button.removeAttribute("tabindex");
    else button.setAttribute("tabindex", "-1");
  });
  if (!isHomeDaycareHubTestingEnabled() || !isLoggedIn()) return;
  const visibility = currentAccountHdhVisibility();
  if (!visibility) return;
  document.querySelectorAll("#platformNav .nav-link[data-view]").forEach((button) => {
    if (button.hasAttribute("data-nav-hidden")) return;
    const view = button.dataset.view;
    if (!staffMaySeeHdhView(view)) {
      button.hidden = true;
      button.setAttribute("aria-hidden", "true");
      button.setAttribute("tabindex", "-1");
    }
  });
}

function isPlatformNavActive(buttonView, requestedView, resolvedView) {
  if (!buttonView) return false;
  if (buttonView === requestedView) return true;
  // Dedicated alias links (Daily Logs, Behavior & Support) should not also
  // highlight their resolved destination (Child Profiles / Resources).
  if (requestedView !== resolvedView && buttonView === resolvedView) {
    const aliasHasOwnNav = Boolean(
      childToolTabFromView(requestedView)
      || requestedView === "behavior-support"
      || requestedView === "membership"
    );
    if (aliasHasOwnNav) return false;
  }
  if (buttonView === resolvedView) return true;
  if (buttonView === "resources" && ["resources", "support-center", "menus", "observations"].includes(resolvedView) && requestedView !== "behavior-support") {
    return true;
  }
  // Billing and Staff have their own sidebar items — do not also mark Settings active.
  if (
    buttonView === "settings"
    && ["settings", "account", "program-settings", "forms-settings", "curriculum-settings", "subscription", "billing-history", "contact", "faq", "plans", "upgrade", "cancel-subscription"].includes(resolvedView)
  ) {
    return true;
  }
  if (buttonView === "billing" && ["billing", "subscription", "billing-history", "cancel-subscription"].includes(resolvedView)) {
    return true;
  }
  if (buttonView === "calendar" && resolvedView === "planner") return true;
  if (buttonView === "ai" && resolvedView === "generators") return true;
  if (buttonView === "director-center" && resolvedView === "director-center") return true;
  if (buttonView === "home-daycare-hub" && resolvedView === "home-daycare-hub") return true;
  if (buttonView === "home" && resolvedView === "home") return true;
  return false;
}

function installPromptState() {
  if (currentUser) return currentAccount()?.installPrompt || {};
  return readSavedJson("llhGuestInstallPrompt", {});
}

function saveInstallPromptState(updates = {}) {
  const nextState = { ...installPromptState(), ...updates };
  if (currentUser) {
    updateAccount(currentUser, { installPrompt: nextState });
  } else {
    localStorage.setItem("llhGuestInstallPrompt", JSON.stringify(nextState));
  }
  return nextState;
}

function isIosDevice() {
  return /iphone|ipad|ipod/i.test(window.navigator.userAgent) || (window.navigator.platform === "MacIntel" && window.navigator.maxTouchPoints > 1);
}

function isAndroidDevice() {
  return /android/i.test(window.navigator.userAgent);
}

function isSafariBrowser() {
  const agent = window.navigator.userAgent || "";
  return /safari/i.test(agent) && !/chrome|android|crios|fxios|edgios/i.test(agent);
}

function isStandaloneDisplayMode() {
  return window.matchMedia?.("(display-mode: standalone)")?.matches || window.navigator.standalone === true;
}

function canTriggerInstallPrompt() {
  return Boolean(deferredInstallPrompt && typeof deferredInstallPrompt.prompt === "function");
}

function shouldShowInstallPromptCard() {
  if (isStandaloneDisplayMode()) return false;
  const state = installPromptState();
  if (state.installedAt) return false;
  if (state.deferredUntil && new Date(state.deferredUntil).getTime() > Date.now()) return false;
  // First-login overlay budget: never stack install with boot verification or Free upgrade chrome.
  if (typeof requiresVerifiedAppBoot === "function" && requiresVerifiedAppBoot() && !isAppBootInteractive()) return false;
  if (document.body.classList.contains("app-boot-verifying")) return false;
  if (typeof canSeePaidUpgradeOffer === "function" && canSeePaidUpgradeOffer()) {
    if (!isFreeWelcomeCardDismissed()) return false;
    if (!isFreePlanReminderDismissed()) return false;
  }
  return true;
}

