function refreshInstallSurfaces() {
  const activeView = document.querySelector(".active-view")?.id.replace("view-", "") || "";
  syncPlatformInstallCard();
  if (activeView === "home") renderHome();
  if (activeView === "account") renderAccountPage();
  if (activeView === "settings") renderSettingsHubPage();
  updateInstallSettingsPanel();
}

function updateInstallSettingsPanel() {
  const description = document.querySelector("#accountInstallDescription");
  const installButton = document.querySelector("#accountInstallAppButton");
  const instructionsButton = document.querySelector("#accountInstallInstructionsButton");
  if (!description || !installButton || !instructionsButton) return;
  if (isStandaloneDisplayMode()) {
    description.textContent = "Little Learner Hub is already installed on this device and ready to use like an app.";
    installButton.textContent = "Installed";
    installButton.disabled = true;
    instructionsButton.textContent = "View Instructions";
    return;
  }
  description.textContent = canTriggerInstallPrompt()
    ? "Install Little Learner Hub for faster access, app-style launching, and a smoother daily workflow."
    : "Add Little Learner Hub to your Home Screen for faster access. If your browser does not show an install prompt, we'll walk you through the steps.";
  installButton.textContent = canTriggerInstallPrompt() ? "Install App" : "Add to Home Screen";
  installButton.disabled = false;
  instructionsButton.textContent = "View Instructions";
}

function closeInstallAppModal() {
  const modal = document.querySelector("#installAppModal");
  if (!modal) return;
  modal.classList.remove("open");
  modal.setAttribute("aria-hidden", "true");
  document.body.classList.remove("auth-modal-open");
}

function openInstallAppModal({ source = "settings", forceInstructions = false } = {}) {
  const modal = document.querySelector("#installAppModal");
  const body = document.querySelector("#installAppBody");
  const primaryButton = document.querySelector("#installAppPrimaryButton");
  const secondaryButton = document.querySelector("#installAppSecondaryButton");
  if (!modal || !body || !primaryButton || !secondaryButton) return;
  installModalSource = source;
  body.innerHTML = installInstructionsMarkup();
  primaryButton.textContent = canTriggerInstallPrompt() && !forceInstructions ? "Add to Home Screen" : "Got It";
  primaryButton.dataset.installMode = canTriggerInstallPrompt() && !forceInstructions ? "prompt" : "close";
  const deferrable = source === "dashboard" || source === "calendar" || source === "settings-prompt";
  secondaryButton.textContent = deferrable ? "Maybe Later" : "Close";
  secondaryButton.dataset.installMode = deferrable ? "later" : "close";
  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
  document.body.classList.add("auth-modal-open");
}

async function promptInstallFlow({ source = "settings", forceInstructions = false } = {}) {
  if (!forceInstructions && canTriggerInstallPrompt()) {
    const promptEvent = deferredInstallPrompt;
    deferredInstallPrompt = null;
    await promptEvent.prompt();
    const choice = await promptEvent.userChoice;
    if (choice?.outcome === "accepted") {
      saveInstallPromptState({ installedAt: new Date().toISOString(), deferredUntil: "", dismissedAt: "" });
      closeInstallAppModal();
      refreshInstallSurfaces();
      updateInstallSettingsPanel();
      return;
    }
  }
  openInstallAppModal({ source, forceInstructions });
  updateInstallSettingsPanel();
}

function deferInstallPrompt() {
  const deferredUntil = new Date(Date.now() + installPromptDeferDays * 24 * 60 * 60 * 1000).toISOString();
  saveInstallPromptState({
    dismissedAt: new Date().toISOString(),
    deferredUntil,
  });
  closeInstallAppModal();
  refreshInstallSurfaces();
  updateInstallSettingsPanel();
}

// ─── Member Messaging Center + Push Notifications ──────────────────────────
// In-app messages/notifications are always the source of truth (fetched from
// the server on every refresh). Push is a best-effort layer on top: if the
// browser doesn't support it, the user declined, or a send fails, the bell
// and Messages tab keep working exactly the same.

let notificationBellState = { items: [], unreadCount: 0, open: false, loaded: false };
let notificationBellLoadPromise = null;
let librarySearchRemountTimer = null;
let messagesViewState = { tab: "conversation", conversation: [], inbox: [], reply: "", loaded: false };
let pushUiState = { preference: null, deviceCount: 0, publicKey: "", supportedOnServer: false, busy: false, lastMessage: "" };
let notificationBellPollTimer = null;

async function messagingAuthHeaders() {
  if (!isLoggedIn() || !canUseLaunchBackend()) return null;
  return staffAuthHeaders();
}

function notificationTypeIcon(type) {
  switch (type) {
    case "message": return "💬";
    case "announcement": return "📣";
    case "feature_update": return "🚀";
    case "support_reply": return "🛟";
    case "bug_update": return "🛠️";
    default: return "🔔";
  }
}

function isAdminOnlyBellNotification(type) {
  const key = String(type || "").trim().toLowerCase();
  return key.startsWith("admin_") || key === "admin_message_reply";
}

function messagingRelativeTime(iso) {
  const then = new Date(iso || "").getTime();
  if (!Number.isFinite(then)) return "";
  const diffMs = Date.now() - then;
  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (diffMs < minute) return "Just now";
  if (diffMs < hour) return `${Math.max(1, Math.round(diffMs / minute))}m ago`;
  if (diffMs < day) return `${Math.round(diffMs / hour)}h ago`;
  if (diffMs < 7 * day) return `${Math.round(diffMs / day)}d ago`;
  return new Date(then).toLocaleDateString();
}

async function fetchNotificationsFromBackend() {
  const headers = await messagingAuthHeaders();
  if (!headers) return { notifications: [], unreadCount: 0 };
  try {
    const res = await fetch("/api/notifications?limit=50", { headers, cache: "no-store" });
    if (!res.ok) return { notifications: [], unreadCount: 0 };
    return await res.json();
  } catch (error) {
    console.warn("Could not load notifications", error);
    return { notifications: [], unreadCount: 0 };
  }
}

async function refreshNotificationBell() {
  if (!isLoggedIn()) {
    notificationBellLoadPromise = null;
    notificationBellState = { items: [], unreadCount: 0, open: notificationBellState.open, loaded: true };
    renderNotificationBell();
    return;
  }
  if (notificationBellLoadPromise) return notificationBellLoadPromise;
  notificationBellLoadPromise = (async () => {
    const previousUnread = Number(notificationBellState.unreadCount) || 0;
    const data = await fetchNotificationsFromBackend();
    // Defense in depth: never show owner/admin-only alerts in a normal member bell.
    const rawItems = Array.isArray(data.notifications) ? data.notifications : [];
    const items = isSignedInPlatformOwner() || isAdminUnlocked()
      ? rawItems
      : rawItems.filter((item) => !isAdminOnlyBellNotification(item?.type));
    notificationBellState.items = items;
    notificationBellState.unreadCount = items.filter((item) => !item.read).length;
    notificationBellState.loaded = true;
    renderNotificationBell();
    // When a new notification arrives while Messages is open, refresh the thread
    // so Leah's reply appears without a manual page reload.
    if (
      notificationBellState.unreadCount > previousUnread
      && document.querySelector("#view-messages.active-view")
      && typeof window.refreshMyMessagesCenterLive === "function"
    ) {
      window.refreshMyMessagesCenterLive().catch(() => {});
    }
  })().finally(() => {
    notificationBellLoadPromise = null;
  });
  return notificationBellLoadPromise;
}

function notificationBellIsMobileViewport() {
  return typeof window.matchMedia === "function"
    && window.matchMedia("(max-width: 640px)").matches;
}

function clearNotificationBellPanelInlineStyles(panel) {
  if (!panel) return;
  [
    "position", "top", "left", "right", "width", "maxWidth", "maxHeight", "margin", "zIndex",
  ].forEach((prop) => {
    panel.style[prop] = "";
  });
}

function readSafeAreaInset(edge = "bottom") {
  const probe = document.createElement("div");
  probe.setAttribute("aria-hidden", "true");
  probe.style.cssText = `position:fixed;${edge}:0;width:0;height:0;padding-${edge}:env(safe-area-inset-${edge},0px);visibility:hidden;pointer-events:none;`;
  document.body.appendChild(probe);
  const value = edge === "bottom" || edge === "top"
    ? probe.getBoundingClientRect().height
    : probe.getBoundingClientRect().width;
  probe.remove();
  return Number.isFinite(value) ? value : 0;
}

function notificationBellBottomReserve() {
  let reserve = 12 + readSafeAreaInset("bottom");
  [
    "[data-admin-preview-badge]",
    ".admin-mobile-bottom-nav",
    ".admin-bottom-nav",
    "[data-admin-mobile-nav]",
  ].forEach((selector) => {
    const el = document.querySelector(selector);
    if (!el || el.hidden) return;
    const style = getComputedStyle(el);
    if (style.display === "none" || style.visibility === "hidden") return;
    const rect = el.getBoundingClientRect();
    if (rect.height > 0 && rect.top < window.innerHeight && rect.bottom > window.innerHeight - 120) {
      reserve = Math.max(reserve, Math.round(window.innerHeight - rect.top) + 12);
    }
  });
  return reserve;
}

function syncNotificationBellPortal(open) {
  const wrap = document.querySelector("#notificationBellWrap");
  const panel = document.querySelector("#notificationBellPanel");
  const backdrop = document.querySelector("#notificationBellBackdrop");
  if (!wrap || !panel || !backdrop) return { panel, backdrop };
  const mobile = notificationBellIsMobileViewport();
  if (open && mobile) {
    // Escape the topbar stacking context so Admin mode / bottom chrome cannot cover the panel.
    if (backdrop.parentElement !== document.body) document.body.appendChild(backdrop);
    if (panel.parentElement !== document.body) document.body.appendChild(panel);
  } else {
    if (panel.parentElement !== wrap) wrap.appendChild(panel);
    if (backdrop.parentElement !== wrap) wrap.insertBefore(backdrop, wrap.firstChild);
  }
  return { panel, backdrop };
}

function positionNotificationBellPanel() {
  const wrap = document.querySelector("#notificationBellWrap");
  const bell = document.querySelector("#notificationBellBtn");
  const open = Boolean(notificationBellState.open && isLoggedIn());
  const mobile = notificationBellIsMobileViewport();
  document.body.classList.toggle("notification-bell-open", open && mobile);
  const { panel, backdrop } = syncNotificationBellPortal(open);
  if (backdrop) {
    backdrop.hidden = !open || !mobile;
    backdrop.setAttribute("aria-hidden", backdrop.hidden ? "true" : "false");
  }
  if (!panel || !open || !bell) {
    clearNotificationBellPanelInlineStyles(panel);
    if (wrap) wrap.dataset.portalOpen = "false";
    return;
  }

  const sidePad = 12;
  const gap = 8;
  const safeTop = readSafeAreaInset("top");
  const bellRect = bell.getBoundingClientRect();
  // Anchor under the bell only — do not push below the Early Supporter/upgrade
  // card. The list scrolls internally so Open Messages stays on-screen.
  const top = Math.max(sidePad + safeTop, bellRect.bottom + gap);
  const maxPanelWidth = mobile ? 420 : 360;
  const width = Math.min(maxPanelWidth, Math.max(240, window.innerWidth - sidePad * 2));
  let left;
  if (mobile) {
    left = Math.max(sidePad, Math.round((window.innerWidth - width) / 2));
  } else {
    // Align under the bell, but keep the panel inside the main column so it
    // never slides under the desktop sidebar.
    const main = document.querySelector(".main");
    const mainLeft = main ? Math.round(main.getBoundingClientRect().left) + sidePad : sidePad;
    left = Math.round(bellRect.right - width);
    left = Math.min(left, window.innerWidth - sidePad - width);
    left = Math.max(mainLeft, left);
  }
  const bottomPad = mobile ? notificationBellBottomReserve() : 24;
  const maxHeight = Math.max(200, window.innerHeight - top - bottomPad);

  panel.style.position = "fixed";
  panel.style.top = `${Math.round(top)}px`;
  panel.style.left = `${left}px`;
  panel.style.right = "auto";
  panel.style.width = `${width}px`;
  panel.style.maxWidth = `calc(100vw - ${sidePad * 2}px)`;
  panel.style.maxHeight = `${Math.round(maxHeight)}px`;
  panel.style.margin = "0";
  panel.style.zIndex = mobile ? "1260" : "260";
  if (backdrop && mobile) {
    backdrop.style.position = "fixed";
    backdrop.style.inset = "0";
    backdrop.style.zIndex = "1250";
  }
  if (wrap) wrap.dataset.portalOpen = mobile ? "true" : "false";
}

function renderNotificationBell() {
  const wrap = document.querySelector("#notificationBellWrap");
  if (wrap) wrap.hidden = !isLoggedIn();
  const supportBtn = document.querySelector("#messageSupportBtn");
  if (supportBtn) {
    supportBtn.hidden = !isLoggedIn();
    if (isLoggedIn()) {
      supportBtn.textContent = (isLinkedProgramStaffAccount() || isIndependentHdhTesterAccount())
        ? "Message Leah"
        : "Message Support";
    }
  }
  const count = notificationBellState.unreadCount;
  const badgeText = count > 99 ? "99+" : String(count);
  [document.querySelector("#notificationBellBadge"), document.querySelector("#messagesNavBadge")].forEach((el) => {
    if (!el) return;
    el.hidden = count <= 0;
    el.textContent = badgeText;
  });
  const bellBtn = document.querySelector("#notificationBellBtn");
  if (bellBtn) bellBtn.setAttribute("aria-expanded", String(notificationBellState.open));
  const panel = document.querySelector("#notificationBellPanel");
  if (panel) panel.hidden = !notificationBellState.open;
  const list = document.querySelector("#notificationBellList");
  if (!list) {
    positionNotificationBellPanel();
    return;
  }
  if (!notificationBellState.items.length) {
    list.innerHTML = `<p class="notification-empty">No notifications yet. New messages, support replies, announcements, and feature updates will show up here.</p>`;
  } else {
    list.innerHTML = notificationBellState.items.slice(0, 20).map((n) => `
      <button type="button" class="notification-bell-item${n.read ? "" : " unread"}" data-notification-id="${escapeHtml(n.id)}" data-notification-conversation="${escapeHtml(n.conversationEmail || "")}">
        <span class="notification-item-icon" aria-hidden="true">${notificationTypeIcon(n.type)}</span>
        <span class="notification-item-body">
          <strong>${escapeHtml(n.title || "Little Learner Hub")}</strong>
          <span>${escapeHtml(n.preview || "")}</span>
          <small>${escapeHtml(messagingRelativeTime(n.createdAt))}</small>
        </span>
      </button>
    `).join("");
  }
  positionNotificationBellPanel();
}

function toggleNotificationBellPanel(forceOpen) {
  const willOpen = typeof forceOpen === "boolean" ? forceOpen : !notificationBellState.open;
  if (willOpen && !notificationBellState.open) {
    notificationBellReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : document.querySelector("#notificationBellBtn");
  }
  notificationBellState.open = willOpen;
  renderNotificationBell();
  if (notificationBellState.open) {
    refreshNotificationBell().finally(() => positionNotificationBellPanel());
    requestAnimationFrame(() => positionNotificationBellPanel());
  } else {
    positionNotificationBellPanel();
    const returnFocus = notificationBellReturnFocus;
    notificationBellReturnFocus = null;
    restoreLlhFocus(returnFocus || document.querySelector("#notificationBellBtn"));
  }
}

async function markNotificationRead({ id, conversationEmail, all } = {}) {
  const headers = await messagingAuthHeaders();
  if (!headers) return;
  try {
    const body = {};
    if (all) body.all = true;
    else if (conversationEmail) body.conversationEmail = conversationEmail;
    else if (id) body.notificationIds = [id];
    await fetch("/api/messages/mark-read", { method: "POST", headers, body: JSON.stringify(body) });
  } catch (error) {
    console.warn("Could not mark notification read", error);
  }
  await refreshNotificationBell();
}
window.markNotificationRead = markNotificationRead;

function startNotificationBellPolling() {
  if (notificationBellPollTimer) clearInterval(notificationBellPollTimer);
  notificationBellPollTimer = setInterval(() => {
    if (isLoggedIn() && document.visibilityState === "visible") refreshNotificationBell();
  }, 45000);
}

