function resourcePrintableHtml(resource, options = {}) {
  const mode = options.mode || "screen";
  if (
    (canDownloadLessonWorkspacePlan(resource) || resource._curriculumManaged)
    && resource.category === "Lesson Plans"
    && resource._curriculumLessonPlan
  ) {
    return lessonPlanPrintVariantHtml(resource, options);
  }
  if (resource._curriculumManaged && resource.category === "Activity Center") {
    return `<article class="printable-resource-page curriculum-activity-viewer">${structuredCurriculumActivityHtml(resource)}</article>`;
  }
  const text = resourceDocumentText(resource);
  const headingPattern = /^(Short Description|What Is Included|Who It Is For|How To Use It|Materials \/ Information Needed|ELG \/ Early Learning Standard Connections|Full Resource Content|Weekly Lesson Plan|Weekly Overview|Age Group Teaching Approach|Learning Objectives|Weekly Learning Objectives|Complete Materials List|Materials|Vocabulary|Vocabulary Words|Teacher Language Guide|Questions to Ask Children|Monday Through Friday|Monday — Introduce and Explore|Monday — Introduce the Theme|Tuesday — Songs and Vocabulary|Tuesday — Build Vocabulary and Concepts|Wednesday — Hands-On Exploration|Wednesday — Hands-On .+ Practice|Thursday — Art and Movement|Thursday — Creative Expression and Child Choice|Friday — Review and Share|Friday — Review, Document, and Connect Home|Art Activity|Sensory Activity|Fine Motor Activity|Gross Motor Activity|Social-Emotional Connection|Adaptations for Different Abilities|Extensions|Assessment and Observation Notes|Family Connection Idea|Related Activities|Differentiation and Supports|Child Support Connection|Provider Reflection|Provider Notes|Observation Resource|Professional Observation Wording|What to Look For|Learning Standard Category|Evidence To Add|Next Steps|Editable Note|Follow-Up Planning|Purpose|Provider Instructions|Details \/ Notes|Weekly Daycare Menu|Shopping List|Provider Reminder|Setup|Steps|Learning Objective|Extension|Teacher Directions|Child Directions|Activity Ideas|Learning Goal|Provider Note|Printable Planning Notes|Daily Notes|Printable Observation Record|Additional Write-In Space|Checklist|Menu Notes|Shopping Notes|Activity Prep Sheet|Printable Resource|Printable Type|Theme \/ Skill|Printable Page|Tracing Practice|Warm-Up Paths|Letter And Word Tracing|Portfolio Work Sample|Printable Picture Space|Independent Practice|Count And Show|Shape Builder|Child Work Space|Coloring Page|Picture Checklist|Color Key|Talk About It|Alphabet Practice Page|Find The Letter|Trace The Letter|Beginning Sound Words|Number Practice Page|Trace The Number|Count And Mark|Compare|Shape Practice Page|Trace The Shapes|Shape Hunt|Teacher Check|Name Writing Page|My Name|Trace My Name|Try My Name|Name Hunt|Cutting Practice Page|Provider Safety Check|Cutting Lines|Cut And Sort|Teacher Note|Matching Activity Page|Draw Lines To Match|Match Here|Make Your Own Match|Seasonal Worksheet Page|Weather Check|Seasonal Words|I Notice|Count And Color|Seasonal Work Sample|Holiday Worksheet Page|Holiday Vocabulary|Trace And Write|Count The Holiday Items|Teacher Notes|Printable Worksheet Page|Try It|Reflection \/ Teacher Note)$/;
  const blocks = text.split(/\n{2,}/).map((block) => block.trim()).filter(Boolean);
  const content = blocks.map((block, index) => {
    const lines = block.split("\n").map((line) => line.trimEnd()).filter((line) => line.length);
    const first = lines[0] || "";
    const allCapsHeading = first.length >= 8 && first === first.toUpperCase() && /^[A-Z0-9][A-Z0-9 &'./():-]+$/.test(first) && !first.includes("___");
    if (index === 0 || first === "Little Learner Hub") {
      return `<section class="print-section print-cover">${printableLinesHtml(lines)}</section>`;
    }
    if ((headingPattern.test(first) || allCapsHeading) && lines.length > 1) {
      return `<section class="print-section"><h3>${escapeHtml(first)}</h3>${printableLinesHtml(lines.slice(1))}</section>`;
    }
    return `<section class="print-section">${printableLinesHtml(lines)}</section>`;
  }).join("");
  const resourcesHtml = lessonPlanAttachedResourcesHtml(resource);
  const copyrightHtml = typeof globalThis !== "undefined" && globalThis.LlhCopyright?.noticeBlockHtml
    ? globalThis.LlhCopyright.noticeBlockHtml("llh-copyright-block printable-copyright-footer")
    : `<footer class="llh-copyright-block printable-copyright-footer" aria-label="Copyright"><p class="llh-copyright-notice">${escapeHtml(llhCopyrightText())}</p></footer>`;
  const trialMark = options.trialWatermark
    ? `<p class="trial-curriculum-watermark-print" data-trial-curriculum-watermark="true">${escapeHtml(options.trialWatermark)}</p>`
    : "";
  return `<article class="printable-resource-page">${trialMark}${printableCartoonPreviewHtml(resource)}${content}${printableQualityCheckHtml(resource, text)}${resourcesHtml}${copyrightHtml}</article>`;
}

function lessonPlanAttachedResourcesHtml(resource) {
  if (resource.category !== "Lesson Plans") return "";
  const override = resource.lessonPlanOverride || lessonPlanOverrideFor(resource.id) || null;
  let attachedResources = Array.isArray(override?.resources) ? override.resources : [];
  if (!attachedResources.length && resource._curriculumManaged) {
    attachedResources = Array.isArray(resource._curriculumAttachedResources)
      ? resource._curriculumAttachedResources
      : [];
  }
  if (!attachedResources.length) return "";

  // Group by category and sort within each group
  const grouped = {};
  attachedResources.forEach((r) => { (grouped[r.category] = grouped[r.category] || []).push(r); });
  Object.values(grouped).forEach((arr) => arr.sort((a, b) => a.order - b.order));

  const categorySections = Object.entries(grouped).map(([cat, items]) => {
    const itemsHtml = items.map((r) => {
      const isImage = r.mimeType && r.mimeType.startsWith("image/");
      const isPdf = r.mimeType === "application/pdf";
      const isExternal = r.url && (r.url.startsWith("http") || r.url.startsWith("data:"));
      return `
        <div class="lp-resource-viewer-item">
          ${isImage && r.url ? `<img class="lp-resource-viewer-img" src="${escapeHtml(r.url)}" alt="${escapeHtml(r.title)}" />` : ""}
          <div class="lp-resource-viewer-meta">
            <strong>${escapeHtml(r.title)}</strong>
            ${isPdf || isExternal ? `<a class="ghost-button lp-resource-open-btn" href="${escapeHtml(r.url)}" target="_blank" rel="noopener noreferrer">${isPdf ? "Open PDF" : "Open Resource"}</a>` : ""}
          </div>
        </div>
      `;
    }).join("");
    return `
      <details class="lp-resource-category-viewer" open>
        <summary><strong>${escapeHtml(cat)}</strong> <span class="lp-resource-count">(${items.length})</span></summary>
        <div class="lp-resource-viewer-grid">${itemsHtml}</div>
      </details>
    `;
  }).join("");

  return `
    <section class="print-section lp-resources-section no-print-break">
      <h3>Lesson Resources</h3>
      <p>Expand a category to view, print, or open attached resources for this lesson plan.</p>
      ${categorySections}
    </section>
  `;
}

async function fetchAuthorizedCurriculumLessonPlan(planId) {
  const targetId = String(planId || "").trim();
  if (!targetId || !canUseLaunchBackend()) {
    return { ok: false, reason: !targetId ? "missing-id" : "backend-unavailable", lessonPlan: null };
  }
  const cacheKey = `plan:${targetId}`;
  if (curriculumAuthorizedContentCache.has(cacheKey)) {
    return { ok: true, reason: "cache", lessonPlan: curriculumAuthorizedContentCache.get(cacheKey) };
  }
  const authHeaders = typeof firebaseAuthHeaders === "function" ? await firebaseAuthHeaders().catch(() => null) : null;
  const headers = {
    ...(await siteContentRequestHeaders()),
    ...(authHeaders && typeof authHeaders === "object" ? authHeaders : {}),
  };
  const response = await fetch(`${curriculumAccessConfig.lessonPlanEndpoint}/${encodeURIComponent(targetId)}`, {
    headers,
    cache: "no-store",
  });
  if (!response.ok) {
    return { ok: false, reason: response.status === 403 ? "forbidden" : "fetch-failed", lessonPlan: null, status: response.status };
  }
  const data = await response.json().catch(() => ({}));
  const lessonPlan = data?.lessonPlan || null;
  if (!lessonPlan) return { ok: false, reason: "empty", lessonPlan: null, status: response.status };
  curriculumAuthorizedContentCache.set(cacheKey, lessonPlan);
  return { ok: true, reason: "ok", lessonPlan };
}

async function withHydratedCurriculumLessonContent(resource) {
  if (!resource?._curriculumManaged || resource.category !== "Lesson Plans") {
    return { resource, hydrated: true, reason: "not-managed" };
  }
  if (hasAdminFullAccess()) return { resource, hydrated: true, reason: "admin" };
  const existingDays = resource._curriculumLessonPlan?.dailyPlans || {};
  const hasFullDays = Object.values(existingDays).some((day) => Array.isArray(day?.items) && day.items.length);
  if (hasFullDays) return { resource, hydrated: true, reason: "already-full" };
  // Library browse payloads are intentionally slim (no dailyPlans). Fetch full
  // content on open for any plan the member can access.
  const canOpenFull = canAccess(resource) || (resource.plan === "Pro" && isProUser());
  if (!canOpenFull) return { resource, hydrated: true, reason: "not-authorized" };
  const result = await fetchAuthorizedCurriculumLessonPlan(resource.id);
  if (!result.ok || !result.lessonPlan) {
    return { resource, hydrated: false, reason: result.reason || "fetch-failed", status: result.status };
  }
  const fullPlan = result.lessonPlan;
  return {
    resource: {
      ...resource,
      weeklyOverview: fullPlan.weeklyOverview || resource.weeklyOverview,
      materials: fullPlan.weeklyMaterials || resource.materials,
      description: fullPlan.weeklyOverview || resource.description,
      theme: fullPlan.theme || resource.theme,
      _curriculumLessonPlan: fullPlan,
      _curriculumResourceIds: curriculumAsStringArray(fullPlan.resourceIds),
      customContent: buildLessonPlanTextFromCurriculum(fullPlan),
    },
    hydrated: true,
    reason: "authorized",
  };
}

async function fetchAuthorizedCurriculumActivity(activityId) {
  const targetId = String(activityId || "").trim();
  if (!targetId || !canUseLaunchBackend()) return null;
  const cacheKey = `activity:${targetId}`;
  if (curriculumAuthorizedContentCache.has(cacheKey)) return curriculumAuthorizedContentCache.get(cacheKey);
  const authHeaders = typeof firebaseAuthHeaders === "function" ? await firebaseAuthHeaders().catch(() => null) : null;
  const headers = {
    ...(await siteContentRequestHeaders()),
    ...(authHeaders && typeof authHeaders === "object" ? authHeaders : {}),
  };
  const response = await fetch(`${curriculumAccessConfig.activityEndpoint}/${encodeURIComponent(targetId)}`, {
    headers,
    cache: "no-store",
  });
  if (!response.ok) return null;
  const data = await response.json().catch(() => ({}));
  const activity = data?.activity || null;
  if (activity) curriculumAuthorizedContentCache.set(cacheKey, activity);
  return activity;
}

async function withHydratedCurriculumActivityContent(resource) {
  if (!resource?._curriculumManaged || resource.category !== "Activity Center") return resource;
  if (hasAdminFullAccess()) {
    const full = curriculumActivityById(resource.id);
    if (!full) return resource;
    if (resource.steps || resource.materials || resource.description) return resource;
    return {
      ...resource,
      description: full.description || resource.description,
      objective: full.objective || "",
      materials: full.materials || "",
      setup: full.setup || "",
      steps: full.steps || "",
      learningGoals: Array.isArray(full.learningGoals) ? full.learningGoals : [],
      learningDomains: Array.isArray(full.learningDomains) ? full.learningDomains : [],
      teacherRole: full.teacherRole || "",
      teacherLanguage: full.teacherLanguage || "",
      vocabulary: full.vocabulary || "",
      observationOpportunities: full.observationOpportunities || "",
      extensions: full.extensions || "",
      adaptations: full.adaptations || "",
      safetyNotes: full.safetyNotes || "",
      ageModifications: full.ageModifications || "",
      customContent: buildActivityTextFromCurriculum({ ...full, parentTitle: resource.tags?.[2], dayOfWeek: resource.tags?.[1] }),
    };
  }
  // Browse payloads are slim; hydrate full how-to when opening an accessible activity.
  if (resource.steps || resource.materials) return resource;
  if (!canAccess(resource) && !(resource.plan === "Pro" && isProUser())) return resource;
  const fullActivity = await fetchAuthorizedCurriculumActivity(resource.id);
  if (!fullActivity) return resource;
  return {
    ...resource,
    description: fullActivity.description || resource.description,
    materials: fullActivity.materials || "",
    setup: fullActivity.setup || "",
    steps: fullActivity.steps || "",
    learningGoals: Array.isArray(fullActivity.learningGoals) ? fullActivity.learningGoals : [],
    learningDomains: Array.isArray(fullActivity.learningDomains) ? fullActivity.learningDomains : [],
    teacherRole: fullActivity.teacherRole || "",
    teacherLanguage: fullActivity.teacherLanguage || "",
    vocabulary: fullActivity.vocabulary || "",
    extensions: fullActivity.extensions || "",
    adaptations: fullActivity.adaptations || "",
    safetyNotes: fullActivity.safetyNotes || "",
    ageModifications: fullActivity.ageModifications || "",
    customContent: buildActivityTextFromCurriculum(fullActivity),
    _curriculumActivity: fullActivity,
  };
}

async function fetchPublishedCurriculumResourceFile(resourceId) {
  const id = String(resourceId || "").trim();
  if (!id || !curriculumResourceConfig.publicFileEndpoint) return null;
  const params = new URLSearchParams({ id, t: String(Date.now()) });
  const headers = await firebaseAuthHeaders();
  const response = await fetch(`${curriculumResourceConfig.publicFileEndpoint}?${params.toString()}`, {
    headers: headers || {},
    cache: "no-store",
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data?.error || "Could not open curriculum resource file.");
  return data.resource || null;
}

async function withHydratedCurriculumAttachments(resource) {
  if (!resource?._curriculumManaged || resource.category !== "Lesson Plans") return resource;
  const ids = Array.isArray(resource._curriculumResourceIds) ? resource._curriculumResourceIds : [];
  if (!ids.length) return resource;
  const attached = [];
  for (const resourceId of ids) {
    const meta = curriculumLibraryResourceById(resourceId) || curriculumResourceById(resourceId);
    if (!meta || meta.status === "archived" || meta.status === "draft") continue;
    let url = "";
    const existingData = String(meta.fileData || "").trim();
    if (existingData.startsWith("data:") || /^https:\/\//i.test(existingData)) {
      url = existingData;
    } else if (meta.hasFile !== false) {
      try {
        const file = await fetchPublishedCurriculumResourceFile(resourceId);
        url = String(file?.fileData || "").trim();
      } catch (error) {
        console.warn(error);
      }
    }
    attached.push({
      title: meta.title || "Resource",
      category: meta.resourceCategory || "Classroom Resources",
      mimeType: meta.mimeType || "",
      url,
      order: attached.length,
    });
  }
  return {
    ...resource,
    _curriculumAttachedResources: attached,
    lessonPlanOverride: {
      ...(resource.lessonPlanOverride || {}),
      resources: attached,
    },
  };
}

function decodedTextFileData(resource) {
  if (!resource.fileData || !resource.fileData.startsWith("data:text")) return "";
  const encoded = resource.fileData.split(",")[1] || "";
  try {
    return decodeURIComponent(encoded);
  } catch (error) {
    return "";
  }
}

function lessonAgeApproach(age) {
  const approaches = {
    Infant: "Use short one-to-one or very small group moments (5–10 minutes), responsive language, safe floor play, repeated songs, picture cards, and sensory-safe materials. Follow each baby's cues and stop before overstimulation. Never use worksheets, scissors, small parts, or multi-step directions with infants.",
    "Young Toddler": "Use very short, active lessons (8–12 minutes) with movement, repetition, visual cues, sensory play, and one-step directions. Offer two simple choices, expect lots of modeling, and keep adult support close throughout the activity.",
    "Older Toddler": "Use short hands-on lessons (10–15 minutes) with pretend play, sorting, simple art, movement, and one-to-two step directions. Keep language concrete, repeat key vocabulary, and build in chances to practice independence without adding academic pressure.",
    Toddler: "Use short active lessons (10–15 minutes) with two-choice options, movement breaks, repetition, simple naming, hands-on practice, and sensory exploration. Expect children to move in and out of activities. Never use worksheets or academic pressure. Model first, then invite participation.",
    Preschool: "Use small-group discussion, hands-on investigation, early writing or drawing, counting, comparison, prediction, cooperative play, and child-led extensions. Invite children to explain their thinking and make decisions. Activities run 15–20 minutes with open-ended outcomes.",
    "School Age": "Use project-based lessons (20–30 minutes or more) with collaboration, writing, discussion, problem-solving, reflection, and meaningful choice. Invite children to explain strategies, document discoveries, take leadership roles, and connect the theme to real-world experiences.",
  };
  return lessonAgeData(approaches, age);
}

function lessonAreaPractice(area, theme, age) {
  const ageWord = String(age || "children").toLowerCase();
  const themeWord = String(theme || "the theme").toLowerCase();
  const practices = {
    Cognitive: `${ageWord} learners sort, match, compare, remember routines, and solve simple problems using ${themeWord} pictures, props, and materials. Teacher scaffolds with open-ended prompts and thinking questions.`,
    Language: `${ageWord} learners hear, repeat, point to, name, and use ${themeWord} vocabulary during songs, books, play, and back-and-forth conversation with the teacher and peers.`,
    Literacy: `${ageWord} learners explore books, pictures, print, storytelling, beginning sounds, mark making, and retelling stories connected to ${themeWord}. Teacher models reading behaviors and invites participation.`,
    "Social Emotional": `${ageWord} learners practice connection, confidence, feelings vocabulary, turn-taking, gentle touch, waiting, helping, and belonging through ${themeWord} routines. Teacher names emotions and models positive interactions.`,
    "Fine Motor": `${ageWord} learners grasp, squeeze, place, stack, tear, trace, draw, turn pages, or use age-appropriate tools with ${themeWord} materials. Teacher provides scaffolding and celebrates effort and attempts.`,
    "Gross Motor": `${ageWord} learners crawl, walk, balance, reach, jump, stretch, dance, carry, or move with ${themeWord} themes while practicing coordination, spatial awareness, and body control.`,
    Science: `${ageWord} learners observe, ask questions, explore textures, notice changes, compare objects, and investigate safe ${themeWord} materials. Teacher models scientific thinking: "I wonder…" and "What do you notice?"`,
    Math: `${ageWord} learners count, match, sort, compare size, notice patterns, use position words, and group ${themeWord} materials. Teacher names math concepts during play and daily routines.`,
    "Creative Arts": `${ageWord} learners create, move, sing, pretend, build, paint, collage, and use open-ended materials inspired by ${themeWord}. Teacher values process over product and invites children to describe their work.`,
    "Self Help": `${ageWord} learners practice simple routines, clean-up, choices, independence, handwashing, dressing, transitions, and asking for help using ${themeWord} supports and visual cues.`,
  };
  return practices[area] || practices.Cognitive;
}

