/** New Free users default Access filter to Free until they change it. */
function freeLibraryFilterTouched() {
  try {
    return localStorage.getItem("llhFreeLibraryFilterTouched") === "1";
  } catch {
    return false;
  }
}

function markFreeLibraryFilterTouched() {
  try {
    localStorage.setItem("llhFreeLibraryFilterTouched", "1");
  } catch {
    /* ignore */
  }
}

function shouldDefaultFreeLibraryFilters() {
  if (!isLoggedIn() || isProUser() || hasAdminFullAccess()) return false;
  if (freeLibraryFilterTouched()) return false;
  const onboarding = typeof NewUserOnboarding?.getState === "function" ? NewUserOnboarding.getState() : null;
  if (!onboarding) return false;
  // Only brand-new Free signup/onboarding — do not treat blank defaultState.firstTimeUser as new.
  return Boolean(
    onboarding.freeChosenAtSignup
    || onboarding.freeSelectedAt
    || (onboarding.deferGenericUpgrades && onboarding.accountCreatedAt),
  );
}

function applyDefaultFreeLibraryFilters(options = {}) {
  if (!isLoggedIn() || isProUser() || hasAdminFullAccess()) return false;
  if (freeLibraryFilterTouched()) return false;
  if (!options.force && !shouldDefaultFreeLibraryFilters()) return false;
  let changed = false;
  if (lessonLibraryPlanFilter === "All") {
    lessonLibraryPlanFilter = "Free";
    changed = true;
  }
  if (activityLibraryPlanFilter === "All") {
    activityLibraryPlanFilter = "Free";
    changed = true;
  }
  return changed;
}

function clearActivityLibraryAdvancedFilters() {
  activityLibraryPlanFilter = "All";
  activityLibraryShowSavedOnly = false;
  activityLibraryShowRecentOnly = false;
  activityLibraryViewAllKey = "";
  activeFilter = "All";
  if (searchInput) searchInput.value = "";
}

function renderCategoryPage(view) {
  const category = viewMap[view];
  const section = document.querySelector(`#view-${view}`);
  const isLessonPlanCategory = category === "Lesson Plans";

  if (category === "Printables" || isPrintablesUpgradeModeActive() && view === "printables") {
    setView("activities");
    return;
  }

  const searchedChild = !isLessonPlanCategory ? childFromSearchQuery(searchInput.value.trim(), childRecords()) : null;
  const items = categoryResources(category);
  const accessCounts = isLessonPlanCategory ? null : categoryAccessCounts(category);
  const filters = categoryFilters(category);
  if (isLessonPlanCategory && !filters.includes(activeFilter)) activeFilter = "All";
  const displayTitle = view === "lessons" ? "Lesson Plan Library" : category;
  const emptyStateHtml = category === "Activity Center"
    ? (curriculumLibraryLoadFailed
      ? `<div class="empty-state" role="alert"><strong>Activities could not load.</strong><br />${escapeHtml(curriculumLibraryLoadError || "Please check your connection and try again.")}<br /><button class="primary-button" type="button" data-retry-curriculum-library style="margin-top:12px">Retry</button></div>`
      : (curriculumLibraryLoading || siteContentLoadPromise)
        ? `<div class="empty-state" role="status" aria-live="polite"><strong>Loading activities…</strong><br />Hang tight — your library is syncing.</div>`
        : `<div class="empty-state">No activities match your search or filter. Activities appear automatically when lesson plans are published. <button class="inline-link" data-view="lessons" type="button">Browse lesson plans</button>${!searchInput.value.trim() && activeFilter === "All" ? `<br /><button class="primary-button" type="button" data-retry-curriculum-library style="margin-top:12px">Retry</button>` : ""}</div>`)
    : `<div class="empty-state">No resources found. Try another search or filter.</div>`;
  if (isLessonPlanCategory) {
    const isSavedLessonMode = lessonLibraryMode === "saved";
    const isCollectionMode = lessonLibraryMode === "collection" && Boolean(lessonLibraryCollectionKey);
    const activeCollection = isCollectionMode ? curriculumCollectionByKey(lessonLibraryCollectionKey) : null;
    const lessonUpgradeBanner = !isProUser() ? libraryCompactUpgradeStripHtml() : "";
    const hasSearchOrAdvanced = Boolean(searchInput.value.trim() || lessonLibraryPlanFilter !== "All" || lessonLibraryShowAssignedOnly || lessonLibrarySort !== "recommended");
    const useBrowseRows = !isSavedLessonMode && !isCollectionMode && !lessonLibraryViewAllKey && !hasSearchOrAdvanced;
    let browseBody = "";
    if (isCollectionMode) {
      browseBody = `
        <div class="resource-grid lesson-library-grid library-browse-shell is-collection-detail">
          ${lessonUpgradeBanner}
          ${curriculumCollectionDetailHtml(activeCollection, items)}
        </div>
      `;
    } else if (isSavedLessonMode || hasSearchOrAdvanced || lessonLibraryViewAllKey) {
      const matchingCollections = (!isSavedLessonMode && searchInput.value.trim())
        ? filterCurriculumCollectionsForBrowse(curriculumCollections())
        : [];
      const isCollectionsViewAll = lessonLibraryViewAllKey === "curriculum-collections";
      const collectionsViewAll = isCollectionsViewAll
        ? filterCurriculumCollectionsForBrowse(curriculumCollections())
        : [];
      const viewAllItems = lessonLibraryViewAllKey && !isCollectionsViewAll
        ? collectLessonViewAllItems(items, lessonLibraryViewAllKey)
        : (isCollectionsViewAll ? [] : items);
      const viewAllTitle = lessonLibraryViewAllKey
        ? (isCollectionsViewAll
          ? "Curriculum Collections"
          : (buildLessonBrowseRows(items).find((row) => row.key === lessonLibraryViewAllKey)?.title || "All matching plans"))
        : "";
      const collectionResults = (!lessonLibraryViewAllKey && matchingCollections.length)
        ? `
          <section class="browse-row" data-browse-row="curriculum-collections-search">
            <div class="browse-row-header"><h3>Matching Collections</h3></div>
            <div class="browse-row-track-wrap">
              <div class="browse-row-track">
                ${matchingCollections.map(curriculumCollectionCard).join("")}
              </div>
            </div>
          </section>
        `
        : "";
      const freeFilterPrimary = !isSavedLessonMode
        && !lessonLibraryViewAllKey
        && lessonLibraryPlanFilter === "Free"
        && !isProUser();
      browseBody = `
        ${lessonLibraryViewAllKey ? `
          <div class="browse-view-all-bar">
            <h3>${escapeHtml(viewAllTitle)}</h3>
            <button type="button" class="ghost-button" data-clear-lesson-view-all>← Back to browse</button>
          </div>
        ` : (freeFilterPrimary ? `
          <div class="browse-view-all-bar" data-free-plans-primary="true">
            <h3>${escapeHtml(MEMBERSHIP_COPY.freeStarterSection)}</h3>
          </div>
        ` : "")}
        <div class="resource-grid lesson-library-grid library-browse-shell is-filtered-grid">
          ${freeFilterPrimary ? freeStarterLibraryBannerHtml() : ""}
          ${lessonUpgradeBanner}
          ${collectionResults}
          ${isCollectionsViewAll
            ? (collectionsViewAll.length ? collectionsViewAll.map(curriculumCollectionCard).join("") : lessonLibraryEmptyStateHtml())
            : (viewAllItems.length ? viewAllItems.map(lessonPlanCard).join("") : (collectionResults ? "" : lessonLibraryEmptyStateHtml()))}
        </div>
      `;
    } else if (useBrowseRows) {
      const rows = buildLessonBrowseRows(items);
      // Defer in-library upgrade strips for brand-new Free explorers until a value moment.
      const deferUpgrade = typeof shouldDeferGenericUpgradePrompts === "function" && shouldDeferGenericUpgradePrompts();
      browseBody = `
        <div class="resource-grid lesson-library-grid library-browse-shell">
          ${freeStarterLibraryBannerHtml()}
          ${deferUpgrade ? "" : lessonUpgradeBanner}
          ${activeFilter === "All" ? featuredLessonBannerHtml(items) : ""}
          ${rows.length
            ? rows.map((row) => browseRowHtml({ ...row, cardHtml: row.cardHtml || lessonPlanCard })).join("")
            : lessonLibraryEmptyStateHtml()}
        </div>
      `;
    }
    const onboardingSurface = (!isSavedLessonMode && !isCollectionMode && typeof renderLessonLibraryOnboardingHtml === "function")
      ? renderLessonLibraryOnboardingHtml()
      : "";
    section.innerHTML = `
      ${renderLessonPlanLibraryHeader()}
      ${calendarLessonAssignBannerHtml()}
      ${onboardingSurface}
      ${!isSavedLessonMode && !isCollectionMode ? lessonPlanRequestPanelHtml() : ""}
      <div class="lesson-plan-search-bar">
        <label class="lesson-plan-search-label visually-hidden" for="lessonPlanSearch">Search lesson plans</label>
        <input id="lessonPlanSearch" type="search" placeholder="${isSavedLessonMode ? "Search saved plans..." : (isCollectionMode ? "Search this collection..." : "Search lesson plans...")}" value="${escapeHtml(searchInput.value)}" autocomplete="off" />
      </div>
      ${isSavedLessonMode || isCollectionMode ? "" : `<div class="filter-row lesson-library-age-filters library-filter-scroll" role="group" aria-label="Age group filters">
        ${filters.map((filter) => `<button class="${activeFilter === filter ? "active-filter" : ""}" data-filter="${filter}" type="button" aria-pressed="${activeFilter === filter ? "true" : "false"}">${filter}</button>`).join("")}
      </div>`}
      ${isSavedLessonMode || isCollectionMode ? "" : renderLessonLibrarySecondaryControls()}
      ${browseBody}
    `;
    if (!isSavedLessonMode && !isCollectionMode) {
      loadLessonPlanRequestsForCurrentUser().catch(() => {});
    }
    return;
  }

  if (category === "Activity Center") {
    const activityItems = filterActivityBrowseItems(items);
    const activityUpgradeBanner = !isProUser() ? libraryCompactUpgradeStripHtml() : "";
    const categoryBackTarget = isLoggedIn() || hasAdminFullAccess() ? "calendar" : "home";
    const categoryBackButton = activeActivityLessonPlanId
      ? `<button class="ghost-button back-button" data-contextual-back="activities" data-fallback-view="lessons" data-always-visible="true" type="button">${escapeHtml(contextualBackLabel("activities", "lessons"))}</button>`
      : `<button class="ghost-button back-button" data-view="${categoryBackTarget}" type="button">${escapeHtml(fallbackBackLabel(categoryBackTarget))}</button>`;
    const quickFilters = activityQuickFilterOptions();
    const hasSearchOrAdvanced = Boolean(
      searchInput.value.trim()
      || (activeFilter !== "All")
      || activityLibraryPlanFilter !== "All"
      || activityLibraryShowSavedOnly
      || activityLibraryShowRecentOnly
      || activeActivityLessonPlanId,
    );
    const activityAccess = curriculumActivityAccessStats(visibleResourcesForCategory("Activity Center"));
    const activityStatsLine = (curriculumLibraryLoading || siteContentLoadPromise)
      ? `<p class="library-stats-line" role="status" aria-live="polite">Syncing activity library…</p>`
      : `<p class="library-stats-line" data-activity-access-stats="canonical">${activityAccess.total} Activities · ${activityAccess.freeTotal} Free · ${activityAccess.proTotal} Pro</p>`;
    let activityBody = "";
    if (activityLibraryViewAllKey || hasSearchOrAdvanced) {
      const viewAllItems = activityLibraryViewAllKey
        ? collectActivityViewAllItems(activityItems, activityLibraryViewAllKey)
        : activityItems;
      const viewAllTitle = activityLibraryViewAllKey
        ? (buildActivityBrowseRows(activityItems).find((row) => row.key === activityLibraryViewAllKey)?.title || "All matching activities")
        : "";
      const freeActivityPrimary = !activityLibraryViewAllKey
        && activityLibraryPlanFilter === "Free"
        && !isProUser();
      activityBody = `
        ${activityLibraryViewAllKey ? `
          <div class="browse-view-all-bar">
            <h3>${escapeHtml(viewAllTitle)}</h3>
            <button type="button" class="ghost-button" data-clear-activity-view-all>← Back to browse</button>
          </div>
        ` : (freeActivityPrimary ? `
          <div class="browse-view-all-bar" data-free-activities-primary="true">
            <h3>Your Included Free Activities</h3>
          </div>
        ` : "")}
        <div class="resource-grid library-browse-shell is-filtered-grid">
          ${activityUpgradeBanner}
          ${viewAllItems.length ? viewAllItems.map(activityBrowseCard).join("") : emptyStateHtml}
        </div>
      `;
    } else {
      const rows = buildActivityBrowseRows(activityItems);
      activityBody = `
        <div class="resource-grid library-browse-shell">
          ${activityUpgradeBanner}
          ${rows.length
            ? rows.map((row) => browseRowHtml({ ...row, cardHtml: activityBrowseCard })).join("")
            : emptyStateHtml}
        </div>
      `;
    }
    section.innerHTML = `
      ${categoryBackButton}
      <header class="library-compact-header">
        <div class="library-compact-title-row">
          <h2>Activity Center</h2>
          ${libraryAccessBadgeHtml()}
        </div>
        <p class="library-compact-subtitle">Browse ready-to-use activities by age, theme, or activity type.</p>
        ${activityStatsLine}
      </header>
      ${searchedChild ? renderChildLessonSearchContext(searchedChild) : ""}
      ${activeActivityLessonPlanId ? renderActivityLessonFilterBanner() : ""}
      <div class="activity-search-bar">
        <label class="visually-hidden" for="activityCenterSearch">Search activities</label>
        <input id="activityCenterSearch" type="search" placeholder="Search activities..." value="${escapeHtml(searchInput.value)}" autocomplete="off" />
      </div>
      <div class="filter-row library-filter-scroll" role="group" aria-label="Activity filters">
        ${quickFilters.map((filter) => `
          <button class="${activeFilter === filter.value ? "active-filter" : ""}" data-filter="${escapeHtml(filter.value)}" type="button" aria-pressed="${activeFilter === filter.value ? "true" : "false"}">${escapeHtml(filter.label)}</button>
        `).join("")}
      </div>
      ${renderActivityLibraryAdvancedFilters()}
      ${activityBody}
    `;
    return;
  }

  const categoryBackTarget = isLoggedIn() || hasAdminFullAccess() ? "calendar" : "home";
  const categoryBackButton = `<button class="ghost-button back-button" data-view="${categoryBackTarget}" type="button">${escapeHtml(fallbackBackLabel(categoryBackTarget))}</button>`;
  const accessNoticeHtml = `<div class="access-notice ${isProUser() ? "pro" : ""}">
      ${isProUser()
        ? `Pro is active: full in-app library access, saved favorites, viewed resources, and ${aiUsageRemaining()} document creations left this month.`
        : `Free plan: ${accessCounts.freeLimit} ${displayTitle.toLowerCase()} resources are unlocked here. Upgrade to Pro for all ${accessCounts.total}.`}
    </div>`;
  section.innerHTML = `
    ${categoryBackButton}
    <div class="page-title">
      <p class="eyebrow">${displayTitle}</p>
      <h2>${displayTitle}</h2>
      <p>${categoryIntro(category)}</p>
    </div>
    <div class="library-stats">
      <div><strong>${accessCounts.total}</strong><span>ready-made resources</span></div>
      <div><strong>${accessCounts.freeLimit}</strong><span>Free access</span></div>
      <div><strong>${accessCounts.proOnly}</strong><span>Pro unlocks</span></div>
    </div>
    ${accessNoticeHtml}
    ${searchedChild ? renderChildLessonSearchContext(searchedChild) : ""}
    ${category === "Printables" ? renderPrintablesRefreshNotice() : ""}
    <div class="filter-row">
      ${filters.map((filter) => `<button class="${activeFilter === filter ? "active-filter" : ""}" data-filter="${filter}">${filter}</button>`).join("")}
    </div>
    ${category === "Observation Hub" ? renderObservationEditor() : ""}
    <div class="resource-grid">
      ${items.length ? items.map(resourceCard).join("") : emptyStateHtml}
    </div>
  `;
}

function renderChildLessonSearchContext(child) {
  const context = childRecommendationContext(child);
  const primaryArea = context.areas[0] || "Approaches to Learning";
  const primarySupport = context.supportAreas[0] || "None selected";
  return `
    <section class="child-lesson-context">
      <div>
        <strong>Suggested for ${escapeHtml(child.name)}</strong>
        <span>Age Group: ${escapeHtml(normalizeAgeGroup(child.ageGroup) || child.ageGroup || "Not entered")}</span>
        <span>Goal Match: ${escapeHtml(displayDevelopmentArea(primaryArea))}</span>
        <span>Support Area: ${escapeHtml(primarySupport)}</span>
      </div>
      <p><b>Why suggested:</b> Supports ${escapeHtml(child.name)}'s current goals, support needs, observations, and progress history.</p>
    </section>
  `;
}

function renderPrintablesRefreshNotice() {
  return `
    <div class="access-notice printable-refresh-notice">
      <strong>Professional print-ready resources.</strong>
      Worksheets use structured classroom layouts, PDF-ready pages, dotted tracing or cutting practice when appropriate, and quality checks for placeholder or unfinished content before printing.
    </div>
  `;
}

function renderActivityLessonFilterBanner() {
  const lesson = resources.find((item) => item.id === activeActivityLessonPlanId);
  const title = lesson?.title || activeActivityLessonPlanId;
  return `
    <section class="access-notice activity-lesson-filter-banner" role="status">
      <div>
        <strong>Showing activities from:</strong> ${escapeHtml(title)}
      </div>
      <button class="ghost-button" type="button" data-clear-activity-lesson-filter>View all activities</button>
    </section>
  `;
}

function renderLessonPlanLibraryNotice() {
  const stats = curriculumLessonPlanAccessStats();
  const ageBreakdown = formatLessonPlanAgeBreakdown(stats.freeByAge);
  const growth = contentGrowthStats();
  let accessCopy;
  if (hasAdminFullAccess() || (isProUser() && !accountIsInTrial())) {
    accessCopy = `Full access to all ${stats.freeTotal + stats.proTotal} published lesson plans with ${MEMBERSHIP_COPY.unlimitedLabel.toLowerCase()}. New lesson plans are added every week.`;
  } else if (accountIsInTrial()) {
    accessCopy = MEMBERSHIP_COPY.trialCore;
  } else if (stats.freeTotal) {
    accessCopy = `${MEMBERSHIP_COPY.freeCore}${ageBreakdown ? ` (${ageBreakdown} in your included set.)` : ""}`;
  } else {
    accessCopy = `${MEMBERSHIP_COPY.freeCore} Upgrade to Pro anytime to unlock ${Math.max(stats.proTotal, growth.totalPlans)}+ lesson plans.`;
  }
  return `
    <section id="lessonLibraryInfoBanner" class="access-notice lesson-library-notice lesson-library-notice-compact" role="status" aria-live="polite">
      <div class="lesson-update-notice-copy">
        <p>${escapeHtml(accessCopy)}</p>
      </div>
    </section>
  `;
}

function renderPrintablesComingSoon() {
  return `
    <div class="page-title">
      <p class="eyebrow">Printables</p>
      <h2>Printables are being upgraded</h2>
      <p>We're currently refreshing our printable library with higher-quality, teacher-friendly resources. New worksheets, activity pages, and classroom printables will be added soon.</p>
    </div>
    <div class="access-notice">
      <strong>Check back soon.</strong>
      Our updated printable library will include ready-to-print worksheets, tracing pages, coloring sheets, and more — all designed for home daycare and preschool providers.
    </div>
  `;
}

function renderObservationEditor() {
  if (!activeObservationEditId) return "";
  const resource = resources.find((item) => item.id === activeObservationEditId);
  if (!resource) return "";
  const area = resource.tags.find((tag) => learningAreas.includes(tag)) || "Cognitive";
  return `
    <section class="section-block observation-editor">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Editable Observation</p>
          <h3>${resource.title}</h3>
        </div>
        <button class="ghost-button" data-close-observation-editor type="button">Close</button>
      </div>
      <form id="observationEditForm" class="panel-form">
        <input name="id" type="hidden" value="${resource.id}" />
        <div class="form-grid-two">
          <label>Title<input name="title" value="${resource.title}" /></label>
          <label>Developmental Area<select name="area">${learningAreas.map((item) => `<option ${item === area ? "selected" : ""}>${item}</option>`).join("")}</select></label>
        </div>
        <label>Professional Observation<textarea name="observationText" rows="4">${resource.observationText || resource.description}</textarea></label>
        <label>What to Look For<textarea name="lookFor" rows="3">${resource.lookFor || ""}</textarea></label>
        <label>Next Steps<textarea name="nextSteps" rows="3">${resource.nextSteps || ""}</textarea></label>
        <label>Learning Standard<textarea name="standard" rows="2">${resource.standard || `Early learning guideline category: ${area}.`}</textarea></label>
        <button class="primary-button" type="submit">Save Observation Edit</button>
      </form>
    </section>
  `;
}

const lessonPlanPublicFilters = Object.freeze(["All", "Infant", "Toddler", "Preschool"]);

function categoryFilters(category) {
  const shared = ["All", "Infant", "Toddler", "Preschool", "All Ages"];
  const map = {
    "Lesson Plans": lessonPlanPublicFilters,
    "Observation Hub": [...shared, ...learningAreas],
    "Forms Library": ["All", "All Ages", ...Object.keys(formGroups), "Editable", "PDF"],
    "Menu Center": ["All", "All Ages", "Infant", "Toddler", "Preschool", "52 Weeks of Menus", "Breakfast", "Lunch", "Snack", "Shopping List"],
    "Activity Center": [...shared, ...curriculumActivityFilterCategories],
    "Printables": ["All", "Toddler", "Preschool", ...printableTypes.slice(0, 8), "Seasonal", "Holiday"],
  };
  return map[category] || shared;
}

function categoryIntro(category) {
  const copy = {
    "Lesson Plans": "Search and browse lesson plans by age group or keyword.",
    "Observation Hub": "Search infant, toddler, and preschool observation wording by developmental area, what to look for, standards, and next steps.",
    "Forms Library": "View editable childcare paperwork like parent handbooks, enrollment forms, emergency contacts, reports, trackers, and receipts inside Little Learner Hub.",
    "Activity Center": "Browse play-based activities synced from lesson plans. Filter by age or activity type.",
    "Menu Center": "Browse 52 weeks of daycare menus, infant/toddler/preschool meal ideas, shopping lists, and CACFP-style inspiration.",
    "Printables": "View tracing pages, coloring pages, alphabet, numbers, shapes, cutting, matching, seasonal, and holiday worksheet concepts inside Little Learner Hub.",
  };
  return copy[category];
}

function reviewCardHtml(review) {
  const initials = initialsFromName(review.name || review.businessName || "LL", "LL");
  const image = sanitizedImageSource(review.imageUrl);
  return `
    <article class="lp-review-card${review.order === 1 ? " featured" : ""}">
      <p>${escapeHtml(review.text || "")}</p>
      <div class="lp-reviewer">
        ${image
          ? `<img class="lp-reviewer-avatar lp-reviewer-image" src="${escapeHtml(image)}" alt="${escapeHtml(review.name || "Reviewer")}" />`
          : `<span class="lp-reviewer-avatar" aria-hidden="true">${escapeHtml(initials)}</span>`}
        <div><strong>${escapeHtml(review.name || "Anonymous reviewer")}</strong><small>${escapeHtml(review.businessName || "Little Learner Hub")}</small></div>
      </div>
    </article>
  `;
}

function renderManagedHomeContent() {
  const content = effectiveSiteContent();
  const homepage = content.homepage || {};
  const founder = content.founder || {};
  const reviews = (content.reviews || []).filter((item) => item.visible !== false).sort((a, b) => (a.order || 0) - (b.order || 0));
  const setText = (selector, value) => {
    const node = document.querySelector(selector);
    if (node && normalizedMultilineText(value)) node.textContent = value;
  };
  const redesignedHome = Boolean(document.querySelector(".llh-hero"));
  // Redesigned homepage owns positioning copy so stale CMS hero/journey text cannot
  // reintroduce outdated claims or conflicting pricing messaging.
  if (!redesignedHome) {
    setText(".lp-hero-badge", homepage.heroBadge);
    setText(".lp-hero-headline", homepage.heroHeadline);
    setText(".lp-hero-sub", homepage.heroSubheadline);
    setText(".lp-social-proof p", homepage.socialProofText);
    setText(".lp-final-cta h2", homepage.finalCtaHeadline);
    setText(".lp-final-cta .lp-cta-body", homepage.finalCtaText);
    setText(".lp-final-cta .lp-cta-subtext", homepage.finalCtaSubtext);
    const heroPrimary = document.querySelector(".lp-hero-actions .lp-btn-primary");
    if (heroPrimary && homepage.heroCtaText) heroPrimary.textContent = homepage.heroCtaText;
    const heroSecondary = document.querySelector(".lp-hero-actions .lp-btn-secondary");
    if (heroSecondary && homepage.heroSecondaryCtaText) heroSecondary.textContent = homepage.heroSecondaryCtaText;
    const finalButton = document.querySelector(".lp-final-cta .lp-btn-primary");
    if (finalButton && homepage.finalCtaButtonText) finalButton.textContent = homepage.finalCtaButtonText;

    if (homepage.heroBenefits?.length) {
      const heroBenefitsList = document.querySelector(".lp-hero-benefits");
      if (heroBenefitsList) {
        heroBenefitsList.innerHTML = homepage.heroBenefits.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
      }
    }

    setText(".lp-hero-testimonials .lp-section-title", homepage.trustSectionHeading);
    setText("#homePlatformPreview .lp-section-title", homepage.showcaseSectionHeading);
    setText("#homePlatformPreview .lp-section-sub", homepage.showcaseSectionSubtitle);
    setText(".lp-home-journey .lp-section-title", homepage.journeySectionHeading);
    setText(".lp-home-journey .lp-section-sub", homepage.journeySectionSubtitle);
    setText(".lp-journey-card[aria-label='How it works'] h3", homepage.journeyHowItWorksHeading);
    setText(".lp-journey-card[aria-label='Coming soon features'] h3", homepage.journeyComingSoonHeading);
    setText(".lp-why-section .lp-section-title", homepage.whySectionHeading);

    if (homepage.whyItems?.length) {
      const whyTitles = document.querySelectorAll(".lp-why-item strong");
      homepage.whyItems.forEach((item, index) => {
        if (whyTitles[index] && item.title) whyTitles[index].textContent = item.title;
      });
    }

    document.querySelectorAll(".lp-proof-card").forEach((card, index) => {
      const item = homepage.featureCards?.[index];
      if (!item) return;
      const title = card.querySelector("strong");
      const text = card.querySelector("p");
      if (title && item.title) title.textContent = item.title;
      if (text && item.text) text.textContent = item.text;
    });

    document.querySelectorAll(".lp-how-grid .lp-step-card").forEach((card, index) => {
      const item = homepage.howItWorks?.[index];
      const title = card.querySelector("strong");
      if (title && item?.title) title.textContent = item.title;
    });

    const comingSoonList = document.querySelector(".lp-coming-soon-list");
    if (comingSoonList && homepage.comingSoon?.length) {
      comingSoonList.innerHTML = homepage.comingSoon.map((item) => `<span>${escapeHtml(item.title)}</span>`).join("");
    }

    document.querySelectorAll(".lp-showcase-card").forEach((card, index) => {
      const item = homepage.previewCards?.find((entry) => entry.id === card.dataset.preview) || homepage.previewCards?.[index];
      if (!item) return;
      const title = card.querySelector(".lp-showcase-info h3");
      const text = card.querySelector(".lp-showcase-info p");
      if (title && item.title) title.textContent = item.title;
      if (text && item.text) text.textContent = item.text;
      const screen = card.querySelector(".lp-showcase-screen");
      if (!screen) return;
      screen.querySelector(".lp-showcase-managed-image")?.remove();
      if (item.imageUrl) {
        screen.insertAdjacentHTML("afterbegin", `<img class="lp-showcase-managed-image" src="${escapeHtml(item.imageUrl)}" alt="${escapeHtml(item.title || "Preview image")}" />`);
      }
    });

    const heroVisual = document.querySelector(".lp-hero-visual");
    if (heroVisual) {
      heroVisual.querySelector(".lp-home-hero-image")?.remove();
      if (homepage.heroImageUrl) {
        heroVisual.insertAdjacentHTML("afterbegin", `<img class="lp-home-hero-image" src="${escapeHtml(homepage.heroImageUrl)}" alt="Little Learner Hub preview" />`);
      }
    }
  }

  setText(".lp-reviews-section .lp-section-title", homepage.reviewsSectionHeading);

  const reviewsGrid = document.querySelector(".lp-reviews-grid");
  // Redesigned homepage ships a curated multi-review grid in HTML (Tiffany + peers).
  // Never wipe those cards when CMS reviews load — only append unique extras once.
  if (reviewsGrid && reviews.length && !redesignedHome) {
    reviewsGrid.innerHTML = reviews.map(reviewCardHtml).join("");
  } else if (reviewsGrid && reviews.length && redesignedHome) {
    if (reviewsGrid.dataset.cmsReviewsAppended !== "1") {
      const existingNames = new Set(
        Array.from(reviewsGrid.querySelectorAll(".lp-reviewer strong"))
          .map((node) => String(node.textContent || "").trim().toLowerCase())
          .filter(Boolean),
      );
      const extras = reviews.filter((item) => {
        const name = String(item.name || item.author || "").trim().toLowerCase();
        return Boolean(name) && !existingNames.has(name);
      });
      if (extras.length) {
        reviewsGrid.insertAdjacentHTML("beforeend", extras.map(reviewCardHtml).join(""));
      }
      reviewsGrid.dataset.cmsReviewsAppended = "1";
    }
  }

  if (!redesignedHome) {
    const founderTitle = founder.title || founder.name;
    if (founderTitle) setText(".lp-founder-content h2", founderTitle);
    const founderParagraphs = document.querySelectorAll(".lp-founder-content p");
    const aboutText = normalizedMultilineText(founder.aboutText || "");
    if (founderParagraphs.length && aboutText) {
      const parts = aboutText.split(/\n{2,}/).filter(Boolean);
      founderParagraphs[0].textContent = parts[0] || founder.shortBio || founderParagraphs[0].textContent;
      if (founderParagraphs[1]) founderParagraphs[1].textContent = parts[1] || founderParagraphs[1].textContent;
      if (founderParagraphs[2]) founderParagraphs[2].textContent = parts[2] || founderParagraphs[2].textContent;
    } else if (founderParagraphs[0] && founder.shortBio) {
      founderParagraphs[0].textContent = founder.shortBio;
    }
  }
  const founderLinks = document.querySelector(".lp-founder-links");
  if (founderLinks) {
    const linkItems = [];
    if (founder.websiteUrl) linkItems.push(`<a class="lp-founder-link" href="${escapeHtml(founder.websiteUrl)}" target="_blank" rel="noopener noreferrer">🌐 Website</a>`);
    if (founder.instagramUrl) linkItems.push(`<a class="lp-founder-link" href="${escapeHtml(founder.instagramUrl)}" target="_blank" rel="noopener noreferrer">📷 Instagram</a>`);
    if (founder.linkedInUrl) linkItems.push(`<a class="lp-founder-link" href="${escapeHtml(founder.linkedInUrl)}" target="_blank" rel="noopener noreferrer">💼 LinkedIn</a>`);
    founderLinks.innerHTML = linkItems.join("");
  }
  const founderImg = document.querySelector(".lp-founder-photo-img");
  const founderFallback = document.querySelector(".lp-founder-photo-fallback");
  const defaultFounderSrc = founderImg?.dataset?.founderDefaultSrc || "images/leah-founder.jpg";
  const founderImage = founder.homeImageUrl || founder.profileImageUrl || defaultFounderSrc;
  if (founderImg) {
    founderImg.src = founderImage;
    founderImg.style.display = "";
    if (founderFallback) {
      founderFallback.hidden = true;
      founderFallback.style.display = "none";
    }
    founderImg.onerror = () => {
      founderImg.style.display = "none";
      if (founderFallback) {
        founderFallback.hidden = false;
        founderFallback.style.display = "grid";
      }
    };
  }
}

function renderManagedPricingText() {
  const content = effectiveSiteContent();
  const pricing = content.pricing || {};
  if (pricing._draft) return;
  // Homepage redesign features Founding Member ($9.99/mo locked while continuously active) as the paid plan.
  // Never let legacy CMS "Pro $19.99" copy overwrite that offer.
  if (document.querySelector(".llh-founding-card")) {
    const setText = (selector, value) => {
      const node = document.querySelector(selector);
      if (node && value) node.textContent = value;
    };
    // Allow free-card CMS tweaks only; keep founding price/features authoritative.
    setText(".lp-free-card h3", pricing.freePlanName);
    const freePriceStrong = document.querySelector(".lp-free-card .lp-price-amount strong");
    if (freePriceStrong && pricing.freePlanPrice) freePriceStrong.textContent = pricing.freePlanPrice;
    const freePriceSpan = document.querySelector(".lp-free-card .lp-price-amount span");
    if (freePriceSpan && pricing.freePlanPriceInterval) freePriceSpan.textContent = pricing.freePlanPriceInterval;
    const freeList = document.querySelector(".lp-free-card .lp-price-features[data-homepage-free-features], .lp-free-card .lp-price-features");
    if (freeList) {
      freeList.innerHTML = HOMEPAGE_PUBLIC_FREE_PLAN_FEATURES.map((feature) => `<li>✓ ${escapeHtml(feature)}</li>`).join("");
    }
    return;
  }
  const setText = (selector, value) => {
    const node = document.querySelector(selector);
    if (node && value) node.textContent = value;
  };
  setText(".lp-pricing-section .lp-section-title", pricing.sectionTitle);
  setText(".lp-pricing-section .lp-section-sub", pricing.sectionSubtitle);
  setText(".lp-free-card h3", pricing.freePlanName);
  setText(".lp-pro-card h3", pricing.proPlanName);
  setText(".lp-pro-highlight-badge", pricing.proPlanHighlightBadge);
  const trialBtn = document.querySelector(".lp-pro-card [data-action='upgrade-trial']");
  if (trialBtn && pricing.trialButtonText) trialBtn.textContent = pricing.trialButtonText;
  setText(".lp-price-note", pricing.trialNoteText);

  const freePriceStrong = document.querySelector(".lp-free-card .lp-price-amount strong");
  if (freePriceStrong && pricing.freePlanPrice) freePriceStrong.textContent = pricing.freePlanPrice;
  const freePriceSpan = document.querySelector(".lp-free-card .lp-price-amount span");
  if (freePriceSpan && pricing.freePlanPriceInterval) freePriceSpan.textContent = pricing.freePlanPriceInterval;
  const freeCtaBtn = document.querySelector(".lp-free-card [data-plan='Free']");
  if (freeCtaBtn && pricing.freePlanCtaText) freeCtaBtn.textContent = pricing.freePlanCtaText;

  const proPriceStrong = document.querySelector(".lp-pro-card .lp-price-amount strong");
  if (proPriceStrong && pricing.proPlanPrice) proPriceStrong.textContent = pricing.proPlanPrice;
  const proPriceSpan = document.querySelector(".lp-pro-card .lp-price-amount span");
  if (proPriceSpan && pricing.proPlanPriceInterval) proPriceSpan.textContent = pricing.proPlanPriceInterval;

  if (pricing.freePlanFeatures?.length) {
    const freeList = document.querySelector(".lp-free-card .lp-price-features");
    if (freeList) {
      freeList.innerHTML = refreshFreePlanFeatureLines(pricing.freePlanFeatures).map((f) => `<li>${escapeHtml(f)}</li>`).join("");
    }
  } else {
    const freeList = document.querySelector(".lp-free-card .lp-price-features");
    if (freeList) freeList.innerHTML = refreshFreePlanFeatureLines([]).map((f) => `<li>${escapeHtml(f)}</li>`).join("");
  }
  if (pricing.proPlanFeatures?.length) {
    const proList = document.querySelector(".lp-pro-card .lp-price-features");
    if (proList) proList.innerHTML = pricing.proPlanFeatures.map((f) => `<li>${escapeHtml(f)}</li>`).join("");
  }
}

function renderManagedFaqContent() {
  const target = document.querySelector("#faqList");
  if (!target) return;
  const content = effectiveSiteContent();
  const faqs = (content.faqs || [])
    .filter((f) => f.visible !== false)
    .sort((a, b) => (a.order || 0) - (b.order || 0));
  if (!faqs.length) {
    // Fall back to static default content if no dynamic FAQs are saved
    const defaultFaqs = document.querySelectorAll("#defaultFaqList .faq-item");
    if (defaultFaqs.length) {
      target.innerHTML = Array.from(defaultFaqs).map((el) => el.outerHTML).join("");
    }
    return;
  }
  target.innerHTML = faqs.map((f) => {
    let answer = f.answer || "";
    if (/what is included in the free plan/i.test(f.question || "") || /is there a free plan/i.test(f.question || "")) {
      answer = refreshFreePlanFaqAnswer(answer, f.question || "");
    }
    answer = String(answer)
      .replace(/,?\s*printables,?/gi, ",")
      .replace(/,\s*,/g, ",")
      .replace(/\s+,/g, ",")
      .replace(/,\s*$/g, "")
      .replace(/^\s*,\s*/g, "")
      .trim();
    return `
    <article class="faq-item">
      <h3>${escapeHtml(f.question)}</h3>
      <p>${escapeHtml(answer)}</p>
    </article>
  `;
  }).join("");
}

/** Closed Founding acquisition CTAs must never appear in customer chrome. */
function isFoundingAcquisitionOfferText(text) {
  return /Founding\s+Membership|Founding\s+Member|Founding\s+Price|Lock In My \$9\.99|Lock In \$9\.99|\$9\.99\s+Founding|founding price of just \$9\.99/i.test(String(text || ""));
}

function renderManagedAnnouncementBanner() {
  const banner = document.querySelector("#siteAnnouncementBanner");
  const textEl = document.querySelector("#siteAnnouncementText");
  if (!banner || !textEl) return;
  // Public marketing homepage uses the dedicated founding announcement banner instead.
  if (!currentUser && document.querySelector("#view-home.landing-home .llh-announce-banner")) {
    banner.hidden = true;
    textEl.textContent = "";
    return;
  }
  const content = effectiveSiteContent();
  const ann = content.announcement || {};
  const dismissed = sessionStorage.getItem("llhAnnouncementDismissed") === ann.text;
  const isExpired = ann.expiresAt && new Date(ann.expiresAt) < new Date();
  // Founding acquisition is closed — never show Lock-In / Founding-price pitches
  // to Free or other customers. Existing Founding entitlements are unchanged.
  const foundingAcquisitionPitch = isFoundingAcquisitionOfferText(ann.text) && !foundingOpenForAcquisition();
  const shouldShow = ann.visible === true
    && !ann._draft
    && !dismissed
    && !isExpired
    && ann.text
    && !foundingAcquisitionPitch;
  if (shouldShow) {
    textEl.textContent = ann.text;
    banner.hidden = false;
  } else {
    banner.hidden = true;
    textEl.textContent = "";
  }
}

