function setHomePublicMenuOpen(open) {
  const shouldOpen = Boolean(open);
  document.body.classList.toggle("llh-public-menu-open", shouldOpen);
  const menu = document.querySelector("#llhPublicMobileMenu");
  const backdrop = document.querySelector("#llhPublicMenuBackdrop");
  const toggle = document.querySelector("#llhPublicMenuToggle");
  if (menu) menu.hidden = !shouldOpen;
  if (backdrop) backdrop.hidden = !shouldOpen;
  if (toggle) {
    toggle.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
    toggle.setAttribute("aria-label", shouldOpen ? "Close menu" : "Open menu");
  }
}

function bindHomePublicChrome() {
  const toggle = document.querySelector("#llhPublicMenuToggle");
  const backdrop = document.querySelector("#llhPublicMenuBackdrop");
  if (toggle && !toggle.dataset.bound) {
    toggle.dataset.bound = "1";
    toggle.addEventListener("click", () => {
      setHomePublicMenuOpen(!document.body.classList.contains("llh-public-menu-open"));
    });
  }
  if (backdrop && !backdrop.dataset.bound) {
    backdrop.dataset.bound = "1";
    backdrop.addEventListener("click", () => setHomePublicMenuOpen(false));
  }
  const foundingAnnounce = document.querySelector("#llhFoundingAnnounceBanner");
  const foundingDismiss = document.querySelector("#llhFoundingAnnounceDismiss");
  if (foundingAnnounce && foundingDismiss && !foundingDismiss.dataset.bound) {
    foundingDismiss.dataset.bound = "1";
    try {
      if (localStorage.getItem(LLH_FOUNDING_ANNOUNCE_DISMISS_KEY) === "1") {
        foundingAnnounce.hidden = true;
      }
    } catch { /* ignore */ }
    foundingDismiss.addEventListener("click", () => {
      foundingAnnounce.hidden = true;
      try { localStorage.setItem(LLH_FOUNDING_ANNOUNCE_DISMISS_KEY, "1"); } catch { /* ignore */ }
    });
  }
  bindHomeShapeFeedbackForm();
  prefillHomeShapeFeedbackEmail();
  bindIdeaRequestForm();
  setHomePublicMenuOpen(false);
}

function homeStickyNavOffsetPx() {
  const nav = document.querySelector("body.home-view .llh-public-nav");
  if (!nav) return 72;
  const height = nav.getBoundingClientRect().height;
  return Math.max(56, Math.ceil(height || 72));
}

function scrollToHomeSection(sectionKeyOrId) {
  const sectionId = HOME_NAV_SECTION_IDS[sectionKeyOrId] || sectionKeyOrId;
  const target = document.getElementById(sectionId);
  if (!target) return false;
  const alreadyOnHome = Boolean(document.querySelector("#view-home.active-view"));
  // Avoid setView's default scroll-to-top — it races section scrolling and makes
  // Home / Lesson Plans / Reviews nav links feel like they do nothing.
  if (!alreadyOnHome) {
    setView("home", { allowDashboard: true, skipScrollReset: true });
  } else {
    document.body.classList.add("home-view");
  }
  setHomePublicMenuOpen(false);
  // Instant scroll (not smooth): sticky-nav offset math stays accurate and section
  // links feel reliable on long homepage pages / mobile menu close.
  window.setTimeout(() => {
    const el = document.getElementById(sectionId);
    if (!el) return;
    const offset = homeStickyNavOffsetPx() + 10;
    const top = Math.max(0, window.scrollY + el.getBoundingClientRect().top - offset);
    window.scrollTo({ top, behavior: "auto" });
    try {
      if (sectionId === "homeHero") {
        history.replaceState(null, "", window.location.pathname + window.location.search);
      } else {
        history.replaceState(null, "", `#${sectionId}`);
      }
    } catch {
      /* ignore */
    }
  }, alreadyOnHome ? 40 : 120);
  return true;
}

function captureHomePreviewScrollPosition(sectionId = "") {
  homePreviewReturnScrollY = window.scrollY || document.documentElement.scrollTop || 0;
  homePreviewReturnSectionId = sectionId || "";
}

function restoreHomePreviewScrollPosition() {
  if (!document.querySelector("#view-home.active-view") && !document.querySelector("#view-home.landing-home")) {
    return;
  }
  const sectionId = homePreviewReturnSectionId;
  const y = homePreviewReturnScrollY;
  homePreviewReturnSectionId = "";
  homePreviewReturnScrollY = 0;
  requestAnimationFrame(() => {
    if (sectionId) {
      const target = document.getElementById(sectionId);
      if (target) {
        target.scrollIntoView({ behavior: "auto", block: "start" });
        return;
      }
    }
    window.scrollTo({ top: y, behavior: "auto" });
  });
}

function homeCurriculumLessonPlans() {
  return (resources || []).filter((resource) => (
    resource
    && resource.category === "Lesson Plans"
    && resource._curriculumManaged
    && isResourceVisibleToCurrentUser(resource)
    && String(resource.plan || "Free").trim() !== "Pro"
  ));
}

function homeCurriculumActivities() {
  return (resources || []).filter((resource) => (
    resource
    && resource.category === "Activity Center"
    && resource._curriculumManaged
    && isResourceVisibleToCurrentUser(resource)
    && String(resource.plan || "Free").trim() !== "Pro"
  ));
}

function pickHomeLessonPreviewPlans(limit = 5) {
  const freePlans = homeCurriculumLessonPlans();
  const selected = [];
  const used = new Set();
  for (const hint of HOME_LESSON_PREVIEW_HINTS) {
    const match = freePlans.find((plan) => {
      if (used.has(plan.id)) return false;
      const hay = `${plan.title || ""} ${plan.theme || ""}`.toLowerCase();
      return hay.includes(String(hint).toLowerCase());
    });
    if (match) {
      selected.push(match);
      used.add(match.id);
    }
    if (selected.length >= limit) break;
  }
  for (const plan of freePlans) {
    if (selected.length >= limit) break;
    if (used.has(plan.id)) continue;
    selected.push(plan);
    used.add(plan.id);
  }
  return selected;
}

function pickHomeActivityPreviews(limit = 6) {
  const activities = homeCurriculumActivities();
  const selected = [];
  const used = new Set();
  for (const category of HOME_ACTIVITY_CATEGORY_ORDER) {
    const match = activities.find((activity) => {
      if (used.has(activity.id)) return false;
      const cat = String(activity.activityCategory || activity.tags?.[0] || "").trim();
      return cat.toLowerCase() === category.toLowerCase();
    });
    if (match) {
      selected.push(match);
      used.add(match.id);
    }
    if (selected.length >= limit) break;
  }
  for (const activity of activities) {
    if (selected.length >= limit) break;
    if (used.has(activity.id)) continue;
    selected.push(activity);
    used.add(activity.id);
  }
  return selected;
}

function countLessonPlanDaysOrActivities(resource) {
  const plan = resource?._curriculumLessonPlan || {};
  const days = ["monday", "tuesday", "wednesday", "thursday", "friday"];
  let activityCount = 0;
  let dayCount = 0;
  days.forEach((day) => {
    const items = plan?.dailyPlans?.[day]?.items;
    if (Array.isArray(items) && items.length) {
      dayCount += 1;
      activityCount += items.length;
    }
  });
  if (activityCount > 0) return `${activityCount} activities · ${dayCount || 5} days`;
  return "5-day week";
}

function homeLessonPreviewCardHtml(resource) {
  const overview = String(resource.description || resource._curriculumLessonPlan?.weeklyOverview || "").trim();
  const shortOverview = overview.length > 140 ? `${overview.slice(0, 137)}…` : overview || "Play-based weekly lesson plan ready to preview.";
  return `
    <article class="llh-preview-card" data-home-preview-resource="${escapeHtml(resource.id)}">
      <div class="llh-preview-meta">
        <span class="llh-chip free">Free</span>
        <span>${escapeHtml(normalizeAgeGroup(resource.age) || resource.age || "All Ages")}</span>
        ${resource.theme ? `<span>${escapeHtml(resource.theme)}</span>` : ""}
      </div>
      <h3>${escapeHtml(resource.title)}</h3>
      <p>${escapeHtml(shortOverview)}</p>
      <p><strong>${escapeHtml(countLessonPlanDaysOrActivities(resource))}</strong></p>
      <button class="llh-btn llh-btn-secondary" type="button" data-home-open-preview="${escapeHtml(resource.id)}" data-home-preview-section="homeLessonPlans">View Lesson Plan</button>
    </article>
  `;
}

function homeActivityPreviewDescription(resource) {
  const activity = resource?._curriculumActivity || {};
  const candidates = [
    resource?.description,
    activity.description,
    resource?.objective,
    activity.objective,
    Array.isArray(activity.learningGoals) && activity.learningGoals.length
      ? activity.learningGoals.slice(0, 2).join(" · ")
      : "",
    Array.isArray(resource?.learningDomains) && resource.learningDomains.length
      ? `${resource.learningDomains.slice(0, 2).join(" · ")} focus`
      : "",
    resource?._curriculumParentTitle ? `From ${resource._curriculumParentTitle}` : "",
    activity.parentTitle ? `From ${activity.parentTitle}` : "",
    resource?.theme,
    activity.parentTheme,
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const seen = new Set();
  for (const candidate of candidates) {
    const key = candidate.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    return candidate;
  }
  const category = resource?.activityCategory || activity.activityCategory || "Activity";
  const age = normalizeAgeGroup(resource?.age || activity.parentAge) || "all ages";
  return `${category} for ${age}.`;
}

function homeActivityPreviewCardHtml(resource) {
  const category = resource.activityCategory || resource.tags?.[0] || "Activity";
  const overview = homeActivityPreviewDescription(resource);
  const shortOverview = overview.length > 120 ? `${overview.slice(0, 117)}…` : overview;
  return `
    <article class="llh-preview-card" data-home-preview-resource="${escapeHtml(resource.id)}">
      <div class="llh-preview-meta">
        <span>${escapeHtml(category)}</span>
        <span>${escapeHtml(normalizeAgeGroup(resource.age) || resource.age || "All Ages")}</span>
      </div>
      <h3>${escapeHtml(resource.title)}</h3>
      <p>${escapeHtml(shortOverview)}</p>
      <button class="llh-btn llh-btn-secondary" type="button" data-home-open-preview="${escapeHtml(resource.id)}" data-home-preview-section="homeActivities">View Activity</button>
    </article>
  `;
}

function publicActivityPreviewCtaHtml() {
  if (isLoggedIn() || hasAdminFullAccess()) return "";
  const foundingOpen = foundingOpenForAcquisition();
  const paidCta = foundingOpen
    ? `<button class="ghost-button" type="button" data-checkout-plan="founding">Upgrade to Pro — $19.99/month</button>`
    : `<button class="ghost-button" type="button" data-checkout-plan="monthly">Upgrade to Pro — $19.99/month</button>`;
  return `
    <section class="llh-public-preview-cta">
      <p>Create an account to save activities and use them in your weekly planning.</p>
      <div class="llh-public-preview-cta-actions">
        <button class="primary-button" type="button" data-action="start-free">Create Free Account</button>
        ${paidCta}
      </div>
    </section>
  `;
}

async function openHomePublicPreview(resourceId, sectionId = "") {
  const resource = (resources || []).find((item) => item.id === resourceId);
  if (!resource) return;
  captureHomePreviewScrollPosition(sectionId);
  lessonLibraryReturnView = "home";
  if (!canAccess(resource)) {
    openLockedResourcePreview(resource);
    return;
  }
  await openResourceViewer(resourceId, { returnTo: "" });
  if (!isLoggedIn() && !hasAdminFullAccess() && resource.category === "Activity Center") {
    const body = document.querySelector("#resourceViewerBody");
    if (body && !body.querySelector(".llh-public-preview-cta")) {
      body.insertAdjacentHTML("beforeend", publicActivityPreviewCtaHtml());
    }
  }
}

function renderHomeHeroInventory(data) {
  const host = document.querySelector("#homeHeroInventory");
  if (!host) return;
  const lessonPlanCount = Number(data?.lessonPlanCount || 0);
  const activityCount = Number(data?.activityCount || 0);
  if (!lessonPlanCount && !activityCount) {
    host.setAttribute("data-state", "loading");
    host.setAttribute("aria-busy", "true");
    host.innerHTML = `<p class="llh-hero-inventory-loading">Loading live curriculum inventory…</p>`;
    return;
  }
  const coverage = data?.ageCoverage || {};
  const coverageLabels = [];
  if (coverage.infant) coverageLabels.push("Infant");
  if (coverage.toddler) coverageLabels.push("Toddler");
  if (coverage.preschool) coverageLabels.push("Preschool");
  host.setAttribute("data-state", "ready");
  host.setAttribute("aria-busy", "false");
  host.innerHTML = `
    <ul class="llh-hero-inventory-list" aria-label="Published curriculum inventory">
      <li><strong>${lessonPlanCount}</strong> published lesson plans</li>
      <li><strong>${activityCount}</strong> published activities</li>
      <li><span class="llh-hero-inventory-coverage">Coverage: <strong>${escapeHtml(coverageLabels.join(", ") || "All ages")}</strong></span></li>
    </ul>
  `;
}

let homeHeroInventoryPromise = null;

async function refreshHomeHeroInventory() {
  const host = document.querySelector("#homeHeroInventory");
  if (!host || currentUser || !canUseLaunchBackend()) return;
  if (homeHeroInventoryPromise) return homeHeroInventoryPromise;
  homeHeroInventoryPromise = (async () => {
    try {
      const response = await fetch(`/api/public/home-inventory?t=${Date.now()}`, { cache: "no-store" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data?.ok) throw new Error(data?.error || "inventory_unavailable");
      renderHomeHeroInventory(data);
    } catch (error) {
      host.setAttribute("data-state", "unavailable");
      host.setAttribute("aria-busy", "false");
      host.innerHTML = `<p class="llh-hero-inventory-fallback muted-copy">Live curriculum inventory is temporarily unavailable.</p>`;
    } finally {
      homeHeroInventoryPromise = null;
    }
  })();
  return homeHeroInventoryPromise;
}

function renderHomePublicPreviews() {
  const lessonGrid = document.querySelector("#homeLessonPreviewGrid");
  const activityGrid = document.querySelector("#homeActivityPreviewGrid");
  if (lessonGrid) {
    const lessons = pickHomeLessonPreviewPlans(5);
    if (lessons.length) {
      lessonGrid.innerHTML = lessons.map(homeLessonPreviewCardHtml).join("");
    } else if (curriculumLibraryLoading || siteContentLoadPromise) {
      lessonGrid.innerHTML = `<div class="llh-preview-empty muted-copy" role="status">Loading free lesson plan previews…</div>`;
    } else if (curriculumLibraryLoadFailed) {
      lessonGrid.innerHTML = `<div class="llh-preview-empty muted-copy" role="alert">Lesson plan previews could not load. <button class="link-button" type="button" data-retry-curriculum-library>Retry</button></div>`;
    } else {
      lessonGrid.innerHTML = `<div class="llh-preview-empty muted-copy">Free lesson plan previews will appear here as published curriculum is available. <button class="link-button" type="button" data-retry-curriculum-library>Retry</button> · <button class="link-button" type="button" data-view="lessons">Browse Lesson Plans</button></div>`;
    }
  }
  if (activityGrid) {
    const activities = pickHomeActivityPreviews(6);
    if (activities.length) {
      activityGrid.innerHTML = activities.map(homeActivityPreviewCardHtml).join("");
    } else if (curriculumLibraryLoading || siteContentLoadPromise) {
      activityGrid.innerHTML = `<div class="llh-preview-empty muted-copy" role="status">Loading activity previews…</div>`;
    } else if (curriculumLibraryLoadFailed) {
      activityGrid.innerHTML = `<div class="llh-preview-empty muted-copy" role="alert">Activity previews could not load. <button class="link-button" type="button" data-retry-curriculum-library>Retry</button></div>`;
    } else {
      activityGrid.innerHTML = `<div class="llh-preview-empty muted-copy">Activity previews will appear here as published activities are available. <button class="link-button" type="button" data-retry-curriculum-library>Retry</button> · <button class="link-button" type="button" data-view="activities">Browse Activities</button></div>`;
    }
  }
}

function renderHome() {
  if (currentUser) {
    if (isWorkModeNavEnabled() && (workModeRole() === "owner" || workModeRole() === "director")) {
      renderOwnerHomeDashboard();
      updatePlanLabel();
      return;
    }
    if (isWorkModeNavEnabled()) {
      updatePlanLabel();
      setView(workModeLandingView(), { allowDashboard: true, skipAccessRedirect: true });
      return;
    }
    renderUserDashboard();
    updatePlanLabel();
    return;
  }
  const homeSection = document.querySelector("#view-home");
  if (homeSection) {
    homeSection.classList.add("landing-home");
    homeSection.classList.remove("user-dashboard-view");
  }
  if (!document.querySelector("#homePricing")) {
    if (homeSection) homeSection.innerHTML = homeViewTemplate;
  }
  renderManagedHomeContent();
  renderManagedPricingText();
  renderManagedFaqContent();
  renderManagedAnnouncementBanner();
  const stats = {
    total: resources.length,
    lessons: resources.filter((resource) => resource.category === "Lesson Plans").length,
    observations: resources.filter((resource) => resource.category === "Observation Hub").length,
    downloads: resources.filter((resource) => ["Forms Library", "Menu Center"].includes(resource.category)).length,
  };
  const homeStats = document.querySelector("#homeStats");
  if (homeStats) {
    homeStats.innerHTML = `
      <div><strong>${stats.total}</strong><span>ready-made resources</span></div>
      <div><strong>${stats.lessons}</strong><span>lesson plans</span></div>
      <div><strong>${stats.observations}</strong><span>observations</span></div>
      <div><strong>${stats.downloads}</strong><span>in-app resources</span></div>
    `;
  }
  const categoryGrid = document.querySelector("#categoryGrid");
  if (categoryGrid) {
    categoryGrid.innerHTML = categories.filter((category) => isCategoryVisibleToCurrentUser(category.title)).map((category) => `
      <button class="category-button" data-view="${category.view}">
        <span class="icon">${category.icon}</span>
        <strong>${category.title}</strong>
        <span>${category.detail}</span>
      </button>
    `).join("");
  }

  const newItems = resources.filter((resource) => resource.month === "June" && isResourceVisibleToCurrentUser(resource)).slice(0, 4);
  const newThisMonth = document.querySelector("#newThisMonth");
  if (newThisMonth) newThisMonth.innerHTML = newItems.map(compactItem).join("");
  renderHomeFoundingOffer();
  renderHomePublicPreviews();
  refreshHomeHeroInventory().catch(() => {});
  bindHomePublicChrome();
  const footerYear = document.querySelector("#llhFooterYear");
  if (footerYear) footerYear.textContent = String(new Date().getFullYear());
  if (canUseLaunchBackend()) {
    syncFoundingStatus({ render: true }).catch(() => {});
    refreshPublicCurriculumLibrary()
      .catch(() => {})
      .then(() => {
        if (document.querySelector("#view-home.landing-home") && !currentUser) {
          renderHomePublicPreviews();
        }
      });
  }
  renderPreviewLibrary();
  renderFavorites();
  updatePlanLabel();
}

function weekStartDate(date = new Date()) {
  const monday = new Date(date);
  const day = monday.getDay() || 7;
  monday.setHours(0, 0, 0, 0);
  monday.setDate(monday.getDate() - day + 1);
  return monday;
}

function isoDateFromLocalDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function addDaysToIso(iso, days) {
  const date = new Date(`${String(iso || "").slice(0, 10)}T12:00:00`);
  if (Number.isNaN(date.getTime())) return "";
  date.setDate(date.getDate() + Number(days || 0));
  return isoDateFromLocalDate(date);
}

function isoWeekdayIndex(iso) {
  const date = new Date(`${String(iso || "").slice(0, 10)}T12:00:00`);
  return Number.isNaN(date.getTime()) ? -1 : date.getDay();
}

function isoIsWeekend(iso) {
  const dow = isoWeekdayIndex(iso);
  return dow === 0 || dow === 6;
}

function calendarLongDateLabel(iso) {
  const date = new Date(`${String(iso || "").slice(0, 10)}T12:00:00`);
  if (Number.isNaN(date.getTime())) return iso || "";
  return date.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" });
}

function curriculumDayKeyForIso(iso) {
  const dow = isoWeekdayIndex(iso);
  const index = dow - 1; // Mon=1 -> 0 ... Fri=5 -> 4
  return index >= 0 && index < CURRICULUM_WEEKDAYS.length ? CURRICULUM_WEEKDAYS[index] : "";
}

function plannerWeekIndex(weekOf) {
  const [year, month, day] = String(weekOf || "").split("-").map(Number);
  if (!year || !month || !day) return 0;
  const baseWeek = Date.UTC(2026, 0, 5);
  const selectedWeek = Date.UTC(year, month - 1, day);
  return Math.floor((selectedWeek - baseWeek) / (7 * 24 * 60 * 60 * 1000));
}

function plannerThemeForWeek(weekOf) {
  const index = plannerWeekIndex(weekOf);
  return lessonThemes[((index % lessonThemes.length) + lessonThemes.length) % lessonThemes.length];
}

function plannerFocusForTheme(theme) {
  const lowerTheme = String(theme || "").toLowerCase();
  if (lowerTheme.includes("feel") || lowerTheme.includes("friend")) return "Social emotional skills, language, and cooperative play";
  if (lowerTheme.includes("letters")) return "Early literacy, letter sounds, and fine motor practice";
  if (lowerTheme.includes("numbers") || lowerTheme.includes("shapes") || lowerTheme.includes("colors")) return "Early math, vocabulary, and hands-on exploration";
  if (lowerTheme.includes("healthy")) return "Self help skills, routines, and body awareness";
  if (lowerTheme.includes("music")) return "Language, movement, and listening skills";
  return "Language, fine motor, and social emotional skills";
}

function defaultPlanner(date = new Date()) {
  const monday = weekStartDate(date);
  const weekOf = isoDateFromLocalDate(monday);
  const theme = plannerThemeForWeek(weekOf);
  return {
    weekOf,
    ageGroup: "Toddler",
    theme,
    focus: plannerFocusForTheme(theme),
    notes: "Keep activities low-prep, flexible, and easy to repeat.",
    resourceId: "",
    days: Object.fromEntries(plannerDays.map((plannerDay) => [plannerDay, {
      circle: "",
      activity: "",
      meal: "",
      rest: "",
      support: "",
    }])),
  };
}

function currentWeekPlanner(existing = weeklyPlanner()) {
  const planner = defaultPlanner();
  return {
    ...planner,
    ageGroup: existing?.ageGroup || planner.ageGroup,
  };
}

function weeklyPlanner() {
  const saved = readSavedJson("llhWeeklyPlanner", null);
  const planner = { ...defaultPlanner(), ...(saved || {}) };
  planner.days = { ...defaultPlanner().days, ...(planner.days || {}) };
  return planner;
}

function saveWeeklyPlanner(planner) {
  localStorage.setItem("llhWeeklyPlanner", JSON.stringify(planner));
  updateSidebarDashboard();
}

function plannerSuggestions(planner) {
  const query = [planner.theme, planner.ageGroup, planner.focus].join(" ").toLowerCase();
  return resources
    .filter((resource) => ["Lesson Plans", "Activity Center", "Menu Center"].includes(resource.category))
    .filter((resource) => isResourceVisibleToCurrentUser(resource))
    .filter((resource) => canAccess(resource))
    .map((resource) => {
      const haystack = [resource.title, resource.age, resource.description, ...resource.tags].join(" ").toLowerCase();
      const score = query.split(/\s+/).filter((word) => word.length > 2 && haystack.includes(word)).length;
      return { resource, score };
    })
    .filter((item) => item.score > 0 || item.resource.age === planner.ageGroup || item.resource.age === "All Ages")
    .sort((a, b) => b.score - a.score)
    .slice(0, 6)
    .map((item) => item.resource);
}

function plannerResourceOptions(planner) {
  const suggested = plannerSuggestions(planner);
  const selected = resources.find((resource) => resource.id === planner.resourceId);
  const options = selected && !suggested.some((resource) => resource.id === selected.id)
    ? [selected, ...suggested]
    : suggested;
  return [
    `<option value="">No library resource selected</option>`,
    ...options.map((resource) => `<option value="${resource.id}" ${resource.id === planner.resourceId ? "selected" : ""}>${resource.title} - ${resource.category}</option>`),
  ].join("");
}

function weeklyPlannerDayKeyFromDate(date = new Date()) {
  const key = CURRICULUM_WEEKDAYS[(date.getDay() + 6) % 7] || "monday";
  return key;
}

function setWeeklyPlannerActiveDay(day, options = {}) {
  const next = CURRICULUM_WEEKDAYS.includes(day) ? day : "monday";
  weeklyPlannerActiveDay = next;
  if (options.openNotes) {
    weeklyPlannerNotesOpen = true;
    weeklyPlannerEditDay = "";
  }
  if (options.closeNotes) weeklyPlannerNotesOpen = false;
  if (weeklyPlannerEditDay) {
    weeklyPlannerEditDay = next;
    renderWeeklyPlanner();
    return;
  }
  const app = document.querySelector("#weeklyPlannerApp");
  if (!app) return;
  app.querySelectorAll("[data-week-day-tab]").forEach((tab) => {
    const active = tab.dataset.weekDayTab === next;
    tab.classList.toggle("is-active", active);
    tab.setAttribute("aria-selected", active ? "true" : "false");
  });
  app.querySelectorAll("[data-week-day-card]").forEach((card) => {
    card.classList.toggle("is-active", card.dataset.weekDayCard === next);
  });
  const panel = app.querySelector("[data-week-notes-panel]");
  if (panel) {
    panel.classList.toggle("is-open", weeklyPlannerNotesOpen);
    panel.hidden = !weeklyPlannerNotesOpen;
    const label = panel.querySelector("[data-week-notes-day-label]");
    if (label) label.textContent = curriculumPlannerWeekdayLabel(next);
    // Move focus fields to match active day without full re-render when possible
    panel.querySelectorAll("[data-schedule-day-note], [data-schedule-day-obs]").forEach((input) => {
      const forDay = input.dataset.scheduleDayNote || input.dataset.scheduleDayObs;
      input.closest(".llh-week-notes-day")?.classList.toggle("is-active", forDay === next);
    });
  }
  // Keep active card scrolled into view on mobile horizontal board
  const activeCard = app.querySelector(`.llh-day-card.is-active`);
  if (activeCard && typeof activeCard.scrollIntoView === "function") {
    activeCard.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
  }
}

function weeklyPlannerMaterialsForDay(planDay = {}, snapshot = {}) {
  const fromItems = (Array.isArray(planDay.items) ? planDay.items : [])
    .map((item) => String(item.materials || item.material || "").trim())
    .filter(Boolean);
  if (fromItems.length) return [...new Set(fromItems)].slice(0, 6);
  const weekly = String(snapshot.weeklyMaterials || "").trim();
  if (!weekly) return [];
  return weekly.split(/[\n,;]+/).map((part) => part.trim()).filter(Boolean).slice(0, 6);
}

function syncWeeklyPlanPageTitle(mode = weeklyPlanScreenMode) {
  const titleBlock = document.querySelector("[data-weekly-plan-page-title]");
  if (!titleBlock) return;
  const eyebrow = titleBlock.querySelector(".eyebrow");
  const heading = titleBlock.querySelector("h2");
  if (eyebrow) eyebrow.textContent = mode === "edit" ? "Edit assigned week" : "Calendar week";
  if (heading) heading.textContent = mode === "edit" ? "Edit Week" : "View Weekly Plan";
}

function weeklyPlanActivityLibraryOptionsHtml(selectedTitle = "") {
  const library = (Array.isArray(resources) ? resources : [])
    .filter((item) => item.category === "Activities" && isResourceVisibleToCurrentUser(item))
    .slice(0, 80);
  const options = [
    `<option value="">Keep current / custom title</option>`,
    ...library.map((item) => {
      const title = String(item.title || "").trim();
      if (!title) return "";
      return `<option value="${escapeHtml(title)}" ${selectedTitle === title ? "selected" : ""}>${escapeHtml(title)}</option>`;
    }).filter(Boolean),
  ];
  return options.join("");
}

function weeklyPlanViewDayHtml(scheduleItem, day, weekStart, snapshot) {
  const planDay = snapshot.dailyPlans?.[day] || {};
  const activities = Array.isArray(planDay.items) ? planDay.items : [];
  const materials = weeklyPlannerMaterialsForDay(planDay, snapshot);
  const dayNote = scheduleItem.execution?.dailyTeacherNotes?.[day] || "";
  const materialsLine = materials.join(" · ");
  return `
    <article class="llh-weekly-plan-day" data-weekly-plan-day="${escapeHtml(day)}">
      <header class="llh-weekly-plan-day-head">
        <div>
          <p class="eyebrow">${escapeHtml(curriculumPlannerWeekdayLabel(day))}</p>
          <h3>${escapeHtml(planDay.theme || snapshot.theme || curriculumPlannerWeekdayLabel(day))}</h3>
          <p class="muted-copy">${escapeHtml(curriculumPlannerDateForDay(weekStart, day))}</p>
        </div>
      </header>
      <div class="llh-weekly-plan-day-body">
        <div class="llh-weekly-plan-section">
          <p class="eyebrow">Activities</p>
          ${activities.length
            ? `<ul class="llh-weekly-plan-activity-list">${activities.map((item) => `
                <li>
                  <strong>${escapeHtml(item.title || "Activity")}</strong>
                  ${item.materials ? `<span class="muted-copy">${escapeHtml(item.materials)}</span>` : ""}
                  ${item.description || item.objective
                    ? `<span class="muted-copy">${escapeHtml(item.description || item.objective || "")}</span>`
                    : ""}
                </li>`).join("")}</ul>`
            : `<p class="muted-copy">No activities</p>`}
        </div>
        <div class="llh-weekly-plan-section">
          <p class="eyebrow">Materials</p>
          ${materialsLine
            ? `<p>${escapeHtml(materialsLine)}</p>`
            : `<p class="muted-copy">None listed</p>`}
        </div>
        <div class="llh-weekly-plan-section">
          <p class="eyebrow">Daily notes</p>
          ${dayNote
            ? `<p>${escapeHtml(dayNote)}</p>`
            : `<p class="muted-copy">No notes yet</p>`}
        </div>
      </div>
    </article>
  `;
}

function weeklyPlanEditDayHtml(scheduleItem, day, weekStart, snapshot) {
  const planDay = snapshot.dailyPlans?.[day] || {};
  const activities = Array.isArray(planDay.items) ? planDay.items : [];
  const dayNote = scheduleItem.execution?.dailyTeacherNotes?.[day] || "";
  const rows = (activities.length ? activities : []).map((activity, index) => `
    <div class="llh-week-edit-activity-row" data-week-edit-activity-row data-week-edit-from-day="${escapeHtml(day)}">
      <input type="hidden" data-week-edit-activity-id value="${escapeHtml(ensureClassroomCopyActivityId(activity))}" />
      <label class="llh-week-edit-field">Activity ${index + 1}
        <input type="text" data-week-edit-activity-title value="${escapeHtml(activity.title || "")}" placeholder="Activity title" />
      </label>
      <label class="llh-week-edit-field">Materials
        <input type="text" data-week-edit-activity-materials value="${escapeHtml(activity.materials || "")}" placeholder="Optional materials" />
      </label>
      <label class="llh-week-edit-field">Day
        <select data-week-edit-activity-day>
          ${CURRICULUM_WEEKDAYS.map((optionDay) => `
            <option value="${escapeHtml(optionDay)}" ${optionDay === day ? "selected" : ""}>${escapeHtml(curriculumPlannerWeekdayLabel(optionDay))}</option>
          `).join("")}
        </select>
      </label>
      <label class="llh-week-edit-field">Replace from Activity Library
        <select data-week-edit-activity-replace>
          ${weeklyPlanActivityLibraryOptionsHtml(activity.title || "")}
        </select>
      </label>
      <button type="button" class="ghost-button" data-week-edit-remove-activity aria-label="Remove activity">Remove</button>
    </div>
  `).join("");
  return `
    <section class="llh-weekly-plan-edit-day" data-week-edit-day-block="${escapeHtml(day)}">
      <header>
        <h3>${escapeHtml(curriculumPlannerWeekdayLabel(day))}</h3>
        <p class="muted-copy">${escapeHtml(curriculumPlannerDateForDay(weekStart, day))}</p>
      </header>
      <label class="llh-week-edit-field">Day theme
        <input type="text" data-week-edit-day-theme value="${escapeHtml(planDay.theme || "")}" placeholder="Optional day theme" />
      </label>
      <div class="llh-week-edit-activities" data-week-edit-activities="${escapeHtml(day)}">
        ${rows || `<p class="muted-copy" data-week-edit-empty>No activities yet. Add one below.</p>`}
      </div>
      <div class="form-actions">
        <button type="button" class="ghost-button" data-week-edit-add-activity data-week-edit-add-day="${escapeHtml(day)}">Add activity</button>
        <button type="button" class="ghost-button" data-week-edit-add-custom data-week-edit-add-day="${escapeHtml(day)}">Add custom activity</button>
      </div>
      <label class="llh-week-edit-field">Daily notes
        <textarea rows="3" data-week-edit-day-note="${escapeHtml(day)}" placeholder="Prep, transitions, reminders…">${escapeHtml(dayNote)}</textarea>
      </label>
    </section>
  `;
}

