/* ─── Phase F1/F2/F3: Curriculum Planner ───
 * F3 Parent Calendar: Classroom Events such as Water Day, Pajama Day,
 * Field Trip, Picture Day, Grandparents Day, Holiday Parties,
 * Special Visitors, Items to Bring, School Closures, Important Reminders.
 * F2 teacherNotes / dailyTeacherNotes / observations are PRIVATE and must
 * never appear in parentCalendar DTOs, previews, printouts, or exports.
 */

const CURRICULUM_CLASSROOM_EVENT_TYPES = [
  "Water Day",
  "Pajama Day",
  "Field Trip",
  "Picture Day",
  "Grandparents Day",
  "Holiday Party",
  "Special Visitor",
  "Items to Bring",
  "School Closure",
  "Important Reminder",
  "Other",
];
function curriculumPlannerWeekStartIso(value = new Date()) {
  const date = value instanceof Date ? value : new Date(`${String(value || "").slice(0, 10)}T12:00:00`);
  if (Number.isNaN(date.getTime())) return isoDateFromLocalDate(weekStartDate(new Date()));
  return isoDateFromLocalDate(weekStartDate(date));
}

function curriculumPlannerWeekEndIso(weekStart) {
  const start = new Date(`${curriculumPlannerWeekStartIso(weekStart)}T12:00:00`);
  start.setDate(start.getDate() + 4);
  return isoDateFromLocalDate(start);
}

function curriculumPlannerWeekdayLabel(dayKey) {
  const key = String(dayKey || "").toLowerCase();
  return key ? key.charAt(0).toUpperCase() + key.slice(1) : "";
}

function curriculumPlannerDateForDay(weekStart, dayKey) {
  const index = CURRICULUM_WEEKDAYS.indexOf(String(dayKey || "").toLowerCase());
  if (index < 0) return "";
  const date = new Date(`${curriculumPlannerWeekStartIso(weekStart)}T12:00:00`);
  date.setDate(date.getDate() + index);
  return isoDateFromLocalDate(date);
}

function curriculumAssignmentsStoreKey() {
  return currentUser ? `llhCurriculumAssignments:${currentUser}` : "llhCurriculumAssignments:guest";
}

function scheduleApiEmail() {
  return currentUser || "";
}

function getScheduleApi() {
  return window.LLHSchedule || null;
}

/** Rollback: localStorage.setItem('llhCurriculumPlannerLegacy','1') then reload */
function isCurriculumPlannerLegacyEnabled() {
  try {
    return localStorage.getItem("llhCurriculumPlannerLegacy") === "1";
  } catch {
    return false;
  }
}

let pendingCurriculumPlannerRetirementNotice = false;

function syncCurriculumPlannerNavVisibility() {
  const showLegacy = isCurriculumPlannerLegacyEnabled();
  document.querySelectorAll('[data-view="curriculum-planner"]').forEach((button) => {
    button.hidden = !showLegacy;
    button.setAttribute("aria-hidden", showLegacy ? "false" : "true");
    if (showLegacy) button.removeAttribute("tabindex");
    else button.setAttribute("tabindex", "-1");
  });
  document.body.classList.toggle("curriculum-planner-retired", !showLegacy);
}

function curriculumPlannerRetirementBannerHtml() {
  if (!pendingCurriculumPlannerRetirementNotice) return "";
  pendingCurriculumPlannerRetirementNotice = false;
  return `
    <div class="llh-calendar-retire-banner" role="status">
      <p><strong>Curriculum Planner has moved.</strong> Plan weeks and assign lesson plans here in Calendar. Open View Weekly Plan for that week.</p>
      <button type="button" class="ghost-button" data-view="planner">View Weekly Plan</button>
    </div>
  `;
}

async function ensureScheduleLoaded(options = {}) {
  const api = getScheduleApi();
  if (!api) return null;
  if (scheduleDocCache && !options.force && scheduleSyncState === "ready") return scheduleDocCache;
  if (scheduleDocCache && !options.force && scheduleSyncState === "error" && !options.retry) {
    return scheduleDocCache;
  }
  if (scheduleSyncPromise && !options.force) return scheduleSyncPromise;
  scheduleSyncState = "loading";
  scheduleSyncError = "";
  scheduleSyncPromise = (async () => {
    const email = scheduleApiEmail();
    if (!email) {
      scheduleDocCache = api.emptyDoc();
      scheduleSyncState = "ready";
      scheduleSyncSynced = false;
      return scheduleDocCache;
    }
    const localBefore = api.readCache(email);
    let lastError = "";
    for (let attempt = 0; attempt < 4; attempt += 1) {
      try {
        const migratedFlag = localStorage.getItem(`llhScheduleMigrated:${email}`);
        if (!migratedFlag || options.forceMigrate) {
          const legacy = loadCurriculumWeekAssignments();
          const planner = typeof weeklyPlanner === "function" ? weeklyPlanner() : null;
          await api.migrateFromLegacy(firebaseAuthHeaders, email, {
            curriculumAssignments: legacy,
            weeklyPlanner: planner,
            force: Boolean(options.forceMigrate),
          });
        }
        const fetched = await api.fetchSchedule(firebaseAuthHeaders, email);
        const merged = api.mergeScheduleDocs
          ? api.mergeScheduleDocs(localBefore, fetched || api.emptyDoc())
          : (fetched || localBefore);
        // Guard: never drop local items on refresh.
        if ((localBefore.items || []).length > (merged.items || []).length) {
          scheduleDocCache = api.mergeScheduleDocs(merged, localBefore);
          api.writeCache(email, scheduleDocCache);
        } else {
          scheduleDocCache = {
            classrooms: merged.classrooms,
            items: merged.items,
            updatedAt: merged.updatedAt,
            schemaVersion: 1,
          };
          api.writeCache(email, scheduleDocCache);
        }
        const synced = fetched?._synced !== false;
        scheduleSyncSynced = synced;
        if (synced) {
          scheduleSyncState = "ready";
          scheduleSyncError = "";
          return scheduleDocCache;
        }
        lastError = fetched?._syncError || "Calendar is waking up. Tap Retry in a moment.";
        if (attempt < 3) await delayMs(400 * (attempt + 1));
      } catch (error) {
        lastError = error?.message || "Calendar is waking up. Tap Retry in a moment.";
        if (attempt < 3) await delayMs(400 * (attempt + 1));
      }
    }
    scheduleDocCache = api.readCache(email) || localBefore || api.emptyDoc();
    scheduleSyncState = "error";
    scheduleSyncError = lastError || "Calendar could not sync. Showing your saved copy.";
    scheduleSyncSynced = false;
    return scheduleDocCache;
  })().finally(() => {
    scheduleSyncPromise = null;
  });
  return scheduleSyncPromise;
}

function calendarScheduleStatusHtml() {
  if (scheduleSyncState === "loading") {
    return `<div class="llh-calendar-sync-banner is-loading" role="status" data-calendar-sync-banner>
      <p>Loading your calendar…</p>
    </div>`;
  }
  if (scheduleSyncState === "error" && scheduleSyncError) {
    return `<div class="llh-calendar-sync-banner is-error" role="alert" data-calendar-sync-banner>
      <div>
        <p><strong>Calendar sync paused.</strong> ${escapeHtml(scheduleSyncError)}</p>
        <p class="muted-copy">Your notes and plans are kept on this device until sync finishes.</p>
      </div>
      <button type="button" class="primary-button" data-calendar-retry-sync>Retry</button>
    </div>`;
  }
  return "";
}

