function finishCalendarLessonAssignSuccess(assignment) {
  const week = assignment?.weekStartDate || calendarLessonAssignContext?.weekStartDate || "";
  const title = assignment?.lessonPlanTitle || assignment?.title || "Lesson plan";
  pendingCalendarAssignNotice = week
    ? `Added “${title}” to the week of ${week}. Customize days, then print your week-at-a-glance.`
    : `Added “${title}” to your Calendar.`;
  clearCalendarLessonAssignContext();
  toggleLessonWorkspaceActionSheet(false);
  dismissResourceViewerForNavigation();
  mainCalendarSelectedWeek = week || mainCalendarSelectedWeek;
  mainCalendarSubView = week ? "week" : "month";
  setView("calendar", week ? { weekStartDate: week } : {});
}

function scheduleClassroomName(doc) {
  return doc?.classrooms?.[0]?.name || "Main Classroom";
}

function dualWriteLegacyAssignmentsFromSchedule(doc) {
  const api = getScheduleApi();
  if (!api || !currentUser) return;
  const classroomName = scheduleClassroomName(doc);
  const legacy = (doc.items || [])
    .filter((item) => item.type === "lesson_plan")
    .map((item) => api.scheduleItemToLegacyAssignment(item, classroomName))
    .filter(Boolean)
    .map(normalizeCurriculumWeekAssignment);
  legacy.sort((a, b) => String(b.weekStartDate || "").localeCompare(String(a.weekStartDate || "")));
  saveCurriculumWeekAssignments(legacy);
}

function syncWeeklyPlannerFromScheduleItem(item) {
  const api = getScheduleApi();
  if (!api || !item) return null;
  const planner = api.buildPlannerFromLessonItem(item);
  if (!planner) return null;
  saveWeeklyPlanner({ ...weeklyPlanner(), ...planner, days: { ...weeklyPlanner().days, ...planner.days } });
  return planner;
}

function classroomCopyActivityKey(item = {}) {
  return String(item.itemId || item.id || item.title || "").trim();
}

function ensureClassroomCopyActivityId(item = {}) {
  const existing = String(item.itemId || item.id || "").trim();
  if (existing) return existing;
  const api = getScheduleApi();
  return api?.randomId ? api.randomId("act") : `act-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
}

/**
 * Update the classroom ScheduleItem.snapshot only — never mutates the library
 * curriculum lesson plan. Keeps Weekly Planner + Calendar in sync via dual-write.
 */
async function updateScheduleLessonSnapshot(itemId, patchFn) {
  const api = getScheduleApi();
  if (!api || !itemId) return null;
  if (!isLoggedIn() && !hasAdminFullAccess()) {
    openAuthModal("login");
    throw new Error("Log in to customize your classroom copy.");
  }
  await ensureScheduleLoaded();
  const doc = scheduleDocCache || api.readCache(scheduleApiEmail());
  const item = (doc.items || []).find((entry) => entry.id === itemId);
  if (!item || item.type !== "lesson_plan") {
    throw new Error("No classroom lesson plan found for this week.");
  }
  const snapshot = JSON.parse(JSON.stringify(item.snapshot || {}));
  const patched = typeof patchFn === "function" ? (patchFn(snapshot) || snapshot) : snapshot;
  const dailyPlans = {};
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const dayPlan = patched.dailyPlans?.[day] || {};
    const normalized = snapshotCurriculumDailyDay(dayPlan);
    normalized.items = (Array.isArray(dayPlan.items) ? dayPlan.items : [])
      .map((activity) => {
        const next = snapshotCurriculumDailyItem({
          ...activity,
          itemId: ensureClassroomCopyActivityId(activity),
        });
        return next;
      })
      .filter((activity) => activity.title);
    dailyPlans[day] = normalized;
  });
  const nextSnapshot = {
    ...patched,
    dailyPlans,
    snapshotEditedAt: new Date().toISOString(),
    snapshotSourceLessonPlanId: item.lessonPlanId || patched.snapshotSourceLessonPlanId || "",
  };
  await api.upsertItem(firebaseAuthHeaders, scheduleApiEmail(), {
    ...item,
    snapshot: nextSnapshot,
    lessonPlanTitle: nextSnapshot.title || item.lessonPlanTitle,
  });
  scheduleDocCache = api.readCache(scheduleApiEmail());
  dualWriteLegacyAssignmentsFromSchedule(scheduleDocCache);
  const latest = (scheduleDocCache.items || []).find((entry) => entry.id === itemId) || item;
  syncWeeklyPlannerFromScheduleItem(latest);
  return latest;
}

function openWeeklyPlannerDayEditor(dayKey, options = {}) {
  const day = CURRICULUM_WEEKDAYS.includes(dayKey) ? dayKey : weeklyPlannerActiveDay || "monday";
  weeklyPlannerNotesOpen = false;
  weeklyPlannerEditDay = "";
  weeklyPlanScreenMode = "edit";
  if (options.weekStartDate) {
    weeklyPlannerFocusWeek = curriculumPlannerWeekStartIso(options.weekStartDate);
  }
  setWeeklyPlannerActiveDay(day);
  if (document.querySelector("#view-planner.active-view")) {
    renderWeeklyPlanner();
  } else {
    setView("planner", {
      weekStartDate: weeklyPlannerFocusWeek || undefined,
      mode: "edit",
    });
  }
  queueMicrotask(() => {
    document.querySelector(`[data-week-edit-day-block="${day}"]`)?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

function closeWeeklyPlannerDayEditor() {
  weeklyPlannerEditDay = "";
  weeklyPlanScreenMode = "view";
  renderWeeklyPlanner();
}

function weeklyPlannerDayEditorHtml(scheduleItem, day) {
  const planDay = scheduleItem?.snapshot?.dailyPlans?.[day] || {};
  const activities = Array.isArray(planDay.items) ? planDay.items : [];
  const rows = (activities.length ? activities : [{ title: "" }]).map((activity, index) => `
    <div class="llh-week-edit-activity-row" data-week-edit-activity-row>
      <input type="hidden" data-week-edit-activity-id value="${escapeHtml(ensureClassroomCopyActivityId(activity))}" />
      <label class="llh-week-edit-field">Activity ${index + 1}
        <input type="text" data-week-edit-activity-title value="${escapeHtml(activity.title || "")}" placeholder="Activity title" />
      </label>
      <label class="llh-week-edit-field">Materials
        <input type="text" data-week-edit-activity-materials value="${escapeHtml(activity.materials || "")}" placeholder="Optional materials" />
      </label>
      <button type="button" class="ghost-button" data-week-edit-remove-activity aria-label="Remove activity">Remove</button>
    </div>
  `).join("");
  return `
    <aside class="llh-week-edit-panel is-open" data-week-edit-panel>
      <div class="llh-week-notes-head">
        <div>
          <p class="eyebrow">Classroom copy</p>
          <h3>Edit ${escapeHtml(curriculumPlannerWeekdayLabel(day))}</h3>
          <p class="muted-copy">Changes stay on your Calendar week — the Lesson Library original is not changed.</p>
        </div>
        <button type="button" class="ghost-button" data-week-edit-cancel>Cancel</button>
      </div>
      <label class="llh-week-edit-field">Day theme
        <input type="text" data-week-edit-day-theme value="${escapeHtml(planDay.theme || "")}" placeholder="Optional day theme" />
      </label>
      <div class="llh-week-edit-activities" data-week-edit-activities>
        ${rows}
      </div>
      <div class="form-actions">
        <button type="button" class="ghost-button" data-week-edit-add-activity>Add activity</button>
        <button type="button" class="primary-button" data-week-edit-save="${escapeHtml(scheduleItem.id)}" data-week-edit-save-day="${escapeHtml(day)}" ${weeklyPlannerEditBusy ? "disabled" : ""}>${weeklyPlannerEditBusy ? "Saving…" : "Save classroom day"}</button>
      </div>
      <p class="muted-copy llh-week-edit-status" data-week-edit-status hidden></p>
    </aside>
  `;
}

async function saveWeeklyPlannerDayEditor(itemId, day) {
  const panel = document.querySelector("[data-week-edit-panel]");
  const status = document.querySelector("[data-week-edit-status]");
  const saveBtn = document.querySelector("[data-week-edit-save]");
  if (!panel || !itemId || !day) return;
  const theme = String(panel.querySelector("[data-week-edit-day-theme]")?.value || "").trim();
  const rows = [...panel.querySelectorAll("[data-week-edit-activity-row]")];
  const items = rows.map((row) => ({
    itemId: String(row.querySelector("[data-week-edit-activity-id]")?.value || "").trim(),
    title: String(row.querySelector("[data-week-edit-activity-title]")?.value || "").trim(),
    materials: String(row.querySelector("[data-week-edit-activity-materials]")?.value || "").trim(),
  })).filter((item) => item.title);
  weeklyPlannerEditBusy = true;
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = "Saving…";
  }
  if (status) {
    status.hidden = false;
    status.textContent = "Saving classroom copy…";
    status.classList.remove("is-error");
  }
  try {
    await updateScheduleLessonSnapshot(itemId, (snapshot) => {
      const dailyPlans = { ...(snapshot.dailyPlans || {}) };
      const current = dailyPlans[day] || {};
      dailyPlans[day] = {
        ...current,
        theme,
        items,
      };
      return { ...snapshot, dailyPlans };
    });
    weeklyPlannerEditBusy = false;
    weeklyPlannerEditDay = "";
    renderWeeklyPlanner();
    if (document.querySelector("#view-calendar.active-view")) renderMainCalendar();
  } catch (error) {
    weeklyPlannerEditBusy = false;
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.textContent = "Save classroom day";
    }
    if (status) {
      status.hidden = false;
      status.textContent = error.message || "Could not save classroom day.";
      status.classList.add("is-error");
    }
  }
}

async function assignScheduleLessonPlan({
  resourceId,
  weekStartDate,
  ageGroup,
  classroomLabel = "",
  replaceExisting = false,
} = {}) {
  const api = getScheduleApi();
  if (!api) {
    return assignCurriculumLessonPlanToWeek({
      resourceId,
      weekStartDate,
      ageGroup,
      classroomLabel,
      replaceExisting,
      _skipSchedule: true,
    });
  }
  if (!isLoggedIn() && !hasAdminFullAccess()) {
    openAuthModal("login");
    throw new Error("Log in to assign a lesson plan to your week.");
  }
  const week = api.weekStartMonday(weekStartDate || curriculumPlannerSelectedWeek || new Date());
  await ensureScheduleLoaded();
  const doc = scheduleDocCache || api.readCache(scheduleApiEmail());
  const rooms = typeof activeScheduleClassrooms === "function" ? activeScheduleClassrooms(doc) : (doc?.classrooms || []);
  const matchedRoom = rooms.find((room) => {
    const label = String(classroomLabel || "").trim().toLowerCase();
    if (!label) return false;
    return String(room.name || "").trim().toLowerCase() === label
      || String(room.id || "").trim().toLowerCase() === label;
  }) || rooms[0] || null;
  const classroomId = matchedRoom?.id || doc?.classrooms?.[0]?.id || "classroom-main";
  const existing = api.lessonForWeek(doc, week, classroomId);
  if (existing && existing.lessonPlanId !== resourceId && !replaceExisting) {
    const error = new Error("This week already has a lesson plan assigned.");
    error.code = "replace-required";
    error.existing = existing;
    throw error;
  }
  const { resource, plan } = await resolveCurriculumPlanForAssignment(resourceId, { weekStartDate: week });
  const snapshot = buildCurriculumLessonPlanSnapshot(plan);
  const activityCount = assertAssignableCurriculumSnapshot(snapshot, resource);
  const rosterChildren = (typeof getActiveChildren === "function" ? getActiveChildren(childRecords()) : (childStore("Profiles") || []))
    .filter((child) => String(child.classroomId || "") === String(classroomId));
  const childIds = rosterChildren.map((child) => child.id).filter(Boolean);
  const rosterLabel = rosterChildren.map((child) => child.name).filter(Boolean).slice(0, 8).join(", ");
  const item = await api.assignLessonPlanToWeek(firebaseAuthHeaders, scheduleApiEmail(), {
    id: existing?.id,
    weekStartDate: week,
    classroomId,
    childIds,
    rosterLabel,
    lessonPlanId: resource.id,
    lessonPlanTitle: snapshot.title || resource.title || "Untitled Lesson Plan",
    lessonPlanPlan: snapshot.plan,
    lessonPlanUpdatedAt: snapshot.updatedAt || "",
    ageGroup: String(ageGroup || snapshot.age || "Preschool").trim() || "Preschool",
    snapshot,
    preserveExecution: true,
  });
  if (classroomLabel && matchedRoom) {
    const nextDoc = api.readCache(scheduleApiEmail());
    const nextRooms = (nextDoc.classrooms || []).map((room) => (
      room.id === matchedRoom.id
        ? { ...room, name: String(classroomLabel).trim() || room.name }
        : room
    ));
    nextDoc.classrooms = nextRooms.length ? nextRooms : nextDoc.classrooms;
    scheduleDocCache = await api.saveSchedule(firebaseAuthHeaders, scheduleApiEmail(), nextDoc);
  } else {
    scheduleDocCache = api.readCache(scheduleApiEmail());
  }
  dualWriteLegacyAssignmentsFromSchedule(scheduleDocCache);
  syncWeeklyPlannerFromScheduleItem(item);
  curriculumPlannerSelectedWeek = week;
  curriculumPlannerAssignResourceId = "";
  if (typeof runLessonAssignedAutomation === "function") {
    try { runLessonAssignedAutomation(item, { classroomId, childIds, week }); } catch (_e) { /* non-blocking */ }
  }
  curriculumPlannerMessage = {
    text: existing
      ? `Updated assignment to “${item.lessonPlanTitle}” (${activityCount} activities). Notes were preserved.`
      : `Assigned “${item.lessonPlanTitle}” (${activityCount} activities) to the week of ${item.weekStartDate}.`,
    isSuccess: true,
  };
  const assignDetail = {
    weekStartDate: item.weekStartDate,
    lessonPlanId: item.lessonPlanId,
    plan: item.lessonPlanPlan,
    activityCount,
    replaced: Boolean(existing),
  };
  trackEvent("schedule_assign_lesson", assignDetail);
  trackEvent("lesson_plan_added_to_calendar", assignDetail);
  refreshCalendarSurfacesAfterScheduleChange(week);
  return item;
}

function emptyCurriculumDailyTeacherNotes() {
  return Object.fromEntries(CURRICULUM_WEEKDAYS.map((day) => [day, ""]));
}

function generateCurriculumPlannerObservationId() {
  const bytes = new Uint8Array(6);
  crypto.getRandomValues(bytes);
  return `cpo-${Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
}

function generateCurriculumPlannerClassroomEventId() {
  const bytes = new Uint8Array(6);
  crypto.getRandomValues(bytes);
  return `cce-${Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
}

function normalizeCurriculumPlannerClassroomEvent(entry = {}, options = {}) {
  const dayOfWeek = CURRICULUM_WEEKDAYS.includes(String(entry.dayOfWeek || "").toLowerCase())
    ? String(entry.dayOfWeek).toLowerCase()
    : "";
  const eventType = CURRICULUM_CLASSROOM_EVENT_TYPES.includes(String(entry.eventType || "").trim())
    ? String(entry.eventType).trim()
    : (String(entry.eventType || "").trim() || "Other");
  const title = String(entry.title || eventType || "").trim() || eventType || "Classroom Event";
  return {
    id: String(entry.id || "").trim() || generateCurriculumPlannerClassroomEventId(),
    title,
    eventType,
    date: String(entry.date || options.weekStartDate || "").trim().slice(0, 10),
    dayOfWeek,
    description: String(entry.description || "").trim(),
    itemsToBring: String(entry.itemsToBring || "").trim(),
    createdAt: String(entry.createdAt || "").trim() || new Date().toISOString(),
    updatedAt: String(entry.updatedAt || "").trim() || new Date().toISOString(),
  };
}

function emptyCurriculumParentCalendar() {
  return {
    classroomEvents: [],
    parentMessage: "",
    updatedAt: "",
  };
}

function normalizeCurriculumParentCalendar(raw = null, options = {}) {
  if (!raw || typeof raw !== "object") return emptyCurriculumParentCalendar();
  const events = (Array.isArray(raw.classroomEvents) ? raw.classroomEvents : [])
    .map((entry) => normalizeCurriculumPlannerClassroomEvent(entry, options))
    .filter((item) => item.title);
  events.sort((a, b) => `${a.date} ${a.title}`.localeCompare(`${b.date} ${b.title}`));
  return {
    classroomEvents: events,
    parentMessage: String(raw.parentMessage || "").trim(),
    updatedAt: String(raw.updatedAt || "").trim(),
  };
}

function normalizeCurriculumPlannerObservation(entry = {}) {
  const dayOfWeek = CURRICULUM_WEEKDAYS.includes(String(entry.dayOfWeek || "").toLowerCase())
    ? String(entry.dayOfWeek).toLowerCase()
    : "";
  return {
    id: String(entry.id || "").trim() || generateCurriculumPlannerObservationId(),
    date: String(entry.date || "").trim().slice(0, 10),
    dayOfWeek,
    lessonPlanId: String(entry.lessonPlanId || "").trim(),
    activityItemId: String(entry.activityItemId || "").trim(),
    activityTitle: String(entry.activityTitle || "").trim(),
    note: String(entry.note || "").trim(),
    followUpNeeded: Boolean(entry.followUpNeeded),
    childId: String(entry.childId || "").trim(),
    childName: String(entry.childName || "").trim(),
    activityMissing: Boolean(entry.activityMissing),
    createdAt: String(entry.createdAt || "").trim() || new Date().toISOString(),
    updatedAt: String(entry.updatedAt || "").trim() || new Date().toISOString(),
  };
}

function normalizeCurriculumWeekAssignment(raw = {}) {
  const dailyTeacherNotes = emptyCurriculumDailyTeacherNotes();
  const incomingNotes = raw.dailyTeacherNotes && typeof raw.dailyTeacherNotes === "object" ? raw.dailyTeacherNotes : {};
  CURRICULUM_WEEKDAYS.forEach((day) => {
    dailyTeacherNotes[day] = String(incomingNotes[day] || "").trim();
  });
  return {
    ...raw,
    teacherNotes: String(raw.teacherNotes || "").trim(),
    preparationNotes: String(raw.preparationNotes || "").trim(),
    dailyTeacherNotes,
    observations: (Array.isArray(raw.observations) ? raw.observations : [])
      .map(normalizeCurriculumPlannerObservation)
      .filter((item) => item.note),
    // Phase F3 Parent Calendar — separate from teacher-private notes/observations.
    parentCalendar: normalizeCurriculumParentCalendar(raw.parentCalendar, {
      weekStartDate: String(raw.weekStartDate || "").trim(),
    }),
  };
}

function loadCurriculumWeekAssignments() {
  const list = readSavedJson(curriculumAssignmentsStoreKey(), []);
  return (Array.isArray(list) ? list : []).map(normalizeCurriculumWeekAssignment);
}

function saveCurriculumWeekAssignments(list) {
  localStorage.setItem(
    curriculumAssignmentsStoreKey(),
    JSON.stringify((Array.isArray(list) ? list : []).map(normalizeCurriculumWeekAssignment)),
  );
}

function curriculumAssignmentForWeek(weekStartDate) {
  const week = curriculumPlannerWeekStartIso(weekStartDate);
  return loadCurriculumWeekAssignments().find((item) => item.weekStartDate === week) || null;
}

function generateCurriculumAssignmentId() {
  const bytes = new Uint8Array(6);
  crypto.getRandomValues(bytes);
  return `cwa-${Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
}

/** Parent-safe DTO helper (F3). Strips all teacher-private fields. */
function buildCurriculumPlannerParentSafeDto(assignment) {
  if (!assignment) return null;
  const snapshot = assignment.snapshot || {};
  const parentCalendar = normalizeCurriculumParentCalendar(assignment.parentCalendar, {
    weekStartDate: assignment.weekStartDate,
  });
  const classroomEvents = parentCalendar.classroomEvents.map((event) => ({
    id: event.id,
    title: event.title,
    eventType: event.eventType,
    date: event.date,
    dayOfWeek: event.dayOfWeek,
    description: event.description,
    itemsToBring: event.itemsToBring,
  }));
  const daily = {};
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const dayPlan = snapshot.dailyPlans?.[day] || {};
    const dayEvents = classroomEvents.filter((event) => event.dayOfWeek === day);
    daily[day] = {
      theme: dayPlan.theme || "",
      books: (dayPlan.books || []).map((book) => ({ title: book.title || "", author: book.author || "" })),
      songs: (dayPlan.songs || []).map((song) => ({ title: song.title || "" })),
      activities: (dayPlan.items || []).map((item) => ({ title: item.title || "", activityCategory: item.activityCategory || "" })),
      familyConnection: dayPlan.familyConnection || "",
      classroomEvents: dayEvents,
    };
  });
  return {
    weekStartDate: assignment.weekStartDate || "",
    weekEndDate: curriculumPlannerWeekEndIso(assignment.weekStartDate),
    ageGroup: assignment.ageGroup || "",
    classroomLabel: assignment.classroomLabel || "",
    lessonPlanTitle: assignment.lessonPlanTitle || snapshot.title || "",
    theme: snapshot.theme || "",
    familyConnection: snapshot.familyConnection || "",
    parentMessage: parentCalendar.parentMessage || "",
    books: (snapshot.books || []).map((book) => ({ title: book.title || "", author: book.author || "" })),
    songs: (snapshot.songs || []).map((song) => ({ title: song.title || "" })),
    daily,
    classroomEvents,
    parentCalendar: {
      parentMessage: parentCalendar.parentMessage || "",
      classroomEvents,
    },
  };
}

function curriculumPlannerParentSafeDtoContainsPrivateLeak(dto) {
  if (!dto || typeof dto !== "object") return false;
  const text = JSON.stringify(dto).toLowerCase();
  return [
    "teachernotes",
    "preparationnotes",
    "dailyteachernotes",
    "followupneeded",
    "teacherrole",
    "teacherlanguage",
    "safetynotes",
    '"observations":[',
  ].some((needle) => text.includes(needle));
}

function curriculumPlannerActivityOptions(assignment, dayKey = "") {
  const options = [];
  const days = dayKey ? [dayKey] : CURRICULUM_WEEKDAYS;
  days.forEach((day) => {
    (assignment?.snapshot?.dailyPlans?.[day]?.items || []).forEach((item) => {
      if (!item?.itemId && !item?.title) return;
      options.push({
        day,
        itemId: item.itemId || "",
        title: item.title || "Activity",
        label: `${curriculumPlannerWeekdayLabel(day)}: ${item.title || "Activity"}`,
      });
    });
  });
  return options;
}

function markCurriculumPlannerObservationActivityLinks(assignment) {
  const validIds = new Set();
  CURRICULUM_WEEKDAYS.forEach((day) => {
    (assignment?.snapshot?.dailyPlans?.[day]?.items || []).forEach((item) => {
      if (item?.itemId) validIds.add(item.itemId);
    });
  });
  const observations = (assignment.observations || []).map((entry) => {
    const obs = normalizeCurriculumPlannerObservation(entry);
    if (obs.activityItemId && !validIds.has(obs.activityItemId)) {
      return { ...obs, activityMissing: true };
    }
    return { ...obs, activityMissing: false };
  });
  return { ...assignment, observations };
}

function preserveCurriculumPlannerPrivateFields(existing = {}) {
  const normalized = normalizeCurriculumWeekAssignment(existing || {});
  return {
    teacherNotes: normalized.teacherNotes || "",
    preparationNotes: normalized.preparationNotes || "",
    dailyTeacherNotes: { ...normalized.dailyTeacherNotes },
    observations: [...(normalized.observations || [])],
    parentCalendar: normalizeCurriculumParentCalendar(normalized.parentCalendar, {
      weekStartDate: normalized.weekStartDate,
    }),
  };
}

function snapshotCurriculumBook(book = {}) {
  return {
    title: String(book?.title || "").trim(),
    author: String(book?.author || "").trim(),
    notes: String(book?.notes || "").trim(),
  };
}

function snapshotCurriculumSong(song = {}) {
  return {
    title: String(song?.title || "").trim(),
    notes: String(song?.notes || "").trim(),
  };
}

function snapshotCurriculumDailyItem(item = {}) {
  return {
    itemId: String(item?.itemId || "").trim(),
    activityCategory: String(item?.activityCategory || "").trim(),
    title: String(item?.title || "").trim(),
    objective: String(item?.objective || "").trim(),
    description: String(item?.description || "").trim(),
    learningDomains: Array.isArray(item?.learningDomains) ? item.learningDomains.map((entry) => String(entry || "").trim()).filter(Boolean) : [],
    materials: String(item?.materials || "").trim(),
    setup: String(item?.setup || "").trim(),
    steps: String(item?.steps || item?.directions || "").trim(),
    teacherRole: String(item?.teacherRole || "").trim(),
    teacherLanguage: String(item?.teacherLanguage || "").trim(),
    learningGoals: Array.isArray(item?.learningGoals) ? item.learningGoals.map((entry) => String(entry || "").trim()).filter(Boolean) : [],
    observationOpportunities: String(item?.observationOpportunities || "").trim(),
    vocabulary: String(item?.vocabulary || "").trim(),
    extensions: String(item?.extensions || "").trim(),
    adaptations: String(item?.adaptations || "").trim(),
    safetyNotes: String(item?.safetyNotes || "").trim(),
    ageModifications: String(item?.ageModifications || "").trim(),
  };
}

function snapshotCurriculumDailyDay(dayPlan = {}) {
  return {
    theme: String(dayPlan?.theme || "").trim(),
    objectives: String(dayPlan?.objectives || "").trim(),
    learningDomains: Array.isArray(dayPlan?.learningDomains) ? dayPlan.learningDomains.map((entry) => String(entry || "").trim()).filter(Boolean) : [],
    materials: String(dayPlan?.materials || "").trim(),
    vocabulary: String(dayPlan?.vocabulary || "").trim(),
    books: (Array.isArray(dayPlan?.books) ? dayPlan.books : []).map(snapshotCurriculumBook).filter((book) => book.title),
    songs: (Array.isArray(dayPlan?.songs) ? dayPlan.songs : []).map(snapshotCurriculumSong).filter((song) => song.title),
    circleTime: (Array.isArray(dayPlan?.circleTime) ? dayPlan.circleTime : []).map((entry) => String(entry || "").trim()).filter(Boolean),
    transitions: (Array.isArray(dayPlan?.transitions) ? dayPlan.transitions : []).map((entry) => String(entry || "").trim()).filter(Boolean),
    outdoorPlay: String(dayPlan?.outdoorPlay || "").trim(),
    familyConnection: String(dayPlan?.familyConnection || "").trim(),
    observations: (Array.isArray(dayPlan?.observations) ? dayPlan.observations : []).map((entry) => String(entry || "").trim()).filter(Boolean),
    adaptations: String(dayPlan?.adaptations || "").trim(),
    safetyNotes: String(dayPlan?.safetyNotes || "").trim(),
    items: (Array.isArray(dayPlan?.items) ? dayPlan.items : []).map(snapshotCurriculumDailyItem).filter((item) => item.title),
  };
}

function buildCurriculumLessonPlanSnapshot(plan = {}) {
  const dailyPlans = {};
  CURRICULUM_WEEKDAYS.forEach((day) => {
    dailyPlans[day] = snapshotCurriculumDailyDay(plan?.dailyPlans?.[day] || {});
  });
  return {
    title: String(plan?.title || "").trim(),
    age: String(plan?.age || "").trim(),
    theme: String(plan?.theme || "").trim(),
    plan: String(plan?.plan || "Free").trim() === "Pro" ? "Pro" : "Free",
    learningDomains: Array.isArray(plan?.learningDomains) ? plan.learningDomains.map((entry) => String(entry || "").trim()).filter(Boolean) : [],
    weeklyOverview: String(plan?.weeklyOverview || "").trim(),
    objectives: String(plan?.objectives || "").trim(),
    weeklyMaterials: String(plan?.weeklyMaterials || "").trim(),
    vocabularyWords: String(plan?.vocabularyWords || "").trim(),
    observationOpportunities: String(plan?.observationOpportunities || "").trim(),
    adaptations: String(plan?.adaptations || "").trim(),
    familyConnection: String(plan?.familyConnection || "").trim(),
    books: (Array.isArray(plan?.books) ? plan.books : []).map(snapshotCurriculumBook).filter((book) => book.title),
    songs: (Array.isArray(plan?.songs) ? plan.songs : []).map(snapshotCurriculumSong).filter((song) => song.title),
    dailyPlans,
    updatedAt: String(plan?.updatedAt || "").trim(),
  };
}

function curriculumPlanHasAssignableDayItems(plan = null) {
  if (!plan || typeof plan !== "object") return false;
  return CURRICULUM_WEEKDAYS.some((day) => {
    const items = plan.dailyPlans?.[day]?.items;
    return Array.isArray(items) && items.some((item) => String(item?.title || "").trim());
  });
}

function countCurriculumSnapshotActivities(snapshot = {}) {
  const dailyPlans = snapshot?.dailyPlans || snapshot?.snapshot?.dailyPlans || {};
  return CURRICULUM_WEEKDAYS.reduce((sum, day) => {
    const items = dailyPlans?.[day]?.items;
    if (!Array.isArray(items)) return sum;
    return sum + items.filter((item) => String(item?.title || "").trim()).length;
  }, 0);
}

function syncHydratedCurriculumPlanOntoResource(resource, plan) {
  if (!resource || !plan || typeof plan !== "object") return resource;
  const next = {
    ...resource,
    weeklyOverview: plan.weeklyOverview || resource.weeklyOverview,
    materials: plan.weeklyMaterials || resource.materials,
    description: plan.weeklyOverview || resource.description,
    theme: plan.theme || resource.theme,
    _curriculumLessonPlan: plan,
    _curriculumResourceIds: curriculumAsStringArray(plan.resourceIds),
    customContent: buildLessonPlanTextFromCurriculum(plan),
  };
  const idx = Array.isArray(resources) ? resources.findIndex((item) => item.id === resource.id) : -1;
  if (idx >= 0) resources[idx] = { ...resources[idx], ...next, id: resource.id };
  if (activeResourceViewerResource?.id === resource.id) {
    activeResourceViewerResource = { ...activeResourceViewerResource, ...next, id: resource.id };
  }
  return next;
}

function enrichCurriculumPlanDailyPlansFromActivities(plan = {}, lessonPlanId = "") {
  const targetId = String(lessonPlanId || plan?.id || "").trim();
  if (!targetId) return plan;
  const library = typeof effectiveCurriculumLibrary === "function" ? effectiveCurriculumLibrary() : { activities: [] };
  const linked = (library.activities || []).filter((activity) => {
    if (String(activity?.lessonPlanId || "").trim() !== targetId) return false;
    const status = String(activity?.status || "published").toLowerCase();
    return status !== "draft" && status !== "archived";
  });
  if (!linked.length) return plan;
  const dailyPlans = { ...(plan.dailyPlans || {}) };
  let added = 0;
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const existing = Array.isArray(dailyPlans[day]?.items) ? dailyPlans[day].items : [];
    if (existing.some((item) => String(item?.title || "").trim())) return;
    const dayItems = linked
      .filter((activity) => String(activity.dayOfWeek || "").toLowerCase() === day)
      .map((activity) => ({
        itemId: String(activity.itemId || activity.id || "").trim(),
        activityCategory: String(activity.activityCategory || "").trim(),
        title: String(activity.title || "").trim(),
        objective: String(activity.objective || "").trim(),
        description: String(activity.description || "").trim(),
        learningDomains: Array.isArray(activity.learningDomains) ? activity.learningDomains : [],
        materials: String(activity.materials || "").trim(),
        setup: String(activity.setup || "").trim(),
        steps: String(activity.steps || activity.directions || "").trim(),
        teacherRole: String(activity.teacherRole || "").trim(),
        teacherLanguage: String(activity.teacherLanguage || "").trim(),
        learningGoals: Array.isArray(activity.learningGoals) ? activity.learningGoals : [],
        observationOpportunities: String(activity.observationOpportunities || "").trim(),
        vocabulary: String(activity.vocabulary || "").trim(),
        extensions: String(activity.extensions || "").trim(),
        adaptations: String(activity.adaptations || "").trim(),
        safetyNotes: String(activity.safetyNotes || "").trim(),
        ageModifications: String(activity.ageModifications || "").trim(),
      }))
      .filter((item) => item.title);
    if (!dayItems.length) return;
    dailyPlans[day] = { ...(dailyPlans[day] || {}), items: dayItems };
    added += dayItems.length;
  });
  if (!added) return plan;
  return { ...plan, dailyPlans };
}

function assertAssignableCurriculumSnapshot(snapshot, resource) {
  const activityCount = countCurriculumSnapshotActivities(snapshot);
  if (activityCount > 0) return activityCount;
  console.error("[llh-assign] refusing empty calendar snapshot", {
    lessonPlanId: resource?.id || "",
    title: resource?.title || snapshot?.title || "",
    theme: snapshot?.theme || "",
    hasOverview: Boolean(String(snapshot?.weeklyOverview || "").trim()),
  });
  throw new Error(
    "This lesson plan could not be added because Monday–Friday activities did not transfer. Please reopen the lesson and try again.",
  );
}

function refreshCalendarSurfacesAfterScheduleChange(weekStartDate = "") {
  const week = weekStartDate ? curriculumPlannerWeekStartIso(weekStartDate) : "";
  if (week) {
    mainCalendarSelectedWeek = week;
    weeklyPlannerFocusWeek = week;
  }
  if (document.querySelector("#view-calendar.active-view") && typeof renderMainCalendar === "function") {
    renderMainCalendar();
  }
  if (document.querySelector("#view-planner.active-view") && typeof renderWeeklyPlanner === "function") {
    renderWeeklyPlanner();
  }
}

function curriculumAssignableLessonResources() {
  return resources.filter((resource) => {
    if (resource?.category !== "Lesson Plans" || !resource?._curriculumManaged) return false;
    if (!canAccess(resource)) return false;
    const status = String(resource?._curriculumLessonPlan?.status || "published");
    return status !== "draft" && status !== "archived";
  });
}

async function resolveCurriculumPlanForAssignment(resourceOrId, options = {}) {
  const resource = typeof resourceOrId === "string"
    ? resources.find((item) => item.id === resourceOrId)
    : resourceOrId;
  if (!resource || resource.category !== "Lesson Plans" || !resource._curriculumManaged) {
    throw new Error("Choose a play-based lesson plan from the library.");
  }
  if (!canAccess(resource)) {
    throw new Error(`${proUnlockValueProp} Upgrade to Pro to assign this premium lesson plan.`);
  }
  const assignWeekHint = options.weekStartDate
    || calendarLessonAssignContext?.weekStartDate
    || (typeof curriculumPlannerSelectedWeek === "string" ? curriculumPlannerSelectedWeek : "");
  if (!canAssignMoreFreeCalendarPlans(assignWeekHint)) {
    trackUpgradePrompt("calendar_limit", {
      weekStartDate: assignWeekHint || "",
      planningDays: effectiveFreeCalendarPlanningDays(),
      horizon: freeCalendarPlanningHorizonIso(),
    });
    showProFeatureModal(freeCalendarLimitMessage, "limit");
    throw new Error(freeCalendarLimitMessage);
  }
  const status = String(resource._curriculumLessonPlan?.status || resource.status || "published");
  if (status === "draft" || status === "archived") {
    throw new Error("Draft and archived lesson plans cannot be assigned.");
  }
  if (String(resource.plan || "").trim() === "Pro" && !isProUser() && !hasAdminFullAccess() && !isCuratedFreeCurriculumPlan(resource)) {
    throw new Error(`${proUnlockValueProp} Upgrade to Pro to assign this premium lesson plan.`);
  }

  // Prefer the already-hydrated lesson viewer body when assigning from Use This Plan.
  let plan = null;
  if (
    activeResourceViewerResource?.id === resource.id
    && curriculumPlanHasAssignableDayItems(activeResourceViewerResource._curriculumLessonPlan)
  ) {
    plan = activeResourceViewerResource._curriculumLessonPlan;
  } else {
    plan = resource._curriculumLessonPlan || null;
  }

  // Browse/list payloads are intentionally slim (no dailyPlans). Always hydrate
  // detail content before snapshotting — Free curated plans included.
  if (!curriculumPlanHasAssignableDayItems(plan)) {
    const fetched = await fetchAuthorizedCurriculumLessonPlan(resource.id);
    if (fetched?.lessonPlan) {
      plan = fetched.lessonPlan;
      syncHydratedCurriculumPlanOntoResource(resource, plan);
    } else if (!fetched?.ok) {
      console.error("[llh-assign] lesson detail hydrate failed", {
        lessonPlanId: resource.id,
        reason: fetched?.reason || "unknown",
        status: fetched?.status || null,
      });
    }
  }

  if (!curriculumPlanHasAssignableDayItems(plan)) {
    plan = enrichCurriculumPlanDailyPlansFromActivities(plan || resource._curriculumLessonPlan || {}, resource.id);
  }

  if (!plan || typeof plan !== "object") {
    throw new Error("Lesson plan content could not be loaded for assignment.");
  }
  if (!curriculumPlanHasAssignableDayItems(plan)) {
    console.error("[llh-assign] no Monday–Friday activities after hydrate", {
      lessonPlanId: resource.id,
      title: resource.title || plan.title || "",
      activityCount: resource.activityCount || plan.activityCount || 0,
      activityIds: Array.isArray(plan.activityIds) ? plan.activityIds.length : 0,
    });
    throw new Error(
      "This lesson plan could not be added because Monday–Friday activities did not load. Please reopen the lesson and try again.",
    );
  }
  return { resource, plan };
}

function upsertCurriculumWeekAssignment(assignment) {
  const list = loadCurriculumWeekAssignments().filter((item) => item.weekStartDate !== assignment.weekStartDate);
  list.unshift(assignment);
  list.sort((a, b) => String(b.weekStartDate || "").localeCompare(String(a.weekStartDate || "")));
  saveCurriculumWeekAssignments(list);
  return assignment;
}

async function assignCurriculumLessonPlanToWeek({
  resourceId,
  weekStartDate,
  ageGroup,
  classroomLabel = "",
  replaceExisting = false,
  _skipSchedule = false,
} = {}) {
  if (!_skipSchedule && getScheduleApi()) {
    return assignScheduleLessonPlan({
      resourceId,
      weekStartDate,
      ageGroup,
      classroomLabel,
      replaceExisting,
    });
  }
  if (!isLoggedIn() && !hasAdminFullAccess()) {
    openAuthModal("login");
    throw new Error("Log in to assign a lesson plan to your week.");
  }
  const week = curriculumPlannerWeekStartIso(weekStartDate || curriculumPlannerSelectedWeek || new Date());
  const existing = curriculumAssignmentForWeek(week);
  if (existing && !replaceExisting) {
    const error = new Error("This week already has a lesson plan assigned.");
    error.code = "replace-required";
    error.existing = existing;
    throw error;
  }
  const { resource, plan } = await resolveCurriculumPlanForAssignment(resourceId, { weekStartDate: week });
  const snapshot = buildCurriculumLessonPlanSnapshot(plan);
  const activityCount = assertAssignableCurriculumSnapshot(snapshot, resource);
  const now = new Date().toISOString();
  const preserved = preserveCurriculumPlannerPrivateFields(existing || {});
  let assignment = {
    id: existing?.id || generateCurriculumAssignmentId(),
    weekStartDate: week,
    ageGroup: String(ageGroup || snapshot.age || "Preschool").trim() || "Preschool",
    classroomLabel: String(classroomLabel || "").trim(),
    lessonPlanId: resource.id,
    lessonPlanTitle: snapshot.title || resource.title || "Untitled Lesson Plan",
    lessonPlanPlan: snapshot.plan,
    lessonPlanUpdatedAt: snapshot.updatedAt || "",
    snapshot,
    organizationId: null,
    classroomId: null,
    assignedBy: currentUser || "",
    createdAt: existing?.createdAt || now,
    updatedAt: now,
    ...preserved,
  };
  assignment = markCurriculumPlannerObservationActivityLinks(normalizeCurriculumWeekAssignment(assignment));
  upsertCurriculumWeekAssignment(assignment);
  curriculumPlannerSelectedWeek = week;
  curriculumPlannerAssignResourceId = "";
  curriculumPlannerMessage = {
    text: existing
      ? `Updated assignment to “${assignment.lessonPlanTitle}” (${activityCount} activities). Teacher notes and observations were preserved.`
      : `Assigned “${assignment.lessonPlanTitle}” (${activityCount} activities) to the week of ${assignment.weekStartDate}.`,
    isSuccess: true,
  };
  const plannerAssignDetail = {
    weekStartDate: assignment.weekStartDate,
    lessonPlanId: assignment.lessonPlanId,
    plan: assignment.lessonPlanPlan,
    activityCount,
    replaced: Boolean(existing),
  };
  trackEvent("curriculum_planner_assign", plannerAssignDetail);
  trackEvent("lesson_plan_added_to_calendar", plannerAssignDetail);
  refreshCalendarSurfacesAfterScheduleChange(week);
  return assignment;
}

function removeCurriculumWeekAssignment(weekStartDate) {
  const week = curriculumPlannerWeekStartIso(weekStartDate);
  saveCurriculumWeekAssignments(loadCurriculumWeekAssignments().filter((item) => item.weekStartDate !== week));
  curriculumPlannerMessage = { text: "Removed the lesson plan assignment for this week.", isSuccess: true };
}

function setCurriculumPlannerMessage(text, isSuccess = false) {
  curriculumPlannerMessage = { text: String(text || ""), isSuccess: Boolean(isSuccess) };
}

function curriculumPlannerAssignableOptionsHtml(selectedId = "") {
  const plans = curriculumAssignableLessonResources()
    .slice()
    .sort((a, b) => String(a.title || "").localeCompare(String(b.title || "")));
  if (!plans.length) {
    return `<option value="">No accessible lesson plans available</option>`;
  }
  return [
    `<option value="">Select a lesson plan</option>`,
    ...plans.map((plan) => `
      <option value="${escapeHtml(plan.id)}"${plan.id === selectedId ? " selected" : ""}>
        ${escapeHtml(plan.title || "Untitled")} · ${escapeHtml(plan.age || "")} · ${escapeHtml(plan.plan || "Free")}
      </option>
    `),
  ].join("");
}

function updateCurriculumWeekAssignmentFields(weekStartDate, updater) {
  const week = curriculumPlannerWeekStartIso(weekStartDate);
  const existing = curriculumAssignmentForWeek(week);
  if (!existing) throw new Error("Assign a lesson plan to this week before saving teacher notes.");
  const next = normalizeCurriculumWeekAssignment({
    ...existing,
    ...(typeof updater === "function" ? updater(existing) : updater),
    updatedAt: new Date().toISOString(),
  });
  upsertCurriculumWeekAssignment(markCurriculumPlannerObservationActivityLinks(next));
  return curriculumAssignmentForWeek(week);
}

function saveCurriculumPlannerTeacherNotesFromForm(form) {
  if (!form) return;
  const formData = new FormData(form);
  const weekStartDate = curriculumPlannerWeekStartIso(formData.get("weekStartDate") || curriculumPlannerSelectedWeek);
  const dailyTeacherNotes = emptyCurriculumDailyTeacherNotes();
  CURRICULUM_WEEKDAYS.forEach((day) => {
    dailyTeacherNotes[day] = String(formData.get(`dailyNote-${day}`) || "").trim();
  });
  updateCurriculumWeekAssignmentFields(weekStartDate, {
    teacherNotes: String(formData.get("teacherNotes") || "").trim(),
    preparationNotes: String(formData.get("preparationNotes") || "").trim(),
    dailyTeacherNotes,
  });
  setCurriculumPlannerMessage("Teacher notes saved. The lesson-plan snapshot was not changed.", true);
  renderCurriculumPlanner();
}

function saveCurriculumPlannerObservationFromForm(form) {
  if (!form) return;
  const formData = new FormData(form);
  const weekStartDate = curriculumPlannerWeekStartIso(formData.get("weekStartDate") || curriculumPlannerSelectedWeek);
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) throw new Error("Assign a lesson plan before adding observations.");
  const observationId = String(formData.get("observationId") || "").trim() || generateCurriculumPlannerObservationId();
  const dayOfWeek = String(formData.get("dayOfWeek") || "").toLowerCase();
  const activityItemId = String(formData.get("activityItemId") || "").trim();
  const activityOptions = curriculumPlannerActivityOptions(assignment);
  const matchedActivity = activityOptions.find((item) => item.itemId === activityItemId);
  const childId = String(formData.get("childId") || "").trim();
  const child = childId ? (childRecords().children || []).find((entry) => entry.id === childId) : null;
  const now = new Date().toISOString();
  const existingObs = (assignment.observations || []).find((item) => item.id === observationId);
  const observation = normalizeCurriculumPlannerObservation({
    id: observationId,
    date: String(formData.get("date") || curriculumPlannerDateForDay(weekStartDate, dayOfWeek) || "").slice(0, 10),
    dayOfWeek: CURRICULUM_WEEKDAYS.includes(dayOfWeek) ? dayOfWeek : "",
    lessonPlanId: assignment.lessonPlanId,
    activityItemId,
    activityTitle: matchedActivity?.title
      || (activityItemId ? String(existingObs?.activityTitle || formData.get("activityTitle") || "").trim() : ""),
    note: String(formData.get("note") || "").trim(),
    followUpNeeded: formData.get("followUpNeeded") === "1" || formData.get("followUpNeeded") === "on",
    childId: child?.id || "",
    childName: child?.name || "",
    createdAt: existingObs?.createdAt || now,
    updatedAt: now,
    activityMissing: Boolean(activityItemId) && !matchedActivity,
  });
  if (!observation.note) throw new Error("Enter an observation note before saving.");
  const observations = [
    ...(assignment.observations || []).filter((item) => item.id !== observationId),
    observation,
  ].sort((a, b) => `${b.date} ${b.updatedAt}`.localeCompare(`${a.date} ${a.updatedAt}`));
  updateCurriculumWeekAssignmentFields(weekStartDate, { observations });
  curriculumPlannerEditingObservationId = "";
  curriculumPlannerObservationPresetDay = "";
  setCurriculumPlannerMessage("Observation saved. Teacher-only — not shared with parents.", true);
  renderCurriculumPlanner();
}

function deleteCurriculumPlannerObservation(weekStartDate, observationId) {
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) return;
  updateCurriculumWeekAssignmentFields(weekStartDate, {
    observations: (assignment.observations || []).filter((item) => item.id !== observationId),
  });
  if (curriculumPlannerEditingObservationId === observationId) curriculumPlannerEditingObservationId = "";
  setCurriculumPlannerMessage("Observation deleted.", true);
  renderCurriculumPlanner();
}

function clearCurriculumPlannerTeacherNotes(weekStartDate) {
  updateCurriculumWeekAssignmentFields(weekStartDate, {
    teacherNotes: "",
    preparationNotes: "",
    dailyTeacherNotes: emptyCurriculumDailyTeacherNotes(),
  });
  setCurriculumPlannerMessage("Teacher notes cleared. Observations were left unchanged.", true);
  renderCurriculumPlanner();
}

function buildCurriculumPlannerTeacherPrintText(assignment) {
  if (!assignment) return "";
  const lines = [
    "Little Learner Hub — Teacher Curriculum Week (Private)",
    `Week of: ${assignment.weekStartDate} – ${curriculumPlannerWeekEndIso(assignment.weekStartDate)}`,
    `Lesson Plan: ${assignment.lessonPlanTitle || ""}`,
    `Age Group: ${assignment.ageGroup || ""}`,
    `Classroom: ${assignment.classroomLabel || "—"}`,
    "",
    "Weekly Teacher Notes",
    assignment.teacherNotes || "(none)",
    "",
    "Preparation / Materials Reminder",
    assignment.preparationNotes || "(none)",
    "",
  ];
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const dayPlan = assignment.snapshot?.dailyPlans?.[day] || {};
    const note = assignment.dailyTeacherNotes?.[day] || "";
    lines.push(`${curriculumPlannerWeekdayLabel(day)} (${curriculumPlannerDateForDay(assignment.weekStartDate, day)})`);
    lines.push(`Theme: ${dayPlan.theme || assignment.snapshot?.theme || ""}`);
    lines.push(`Activities: ${(dayPlan.items || []).map((item) => item.title).filter(Boolean).join("; ") || "(none)"}`);
    lines.push(`Teacher note: ${note || "(none)"}`);
    lines.push("");
  });
  lines.push("Group Observations (Teacher-only)");
  if (!(assignment.observations || []).length) {
    lines.push("(none)");
  } else {
    (assignment.observations || []).forEach((obs) => {
      lines.push(`- ${obs.date || ""} ${curriculumPlannerWeekdayLabel(obs.dayOfWeek)}: ${obs.note}`);
      if (obs.activityTitle) lines.push(`  Activity: ${obs.activityTitle}${obs.activityMissing ? " (from previous plan)" : ""}`);
      if (obs.followUpNeeded) lines.push("  Follow-up needed");
      if (obs.childName) lines.push(`  Child: ${obs.childName}`);
    });
  }
  lines.push("");
  lines.push("Do not share this teacher printout as a parent calendar.");
  return lines.join("\n");
}

function printCurriculumPlannerTeacherWeek(weekStartDate) {
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) {
    setCurriculumPlannerMessage("Assign a lesson plan before printing the teacher week.", false);
    renderCurriculumPlanner();
    return;
  }
  if (typeof printTextDocument === "function") {
    printTextDocument("Teacher Curriculum Week", buildCurriculumPlannerTeacherPrintText(assignment));
  } else {
    const blob = new Blob([buildCurriculumPlannerTeacherPrintText(assignment)], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    window.open(url, "_blank");
  }
}

function saveCurriculumPlannerParentMessageFromForm(form) {
  if (!form) return;
  const formData = new FormData(form);
  const weekStartDate = curriculumPlannerWeekStartIso(formData.get("weekStartDate") || curriculumPlannerSelectedWeek);
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) throw new Error("Assign a lesson plan before saving the parent calendar.");
  const parentCalendar = normalizeCurriculumParentCalendar({
    ...assignment.parentCalendar,
    parentMessage: String(formData.get("parentMessage") || "").trim(),
    updatedAt: new Date().toISOString(),
  }, { weekStartDate });
  updateCurriculumWeekAssignmentFields(weekStartDate, { parentCalendar });
  setCurriculumPlannerMessage("Parent calendar message saved. Visible to parents — not a teacher note.", true);
  renderCurriculumPlanner();
}

function saveCurriculumPlannerClassroomEventFromForm(form) {
  if (!form) return;
  const formData = new FormData(form);
  const weekStartDate = curriculumPlannerWeekStartIso(formData.get("weekStartDate") || curriculumPlannerSelectedWeek);
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) throw new Error("Assign a lesson plan before adding classroom events.");
  const eventId = String(formData.get("eventId") || "").trim() || generateCurriculumPlannerClassroomEventId();
  const dayOfWeek = String(formData.get("dayOfWeek") || "").toLowerCase();
  const now = new Date().toISOString();
  const existingEvents = assignment.parentCalendar?.classroomEvents || [];
  const existing = existingEvents.find((item) => item.id === eventId);
  const event = normalizeCurriculumPlannerClassroomEvent({
    id: eventId,
    title: String(formData.get("title") || "").trim(),
    eventType: String(formData.get("eventType") || "").trim(),
    date: String(formData.get("date") || curriculumPlannerDateForDay(weekStartDate, dayOfWeek) || weekStartDate).slice(0, 10),
    dayOfWeek: CURRICULUM_WEEKDAYS.includes(dayOfWeek) ? dayOfWeek : "",
    description: String(formData.get("description") || "").trim(),
    itemsToBring: String(formData.get("itemsToBring") || "").trim(),
    createdAt: existing?.createdAt || now,
    updatedAt: now,
  }, { weekStartDate });
  if (!event.title) throw new Error("Enter an event title before saving.");
  const classroomEvents = [
    ...existingEvents.filter((item) => item.id !== eventId),
    event,
  ];
  const parentCalendar = normalizeCurriculumParentCalendar({
    ...assignment.parentCalendar,
    classroomEvents,
    updatedAt: now,
  }, { weekStartDate });
  updateCurriculumWeekAssignmentFields(weekStartDate, { parentCalendar });
  curriculumPlannerEditingEventId = "";
  curriculumPlannerEventPresetDay = "";
  setCurriculumPlannerMessage("Classroom event saved to the Parent Calendar.", true);
  renderCurriculumPlanner();
}

function deleteCurriculumPlannerClassroomEvent(weekStartDate, eventId) {
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) return;
  const parentCalendar = normalizeCurriculumParentCalendar({
    ...assignment.parentCalendar,
    classroomEvents: (assignment.parentCalendar?.classroomEvents || []).filter((item) => item.id !== eventId),
    updatedAt: new Date().toISOString(),
  }, { weekStartDate });
  updateCurriculumWeekAssignmentFields(weekStartDate, { parentCalendar });
  if (curriculumPlannerEditingEventId === eventId) curriculumPlannerEditingEventId = "";
  setCurriculumPlannerMessage("Classroom event deleted from the Parent Calendar.", true);
  renderCurriculumPlanner();
}

function buildCurriculumPlannerParentPrintText(assignment) {
  const dto = buildCurriculumPlannerParentSafeDto(assignment);
  if (!dto) return "";
  const lines = [
    "Little Learner Hub — Parent Calendar",
    `Week of: ${dto.weekStartDate} – ${dto.weekEndDate}`,
    `Classroom: ${dto.classroomLabel || "—"}`,
    `Age Group: ${dto.ageGroup || ""}`,
    `Theme: ${dto.theme || ""}`,
    "",
  ];
  if (dto.parentMessage) {
    lines.push("Message for Families");
    lines.push(dto.parentMessage);
    lines.push("");
  }
  lines.push("Classroom Events");
  if (!dto.classroomEvents.length) {
    lines.push("(none this week)");
  } else {
    dto.classroomEvents.forEach((event) => {
      lines.push(`- ${event.date || ""} ${curriculumPlannerWeekdayLabel(event.dayOfWeek) || ""} · ${event.title} (${event.eventType})`);
      if (event.description) lines.push(`  ${event.description}`);
      if (event.itemsToBring) lines.push(`  Please bring: ${event.itemsToBring}`);
    });
  }
  lines.push("");
  lines.push("This Week’s Curriculum (Family View)");
  lines.push(`Lesson: ${dto.lessonPlanTitle || ""}`);
  if (dto.familyConnection) {
    lines.push(`Family connection: ${dto.familyConnection}`);
  }
  lines.push("");
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const dayData = dto.daily[day] || {};
    lines.push(`${curriculumPlannerWeekdayLabel(day)} (${curriculumPlannerDateForDay(dto.weekStartDate, day)})`);
    lines.push(`Focus: ${dayData.theme || dto.theme || ""}`);
    if ((dayData.classroomEvents || []).length) {
      lines.push(`Events: ${dayData.classroomEvents.map((event) => event.title).join("; ")}`);
    }
    lines.push(`Activities: ${(dayData.activities || []).map((item) => item.title).filter(Boolean).join("; ") || "(none)"}`);
    if ((dayData.books || []).length) {
      lines.push(`Books: ${dayData.books.map((book) => book.title).join("; ")}`);
    }
    if ((dayData.songs || []).length) {
      lines.push(`Songs: ${dayData.songs.map((song) => song.title).join("; ")}`);
    }
    if (dayData.familyConnection) lines.push(`Family: ${dayData.familyConnection}`);
    lines.push("");
  });
  lines.push("Teacher planning notes and observations are not included in this parent calendar.");
  return lines.join("\n");
}

function printCurriculumPlannerParentWeek(weekStartDate) {
  const assignment = curriculumAssignmentForWeek(weekStartDate);
  if (!assignment) {
    setCurriculumPlannerMessage("Assign a lesson plan before printing the parent calendar.", false);
    renderCurriculumPlanner();
    return;
  }
  const text = buildCurriculumPlannerParentPrintText(assignment);
  if (typeof printTextDocument === "function") {
    printTextDocument("Parent Calendar", text);
  } else {
    const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    window.open(url, "_blank");
  }
}

function curriculumPlannerChildOptionsHtml(selectedId = "") {
  const children = getActiveChildren(childRecords());
  if (!children.length) {
    return `<option value="">No child profiles yet (optional)</option>`;
  }
  return [
    `<option value="">Whole group / no child</option>`,
    ...children.map((child) => `
      <option value="${escapeHtml(child.id)}"${child.id === selectedId ? " selected" : ""}>${escapeHtml(child.name || "Child")}</option>
    `),
  ].join("");
}

function curriculumPlannerDayCardHtml(assignment, dayKey) {
  const day = assignment?.snapshot?.dailyPlans?.[dayKey] || snapshotCurriculumDailyDay();
  const dateLabel = curriculumPlannerDateForDay(assignment.weekStartDate, dayKey);
  const activities = (day.items || []).slice(0, 6);
  const dailyNote = assignment?.dailyTeacherNotes?.[dayKey] || "";
  const dayObservations = (assignment?.observations || []).filter((item) => item.dayOfWeek === dayKey);
  const dayEvents = (assignment?.parentCalendar?.classroomEvents || []).filter((item) => item.dayOfWeek === dayKey);
  return `
    <details class="curriculum-planner-day-card" data-curriculum-planner-day="${escapeHtml(dayKey)}" ${dayKey === CURRICULUM_WEEKDAYS[0] ? "open" : ""}>
      <summary class="curriculum-planner-day-header">
        <div>
          <strong>${escapeHtml(curriculumPlannerWeekdayLabel(dayKey))}</strong>
          <small>${escapeHtml(dateLabel || "")}</small>
        </div>
        <span class="tag">${escapeHtml(day.theme || assignment?.snapshot?.theme || "Daily focus")}</span>
      </summary>
      <div class="curriculum-planner-day-body">
        <p class="muted-copy"><strong>${escapeHtml(assignment.lessonPlanTitle)}</strong> · ${escapeHtml(assignment.ageGroup || "")}${assignment.classroomLabel ? ` · ${escapeHtml(assignment.classroomLabel)}` : ""}</p>
        ${dayEvents.length ? `
          <div class="curriculum-planner-day-events">
            <p class="eyebrow">Classroom Events</p>
            <ul class="curriculum-planner-event-chip-list">
              ${dayEvents.map((event) => `<li><span class="tag">${escapeHtml(event.title)}</span></li>`).join("")}
            </ul>
          </div>
        ` : ""}
        ${activities.length ? `
          <ul class="curriculum-planner-activity-list">
            ${activities.map((item) => `<li><strong>${escapeHtml(item.title)}</strong>${item.activityCategory ? ` <span class="muted-copy">(${escapeHtml(item.activityCategory)})</span>` : ""}</li>`).join("")}
          </ul>
        ` : `<p class="muted-copy">No activities on this day in the assigned snapshot.</p>`}
        ${(day.books || []).length ? `<p><strong>Books:</strong> ${escapeHtml(day.books.map((book) => book.title).join(", "))}</p>` : ""}
        ${(day.songs || []).length ? `<p><strong>Songs:</strong> ${escapeHtml(day.songs.map((song) => song.title).join(", "))}</p>` : ""}
        ${(day.circleTime || []).length ? `<p><strong>Circle time:</strong> ${escapeHtml(day.circleTime[0])}${(day.circleTime.length > 1) ? "…" : ""}</p>` : ""}
        ${day.materials ? `<p><strong>Materials:</strong> ${escapeHtml(day.materials.slice(0, 140))}${day.materials.length > 140 ? "…" : ""}</p>` : ""}
        <label class="curriculum-planner-daily-note-label">Private daily note
          <textarea name="dailyNote-${dayKey}" rows="3" form="curriculumPlannerNotesForm" placeholder="Move activity, gather materials, weather backup…">${escapeHtml(dailyNote)}</textarea>
        </label>
        <div class="form-actions">
          <button class="ghost-button" type="button" data-curriculum-planner-add-event="${escapeHtml(dayKey)}">Add classroom event</button>
          <button class="ghost-button" type="button" data-curriculum-planner-add-observation="${escapeHtml(dayKey)}">Add observation</button>
        </div>
        ${dayObservations.length ? `<p class="form-note">${dayObservations.length} observation${dayObservations.length === 1 ? "" : "s"} linked to this day (teacher-only)</p>` : ""}
      </div>
    </details>
  `;
}

function curriculumPlannerObservationCardHtml(assignment, observation) {
  return `
    <article class="curriculum-planner-observation-card" data-curriculum-observation-id="${escapeHtml(observation.id)}">
      <div class="curriculum-planner-observation-meta">
        <strong>${escapeHtml(observation.date || "No date")}</strong>
        <span class="tag">${escapeHtml(curriculumPlannerWeekdayLabel(observation.dayOfWeek) || "Week")}</span>
        ${observation.followUpNeeded ? `<span class="tag">Follow-up</span>` : ""}
      </div>
      <p class="curriculum-planner-observation-note">${escapeHtml(observation.note).replace(/\n/g, "<br>")}</p>
      ${observation.activityTitle ? `<p class="muted-copy">Activity: ${escapeHtml(observation.activityTitle)}</p>` : ""}
      ${observation.activityMissing ? `<p class="form-note curriculum-planner-activity-warning">Linked activity is from a previous lesson plan assignment.</p>` : ""}
      ${observation.childName ? `<p class="muted-copy">Child: ${escapeHtml(observation.childName)}</p>` : `<p class="muted-copy">Whole group</p>`}
      <small class="muted-copy">Updated ${(observation.updatedAt || "").slice(0, 10) || "—"}</small>
      <div class="form-actions">
        <button class="ghost-button" type="button" data-curriculum-planner-edit-observation="${escapeHtml(observation.id)}">Edit</button>
        <button class="danger-button" type="button" data-curriculum-planner-delete-observation="${escapeHtml(observation.id)}">Delete Permanently</button>
      </div>
    </article>
  `;
}

function curriculumPlannerObservationFormHtml(assignment, editingObservation = null, presetDay = "") {
  const obs = editingObservation || {
    id: "",
    date: curriculumPlannerDateForDay(assignment.weekStartDate, presetDay || CURRICULUM_WEEKDAYS[0]),
    dayOfWeek: presetDay || "",
    activityItemId: "",
    note: "",
    followUpNeeded: false,
    childId: "",
  };
  const dayFilter = obs.dayOfWeek || "";
  const activityOptions = curriculumPlannerActivityOptions(assignment, dayFilter || undefined);
  return `
    <form id="curriculumPlannerObservationForm" class="panel-form admin-stacked-form curriculum-planner-observation-form">
      <input type="hidden" name="weekStartDate" value="${escapeHtml(assignment.weekStartDate)}" />
      <input type="hidden" name="observationId" value="${escapeHtml(obs.id || "")}" />
      <div class="form-grid-two">
        <label>Date<input name="date" type="date" value="${escapeHtml(obs.date || "")}" required /></label>
        <label>Weekday
          <select name="dayOfWeek">
            <option value="">Whole week</option>
            ${CURRICULUM_WEEKDAYS.map((day) => `
              <option value="${escapeHtml(day)}"${obs.dayOfWeek === day ? " selected" : ""}>${escapeHtml(curriculumPlannerWeekdayLabel(day))}</option>
            `).join("")}
          </select>
        </label>
      </div>
      <label>Linked activity <span class="muted-copy">(optional)</span>
        <select name="activityItemId">
          <option value="">No specific activity</option>
          ${activityOptions.map((item) => `
            <option value="${escapeHtml(item.itemId)}"${item.itemId && item.itemId === obs.activityItemId ? " selected" : ""}>${escapeHtml(item.label)}</option>
          `).join("")}
        </select>
      </label>
      <label>Child <span class="muted-copy">(optional)</span>
        <select name="childId">${curriculumPlannerChildOptionsHtml(obs.childId || "")}</select>
      </label>
      <label>Observation note
        <textarea name="note" rows="4" required placeholder="What did the group show interest in? What support was needed?">${escapeHtml(obs.note || "")}</textarea>
      </label>
      <label class="admin-inline-toggle">
        <input type="checkbox" name="followUpNeeded" value="1" ${obs.followUpNeeded ? "checked" : ""} />
        <span>Follow-up needed</span>
      </label>
      <p class="form-note">Teacher-only. This observation will not appear on parent calendars.</p>
      <div class="form-actions">
        <button class="primary-button" type="submit">${obs.id ? "Save Observation" : "Add Observation"}</button>
        ${obs.id ? `<button class="ghost-button" type="button" data-curriculum-planner-cancel-observation>Cancel</button>` : ""}
      </div>
    </form>
  `;
}

function curriculumPlannerClassroomEventCardHtml(event) {
  return `
    <article class="curriculum-planner-event-card" data-curriculum-event-id="${escapeHtml(event.id)}">
      <div class="curriculum-planner-observation-meta">
        <strong>${escapeHtml(event.date || "No date")}</strong>
        <span class="tag">${escapeHtml(curriculumPlannerWeekdayLabel(event.dayOfWeek) || "Week")}</span>
        <span class="tag">${escapeHtml(event.eventType || "Event")}</span>
      </div>
      <p class="curriculum-planner-observation-note"><strong>${escapeHtml(event.title)}</strong></p>
      ${event.description ? `<p>${escapeHtml(event.description).replace(/\n/g, "<br>")}</p>` : ""}
      ${event.itemsToBring ? `<p class="muted-copy">Please bring: ${escapeHtml(event.itemsToBring)}</p>` : ""}
      <div class="form-actions">
        <button class="ghost-button" type="button" data-curriculum-planner-edit-event="${escapeHtml(event.id)}">Edit</button>
        <button class="danger-button" type="button" data-curriculum-planner-delete-event="${escapeHtml(event.id)}">Delete Permanently</button>
      </div>
    </article>
  `;
}

function curriculumPlannerClassroomEventFormHtml(assignment, editingEvent = null, presetDay = "") {
  const event = editingEvent || {
    id: "",
    title: "",
    eventType: "Important Reminder",
    date: curriculumPlannerDateForDay(assignment.weekStartDate, presetDay || CURRICULUM_WEEKDAYS[0]),
    dayOfWeek: presetDay || "",
    description: "",
    itemsToBring: "",
  };
  return `
    <form id="curriculumPlannerEventForm" class="panel-form admin-stacked-form curriculum-planner-event-form">
      <input type="hidden" name="weekStartDate" value="${escapeHtml(assignment.weekStartDate)}" />
      <input type="hidden" name="eventId" value="${escapeHtml(event.id || "")}" />
      <div class="form-grid-two">
        <label>Event type
          <select name="eventType" required>
            ${CURRICULUM_CLASSROOM_EVENT_TYPES.map((type) => `
              <option value="${escapeHtml(type)}"${event.eventType === type ? " selected" : ""}>${escapeHtml(type)}</option>
            `).join("")}
          </select>
        </label>
        <label>Title
          <input name="title" value="${escapeHtml(event.title || "")}" placeholder="Water Day, Field Trip to the farm…" required />
        </label>
      </div>
      <div class="form-grid-two">
        <label>Date<input name="date" type="date" value="${escapeHtml(event.date || "")}" required /></label>
        <label>Weekday
          <select name="dayOfWeek">
            <option value="">Whole week</option>
            ${CURRICULUM_WEEKDAYS.map((day) => `
              <option value="${escapeHtml(day)}"${event.dayOfWeek === day ? " selected" : ""}>${escapeHtml(curriculumPlannerWeekdayLabel(day))}</option>
            `).join("")}
          </select>
        </label>
      </div>
      <label>Details for families
        <textarea name="description" rows="3" placeholder="What parents should know…">${escapeHtml(event.description || "")}</textarea>
      </label>
      <label>Items to bring <span class="muted-copy">(optional)</span>
        <input name="itemsToBring" value="${escapeHtml(event.itemsToBring || "")}" placeholder="Towel, swimsuit, labeled water bottle…" />
      </label>
      <p class="form-note">Parent-facing. This appears on the Parent Calendar, not in private teacher notes.</p>
      <div class="form-actions">
        <button class="primary-button" type="submit">${event.id ? "Save Classroom Event" : "Add Classroom Event"}</button>
        ${event.id ? `<button class="ghost-button" type="button" data-curriculum-planner-cancel-event>Cancel</button>` : ""}
      </div>
    </form>
  `;
}

function curriculumPlannerParentPreviewHtml(assignment) {
  const dto = buildCurriculumPlannerParentSafeDto(assignment);
  if (!dto) return "";
  return `
    <div class="curriculum-planner-parent-preview" id="curriculumPlannerParentPreview">
      <div class="dashboard-panel-heading">
        <div>
          <p class="eyebrow">Parent Preview</p>
          <h3>What families will see</h3>
          <p class="muted-copy">Teacher notes and observations are excluded from this preview.</p>
        </div>
      </div>
      ${dto.parentMessage ? `<p class="curriculum-planner-parent-message">${escapeHtml(dto.parentMessage).replace(/\n/g, "<br>")}</p>` : ""}
      <p><strong>${escapeHtml(dto.lessonPlanTitle || "This week")}</strong> · ${escapeHtml(dto.theme || "")}</p>
      ${(dto.classroomEvents || []).length ? `
        <div class="curriculum-planner-preview-events">
          <p class="eyebrow">Classroom Events</p>
          <ul>
            ${dto.classroomEvents.map((event) => `
              <li>
                <strong>${escapeHtml(event.title)}</strong>
                <span class="muted-copy">${escapeHtml(event.date || "")}${event.dayOfWeek ? ` · ${escapeHtml(curriculumPlannerWeekdayLabel(event.dayOfWeek))}` : ""}</span>
                ${event.itemsToBring ? `<br><span class="muted-copy">Bring: ${escapeHtml(event.itemsToBring)}</span>` : ""}
              </li>
            `).join("")}
          </ul>
        </div>
      ` : `<p class="muted-copy">No classroom events this week.</p>`}
      <div class="curriculum-planner-preview-days">
        ${CURRICULUM_WEEKDAYS.map((day) => {
          const dayData = dto.daily[day] || {};
          return `
            <div class="curriculum-planner-preview-day">
              <strong>${escapeHtml(curriculumPlannerWeekdayLabel(day))}</strong>
              <small>${escapeHtml(curriculumPlannerDateForDay(dto.weekStartDate, day))}</small>
              <p>${escapeHtml(dayData.theme || dto.theme || "")}</p>
              <p class="muted-copy">${(dayData.activities || []).map((item) => item.title).filter(Boolean).slice(0, 3).join(" · ") || "No activities listed"}</p>
            </div>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function curriculumPlannerEmptyStateHtml(weekStart) {
  return `
    <section class="section-block curriculum-planner-empty">
      <h3>No lesson plan assigned for this week</h3>
      <p class="muted-copy">Choose a complete Monday–Friday lesson plan below. Monday content maps to Monday, Tuesday to Tuesday, and so on.</p>
      <div class="form-actions">
        <button class="ghost-button" type="button" data-view="lessons">Browse Lesson Plan Library</button>
      </div>
      <p class="form-note">Week of ${escapeHtml(weekStart)} – ${escapeHtml(curriculumPlannerWeekEndIso(weekStart))}</p>
    </section>
  `;
}

function renderCurriculumPlanner() {
  const app = document.querySelector("#curriculumPlannerApp");
  if (!app) return;
  if (!curriculumPlannerSelectedWeek) {
    curriculumPlannerSelectedWeek = curriculumPlannerWeekStartIso(new Date());
  } else {
    curriculumPlannerSelectedWeek = curriculumPlannerWeekStartIso(curriculumPlannerSelectedWeek);
  }
  const weekStart = curriculumPlannerSelectedWeek;
  const assignment = curriculumAssignmentForWeek(weekStart);
  const pendingResourceId = curriculumPlannerAssignResourceId
    || assignment?.lessonPlanId
    || "";
  const pendingResource = resources.find((item) => item.id === pendingResourceId);
  const defaultAge = assignment?.ageGroup
    || pendingResource?.age
    || pendingResource?._curriculumLessonPlan?.age
    || "Preschool";
  const message = curriculumPlannerMessage?.text
    ? `<div class="form-message ${curriculumPlannerMessage.isSuccess ? "success" : ""}" role="status">${escapeHtml(curriculumPlannerMessage.text)}</div>`
    : "";
  const editingObservation = assignment?.observations?.find((item) => item.id === curriculumPlannerEditingObservationId) || null;
  const observationPresetDay = curriculumPlannerObservationPresetDay || "";
  const editingEvent = assignment?.parentCalendar?.classroomEvents?.find((item) => item.id === curriculumPlannerEditingEventId) || null;
  const eventPresetDay = curriculumPlannerEventPresetDay || "";
  const parentEvents = assignment?.parentCalendar?.classroomEvents || [];
  app.innerHTML = `
    <div class="curriculum-planner-shell">
      ${message}
      ${freePlannerUpgradeNudgeHtml()}
      <section class="section-block curriculum-planner-setup">
        <div class="dashboard-panel-heading">
          <div>
            <p class="eyebrow">This Week</p>
            <h3>${escapeHtml(weekStart)} – ${escapeHtml(curriculumPlannerWeekEndIso(weekStart))}</h3>
            <p class="muted-copy">Assign one full play-based lesson plan. Content is saved as a snapshot so Admin edits will not silently change your week.</p>
          </div>
        </div>
        <form id="curriculumPlannerAssignForm" class="panel-form admin-stacked-form curriculum-planner-assign-form">
          <div class="form-grid-two">
            <label>Week of
              <input name="weekStartDate" type="date" value="${escapeHtml(weekStart)}" required />
            </label>
            <label>Age group
              <select name="ageGroup" required>
                ${["Infant", "Toddler", "Preschool", "Mixed Ages"].map((age) => `
                  <option value="${escapeHtml(age)}"${age === defaultAge ? " selected" : ""}>${escapeHtml(age)}</option>
                `).join("")}
              </select>
            </label>
          </div>
          <label>Classroom label <span class="muted-copy">(optional)</span>
            <input name="classroomLabel" value="${escapeHtml(assignment?.classroomLabel || "")}" placeholder="Blue Room, Toddlers, Home daycare" />
          </label>
          <label>Lesson plan
            <select name="lessonPlanId" required>
              ${curriculumPlannerAssignableOptionsHtml(pendingResourceId)}
            </select>
          </label>
          ${assignment ? `
            <p class="form-note">Updating the lesson plan refreshes the snapshot but keeps your teacher notes and observations.</p>
          ` : ""}
          <div class="form-actions">
            <button class="primary-button" type="submit" ${curriculumPlannerBusy ? "disabled" : ""}>
              ${curriculumPlannerBusy ? "Assigning…" : (assignment ? "Update Assignment" : "Assign to Week")}
            </button>
            ${assignment ? `<button class="danger-button" type="button" data-curriculum-planner-remove-week="${escapeHtml(weekStart)}">Remove From Week</button>` : ""}
            <button class="ghost-button" type="button" data-view="lessons">Browse Library</button>
          </div>
        </form>
      </section>

      ${assignment ? `
        <section class="section-block curriculum-planner-week-summary">
          <div class="dashboard-panel-heading">
            <div>
              <p class="eyebrow">Assigned Lesson Plan</p>
              <h3>${escapeHtml(assignment.lessonPlanTitle)}</h3>
              <p class="muted-copy">
                ${escapeHtml(assignment.snapshot?.theme || "Theme")} · ${escapeHtml(assignment.ageGroup)}
                ${assignment.classroomLabel ? ` · ${escapeHtml(assignment.classroomLabel)}` : ""}
                · ${escapeHtml(assignment.lessonPlanPlan || "Free")}
              </p>
            </div>
            <div class="form-actions">
              <button class="ghost-button" type="button" data-view-resource="${escapeHtml(assignment.lessonPlanId)}">Open Lesson Plan</button>
              <button class="ghost-button" type="button" data-curriculum-planner-print-teacher="${escapeHtml(weekStart)}">Print Teacher Week</button>
              <button class="ghost-button" type="button" data-curriculum-planner-print-parent="${escapeHtml(weekStart)}">Print Parent Calendar</button>
              <button class="ghost-button" type="button" data-curriculum-planner-toggle-parent-preview="${escapeHtml(weekStart)}">
                ${curriculumPlannerShowParentPreview ? "Hide Parent Preview" : "Show Parent Preview"}
              </button>
            </div>
          </div>
          ${assignment.snapshot?.weeklyOverview ? `<p>${escapeHtml(assignment.snapshot.weeklyOverview.slice(0, 280))}${assignment.snapshot.weeklyOverview.length > 280 ? "…" : ""}</p>` : ""}
          <p class="form-note">Snapshot saved ${escapeHtml((assignment.updatedAt || "").slice(0, 10) || "today")}. Teacher notes stay private.</p>
          ${curriculumPlannerShowParentPreview ? curriculumPlannerParentPreviewHtml(assignment) : ""}
        </section>

        <section class="curriculum-planner-day-board" aria-label="Monday to Friday assigned content">
          ${CURRICULUM_WEEKDAYS.map((day) => curriculumPlannerDayCardHtml(assignment, day)).join("")}
        </section>

        <section class="section-block curriculum-planner-parent-calendar-section">
          <div class="dashboard-panel-heading">
            <div>
              <p class="eyebrow">Parent Calendar</p>
              <h3>Classroom Events</h3>
              <p class="muted-copy">Parent-facing events and reminders for this week. Separate from private teacher notes.</p>
            </div>
            <button class="ghost-button" type="button" data-curriculum-planner-add-event="">Add Classroom Event</button>
          </div>
          <form id="curriculumPlannerParentMessageForm" class="panel-form admin-stacked-form">
            <input type="hidden" name="weekStartDate" value="${escapeHtml(weekStart)}" />
            <label>Weekly message for families <span class="muted-copy">(optional)</span>
              <textarea name="parentMessage" rows="3" placeholder="Hello families — this week we are exploring gardens. Friday is Water Day!">${escapeHtml(assignment.parentCalendar?.parentMessage || "")}</textarea>
            </label>
            <div class="form-actions">
              <button class="primary-button" type="submit">Save Parent Message</button>
            </div>
          </form>
          <details class="curriculum-planner-events-panel" ${editingEvent || eventPresetDay || !parentEvents.length ? "open" : ""}>
            <summary>${editingEvent || eventPresetDay ? "Classroom event form · tap to collapse" : "Add or edit classroom event · tap to expand"}</summary>
            <div class="curriculum-planner-events-body">
              ${curriculumPlannerClassroomEventFormHtml(assignment, editingEvent, eventPresetDay)}
            </div>
          </details>
          <div class="curriculum-planner-event-list">
            ${parentEvents.length
              ? parentEvents.map((event) => curriculumPlannerClassroomEventCardHtml(event)).join("")
              : `<p class="muted-copy">No classroom events yet. Add Water Day, Field Trip, Items to Bring, and other family reminders here.</p>`
            }
          </div>
        </section>

        <section class="section-block curriculum-planner-notes-section">
          <div class="dashboard-panel-heading">
            <div>
              <p class="eyebrow">Teacher Only</p>
              <h3>Teacher Notes &amp; Preparation</h3>
              <p class="muted-copy">Private planning notes. These never appear on parent calendars.</p>
            </div>
          </div>
          <form id="curriculumPlannerNotesForm" class="panel-form admin-stacked-form">
            <input type="hidden" name="weekStartDate" value="${escapeHtml(weekStart)}" />
            <label>Weekly Teacher Notes
              <textarea name="teacherNotes" rows="4" placeholder="General weekly notes, classroom reminders, changes for next week…">${escapeHtml(assignment.teacherNotes || "")}</textarea>
            </label>
            <label>Preparation / Materials Reminder
              <textarea name="preparationNotes" rows="3" placeholder="Supplies to gather, setup reminders, prep list…">${escapeHtml(assignment.preparationNotes || "")}</textarea>
            </label>
            <p class="form-note">Daily notes are edited on each weekday card above and saved with this form.</p>
            <div class="form-actions">
              <button class="primary-button" type="submit">Save Teacher Notes</button>
              <button class="ghost-button" type="button" data-curriculum-planner-clear-notes="${escapeHtml(weekStart)}">Clear Notes</button>
            </div>
          </form>
        </section>

        <section class="section-block curriculum-planner-observations-section">
          <div class="dashboard-panel-heading">
            <div>
              <p class="eyebrow">Teacher Only</p>
              <h3>Group Observations</h3>
              <p class="muted-copy">Quick classroom notes linked to this week. Child link is optional.</p>
            </div>
            <button class="ghost-button" type="button" data-curriculum-planner-add-observation="">Add Observation</button>
          </div>
          <details class="curriculum-planner-observations-panel" ${editingObservation || observationPresetDay || !(assignment.observations || []).length ? "open" : ""}>
            <summary>${editingObservation || observationPresetDay ? "Observation form · tap to collapse" : "Add or edit observation form · tap to expand"}</summary>
            <div class="curriculum-planner-observations-body">
              ${curriculumPlannerObservationFormHtml(assignment, editingObservation, observationPresetDay)}
            </div>
          </details>
          <div class="curriculum-planner-observation-list">
            ${(assignment.observations || []).length
              ? (assignment.observations || []).map((obs) => curriculumPlannerObservationCardHtml(assignment, obs)).join("")
              : `<p class="muted-copy">No observations yet for this week.</p>`
            }
          </div>
        </section>
      ` : curriculumPlannerEmptyStateHtml(weekStart)}
    </div>
  `;
}

function dashboardBirthdaysThisWeek(weekStart) {
  const records = typeof childRecords === "function" ? childRecords() : { children: [] };
  const children = typeof getActiveChildren === "function" ? getActiveChildren(records) : (records.children || []);
  const birthdays = [];
  CURRICULUM_WEEKDAYS.forEach((day) => {
    const iso = curriculumPlannerDateForDay(weekStart, day);
    if (!iso) return;
    const [, month, date] = iso.split("-");
    children.forEach((child) => {
      const dob = String(child.dob || "");
      if (dob.length < 10) return;
      const [, dobMonth, dobDay] = dob.split("-");
      if (dobMonth === month && dobDay === date) {
        birthdays.push({
          date: iso,
          dayOfWeek: day,
          name: child.name || "Child",
        });
      }
    });
  });
  return birthdays;
}

function dashboardWeekStripMarkup({
  weekStart,
  weekEnd,
  doc,
  assignment,
  todayKey,
} = {}) {
  const todayIso = isoDateFromLocalDate(new Date());
  const weekItems = (doc?.items || []).filter((item) => {
    if (item.type === "lesson_plan") {
      return item.weekStartDate === weekStart;
    }
    return item.startDate >= weekStart && item.startDate <= weekEnd;
  });
  const birthdays = dashboardBirthdaysThisWeek(weekStart);
  const dayCells = CURRICULUM_WEEKDAYS.map((day) => {
    const iso = curriculumPlannerDateForDay(weekStart, day);
    const isToday = iso === todayIso || day === todayKey;
    const dayEvents = weekItems.filter((item) => item.type !== "lesson_plan" && item.startDate === iso);
    const dayBirthdays = birthdays.filter((item) => item.date === iso);
    const hasLesson = Boolean(assignment);
    const marks = [];
    if (hasLesson) marks.push({ kind: "lesson", label: "Lesson" });
    dayEvents.forEach((event) => {
      marks.push({
        kind: event.type === "closure" ? "closure" : event.type === "reminder" ? "reminder" : "event",
        label: event.title || calendarEventTypeLabel(event.type),
      });
    });
    dayBirthdays.forEach((bday) => {
      marks.push({ kind: "birthday", label: `${bday.name}'s birthday` });
    });
    const dayNum = iso ? Number(iso.slice(8, 10)) : "";
    return `
      <button type="button" class="llh-dash-weekstrip-day ${isToday ? "is-today" : ""} ${hasLesson ? "has-lesson" : ""}" data-view="calendar" data-dash-select-week="${escapeHtml(weekStart)}" title="${escapeHtml(curriculumPlannerWeekdayLabel(day))}${marks.length ? ` · ${marks.map((m) => m.label).join(", ")}` : ""}">
        <span class="llh-dash-weekstrip-dow">${escapeHtml(curriculumPlannerWeekdayLabel(day).slice(0, 3))}</span>
        <span class="llh-dash-weekstrip-num">${dayNum}</span>
        <span class="llh-dash-weekstrip-marks" aria-hidden="true">
          ${marks.slice(0, 3).map((mark) => `<i class="llh-dash-mark llh-dash-mark-${escapeHtml(mark.kind)}"></i>`).join("")}
        </span>
      </button>
    `;
  }).join("");

  const legendBits = [];
  if (assignment) legendBits.push(`Lesson: ${assignment.lessonPlanTitle}`);
  const closures = weekItems.filter((item) => item.type === "closure");
  const events = weekItems.filter((item) => item.type === "classroom_event");
  const reminders = weekItems.filter((item) => item.type === "reminder");
  if (closures.length) legendBits.push(`${closures.length} closure${closures.length === 1 ? "" : "s"}`);
  if (events.length) legendBits.push(`${events.length} event${events.length === 1 ? "" : "s"}`);
  if (reminders.length) legendBits.push(`${reminders.length} reminder${reminders.length === 1 ? "" : "s"}`);
  if (birthdays.length) legendBits.push(`${birthdays.length} birthday${birthdays.length === 1 ? "" : "s"}`);

  return `
    <section class="llh-ds-card llh-dash-weekstrip" aria-label="This week at a glance">
      <div class="llh-dash-weekstrip-head">
        <div>
          <p class="eyebrow">This week</p>
          <h3>Week of ${escapeHtml(weekStart)}</h3>
          <p class="muted-copy">${legendBits.length ? escapeHtml(legendBits.join(" · ")) : "No lesson plan or events yet — open Calendar to plan."}</p>
        </div>
        <button type="button" class="ghost-button" data-view="calendar" data-dash-select-week="${escapeHtml(weekStart)}">Open Calendar</button>
      </div>
      <div class="llh-dash-weekstrip-grid" role="group" aria-label="Monday to Friday">
        ${dayCells}
      </div>
      <div class="llh-dash-weekstrip-legend" aria-hidden="true">
        <span><i class="llh-dash-mark llh-dash-mark-lesson"></i> Lesson</span>
        <span><i class="llh-dash-mark llh-dash-mark-event"></i> Event</span>
        <span><i class="llh-dash-mark llh-dash-mark-closure"></i> Closure</span>
        <span><i class="llh-dash-mark llh-dash-mark-reminder"></i> Reminder</span>
        <span><i class="llh-dash-mark llh-dash-mark-birthday"></i> Birthday</span>
      </div>
    </section>
  `;
}

function dashboardScheduleOverviewMarkup() {
  const api = getScheduleApi();
  const weekStart = curriculumPlannerWeekStartIso(new Date());
  const weekEnd = curriculumPlannerWeekEndIso(weekStart);
  const doc = scheduleDocCache || (api ? api.readCache(scheduleApiEmail()) : null);
  const scheduleItem = api && doc ? api.lessonForWeek(doc, weekStart) : null;
  const assignment = scheduleItem
    ? {
      lessonPlanId: scheduleItem.lessonPlanId,
      lessonPlanTitle: scheduleItem.lessonPlanTitle,
      ageGroup: scheduleItem.ageGroup,
      classroomLabel: scheduleClassroomName(doc),
      snapshot: scheduleItem.snapshot,
      execution: scheduleItem.execution,
    }
    : (() => {
      const legacy = curriculumAssignmentForWeek(weekStart);
      return legacy ? { ...legacy, classroomLabel: legacy.classroomLabel || "" } : null;
    })();
  const todayKey = CURRICULUM_WEEKDAYS[(new Date().getDay() + 6) % 7] || "";
  const todayPlan = assignment?.snapshot?.dailyPlans?.[todayKey] || {};
  const todayActivities = (todayPlan.items || []).slice(0, 4);
  const todayReminders = (doc?.items || [])
    .filter((item) => ["reminder", "closure", "classroom_event"].includes(item.type) && item.startDate === curriculumPlannerDateForDay(weekStart, todayKey))
    .slice(0, 3);
  const upcomingLessons = (doc?.items || [])
    .filter((item) => item.type === "lesson_plan" && item.weekStartDate > weekStart)
    .sort((a, b) => a.weekStartDate.localeCompare(b.weekStartDate))
    .slice(0, 2);
  const upcomingEvents = (doc?.items || [])
    .filter((item) => ["classroom_event", "closure", "reminder"].includes(item.type) && item.startDate > curriculumPlannerDateForDay(weekStart, todayKey || "friday"))
    .sort((a, b) => a.startDate.localeCompare(b.startDate))
    .slice(0, 4);
  const obsDueNote = todayKey
    ? (assignment?.execution?.dailyTeacherNotes?.[todayKey] ? "Teacher notes started for today." : "Add observation notes in Weekly Planner.")
    : "Weekend — review the week in Weekly Planner.";

  return `
    ${dashboardWeekStripMarkup({ weekStart, weekEnd, doc, assignment, todayKey })}

    <section class="llh-dash-primary">
      <div class="llh-ds-card llh-dash-today">
        <p class="eyebrow">Today</p>
        <h3>${escapeHtml(curriculumPlannerWeekdayLabel(todayKey) || "Weekend")}</h3>
        ${assignment
          ? `<p class="llh-dash-theme">${escapeHtml(todayPlan.theme || assignment.snapshot?.theme || assignment.lessonPlanTitle)}</p>
            ${todayActivities.length
              ? `<ul class="llh-dash-activity-list">${todayActivities.map((item) => `<li>${escapeHtml(item.title)}</li>`).join("")}</ul>`
              : `<p class="muted-copy">${todayKey ? "No activities listed for today." : "View Weekly Plan to review this week."}</p>`
            }
            <div class="llh-dash-today-meta">
              ${todayReminders.length
                ? `<p class="llh-dash-meta-line"><span>Reminders</span> ${todayReminders.map((item) => escapeHtml(item.title)).join(", ")}</p>`
                : `<p class="llh-dash-meta-line muted-copy"><span>Reminders</span> None today</p>`
              }
              <p class="llh-dash-meta-line muted-copy"><span>Observations</span> ${escapeHtml(obsDueNote)}</p>
            </div>`
          : `<p class="muted-copy">Nothing planned for today yet.</p>`
        }
      </div>

      <div class="llh-ds-card llh-dash-week">
        <p class="eyebrow">This Week</p>
        ${assignment
          ? `<h3>${escapeHtml(assignment.lessonPlanTitle)}</h3>
             <p class="muted-copy">${escapeHtml(weekStart)} – ${escapeHtml(weekEnd)}${assignment.classroomLabel ? ` · ${escapeHtml(assignment.classroomLabel)}` : ""}</p>
             <div class="form-actions">
               <button class="primary-button" type="button" data-view="planner">View Weekly Plan</button>
               <button class="ghost-button" type="button" data-view="calendar">Open Calendar</button>
             </div>`
          : `<h3>No plan assigned</h3>
             <p class="muted-copy">${escapeHtml(weekStart)} – ${escapeHtml(weekEnd)}</p>
             <div class="form-actions">
               <button class="primary-button" type="button" data-view="calendar">Open Calendar</button>
             </div>`
        }
      </div>

      <div class="llh-ds-card llh-dash-upcoming">
        <p class="eyebrow">Upcoming</p>
        ${upcomingLessons.length || upcomingEvents.length
          ? `<ul class="llh-dash-upcoming-list">
              ${upcomingLessons.map((item) => `<li><strong>${escapeHtml(item.lessonPlanTitle)}</strong><small>${escapeHtml(item.weekStartDate)}</small></li>`).join("")}
              ${upcomingEvents.map((item) => `<li>${escapeHtml(item.title || item.type)}<small>${escapeHtml(item.startDate)}</small></li>`).join("")}
            </ul>
            <div class="form-actions">
              <button class="ghost-button" type="button" data-view="calendar">Plan in Calendar</button>
            </div>`
          : `<p class="muted-copy">Nothing upcoming yet.</p>
             <div class="form-actions">
               <button class="ghost-button" type="button" data-view="calendar">Plan in Calendar</button>
             </div>`
        }
      </div>
    </section>
  `;
}

function dashboardCurriculumWeekMarkup() {
  return dashboardScheduleOverviewMarkup();
}

function mainCalendarMonthLabel(date) {
  return date.toLocaleDateString(undefined, { month: "long", year: "numeric" });
}

const CALENDAR_MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

const CALENDAR_FILTER_CATEGORIES = [
  { key: "curriculum", label: "Lesson Plans", icon: "📘" },
  { key: "child", label: "Birthdays & Child", icon: "🎂" },
  { key: "classroom", label: "Classroom", icon: "🎨" },
  { key: "director", label: "Director/Compliance", icon: "🛡️" },
  { key: "family", label: "Family/Center", icon: "🏫" },
];

function loadCalendarFilters() {
  if (mainCalendarActiveFilters) return mainCalendarActiveFilters;
  let parsed = null;
  try {
    parsed = JSON.parse(localStorage.getItem("llhCalendarFilters") || "null");
  } catch {
    parsed = null;
  }
  mainCalendarActiveFilters = CALENDAR_FILTER_CATEGORIES.reduce((acc, cat) => {
    acc[cat.key] = parsed && typeof parsed[cat.key] === "boolean" ? parsed[cat.key] : true;
    return acc;
  }, {});
  return mainCalendarActiveFilters;
}

function saveCalendarFilters() {
  try {
    localStorage.setItem("llhCalendarFilters", JSON.stringify(loadCalendarFilters()));
  } catch {
    /* ignore persistence failures */
  }
}

function toggleCalendarFilter(key) {
  const filters = loadCalendarFilters();
  if (!(key in filters)) return;
  filters[key] = !filters[key];
  saveCalendarFilters();
}

function isCalendarCategoryVisible(category) {
  return loadCalendarFilters()[category] !== false;
}

function calendarItemCategory(type) {
  if (type === "birthday" || type === "enrollment_anniversary" || type === "observation_reminder") return "child";
  const api = getScheduleApi();
  if (api?.scheduleItemCategory) return api.scheduleItemCategory(type);
  if (type === "lesson_plan") return "curriculum";
  if (type === "closure" || type === "family_event") return "family";
  if (type === "director_event") return "director";
  return "classroom";
}

function calendarCategoryLabel(category) {
  return (CALENDAR_FILTER_CATEGORIES.find((cat) => cat.key === category) || {}).label || "Item";
}

function calendarEventTypeLabel(type) {
  const labels = {
    closure: "Closure",
    classroom_event: "Classroom Event",
    reminder: "Reminder",
    director_event: "Director",
    family_event: "Family/Center",
    day_note: "Note",
    birthday: "Birthday",
    enrollment_anniversary: "Anniversary",
    observation_reminder: "Observation",
  };
  return labels[type] || "Item";
}

function calendarFilterBarHtml() {
  const filters = loadCalendarFilters();
  return `
    <div class="llh-cal-filter-bar" role="group" aria-label="Show or hide calendar categories">
      ${CALENDAR_FILTER_CATEGORIES.map((cat) => `
        <button type="button" class="llh-cal-filter-chip ${filters[cat.key] !== false ? "is-active" : ""}" data-calendar-toggle-filter="${cat.key}" aria-pressed="${filters[cat.key] !== false ? "true" : "false"}">
          <span aria-hidden="true">${cat.icon}</span> ${escapeHtml(cat.label)}
        </button>
      `).join("")}
    </div>
  `;
}

function calendarMonthOptionsHtml(selectedMonthIndex) {
  return CALENDAR_MONTH_NAMES.map((name, index) => `<option value="${index}" ${index === selectedMonthIndex ? "selected" : ""}>${name}</option>`).join("");
}

function calendarYearOptionsHtml(selectedYear) {
  const base = new Date().getFullYear();
  const years = new Set();
  for (let y = base - 4; y <= base + 4; y += 1) years.add(y);
  years.add(selectedYear);
  return Array.from(years).sort((a, b) => a - b)
    .map((y) => `<option value="${y}" ${y === selectedYear ? "selected" : ""}>${y}</option>`)
    .join("");
}

function calendarEachDateIso(fromIso, toIso, callback) {
  const cursorDate = new Date(`${String(fromIso || "").slice(0, 10)}T12:00:00`);
  const endDate = new Date(`${String(toIso || "").slice(0, 10)}T12:00:00`);
  if (Number.isNaN(cursorDate.getTime()) || Number.isNaN(endDate.getTime())) return;
  let guard = 0;
  while (cursorDate.getTime() <= endDate.getTime() && guard < 400) {
    callback(isoDateFromLocalDate(cursorDate));
    cursorDate.setDate(cursorDate.getDate() + 1);
    guard += 1;
  }
}

// Phase B — childcare calendar content. These are computed at render time from
// the Children module (dob / enrollmentDate / observation goals) and are never
// written to the ScheduleItem store, so there is no duplicate birthday data and
// no risk of drifting from a child's real profile.
function calendarBirthdayItemsInRange(fromIso, toIso) {
  if (typeof childRecords !== "function") return [];
  const records = childRecords();
  const children = typeof getActiveChildren === "function" ? getActiveChildren(records) : (records.children || []);
  const items = [];
  calendarEachDateIso(fromIso, toIso, (iso) => {
    const [, month, day] = iso.split("-");
    (children || []).forEach((child) => {
      const dob = String(child.dob || "");
      if (dob.length < 10) return;
      const [, dobMonth, dobDay] = dob.split("-");
      if (dobMonth === month && dobDay === day) {
        items.push({
          id: `virtual-birthday-${child.id}-${iso}`,
          type: "birthday",
          category: "child",
          title: `${child.name || "Child"}’s Birthday`,
          startDate: iso,
          endDate: iso,
          allDay: true,
          isVirtual: true,
        });
      }
    });
  });
  return items;
}

function calendarEnrollmentAnniversaryItemsInRange(fromIso, toIso) {
  if (typeof childRecords !== "function") return [];
  const records = childRecords();
  const children = typeof getActiveChildren === "function" ? getActiveChildren(records) : (records.children || []);
  const items = [];
  calendarEachDateIso(fromIso, toIso, (iso) => {
    const [year, month, day] = iso.split("-");
    (children || []).forEach((child) => {
      const enrolled = String(child.enrollmentDate || "");
      if (enrolled.length < 10) return;
      const [enrollYear, enrollMonth, enrollDay] = enrolled.split("-");
      if (enrollMonth === month && enrollDay === day && Number(year) > Number(enrollYear)) {
        const years = Number(year) - Number(enrollYear);
        items.push({
          id: `virtual-enrollment-${child.id}-${iso}`,
          type: "enrollment_anniversary",
          category: "child",
          title: `${child.name || "Child"} — ${years} yr${years === 1 ? "" : "s"} enrolled`,
          startDate: iso,
          endDate: iso,
          allDay: true,
          isVirtual: true,
        });
      }
    });
  });
  return items;
}

function calendarObservationReminderItemsInRange(fromIso, toIso) {
  if (typeof childRecords !== "function" || typeof monthlyObservationSummary !== "function") return [];
  const records = childRecords();
  const children = typeof getActiveChildren === "function" ? getActiveChildren(records) : (records.children || []);
  const observations = records.observations || [];
  const items = [];
  try {
    calendarEachDateIso(fromIso, toIso, (iso) => {
      const date = new Date(`${iso}T12:00:00`);
      const nextDay = new Date(date);
      nextDay.setDate(nextDay.getDate() + 1);
      const isLastDayOfMonth = nextDay.getMonth() !== date.getMonth();
      if (!isLastDayOfMonth) return;
      if (typeof isObservationInCurrentMonth === "function" && !isObservationInCurrentMonth(iso)) return;
      (children || []).forEach((child) => {
        const summary = monthlyObservationSummary(child, observations);
        if (summary.remaining > 0) {
          items.push({
            id: `virtual-observation-${child.id}-${iso}`,
            type: "observation_reminder",
            category: "child",
            title: `${child.name || "Child"}: ${summary.remaining} observation${summary.remaining === 1 ? "" : "s"} due this month`,
            startDate: iso,
            endDate: iso,
            allDay: true,
            isVirtual: true,
          });
        }
      });
    });
  } catch {
    return [];
  }
  return items;
}

function calendarDerivedChildItemsInRange(fromIso, toIso) {
  return [
    ...calendarBirthdayItemsInRange(fromIso, toIso),
    ...calendarEnrollmentAnniversaryItemsInRange(fromIso, toIso),
    ...calendarObservationReminderItemsInRange(fromIso, toIso),
  ];
}

function calendarVisibleItemsForDate(realItems, derivedItems, iso) {
  const real = (realItems || []).filter(
    (item) => item.type !== "lesson_plan"
      && item.type !== "day_note"
      && item.startDate === iso
      && isCalendarCategoryVisible(calendarItemCategory(item.type)),
  );
  const derived = isCalendarCategoryVisible("child") ? (derivedItems || []).filter((item) => item.startDate === iso) : [];
  return [...real, ...derived];
}

function calendarDayNoteForDate(doc, iso) {
  const date = String(iso || "").slice(0, 10);
  if (!date) return null;
  return (doc?.items || []).find((item) => item.type === "day_note" && item.startDate === date) || null;
}

function calendarItemById(itemId) {
  const api = getScheduleApi();
  const doc = scheduleDocCache || (api ? api.readCache(scheduleApiEmail()) : null);
  return (doc?.items || []).find((item) => item.id === itemId) || null;
}

function calendarDayItemCardHtml(item) {
  const category = item.category || calendarItemCategory(item.type);
  const timeLabel = !item.isVirtual && !item.allDay && item.startTime
    ? `${escapeHtml(item.startTime)}${item.endTime ? `–${escapeHtml(item.endTime)}` : ""}`
    : "";
  const isPlacement = item.type === "lesson_plan";
  const removeLabel = isPlacement ? "Remove From Calendar" : "Delete Permanently";
  const menuId = `cal-item-${item.id}`;
  return `
    <article class="llh-cal-day-item llh-cal-day-item-${escapeHtml(category)}">
      <div>
        <p class="eyebrow">${escapeHtml(calendarCategoryLabel(category))}${timeLabel ? ` · ${timeLabel}` : ""}</p>
        <strong>${escapeHtml(item.title || calendarEventTypeLabel(item.type))}</strong>
        ${item.itemsToBring ? `<p class="muted-copy">Bring: ${escapeHtml(item.itemsToBring)}</p>` : ""}
        ${item.notes ? `<p class="muted-copy">${escapeHtml(item.notes)}</p>` : ""}
      </div>
      ${!item.isVirtual ? `
        <div class="llh-cal-day-item-actions">
          <button type="button" class="ghost-button" data-calendar-edit-item="${escapeHtml(item.id)}">Edit</button>
          ${itemActionMenuHtml(menuId, [
            { label: "Open / Edit", attr: `data-calendar-edit-item="${escapeHtml(item.id)}"` },
            { label: removeLabel, attr: `data-calendar-delete-item="${escapeHtml(item.id)}"`, danger: true },
          ])}
        </div>
      ` : ""}
    </article>
  `;
}

function renderMainCalendar() {
  const app = document.querySelector("#mainCalendarApp");
  if (!app) return;
  syncPlatformInstallCard();
  loadCalendarFilters();
  if (mainCalendarSubView === "day" && mainCalendarSelectedDay) {
    renderCalendarDayView(app);
  } else if (mainCalendarSubView === "week" && mainCalendarSelectedWeek) {
    renderCalendarWeekView(app);
  } else {
    mainCalendarSubView = "month";
    renderCalendarMonthView(app);
  }
}

function renderCalendarMonthView(app) {
  const api = getScheduleApi();
  if (!mainCalendarMonthCursor) mainCalendarMonthCursor = new Date();
  const cursor = new Date(mainCalendarMonthCursor.getFullYear(), mainCalendarMonthCursor.getMonth(), 1);
  const year = cursor.getFullYear();
  const month = cursor.getMonth();
  const bounds = api ? api.monthBounds(year, month) : { from: "", to: "" };
  const doc = scheduleDocCache || (api ? api.readCache(scheduleApiEmail()) : null) || { items: [], classrooms: [] };
  const items = api ? api.itemsInRange(doc, bounds.from, bounds.to) : [];
  const monthFrom = bounds.from || `${year}-${String(month + 1).padStart(2, "0")}-01`;
  const monthTo = bounds.to || isoDateFromLocalDate(new Date(year, month + 1, 0));
  const derivedChildItems = calendarDerivedChildItemsInRange(monthFrom, monthTo);
  const todayIso = isoDateFromLocalDate(new Date());
  const monthHasLessons = items.some((item) => item.type === "lesson_plan");

  const firstDow = new Date(year, month, 1).getDay(); // Sunday-first — matches Sun..Sat columns directly
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < firstDow; i += 1) cells.push({ day: null });
  for (let day = 1; day <= daysInMonth; day += 1) {
    const date = new Date(year, month, day);
    const iso = isoDateFromLocalDate(date);
    const week = curriculumPlannerWeekStartIso(date);
    const dow = date.getDay();
    const lesson = api ? api.lessonForWeek(doc, week) : null;
    const dayItems = calendarVisibleItemsForDate(items, derivedChildItems, iso);
    cells.push({ day, iso, week, lesson, dayItems, weekend: dow === 0 || dow === 6, dow });
  }
  while (cells.length % 7 !== 0) cells.push({ day: null });
  const weekRows = [];
  for (let i = 0; i < cells.length; i += 7) weekRows.push(cells.slice(i, i + 7));
  const weekdayHeadLabels = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  app.innerHTML = `
    <div class="llh-calendar-shell">
      ${freeSurfaceUpgradeHtml("calendar")}
      ${calendarScheduleStatusHtml()}
      ${calendarAssignNoticeHtml()}
      ${curriculumPlannerRetirementBannerHtml()}
      <div class="llh-calendar-toolbar">
        <div>
          <h3 class="llh-calendar-month">${escapeHtml(mainCalendarMonthLabel(cursor))}</h3>
          <p class="muted-copy llh-calendar-toolbar-hint">Tap any day to open it. Add notes and events on any day — lesson plans still run Monday–Friday.</p>
        </div>
        <div class="llh-calendar-toolbar-actions">
          <div class="llh-calendar-month-nav" role="group" aria-label="Month and year navigation">
            <button type="button" class="ghost-button" data-calendar-nav="-1" aria-label="Previous month">‹ Prev</button>
            <label class="llh-cal-jump-label">Month
              <select data-calendar-jump-month aria-label="Jump to month">${calendarMonthOptionsHtml(month)}</select>
            </label>
            <label class="llh-cal-jump-label">Year
              <select data-calendar-jump-year aria-label="Jump to year">${calendarYearOptionsHtml(year)}</select>
            </label>
            <button type="button" class="ghost-button" data-calendar-nav="1" aria-label="Next month">Next ›</button>
            <button type="button" class="ghost-button" data-calendar-nav="today">Today</button>
          </div>
          <button type="button" class="primary-button" data-calendar-add-lesson-plan>Add Lesson Plan</button>
        </div>
      </div>
      ${calendarFilterBarHtml()}
      ${!monthHasLessons ? `
        <div class="llh-calendar-empty-banner">
          <p><strong>No lesson plans this month yet.</strong> Weeks stay empty until you add a plan — open a week, then choose from the Lesson Library.</p>
        </div>
      ` : ""}
      <div class="llh-calendar-grid llh-calendar-grid-7" role="grid" aria-label="${escapeHtml(mainCalendarMonthLabel(cursor))}">
        <div class="llh-cal-head llh-cal-head-gutter" aria-hidden="true"></div>
        ${weekdayHeadLabels.map((label, i) => `<div class="llh-cal-head ${i === 0 || i === 6 ? "is-weekend-head" : ""}">${label}</div>`).join("")}
        ${weekRows.map((row) => {
          const weekMonday = row.find((cell) => cell.week)?.week || "";
          return `
            <button type="button" class="llh-cal-week-jump" data-calendar-view-week="${escapeHtml(weekMonday)}" aria-label="View the week of ${escapeHtml(weekMonday)}" ${weekMonday ? "" : "disabled"}>
              <span aria-hidden="true">▸</span><span class="llh-cal-week-jump-label">Wk</span>
            </button>
            ${row.map((cell) => {
              if (!cell.day) return `<div class="llh-cal-cell is-empty"></div>`;
              const isToday = cell.iso === todayIso;
              const hasLesson = Boolean(cell.lesson);
              const isMonday = cell.dow === 1;
              const visibleItems = cell.dayItems.slice(0, 2);
              const extraItems = Math.max(0, cell.dayItems.length - visibleItems.length);
              const title = cell.lesson?.lessonPlanTitle || "";
              const shortTitle = title.length > 24 ? `${title.slice(0, 22)}…` : title;
              const dayNote = calendarDayNoteForDate({ items }, cell.iso);
              const hasDayNote = Boolean(String(dayNote?.notes || "").trim());
              const ariaLabel = `${calendarLongDateLabel(cell.iso)}${cell.weekend ? ", weekend" : ""}${hasLesson ? `, lesson plan: ${title}` : ""}${hasDayNote ? ", has day note" : ""}${cell.dayItems.length ? `, ${cell.dayItems.length} item${cell.dayItems.length === 1 ? "" : "s"}` : ""}`;
              return `
                <button type="button" class="llh-cal-cell ${cell.weekend ? "is-weekend" : ""} ${hasLesson ? "has-lesson" : ""} ${hasDayNote ? "has-day-note" : ""} ${isToday ? "is-today" : ""}" data-calendar-select-day="${escapeHtml(cell.iso)}" aria-label="${escapeHtml(ariaLabel)}">
                  <span class="llh-cal-daynum">${cell.day}${isToday ? '<span class="llh-cal-today-dot" aria-hidden="true"></span>' : ""}</span>
                  ${hasLesson && isMonday ? `<span class="llh-cal-weekbar" title="${escapeHtml(title)}">${escapeHtml(shortTitle)}</span>` : ""}
                  ${hasLesson && !isMonday && !cell.weekend ? `<span class="llh-cal-lesson-stripe" title="${escapeHtml(title)}" aria-hidden="true"></span>` : ""}
                  ${hasDayNote ? `<span class="llh-cal-chip llh-cal-chip-day_note" title="Day note">Note</span>` : ""}
                  ${visibleItems.map((item) => `<span class="llh-cal-chip llh-cal-chip-${escapeHtml(calendarItemCategory(item.type))}" title="${escapeHtml(item.title)}">${escapeHtml(calendarEventTypeLabel(item.type))}: ${escapeHtml(item.title || item.type)}</span>`).join("")}
                  ${extraItems ? `<span class="llh-cal-more">+${extraItems} more</span>` : ""}
                </button>
              `;
            }).join("")}
          `;
        }).join("")}
      </div>
      <div class="form-actions llh-calendar-add-row">
        <button type="button" class="ghost-button" data-calendar-add-item>Add Event / Reminder</button>
      </div>
      ${mainCalendarBusy ? `<p class="muted-copy llh-calendar-busy">Saving…</p>` : ""}
    </div>
  `;
}

function calendarWeekGlanceStats(doc, lesson, sunday, saturday, realItems, derivedItems) {
  const theme = String(lesson?.snapshot?.theme || lesson?.lessonPlanTitle || "").trim();
  let activityCount = 0;
  const dailyPlans = lesson?.snapshot?.dailyPlans && typeof lesson.snapshot.dailyPlans === "object"
    ? lesson.snapshot.dailyPlans
    : {};
  Object.values(dailyPlans).forEach((dayPlan) => {
    activityCount += Array.isArray(dayPlan?.items) ? dayPlan.items.length : 0;
  });
  const noteCount = (doc?.items || []).filter(
    (item) => item.type === "day_note"
      && item.startDate >= sunday
      && item.startDate <= saturday
      && String(item.notes || "").trim(),
  ).length;
  const eventCount = (realItems || []).filter(
    (item) => item.type !== "lesson_plan" && item.type !== "day_note",
  ).length + (derivedItems || []).length;
  return {
    theme,
    activityCount,
    noteCount,
    eventCount,
    hasLesson: Boolean(lesson),
  };
}

