function childStoreKey(key) {
  return currentUser ? `llhChild:${currentUser}:${key}` : `llhChild${key}`;
}

function childCloudUpdatedKey() {
  return currentUser ? `llhChild:${currentUser}:cloudUpdatedAt` : "llhChildCloudUpdatedAt";
}

function childStore(key, fallback = []) {
  const scopedKey = childStoreKey(key);
  const scopedValue = localStorage.getItem(scopedKey);
  if (scopedValue !== null) return readSavedJson(scopedKey, fallback);
  if (currentUser) {
    const legacyValue = localStorage.getItem(`llhChild${key}`);
    if (legacyValue !== null) return readSavedJson(`llhChild${key}`, fallback);
  }
  return fallback;
}

function saveChildStoreLocalOnly(key, value) {
  localStorage.setItem(childStoreKey(key), JSON.stringify(value));
  localStorage.setItem(childCloudUpdatedKey(), new Date().toISOString());
}

function childDataSnapshot() {
  return childDataKeys.reduce((snapshot, key) => {
    snapshot[key] = childStore(key);
    return snapshot;
  }, {});
}

function childDataHasRecords(snapshot = childDataSnapshot()) {
  return childDataKeys.some((key) => Array.isArray(snapshot[key]) && snapshot[key].length);
}

function applyChildDataSnapshot(snapshot = {}, updatedAt = "") {
  childDataKeys.forEach((key) => {
    saveChildStoreLocalOnly(key, Array.isArray(snapshot[key]) ? snapshot[key] : []);
  });
  if (updatedAt) localStorage.setItem(childCloudUpdatedKey(), updatedAt);
  const records = childRecords();
  if (!selectedChildId || !records.children.some((child) => child.id === selectedChildId)) {
    selectedChildId = records.children[0]?.id || "";
    localStorage.setItem("llhSelectedChild", selectedChildId);
  }
}

async function firebaseAuthHeaders() {
  if (!currentUser) return null;
  const memberToken = readMemberSessionToken();
  if (memberToken) {
    return { Authorization: `Bearer ${memberToken}`, "Content-Type": "application/json" };
  }
  if (firebaseAuthEnabled) {
    const client = await getFirebaseAuthClient();
    // Wait for Firebase to finish restoring a persisted session before reading the token.
    // Without this, page refresh / early login sync often runs with no currentUser yet.
    if (typeof client.auth.authStateReady === "function") {
      try {
        await Promise.race([
          client.auth.authStateReady(),
          delayMs(4000),
        ]);
      } catch (error) {
        console.warn("Firebase authStateReady did not complete", error);
      }
    }
    const token = await client.auth.currentUser?.getIdToken();
    if (token) return { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };
  }
  // Local/demo + tests: identify the signed-in account when Firebase/member session
  // isn't available. Server accepts these only for NODE_ENV=test / local-json.
  const email = String(currentUser).trim().toLowerCase();
  return {
    "Content-Type": "application/json",
    "X-LLH-User-Email": email,
    Authorization: `Bearer test:${email}`,
  };
}

async function saveChildDataToBackend(options = {}) {
  if (!currentUser || !canUseLaunchBackend()) return;
  if (childCloudSyncing && !options.force) return;
  const headers = await staffAuthHeaders();
  if (!headers) return;
  await fetch("/api/child-data", {
    method: "POST",
    headers,
    body: JSON.stringify({ data: childDataSnapshot() }),
  });
}

function queueChildDataCloudSave() {
  // Persist Forms / child records whenever the launch API is reachable — not only when Firebase is configured.
  // Family Hub reads live documents from /api/child-data, so local-only saves break the forms spine.
  if (!currentUser || !canUseLaunchBackend()) return;
  clearTimeout(childCloudSaveTimer);
  childCloudSaveTimer = setTimeout(() => {
    saveChildDataToBackend().catch((error) => console.warn("Child data cloud save did not complete", error));
  }, 700);
}

function delayMs(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

let childCloudSyncQueued = false;

async function syncChildDataFromBackend(options = {}) {
  if (!currentUser || !canUseLaunchBackend()) return false;
  if (childCloudSyncing) {
    childCloudSyncQueued = true;
    return false;
  }
  childCloudSyncing = true;
  let applied = false;
  try {
    for (let attempt = 0; attempt < 4; attempt += 1) {
      const headers = await staffAuthHeaders();
      if (!headers) {
        await delayMs(350 * (attempt + 1));
        continue;
      }
      const response = await fetch("/api/child-data", { headers });
      if (!response.ok) {
        console.warn(`Child data cloud sync failed (${response.status}) on attempt ${attempt + 1}`);
        await delayMs(400 * (attempt + 1));
        continue;
      }
      const remote = await response.json();
      const localUpdatedAt = localStorage.getItem(childCloudUpdatedKey()) || "";
      const remoteUpdatedAt = String(remote.updatedAt || "");
      if (remote?.data && (
        options.force
        || !localUpdatedAt
        || remoteUpdatedAt > localUpdatedAt
        || !childDataHasRecords()
      )) {
        applyChildDataSnapshot(remote.data, remote.updatedAt);
        applied = true;
      } else if (remote?.data?.Documents && isHomeDaycareHubTestingEnabled()) {
        // Keep form sign/review status current even when local timestamps are newer.
        const localDocs = childStore("Documents") || [];
        const remoteById = new Map((remote.data.Documents || []).map((doc) => [String(doc.id || ""), doc]));
        let mergedChange = false;
        const mergedDocs = localDocs.map((doc) => {
          const remoteDoc = remoteById.get(String(doc.id || ""));
          if (!remoteDoc) return doc;
          const remoteSigned = Boolean(remoteDoc.signedAt) || /^signed/i.test(String(remoteDoc.status || ""));
          const localSigned = Boolean(doc.signedAt) || /^signed/i.test(String(doc.status || ""));
          if ((remoteSigned && !localSigned)
            || (remoteDoc.providerReviewed && !doc.providerReviewed)
            || (String(remoteDoc.status || "") !== String(doc.status || "") && remoteSigned)) {
            mergedChange = true;
            return {
              ...doc,
              status: remoteDoc.status || doc.status,
              statusLabel: remoteDoc.statusLabel || doc.statusLabel,
              signedAt: remoteDoc.signedAt || doc.signedAt,
              signedBy: remoteDoc.signedBy || doc.signedBy,
              signedSnapshot: remoteDoc.signedSnapshot || doc.signedSnapshot,
              providerReviewed: remoteDoc.providerReviewed ?? doc.providerReviewed,
              reviewedAt: remoteDoc.reviewedAt || doc.reviewedAt,
              updatedAt: remoteDoc.updatedAt || doc.updatedAt,
            };
          }
          return doc;
        });
        remoteById.forEach((remoteDoc, id) => {
          if (id && !localDocs.some((doc) => String(doc.id) === id)) {
            mergedDocs.push(remoteDoc);
            mergedChange = true;
          }
        });
        if (mergedChange) {
          saveChildStoreLocalOnly("Documents", mergedDocs);
          if (remoteUpdatedAt) localStorage.setItem(childCloudUpdatedKey(), remoteUpdatedAt);
          applied = true;
        }
      } else if (!remote?.data && childDataHasRecords()) {
        await saveChildDataToBackend({ force: true });
      }
      if (options.render !== false && document.querySelector("#view-children")?.classList.contains("active-view")) {
        renderChildManagement();
      }
      if (options.render !== false && document.querySelector("#view-home-daycare-hub")?.classList.contains("active-view") && typeof renderHomeDaycareHubPage === "function") {
        renderHomeDaycareHubPage({ refreshHouseholds: false });
      }
      updateSidebarDashboard();
      break;
    }
  } catch (error) {
    console.warn("Child data cloud sync did not complete", error);
  } finally {
    childCloudSyncing = false;
    if (childCloudSyncQueued) {
      childCloudSyncQueued = false;
      syncChildDataFromBackend(options).catch((error) => console.warn("Queued child data sync did not complete", error));
    }
  }
  return applied;
}

function saveChildStore(key, value) {
  saveChildStoreLocalOnly(key, value);
  updateSidebarDashboard();
  queueChildDataCloudSave();
}

function childRecords() {
  return {
    children: childStore("Profiles"),
    observations: childStore("Observations"),
    supportPlans: childStore("SupportPlans"),
    goals: childStore("Goals"),
    differentiations: childStore("Differentiations"),
    attendance: childStore("Attendance"),
    meals: childStore("Meals"),
    reports: childStore("Reports"),
    communications: childStore("Communications"),
    naps: childStore("Naps"),
    diapers: childStore("Diapers"),
    activityLogs: childStore("ActivityLogs"),
    photos: childStore("Photos"),
    documents: childStore("Documents"),
    automationEvents: childStore("AutomationEvents"),
  };
}

function childName(childId) {
  return childRecords().children.find((child) => child.id === childId)?.name || "Child";
}

function selectedChild(records = childRecords()) {
  return records.children.find((child) => child.id === selectedChildId) || records.children[0] || null;
}

function currentWeekStart(date = new Date()) {
  const start = new Date(date);
  start.setHours(0, 0, 0, 0);
  start.setDate(start.getDate() - start.getDay());
  return start;
}

function isThisWeek(dateText) {
  if (!dateText) return false;
  const date = new Date(`${dateText}T12:00:00`);
  const start = currentWeekStart();
  const end = new Date(start);
  end.setDate(start.getDate() + 7);
  return date >= start && date < end;
}

function calculateAgeFromDob(dob) {
  if (!dob) return "";
  const birthDate = new Date(`${dob}T12:00:00`);
  if (Number.isNaN(birthDate.getTime())) return "";
  const today = new Date();
  let years = today.getFullYear() - birthDate.getFullYear();
  let months = today.getMonth() - birthDate.getMonth();
  if (today.getDate() < birthDate.getDate()) months -= 1;
  if (months < 0) {
    years -= 1;
    months += 12;
  }
  const monthCount = Math.max(months, 0);
  const yearPart = years > 0 ? `${years} ${years === 1 ? "year" : "years"}` : "";
  const monthPart = monthCount > 0 ? `${monthCount} ${monthCount === 1 ? "month" : "months"}` : "";
  return [yearPart, monthPart].filter(Boolean).join(" ") || "0 months";
}

function ageGroupFromDob(dob) {
  if (!dob) return "";
  const birthDate = new Date(`${dob}T12:00:00`);
  if (Number.isNaN(birthDate.getTime())) return "";
  const today = new Date();
  let months = (today.getFullYear() - birthDate.getFullYear()) * 12 + (today.getMonth() - birthDate.getMonth());
  if (today.getDate() < birthDate.getDate()) months -= 1;
  if (months < 12) return "Infant";
  if (months < 36) return "Toddler";
  if (months < 60) return "Preschool";
  return "School Age";
}

function childAgeMonths(child = {}) {
  if (child.dob) {
    const birthDate = new Date(`${child.dob}T12:00:00`);
    if (!Number.isNaN(birthDate.getTime())) {
      const today = new Date();
      let months = (today.getFullYear() - birthDate.getFullYear()) * 12 + (today.getMonth() - birthDate.getMonth());
      if (today.getDate() < birthDate.getDate()) months -= 1;
      return Math.max(months, 0);
    }
  }
  const ageText = cleanAgeText(child.age || child.ageLabel || "");
  const monthMatch = ageText.match(/(\d+)\s*months?/i);
  if (monthMatch) return Number(monthMatch[1]);
  const yearMatch = ageText.match(/(\d+)\s*years?/i);
  if (yearMatch) return Number(yearMatch[1]) * 12;
  return null;
}

function isInfantChild(child = {}) {
  return normalizeAgeGroup(child.ageGroup) === "Infant" || (childAgeMonths(child) !== null && childAgeMonths(child) < 12);
}

function cleanAgeText(value) {
  return String(value || "")
    .replace(/[^\x20-\x7E]/g, " ")
    .replace(/\byrs?\b/gi, "years")
    .replace(/\bmos?\b/gi, "months")
    .replace(/\s+/g, " ")
    .trim();
}

function childAgeLabel(child) {
  return calculateAgeFromDob(child.dob) || cleanAgeText(child.age) || "Age not entered";
}

function childAgeGroupLabel(child = {}) {
  return normalizeAgeGroup(child.ageGroup) || cleanAgeText(child.ageGroup);
}

function childRoomAgeLabel(child = {}) {
  const parts = [childAgeGroupLabel(child), cleanAgeText(child.classroom)].filter(Boolean);
  return parts.length ? parts.join(" | ") : "Age group not entered";
}

