function childRecordActionMenuItems(item, storeKey) {
  if (!storeKey || !item?.id) return [];
  const id = escapeHtml(item.id);
  const key = escapeHtml(storeKey);
  const actions = [
    { label: "Edit", attr: `data-edit-child-record="${id}" data-store-key="${key}"` },
  ];
  if (item.archived) {
    actions.push({ label: "Reactivate", attr: `data-archive-child-record="${id}" data-store-key="${key}" data-archive-state="0"` });
  } else {
    actions.push({ label: "Archive", attr: `data-archive-child-record="${id}" data-store-key="${key}" data-archive-state="1"` });
  }
  if (item.shareWithFamily === true) {
    actions.push({ label: storeKey === "Photos" ? "Remove From Parent View" : "Stop Sharing With Family", attr: `data-stop-family-share="${id}" data-store-key="${key}"` });
  } else if (item.shareWithFamily === false || storeKey === "Photos" || storeKey === "Communications" || storeKey === "Reports") {
    actions.push({ label: "Share With Family Hub", attr: `data-start-family-share="${id}" data-store-key="${key}"` });
  }
  actions.push({ divider: true });
  actions.push({ label: "Delete Permanently", attr: `data-delete-child-record="${id}" data-store-key="${key}"`, danger: true });
  return actions;
}

function simpleRecordItem(item, options = {}) {
  const storeKey = options.storeKey || item._storeKey || "";
  const title = item.title || item.type || item.area || item.status || item.date || "Record";
  const detail = item.summary || item.message || item.goal || item.activity || item.notes || item.text || item.support || `${item.date || ""} ${item.status || ""}`.trim();
  const canAct = Boolean(storeKey && item.id);
  const menuId = canAct ? `record-${storeKey}-${item.id}` : "";
  const shareTag = item.shareWithFamily === true ? `<span class="tag">Shared with Family</span>` : "";
  const archivedTag = item.archived ? `<span class="tag">Archived</span>` : "";
  return `
    <div class="compact-item${item.archived ? " is-archived" : ""}">
      <div>
        <strong>${escapeHtml(String(title))}</strong>
        <span>${escapeHtml(String(detail || "Saved record"))}</span>
        ${shareTag}${archivedTag}
      </div>
      ${canAct ? itemActionMenuHtml(menuId, childRecordActionMenuItems(item, storeKey)) : ""}
    </div>
  `;
}

function goalItem(item, child = {}) {
  const progress = goalProgressPercent(item.progress);
  const area = normalizeObservationArea(item.area) || item.area || "Approaches to Learning";
  const connectedObservations = connectedObservationsForGoal(item);
  const activities = suggestedActivitiesForArea(area, child).slice(0, 4);
  const lessonPlans = suggestedLessonPlansForArea(area).slice(0, 3);
  const isTyped = String(item.source || "") === "typed" || String(item.id || "").includes("-typed-goal-");
  const menuActions = isTyped ? [] : [
    { label: "Edit", attr: `data-edit-goal="${item.id}"` },
    progress < 100 ? { label: "Mark Complete", attr: `data-complete-goal="${item.id}"` } : null,
    item.archived
      ? { label: "Reactivate", attr: `data-archive-goal="${item.id}" data-archive-state="0"` }
      : { label: "Archive", attr: `data-archive-goal="${item.id}" data-archive-state="1"` },
    { divider: true },
    { label: "Delete Permanently", attr: `data-delete-goal="${item.id}"`, danger: true },
  ].filter(Boolean);
  return `
    <div class="compact-item${item.archived ? " is-archived" : ""}">
      <div>
        <strong>${escapeHtml(area)} | ${progress}% progress${item.archived ? " · Archived" : ""}</strong>
        <div class="mini-progress"><span style="width:${progress}%"></span></div>
        <span>${escapeHtml(item.goal)}${item.targetDate ? ` | Target: ${escapeHtml(item.targetDate)}` : ""}</span>
        <span><b>Connected Observations:</b> ${connectedObservations.length}</span>
        <span><b>Suggested Activities:</b> ${escapeHtml(activities.join(", "))}</span>
        <span><b>Lesson Plan Topics:</b> ${escapeHtml(lessonPlans.join(", "))}</span>
        ${item.notes ? `<span><b>Progress Notes:</b> ${escapeHtml(item.notes)}</span>` : ""}
      </div>
      <div class="goal-card-actions">
        ${progress < 100 && !item.archived ? `<button class="ghost-button" data-complete-goal="${item.id}" type="button">Mark Complete</button>` : `<span class="tag">${item.archived ? "Archived" : "Complete"}</span>`}
        ${menuActions.length ? itemActionMenuHtml(`goal-${item.id}`, menuActions) : ""}
      </div>
    </div>
  `;
}

function appendChildRecord(key, record, options = {}) {
  const items = childStore(key);
  const saved = { id: `${key}-${Date.now()}`, createdAt: new Date().toISOString(), ...record };
  saveChildStore(key, [...items, saved]);
  if (!options.skipRender) {
    if (activePortfolioChildId) {
      renderChildPortfolioPage(activePortfolioChildId);
    } else if (typeof renderChildManagement === "function") {
      try { renderChildManagement(); } catch (_e) { /* non-blocking */ }
    }
  }
  // Bridge shared parent-facing notes into the Family Hub message thread.
  if (
    !options.skipBridge
    && key === "Communications"
    && saved.shareWithFamily === true
    && isHomeDaycareHubTestingEnabled()
    && typeof maybeBridgeCommunicationToFamilyHub === "function"
  ) {
    maybeBridgeCommunicationToFamilyHub(saved).catch(() => {});
  }
  // Auto-notify Family Hub when provider shares care updates parents care about.
  // Meals / attendance / naps stay silent on purpose (appear on Family Hub Today without push noise).
  if (
    !options.skipNotify
    && saved.shareWithFamily === true
    && isHomeDaycareHubTestingEnabled()
    && ["Photos", "Reports", "Observations", "Goals", "SupportPlans"].includes(key)
  ) {
    maybeNotifyFamilyHubSharedRecord(key, saved).catch(() => {});
  }
  if (!options.skipAutomation && typeof runSmartAutomationForRecord === "function") {
    try { runSmartAutomationForRecord(key, saved, options); } catch (_e) { /* non-blocking */ }
  }
  return saved;
}

async function maybeNotifyFamilyHubSharedRecord(key, record = {}) {
  if (!currentUser || !canUseLaunchBackend() || !record?.childId) return null;
  const headers = await staffAuthHeaders().catch(() => null);
  if (!headers) return null;
  const kidName = typeof childName === "function" ? childName(record.childId) : "Your child";
  const meta = {
    Photos: { type: "photo", title: "New photo shared", href: "photos", body: `${kidName}: ${String(record.caption || record.title || "A new photo is waiting in Family Hub.").trim()}` },
    Reports: { type: "report", title: "Daily report ready", href: "reports", body: `${kidName}: ${String(record.summary || record.title || "Today’s report is ready to read.").trim()}` },
    Observations: { type: "observation", title: "Learning moment shared", href: "today", body: `${kidName}: ${String(record.summary || record.text || record.title || "A new observation was shared.").trim()}` },
    Goals: { type: "goal", title: "Goal update", href: "today", body: `${kidName}: ${String(record.title || record.summary || "A developmental goal was shared.").trim()}` },
    SupportPlans: { type: "support-plan", title: "Support update", href: "today", body: `${kidName}: ${String(record.title || record.summary || "A support plan update was shared.").trim()}` },
  }[key] || { type: "update", title: "Update from your teacher", href: "today", body: `${kidName}: New update` };
  const response = await fetch("/api/family-hub/provider-notifications", {
    method: "POST",
    headers,
    body: JSON.stringify({
      childId: record.childId,
      type: meta.type,
      title: meta.title,
      body: meta.body.slice(0, 180),
      href: meta.href,
    }),
    cache: "no-store",
  });
  if (!response.ok) return null;
  return response.json().catch(() => null);
}

async function unlinkChildFromFamilyHubHouseholds(childId, reason = "child_archived") {
  if (!isHomeDaycareHubTestingEnabled() || !childId || !canUseLaunchBackend()) return { unlinked: 0, revoked: 0 };
  const headers = await staffAuthHeaders().catch(() => null);
  if (!headers) return { unlinked: 0, revoked: 0 };
  const response = await fetch("/api/family-hub/unlink-child", {
    method: "POST",
    headers,
    body: JSON.stringify({ childId, reason }),
    cache: "no-store",
  });
  if (!response.ok) return { unlinked: 0, revoked: 0 };
  return response.json().catch(() => ({ unlinked: 0, revoked: 0 }));
}

async function maybeBridgeCommunicationToFamilyHub(record = {}) {
  const type = String(record.type || record.category || "").toLowerCase();
  if (type.includes("mood") || type.includes("incident")) return null;
  const body = String(record.message || record.summary || record.notes || "").trim();
  if (!body || body.length < 3) return null;
  if (type && !/message|note|family|announce|reminder/.test(type)) return null;
  if (!currentUser || !canUseLaunchBackend()) return null;
  const headers = await staffAuthHeaders().catch(() => null);
  if (!headers) return null;
  const response = await fetch("/api/family-hub/provider-messages", {
    method: "POST",
    headers,
    body: JSON.stringify({
      childId: record.childId || "",
      body: /announce|reminder/.test(type) ? `Announcement: ${body}` : body,
      authorName: "Teacher",
    }),
    cache: "no-store",
  });
  if (!response.ok) return null;
  return response.json().catch(() => null);
}

/** Testing-site smart automation: connect features so providers enter data once. */
function isSmartAutomationEnabled() {
  try {
    return Boolean(typeof isHomeDaycareHubTestingEnabled === "function" && isHomeDaycareHubTestingEnabled());
  } catch (_error) {
    return false;
  }
}

function opsAlertsStorageKey() {
  const email = String(currentUser?.email || currentAccount()?.email || "local").toLowerCase();
  return `llhOpsAlerts:${email}`;
}

function listOpsAlerts() {
  try {
    const raw = JSON.parse(localStorage.getItem(opsAlertsStorageKey()) || "[]");
    return Array.isArray(raw) ? raw : [];
  } catch (_error) {
    return [];
  }
}

function saveOpsAlerts(items = []) {
  localStorage.setItem(opsAlertsStorageKey(), JSON.stringify((items || []).slice(0, 60)));
}

function appendOpsAlert(alert = {}) {
  if (!isSmartAutomationEnabled()) return null;
  const type = String(alert.type || "update").trim() || "update";
  // Notification audit: only matter-worthy types.
  const allowed = new Set([
    "incident_review",
    "form_signed",
    "form_overdue",
    "observation_shared",
    "message",
    "medication_due",
    "lesson_assigned",
    "child_ready",
  ]);
  if (!allowed.has(type)) return null;
  const next = {
    id: `ops-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    createdAt: new Date().toISOString(),
    read: false,
    priority: alert.priority || "normal",
    type,
    title: String(alert.title || "Needs attention").trim(),
    detail: String(alert.detail || "").trim(),
    childId: alert.childId || "",
    hrefView: alert.hrefView || "home",
  };
  const items = listOpsAlerts().filter((item) => !(
    item.type === next.type
    && String(item.childId || "") === String(next.childId || "")
    && String(item.title || "") === next.title
    && !item.read
    && (Date.now() - Date.parse(item.createdAt || 0)) < 5 * 60 * 1000
  ));
  items.unshift(next);
  saveOpsAlerts(items);
  return next;
}

function markOpsAlertRead(id) {
  if (!id) return;
  saveOpsAlerts(listOpsAlerts().map((item) => (item.id === id ? { ...item, read: true } : item)));
}

function dismissNoiseOpsAlerts() {
  // Drop low-value leftover alerts that are not in the matter-worthy set.
  const allowed = new Set([
    "incident_review", "form_signed", "form_overdue", "observation_shared",
    "message", "medication_due", "lesson_assigned", "child_ready",
  ]);
  saveOpsAlerts(listOpsAlerts().filter((item) => allowed.has(String(item.type || ""))));
}

function appendAutomationTimeline(childId, title, detail = "", extras = {}) {
  if (!isSmartAutomationEnabled() || !childId) return null;
  const today = extras.date || (typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10));
  return appendChildRecord("AutomationEvents", {
    childId,
    date: today,
    time: extras.time || (typeof quickActionTime === "function" ? quickActionTime() : ""),
    title,
    detail,
    summary: detail || title,
    source: extras.source || "automation",
    shareWithFamily: false,
  }, { skipAutomation: true, skipNotify: true, skipBridge: true, skipRender: true });
}

function classroomRatioSnapshot(records = childRecords(), today = (typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10))) {
  const children = records.children || [];
  const present = (records.attendance || []).filter((a) => {
    if (a.date !== today) return false;
    const status = String(a.status || "").toLowerCase();
    return status !== "absent" && (a.dropoff || status === "present") && !a.pickup;
  });
  const byRoom = {};
  present.forEach((a) => {
    const child = children.find((c) => c.id === a.childId);
    const room = child?.classroom || child?.classroomId || "Unassigned";
    byRoom[room] = (byRoom[room] || 0) + 1;
  });
  return { checkedIn: present.length, roster: children.length, byRoom };
}

function dayReadinessForChild(childId, records = childRecords(), today = (typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10))) {
  const has = (key) => (records[key] || []).some((item) => item.childId === childId && item.date === today && item.archived !== true);
  return {
    attendance: has("attendance"),
    meals: has("meals"),
    naps: has("naps"),
    observations: (records.observations || []).some((item) => item.childId === childId && item.date === today),
    photos: (records.photos || []).some((item) => item.childId === childId && item.date === today),
    report: (records.reports || []).some((item) => item.childId === childId && item.date === today),
  };
}

function childrenReadyForEndOfDayReport(records = childRecords(), today = (typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10))) {
  return (records.children || []).filter((child) => {
    const ready = dayReadinessForChild(child.id, records, today);
    return ready.attendance && (ready.meals || ready.naps || ready.observations || ready.photos) && !ready.report;
  });
}

function runChildCreatedAutomation(child, { isNew = true } = {}) {
  if (!isSmartAutomationEnabled() || !child?.id || !isNew) return { formsAdded: 0 };
  appendAutomationTimeline(child.id, "Child enrolled", `${child.name || "Child"} is ready for Daily Logs, observations, goals, and reports.`, { source: "child_created" });
  let formsAdded = 0;
  try {
    if (typeof addAllHomeDaycarePackFormsToChild === "function") {
      formsAdded = addAllHomeDaycarePackFormsToChild(child.id) || 0;
    }
  } catch (_error) { formsAdded = 0; }
  if (formsAdded > 0) {
    appendAutomationTimeline(child.id, "Forms folder ready", `${formsAdded} enrollment / care forms added to this child’s file.`, { source: "child_created_forms" });
  }
  // Soft readiness markers (no empty stub records parents would see).
  const profiles = childStore("Profiles");
  saveChildStore("Profiles", profiles.map((item) => (
    item.id === child.id
      ? {
        ...item,
        automation: {
          ...(item.automation || {}),
          timelineReady: true,
          documentsReady: formsAdded > 0,
          observationsReady: true,
          goalsReady: true,
          dailyReportsReady: true,
          connectedAt: new Date().toISOString(),
        },
      }
      : item
  )));
  appendOpsAlert({
    type: "child_ready",
    title: `${child.name || "Child"} is set up`,
    detail: formsAdded ? `${formsAdded} forms ready · linked for Daily Logs & Family Hub` : "Ready for Daily Logs, observations, and reports",
    childId: child.id,
    hrefView: "children",
  });
  return { formsAdded };
}

function runIncidentAutomation(record = {}) {
  if (!isSmartAutomationEnabled() || !record?.childId) return;
  const type = String(record.type || record.category || "").toLowerCase();
  if (!type.includes("incident")) return;
  const today = record.date || (typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10));
  const kid = typeof childName === "function" ? childName(record.childId) : "Child";
  const description = String(record.description || record.summary || record.message || "Incident noted").trim();
  appendAutomationTimeline(record.childId, "Incident recorded", description.slice(0, 160), { date: today, source: "incident" });
  // Internal document on file (dedupe by source id)
  const docs = childStore("Documents") || [];
  const already = docs.some((doc) => doc.sourceRecordId === record.id);
  if (!already) {
    appendChildRecord("Documents", {
      childId: record.childId,
      date: today,
      title: `Incident Report | ${today}`,
      category: "Incident",
      status: "on_file",
      statusLabel: "On file",
      notes: description,
      sourceRecordId: record.id,
      shareWithFamily: false,
    }, { skipAutomation: true, skipNotify: true, skipBridge: true, skipRender: true });
  }
  // Parent message draft (private until provider sends/shares)
  const communications = childStore("Communications") || [];
  const draftExists = communications.some((item) => (
    item.childId === record.childId
    && item.sourceIncidentId === record.id
  ));
  if (!draftExists) {
    appendChildRecord("Communications", {
      childId: record.childId,
      date: today,
      type: "Parent Message",
      title: `Parent update draft | Incident ${today}`,
      summary: `Draft for ${kid}: ${description.slice(0, 100)}`,
      message: `Hi — I wanted to share a brief update about ${kid} today. ${description}\n\nPlease reply if you have any questions.`,
      shareWithFamily: false,
      sourceIncidentId: record.id,
      draft: true,
    }, { skipAutomation: true, skipNotify: true, skipBridge: true, skipRender: true });
  }
  // Behavior history marker
  appendChildRecord("Communications", {
    childId: record.childId,
    date: today,
    type: "Behavior Note",
    title: `Behavior history | ${today}`,
    summary: description.slice(0, 120),
    message: description,
    shareWithFamily: false,
    sourceIncidentId: record.id,
    systemGenerated: true,
  }, { skipAutomation: true, skipNotify: true, skipBridge: true, skipRender: true });
  appendOpsAlert({
    type: "incident_review",
    priority: "high",
    title: `Incident needs review · ${kid}`,
    detail: description.slice(0, 140),
    childId: record.childId,
    hrefView: "child-tools-daily-logs",
  });
}

function runObservationAutomation(record = {}) {
  if (!isSmartAutomationEnabled() || !record?.childId) return;
  const child = (childRecords().children || []).find((item) => item.id === record.childId);
  if (!child) return;
  // Observations already appear on timeline; quietly connect goals + matter-worthy notify.
  if (typeof maybeSuggestGoalFromObservation === "function") {
    try { maybeSuggestGoalFromObservation(child, record); } catch (_e) { /* ignore */ }
  }
  if (record.shareWithFamily === true) {
    appendOpsAlert({
      type: "observation_shared",
      title: `Observation shared · ${child.name || "Child"}`,
      detail: String(record.summary || record.text || "Shared with Family Hub").slice(0, 140),
      childId: record.childId,
      hrefView: "families",
    });
  }
}

function runAttendanceAutomation(record = {}) {
  if (!isSmartAutomationEnabled() || !record?.childId) return;
  // Attendance already appears on the child timeline & Family Hub Today when shared — no duplicate event.
  try {
    if (document.body.classList.contains("work-mode-nav")) {
      const view = document.body.getAttribute("data-view") || "";
      if (view === "home" && typeof renderOwnerHomeDashboard === "function") renderOwnerHomeDashboard();
      if (view === "today" && typeof renderTeacherTodayPage === "function") renderTeacherTodayPage();
    }
  } catch (_e) { /* ignore */ }
}

function runMealAutomation(record = {}) {
  if (!isSmartAutomationEnabled() || !record?.childId) return;
  // Meals already feed timeline, daily history, Family Hub Today, and grounded EOD AI facts.
  try {
    if (document.body.classList.contains("work-mode-nav")) {
      const view = document.body.getAttribute("data-view") || "";
      if (view === "home" && typeof renderOwnerHomeDashboard === "function") renderOwnerHomeDashboard();
      if (view === "today" && typeof renderTeacherTodayPage === "function") renderTeacherTodayPage();
    }
  } catch (_e) { /* ignore */ }
}

function runPhotoAutomation(record = {}) {
  if (!isSmartAutomationEnabled() || !record?.childId) return;
  // Photos already land on profile, timeline, Family Hub gallery/Today, and report photo counts.
}

function runFormSignedAutomation(doc = {}) {
  if (!isSmartAutomationEnabled() || !doc?.id) return;
  const childId = doc.childId;
  if (childId) {
    appendAutomationTimeline(childId, "Parent signed form", `${doc.title || "Form"} signed${doc.signedBy ? ` by ${doc.signedBy}` : ""}`, {
      date: String(doc.signedAt || new Date().toISOString()).slice(0, 10),
      source: "form_signed",
    });
  }
  appendOpsAlert({
    type: "form_signed",
    title: `Form signed${doc.title ? `: ${doc.title}` : ""}`,
    detail: doc.signedBy ? `Signed by ${doc.signedBy}` : "Parent completed a form",
    childId: childId || "",
    hrefView: "forms",
  });
  saveOpsAlerts(listOpsAlerts().map((item) => (
    item.type === "form_overdue" && String(item.detail || "").includes(String(doc.title || ""))
      ? { ...item, read: true }
      : item
  )));
  try {
    if (window.document.body.classList.contains("work-mode-nav")) {
      const view = window.document.body.getAttribute("data-view") || "";
      if (view === "home" && typeof renderOwnerHomeDashboard === "function") renderOwnerHomeDashboard();
      if (view === "families" && typeof renderFamiliesHubPage === "function") renderFamiliesHubPage();
    }
  } catch (_e) { /* ignore */ }
}

function runLessonAssignedAutomation(item = {}, meta = {}) {
  if (!isSmartAutomationEnabled() || !item) return;
  const title = item.lessonPlanTitle || item.title || "Lesson plan";
  const classroomId = item.classroomId || meta.classroomId || "";
  const childIds = Array.isArray(item.childIds) ? item.childIds : (meta.childIds || []);
  childIds.slice(0, 40).forEach((childId) => {
    appendAutomationTimeline(childId, "Lesson assigned", `${title} · on classroom calendar & Teacher Today`, {
      date: item.weekStartDate || meta.week || (typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10)),
      source: "lesson_assigned",
    });
  });
  appendOpsAlert({
    type: "lesson_assigned",
    title: `Lesson ready: ${title}`,
    detail: classroomId ? `Classroom ${classroomId} · opens on Teacher Today & Daily Logs` : "Available on Teacher Today & Daily Logs",
    hrefView: "today",
  });
  try {
    if (window.document.body.classList.contains("work-mode-nav") && typeof renderTeacherTodayPage === "function") {
      const view = window.document.body.getAttribute("data-view") || "";
      if (view === "today") renderTeacherTodayPage();
    }
  } catch (_e) { /* ignore */ }
}

function runSmartAutomationForRecord(key, record = {}, options = {}) {
  if (!isSmartAutomationEnabled() || options.skipAutomation) return;
  if (key === "Attendance") runAttendanceAutomation(record);
  else if (key === "Meals") runMealAutomation(record);
  else if (key === "Observations") runObservationAutomation(record);
  else if (key === "Photos") runPhotoAutomation(record);
  else if (key === "Communications") runIncidentAutomation(record);
  else if (key === "Documents" && (record.signedAt || String(record.status || "").toLowerCase() === "signed")) {
    runFormSignedAutomation(record);
  }
}

function buildActionOnlyAttentionCards() {
  dismissNoiseOpsAlerts();
  const records = childRecords();
  const today = typeof dlcActiveDate === "function" ? dlcActiveDate() : new Date().toISOString().slice(0, 10);
  const cards = [];
  const unreadOps = listOpsAlerts().filter((item) => !item.read).slice(0, 6);
  unreadOps.forEach((alert) => {
    cards.push({
      view: alert.hrefView || "home",
      title: alert.title,
      detail: alert.detail || "Take action",
      primary: alert.priority === "high",
      attrs: `data-ops-alert="${escapeHtml(alert.id)}"`,
    });
  });
  const docsPending = (records.documents || []).filter((d) => {
    const status = String(d.status || d.statusLabel || "").toLowerCase();
    return d.shareWithFamily && !d.signedAt && /need|notif|assign|action|draft|request/.test(status);
  });
  if (docsPending.length) {
    cards.push({
      view: "forms",
      title: `${docsPending.length} form${docsPending.length === 1 ? "" : "s"} awaiting parent`,
      detail: "Follow up or resend from Forms",
    });
  }
  const eodReady = childrenReadyForEndOfDayReport(records, today);
  if (eodReady.length) {
    cards.push({
      view: "child-tools-daily-logs",
      title: `${eodReady.length} daily report${eodReady.length === 1 ? "" : "s"} ready to generate`,
      detail: "AI can draft from today’s logged facts",
      primary: true,
    });
  }
  const incidents = listOpsAlerts().filter((item) => item.type === "incident_review" && !item.read);
  // already included via unreadOps
  return cards;
}

function todayAssignedLessonCardHtml() {
  if (typeof weekLessonForChild !== "function") return "";
  const records = childRecords();
  const children = records.children || [];
  const seen = new Set();
  const lessons = [];
  children.forEach((child) => {
    const lesson = weekLessonForChild(child);
    if (!lesson) return;
    const key = `${lesson.classroomId || ""}:${lesson.lessonPlanId || lesson.id || lesson.lessonPlanTitle || ""}`;
    if (seen.has(key)) return;
    seen.add(key);
    lessons.push(lesson);
  });
  if (!lessons.length) return "";
  return `
    <section class="work-hub-section">
      <h3>Today’s assigned lesson</h3>
      <ul class="work-simple-list">
        ${lessons.slice(0, 3).map((lesson) => `
          <li>
            <strong>${escapeHtml(lesson.lessonPlanTitle || lesson.title || "Lesson plan")}</strong>
            <span>On classroom calendar · Daily Logs · Teacher Today</span>
            <small>${escapeHtml(lesson.weekStartDate || "")}</small>
          </li>
        `).join("")}
      </ul>
      <div class="work-hub-grid" style="margin-top:12px">
        ${workHubTile({ view: "lessons", title: "Open lesson", detail: "Teach from the assigned plan", primary: true })}
        ${workHubTile({ view: "activities", title: "Suggested activities", detail: "Activity Center" })}
      </div>
    </section>
  `;
}


document.addEventListener("click", (event) => {
  const opsTile = event.target.closest("[data-ops-alert]");
  if (!opsTile) return;
  const alertId = opsTile.getAttribute("data-ops-alert");
  if (alertId && typeof markOpsAlertRead === "function") markOpsAlertRead(alertId);
}, true);

let afterActionPromptTimeout = null;

const LLH_DIALOG_FOCUSABLE_SELECTOR = 'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

function llhDialogFocusableElements(root) {
  if (!root) return [];
  return [...root.querySelectorAll(LLH_DIALOG_FOCUSABLE_SELECTOR)].filter((el) => {
    if (el.hasAttribute("disabled") || el.getAttribute("aria-hidden") === "true") return false;
    if (el.closest("[hidden]")) return false;
    const style = window.getComputedStyle(el);
    return style.visibility !== "hidden" && style.display !== "none";
  });
}

function trapLlhDialogFocus(event, root) {
  if (!root || event.key !== "Tab") return false;
  const focusable = llhDialogFocusableElements(root);
  if (!focusable.length) return false;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (!focusable.includes(document.activeElement)) {
    event.preventDefault();
    (event.shiftKey ? last : first).focus();
    return true;
  }
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
    return true;
  }
  if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
    return true;
  }
  return true;
}

function restoreLlhFocus(el) {
  if (el && typeof el.focus === "function") {
    try { el.focus(); } catch (_error) { /* ignore */ }
  }
}

function confirmActionDialogHtml() {
  return `
    <div class="llh-confirm-dialog" data-llh-confirm-dialog hidden>
      <button type="button" class="llh-confirm-backdrop" data-llh-confirm-cancel aria-label="Dismiss confirmation"></button>
      <div class="llh-confirm-panel" role="dialog" aria-modal="true" aria-labelledby="llhConfirmTitle">
        <h3 id="llhConfirmTitle" data-llh-confirm-title>Confirm</h3>
        <p class="muted-copy" data-llh-confirm-message></p>
        <div class="llh-confirm-actions">
          <button type="button" class="primary-button" data-llh-confirm-ok>Confirm</button>
          <button type="button" class="ghost-button" data-llh-confirm-cancel>Cancel</button>
        </div>
      </div>
    </div>
  `;
}

function ensureConfirmActionDialog() {
  let dialog = document.querySelector("[data-llh-confirm-dialog]");
  if (!dialog) {
    document.body.insertAdjacentHTML("beforeend", confirmActionDialogHtml());
    dialog = document.querySelector("[data-llh-confirm-dialog]");
  }
  return dialog;
}

function closeConfirmActionDialog(result = false) {
  const dialog = document.querySelector("[data-llh-confirm-dialog]");
  if (dialog) dialog.hidden = true;
  if (!document.querySelector(".modal.open, .llh-confirm-dialog:not([hidden]), #scheduleEventModal.open")) {
    document.body.classList.remove("auth-modal-open");
  }
  const resolve = confirmActionResolver;
  confirmActionResolver = null;
  const returnFocus = confirmActionReturnFocus;
  confirmActionReturnFocus = null;
  if (resolve) resolve(Boolean(result));
  if (returnFocus && typeof returnFocus.focus === "function") {
    try { returnFocus.focus(); } catch (_error) { /* ignore */ }
  }
}

/**
 * Shared confirm dialog. Prefer clear Remove vs Delete language in title/message/confirmLabel.
 * @param {{ title?: string, message?: string, confirmLabel?: string, cancelLabel?: string, danger?: boolean }} options
 * @returns {Promise<boolean>}
 */
function confirmAction(options = {}) {
  if (confirmActionResolver) {
    const previous = confirmActionResolver;
    confirmActionResolver = null;
    previous(false);
  }
  const dialog = ensureConfirmActionDialog();
  const fallbackMessage = [options.title, options.message].filter(Boolean).join("\n\n") || "Are you sure?";
  if (!dialog) return Promise.resolve(window.confirm(fallbackMessage));
  const titleEl = dialog.querySelector("[data-llh-confirm-title]");
  const messageEl = dialog.querySelector("[data-llh-confirm-message]");
  const okBtn = dialog.querySelector("[data-llh-confirm-ok]");
  const cancelBtns = dialog.querySelectorAll("[data-llh-confirm-cancel]");
  if (titleEl) titleEl.textContent = options.title || "Confirm";
  if (messageEl) messageEl.textContent = options.message || "Are you sure?";
  if (okBtn) {
    okBtn.textContent = options.confirmLabel || "Confirm";
    okBtn.classList.toggle("danger-button", Boolean(options.danger));
    okBtn.classList.toggle("primary-button", !options.danger);
  }
  cancelBtns.forEach((btn) => {
    if (btn.classList.contains("llh-confirm-backdrop")) return;
    btn.textContent = options.cancelLabel || "Cancel";
  });
  dialog.hidden = false;
  document.body.classList.add("auth-modal-open");
  confirmActionReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  okBtn?.focus();
  return new Promise((resolve) => {
    confirmActionResolver = resolve;
  });
}

function itemActionMenuHtml(menuId, actions = []) {
  const safeId = escapeHtml(String(menuId || ""));
  const buttons = (actions || []).filter(Boolean).map((action) => {
    if (action.divider) return `<div class="llh-item-menu-divider" role="separator"></div>`;
    const dangerClass = action.danger ? " llh-item-menu-danger" : "";
    return `<button type="button" class="llh-item-menu-action${dangerClass}" role="menuitem" ${action.attr || ""}>${escapeHtml(action.label || "Action")}</button>`;
  }).join("");
  return `
    <div class="llh-item-menu">
      <button type="button" class="ghost-button llh-item-menu-toggle" data-llh-item-menu-toggle="${safeId}" aria-label="More actions" aria-haspopup="menu" aria-expanded="false">⋮</button>
      <div class="llh-item-menu-panel" data-llh-item-menu="${safeId}" hidden role="menu">${buttons}</div>
    </div>
  `;
}

function itemActionMenuIsMobile() {
  return typeof window.matchMedia === "function"
    && window.matchMedia("(max-width: 767px)").matches;
}

function ensureItemActionMenuBackdrop() {
  let backdrop = document.querySelector("[data-llh-item-menu-backdrop]");
  if (!backdrop) {
    backdrop = document.createElement("button");
    backdrop.type = "button";
    backdrop.className = "llh-item-menu-backdrop";
    backdrop.setAttribute("data-llh-item-menu-backdrop", "");
    backdrop.setAttribute("aria-label", "Close actions menu");
    backdrop.hidden = true;
    document.body.appendChild(backdrop);
    backdrop.addEventListener("click", () => closeAllItemActionMenus());
  }
  return backdrop;
}

function restoreItemActionMenuPanel(panel) {
  if (!panel) return;
  const homeId = panel.getAttribute("data-llh-item-menu-home");
  const home = homeId
    ? document.querySelector(`[data-llh-item-menu-toggle="${homeId}"]`)?.closest(".llh-item-menu")
    : null;
  if (home && panel.parentElement !== home) home.appendChild(panel);
  ["position", "top", "bottom", "left", "right", "width", "maxWidth", "maxHeight", "zIndex", "margin"].forEach((prop) => {
    panel.style[prop] = "";
  });
  panel.classList.remove("is-mobile-sheet");
}

function positionItemActionMenuPanel(panel) {
  if (!panel || panel.hidden) return;
  const mobile = itemActionMenuIsMobile();
  const backdrop = ensureItemActionMenuBackdrop();
  document.body.classList.toggle("llh-item-menu-open", mobile);
  if (!mobile) {
    backdrop.hidden = true;
    restoreItemActionMenuPanel(panel);
    return;
  }
  if (!panel.getAttribute("data-llh-item-menu-home")) {
    panel.setAttribute("data-llh-item-menu-home", panel.getAttribute("data-llh-item-menu") || "");
  }
  if (panel.parentElement !== document.body) document.body.appendChild(panel);
  panel.classList.add("is-mobile-sheet");
  backdrop.hidden = false;
  const sidePad = 12;
  const safeBottom = typeof readSafeAreaInset === "function" ? readSafeAreaInset("bottom") : 0;
  const safeTop = typeof readSafeAreaInset === "function" ? readSafeAreaInset("top") : 0;
  panel.style.position = "fixed";
  panel.style.left = `${sidePad}px`;
  panel.style.right = `${sidePad}px`;
  panel.style.width = `calc(100vw - ${sidePad * 2}px)`;
  panel.style.maxWidth = "100%";
  panel.style.bottom = `${Math.max(sidePad, safeBottom + 8)}px`;
  panel.style.top = "auto";
  panel.style.maxHeight = `${Math.max(180, window.innerHeight - 32 - safeTop - safeBottom)}px`;
  panel.style.zIndex = "1285";
  panel.style.margin = "0";
}

function closeAllItemActionMenus(exceptId = "") {
  document.querySelectorAll("[data-llh-item-menu]").forEach((panel) => {
    const id = panel.getAttribute("data-llh-item-menu") || "";
    if (exceptId && id === exceptId) return;
    panel.hidden = true;
    restoreItemActionMenuPanel(panel);
  });
  document.querySelectorAll("[data-llh-item-menu-toggle]").forEach((btn) => {
    const id = btn.getAttribute("data-llh-item-menu-toggle") || "";
    if (exceptId && id === exceptId) return;
    btn.setAttribute("aria-expanded", "false");
  });
  if (!exceptId) {
    const backdrop = document.querySelector("[data-llh-item-menu-backdrop]");
    if (backdrop) backdrop.hidden = true;
    document.body.classList.remove("llh-item-menu-open");
  }
}

function toggleItemActionMenu(menuId, forceOpen) {
  const panel = document.querySelector(`[data-llh-item-menu="${menuId}"]`);
  const toggle = document.querySelector(`[data-llh-item-menu-toggle="${menuId}"]`);
  if (!panel) return;
  const willOpen = forceOpen === undefined ? panel.hidden : Boolean(forceOpen);
  closeAllItemActionMenus(willOpen ? menuId : "");
  panel.hidden = !willOpen;
  if (toggle) toggle.setAttribute("aria-expanded", willOpen ? "true" : "false");
  if (willOpen) {
    positionItemActionMenuPanel(panel);
    requestAnimationFrame(() => positionItemActionMenuPanel(panel));
  } else {
    restoreItemActionMenuPanel(panel);
    const backdrop = document.querySelector("[data-llh-item-menu-backdrop]");
    if (backdrop) backdrop.hidden = true;
    document.body.classList.remove("llh-item-menu-open");
  }
}

function childRecordEditDialogHtml() {
  return `
    <div class="llh-confirm-dialog" data-llh-record-edit-dialog hidden>
      <button type="button" class="llh-confirm-backdrop" data-llh-record-edit-cancel aria-label="Dismiss edit dialog"></button>
      <div class="llh-confirm-panel" role="dialog" aria-modal="true" aria-labelledby="llhRecordEditTitle">
        <h3 id="llhRecordEditTitle">Edit record</h3>
        <form class="mini-form" data-llh-record-edit-form>
          <input type="hidden" name="storeKey" value="" />
          <input type="hidden" name="recordId" value="" />
          <label>Date<input name="date" type="date" /></label>
          <label>Details<textarea name="details" rows="4" placeholder="Update this entry"></textarea></label>
          <div class="llh-confirm-actions">
            <button type="submit" class="primary-button">Save Changes</button>
            <button type="button" class="ghost-button" data-llh-record-edit-cancel>Cancel</button>
          </div>
        </form>
      </div>
    </div>
  `;
}

function ensureChildRecordEditDialog() {
  let dialog = document.querySelector("[data-llh-record-edit-dialog]");
  if (!dialog) {
    document.body.insertAdjacentHTML("beforeend", childRecordEditDialogHtml());
    dialog = document.querySelector("[data-llh-record-edit-dialog]");
  }
  return dialog;
}

function closeChildRecordEditDialog(saved = false) {
  const dialog = document.querySelector("[data-llh-record-edit-dialog]");
  if (dialog) dialog.hidden = true;
  if (!document.querySelector(".modal.open, .llh-confirm-dialog:not([hidden]), #scheduleEventModal.open")) {
    document.body.classList.remove("auth-modal-open");
  }
  const resolve = childRecordEditResolver;
  childRecordEditResolver = null;
  if (resolve) resolve(Boolean(saved));
  const returnFocus = childRecordEditReturnFocus;
  childRecordEditReturnFocus = null;
  restoreLlhFocus(returnFocus);
}

function primaryChildRecordDetail(item = {}) {
  if (item.message != null && item.message !== "") return { key: "message", value: item.message };
  if (item.notes != null && item.notes !== "") return { key: "notes", value: item.notes };
  if (item.text != null && item.text !== "") return { key: "text", value: item.text };
  if (item.activity != null && item.activity !== "") return { key: "activity", value: item.activity };
  if (item.support != null && item.support !== "") return { key: "support", value: item.support };
  if (item.goal != null && item.goal !== "") return { key: "goal", value: item.goal };
  if (item.summary != null) return { key: "summary", value: item.summary };
  return { key: "summary", value: "" };
}

function openChildRecordEditDialog(storeKey, recordId) {
  const items = childStore(storeKey);
  const item = items.find((entry) => entry.id === recordId);
  if (!item) return Promise.resolve(false);
  if (childRecordEditResolver) {
    const previous = childRecordEditResolver;
    childRecordEditResolver = null;
    previous(false);
  }
  const dialog = ensureChildRecordEditDialog();
  if (!dialog) return Promise.resolve(false);
  const form = dialog.querySelector("[data-llh-record-edit-form]");
  const detail = primaryChildRecordDetail(item);
  form.storeKey.value = storeKey;
  form.recordId.value = recordId;
  form.date.value = item.date || "";
  form.details.value = detail.value || "";
  form.dataset.detailKey = detail.key;
  childRecordEditReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  document.body.classList.add("auth-modal-open");
  dialog.hidden = false;
  form.details.focus();
  return new Promise((resolve) => {
    childRecordEditResolver = resolve;
  });
}

async function deleteChildRecordPermanently(storeKey, recordId) {
  if (!storeKey || !recordId) return false;
  const confirmed = await confirmAction({
    title: "Delete permanently?",
    message: "This permanently deletes this entry. This cannot be undone.",
    confirmLabel: "Delete Permanently",
    danger: true,
  });
  if (!confirmed) return false;
  saveChildStore(storeKey, childStore(storeKey).filter((item) => item.id !== recordId));
  showActionFeedback("Entry deleted.");
  renderChildManagement();
  return true;
}

async function archiveChildRecord(storeKey, recordId, shouldArchive = true) {
  if (!storeKey || !recordId) return false;
  saveChildStore(storeKey, childStore(storeKey).map((item) => (
    item.id === recordId ? { ...item, archived: shouldArchive, updatedAt: new Date().toISOString() } : item
  )));
  showActionFeedback(shouldArchive ? "Entry archived." : "Entry reactivated.");
  renderChildManagement();
  return true;
}

async function setChildRecordFamilyShare(storeKey, recordId, shared) {
  if (!storeKey || !recordId) return false;
  if (!shared) {
    const confirmed = await confirmAction({
      title: storeKey === "Photos" ? "Remove from parent view?" : "Stop sharing with Family Hub?",
      message: storeKey === "Photos"
        ? "This removes the photo from parent/Family Hub view only. The photo stays in your child records."
        : "This stops sharing with Family Hub. The original record stays in your logs.",
      confirmLabel: storeKey === "Photos" ? "Remove From Parent View" : "Stop Sharing",
    });
    if (!confirmed) return false;
  }
  saveChildStore(storeKey, childStore(storeKey).map((item) => (
    item.id === recordId ? { ...item, shareWithFamily: Boolean(shared), updatedAt: new Date().toISOString() } : item
  )));
  showActionFeedback(shared
    ? "Shared with Family Hub — families can see this when they’re invited."
    : (storeKey === "Photos" ? "Removed from the parent view." : "Stopped sharing with Family Hub."));
  renderChildManagement();
  return true;
}

async function archiveChildProfile(childId) {
  if (!childId) return;
  const confirmed = await confirmAction({
    title: "Archive child?",
    message: "Archiving hides this child from Daily Logs and active lists, and removes them from Family Hub. You can reactivate them later. Their records are kept.",
    confirmLabel: "Archive Child",
  });
  if (!confirmed) return;
  const profiles = childStore("Profiles");
  saveChildStore("Profiles", profiles.map((child) => (
    child.id === childId ? { ...child, archived: true, hiddenFromActive: true } : child
  )));
  const unlink = await unlinkChildFromFamilyHubHouseholds(childId, "child_archived").catch(() => ({ unlinked: 0 }));
  showActionFeedback(
    unlink?.unlinked
      ? `Child archived · removed from ${unlink.unlinked} Family Hub household${unlink.unlinked === 1 ? "" : "s"}.`
      : "Child archived.",
  );
  renderChildManagement();
}

async function reactivateChildProfile(childId) {
  if (!childId) return;
  const profiles = childStore("Profiles");
  saveChildStore("Profiles", profiles.map((child) => (
    child.id === childId ? { ...child, archived: false, hiddenFromActive: false } : child
  )));
  showActionFeedback("Child reactivated.");
  renderChildManagement();
}

async function deleteChildProfilePermanently(childId) {
  if (!childId) return;
  const child = childStore("Profiles").find((item) => item.id === childId);
  const confirmed = await confirmAction({
    title: "Delete child permanently?",
    message: `Delete “${child?.name || "this child"}” and all of their logs, observations, goals, and related records permanently? Archive is preferred. This cannot be undone.`,
    confirmLabel: "Delete Child Permanently",
    danger: true,
  });
  if (!confirmed) return;
  await unlinkChildFromFamilyHubHouseholds(childId, "child_deleted").catch(() => ({}));
  const relatedKeys = childDataKeys.filter((key) => key !== "Profiles" && key !== "MealPresets");
  relatedKeys.forEach((key) => {
    saveChildStore(key, childStore(key).filter((item) => item.childId !== childId));
  });
  saveChildStore("Profiles", childStore("Profiles").filter((item) => item.id !== childId));
  if (selectedChildId === childId) {
    selectedChildId = childStore("Profiles")[0]?.id || "";
    localStorage.setItem("llhSelectedChild", selectedChildId);
  }
  showActionFeedback("Child deleted permanently.");
  childManagementMode = "list";
  renderChildManagement();
}

/**
 * Show a transient feedback banner at the bottom of the screen.
 * Prefer showAfterActionPrompt for save events tied to a specific trigger/child.
 * @param {string} message - The text to display in the banner.
 * @param {{label: string, attr: string}|null} action - Optional CTA button. label is the button text; attr is the HTML attribute string (e.g. 'data-view="plans"').
 */
function showActionFeedback(message, action = null) {
  if (!message) return;
  let banner = document.querySelector("#afterActionPrompt");
  if (!banner) {
    banner = document.createElement("div");
    banner.id = "afterActionPrompt";
    banner.className = "after-action-prompt";
    banner.setAttribute("role", "status");
    banner.setAttribute("aria-live", "polite");
    document.querySelector(".main")?.appendChild(banner);
  }
  banner.innerHTML = `
    <span class="after-action-text">${escapeHtml(message)}</span>
    ${action ? `<button class="primary-button after-action-yes" ${action.attr} type="button">${escapeHtml(action.label)}</button>` : ""}
    <button class="ghost-button after-action-dismiss" type="button">Got it</button>
  `;
  banner.classList.add("visible");
  if (afterActionPromptTimeout) clearTimeout(afterActionPromptTimeout);
  afterActionPromptTimeout = setTimeout(() => banner.classList.remove("visible"), 10000);
}

function showAfterActionPrompt(trigger, childId) {
  const prompts = {
    attendance: {
      message: "Attendance saved! Would you like to generate today's daily report?",
      proAction: { label: "Yes, generate", attr: `data-build-daily-report="${childId}"` },
      freeMessage: "Attendance saved! Preview the Pro daily report workflow.",
      freeAction: { label: "Preview daily report", attr: `data-preview="daily-log-reports"` },
    },
    observation: {
      message: "Observation saved! Would you like to generate a parent message?",
      proAction: { label: "Yes, generate", attr: `data-child-quick-entry="${childId}" data-quick-action="parent-message"` },
      freeMessage: "Observation saved! Preview the Pro parent message workflow.",
      freeAction: { label: "Preview parent message", attr: `data-preview="daily-log-parent-messages"` },
    },
    meals: {
      message: "Meals logged! Would you like to create today's portfolio entry?",
      proAction: { label: "Yes, generate", attr: `data-child-quick-entry="${childId}" data-quick-action="portfolio"` },
      freeMessage: "Meals logged! Preview the Pro portfolio workflow.",
      freeAction: { label: "Preview portfolio", attr: `data-preview="portfolio-builder"` },
    },
  };
  const prompt = prompts[trigger];
  if (!prompt || !childId) return;
  showActionFeedback(
    isProUser() ? prompt.message : prompt.freeMessage,
    isProUser() ? prompt.proAction : prompt.freeAction,
  );
}

async function buildDailyReportFromChild(childId, quickNote) {
  const records = childRecords();
  const child = records.children.find((item) => item.id === childId);
  if (!child) return;
  const today = dlcActiveDate();
  const programSettings = getProgramSettings();
  const programName = programSettings.programName || "";
  const tone = programSettings.communicationTone || "Warm and friendly";
  const grounded = buildGroundedDayFactsForAi(child, records, today);
  const ageGroup = childAgeGroupLabel(child);
  const highlights = [quickNote, grounded.highlights].filter(Boolean).join(". ");

  const result = await generateToolOutputWithBackend("daily", {
    childName: child.name,
    age: ageGroup,
    programName,
    date: today,
    classroom: grounded.classroom || child.classroom || "",
    tone,
    highlights,
    meals: grounded.meals,
    nap: grounded.nap,
    diapering: grounded.diapering,
    activities: grounded.activities,
    providerNotes: [
      grounded.factsText,
      grounded.attendance ? `Attendance: ${grounded.attendance}` : "",
      grounded.photos ? `Photos shared: ${grounded.photos}` : "",
      "Use only these logged facts. Do not invent missing details.",
    ].filter(Boolean).join("\n"),
  });
  const report = result.output;

  appendChildRecord("Reports", {
    childId,
    title: `Daily Report | ${today}`,
    date: today,
    summary: report.slice(0, 200),
    message: report,
    shareWithFamily: true,
  });
  return report;
}

function exportChildPortfolio(childId) {
  const records = childRecords();
  const child = records.children.find((item) => item.id === childId);
  if (!child) return;
  const childObservations = records.observations.filter((item) => item.childId === childId);
  const childGoals = records.goals.filter((item) => item.childId === childId);
  const activeGoals = childGoals.filter((item) => goalProgressPercent(item.progress) < 100);
  const childSupportPlans = records.supportPlans.filter((item) => item.childId === childId);
  const childDifferentiations = records.differentiations.filter((item) => item.childId === childId);
  const childAttendance = records.attendance.filter((item) => item.childId === childId);
  const childMeals = records.meals.filter((item) => item.childId === childId);
  const childReports = records.reports.filter((item) => item.childId === childId);
  const childCommunications = records.communications.filter((item) => item.childId === childId);
  const addSection = (lines, title, items) => {
    const filledItems = items.filter((item) => presentPortfolioValue(item));
    if (!filledItems.length) return;
    if (lines[lines.length - 1] !== "") lines.push("");
    lines.push(title, ...filledItems);
  };
  const profileLines = childPortfolioTextDetails(child, activeGoals);
  const lines = [
    `Child Portfolio: ${child.name}`,
    ...(profileLines.length ? ["", ...profileLines] : []),
  ];
  const summaryParts = [
    childObservations.length ? `${childObservations.length} saved observation${childObservations.length === 1 ? "" : "s"}` : "",
    activeGoals.length ? `${activeGoals.length} active goal${activeGoals.length === 1 ? "" : "s"}` : "",
    childDifferentiations.length ? `${childDifferentiations.length} connected activity support${childDifferentiations.length === 1 ? "" : "s"}` : "",
  ].filter(Boolean);
  addSection(lines, "Development Summary", summaryParts.length
    ? [`${child.name} has ${summaryParts.join(", ")}. Use this portfolio as a printable progress record for planning, family conferences, and documentation review.`]
    : []);
  addSection(lines, "Observations", childObservations.map((item) => {
      const analysis = observationAnalysis(item, child);
      return `- ${item.date} | ${analysis.developmentArea}: ${item.text}
  Categories: ${(analysis.categories || []).join(", ")}
  Strengths: ${analysis.strengths}
  Next Steps: ${analysis.nextSteps}
  Suggested Activities: ${(analysis.suggestedActivities || []).join(", ")}
  Suggested Lesson Plans: ${(analysis.suggestedLessonPlans || []).join(", ")}
  ELG Domain: ${analysis.elgDomain}
  ELG Skill Area: ${analysis.elgSkill}`;
    }));
  addSection(lines, "Goals", childGoals.map((item) => {
      const area = normalizeObservationArea(item.area) || item.area;
      return `- ${area}: ${item.goal} | Progress: ${goalProgressPercent(item.progress)}% | Target: ${item.targetDate || ""}
  Connected Observations: ${connectedObservationsForGoal(item, records).length}
  Suggested Activities: ${suggestedActivitiesForArea(area, child).join(", ")}
  Suggested Lesson Plans: ${suggestedLessonPlansForArea(area).join(", ")}
  Progress Notes: ${item.notes || ""}`;
    }));
  addSection(lines, "Support Plans", childSupportPlans.map((item) => portfolioBullet([item.area, item.goal, item.activity, item.status])));
  addSection(lines, "Activities Completed / Lesson Plan Connections", childDifferentiations.map((item) => portfolioBullet([
    portfolioTextLine("Whole Group", item.wholeGroup),
    portfolioTextLine("Individual Support", item.support),
  ], ". ")));
  addSection(lines, "Attendance", childAttendance.map((item) => portfolioBullet([
    item.date,
    item.status,
    item.dropoff ? `drop-off ${item.dropoff}` : "",
    item.pickup ? `pick-up ${item.pickup}` : "",
  ], ", ")));
  addSection(lines, "Meals", childMeals.map((item) => portfolioBullet([
    item.date,
    item.breakfast ? `Breakfast ${item.breakfast}` : "",
    item.lunch ? `Lunch ${item.lunch}` : "",
    item.snack ? `Snack ${item.snack}` : "",
    item.notes ? `Notes ${item.notes}` : "",
  ], "; ")));
  addSection(lines, "Daily Reports", childReports.map((item) => portfolioBullet([item.title, item.summary], ": ")));
  addSection(lines, "Parent Communication", childCommunications.map((item) => portfolioBullet([
    item.date,
    item.type,
    item.message,
  ])));
  printTextDocument(`${child.name} Portfolio`, lines.join("\n"));
}

function preferences() {
  return readSavedJson("llhPreferences", {});
}

function preferenceLine() {
  const prefs = preferences();
  const parts = [
    prefs.programType || "home daycare",
    prefs.agesServed ? `serving ${prefs.agesServed}` : "serving mixed ages",
    prefs.standards ? `aligned with ${prefs.standards}` : "aligned with early learning guidelines",
    prefs.lessonStyle || "simple and low-prep",
  ];
  return parts.join(", ");
}

function renderSavedPreferences() {
  const target = document.querySelector("#savedPreferences");
  if (!target) return;
  const prefs = preferences();
  target.innerHTML = Object.keys(prefs).length
    ? `<p><strong>Saved:</strong> ${preferenceLine()}.</p>`
    : `<p>Save your daycare type, ages served, standards, and favorite formats so the AI can personalize future results.</p>`;
}

function generatedOutputs() {
  return readSavedJson("llhGeneratedOutputs", []);
}

function saveGeneratedOutputs(items) {
  localStorage.setItem("llhGeneratedOutputs", JSON.stringify(items.slice(0, 20)));
  saveCurrentAccountState();
  renderGeneratedHistory();
}

function currentGeneratedResult() {
  const title = document.querySelector("#outputTitle")?.textContent.trim() || "Generated Content";
  const el = document.querySelector("#generatorOutput");
  const text = (el?.dataset.rawMarkdown || el?.textContent || "").trim();
  if (!text || text === "Fill out the form and generate a childcare-ready result.") return null;
  return {
    id: `ai-${Date.now()}`,
    title,
    toolId: document.querySelector("#activeGeneratorForm")?.dataset.generator || "",
    text,
    date: new Date().toLocaleDateString(),
  };
}

function categoryForGenerator(toolId) {
  const categoryMap = {
    lesson: "Lesson Plans",
    observation: "Observation Hub",
    activity: "Activity Center",
    menu: "Menu Center",
    form: "Forms Library",
    daily: "Forms Library",
    newsletter: "Forms Library",
    handbook: "Forms Library",
    contract: "Forms Library",
    assessment: "Observation Hub",
    progress: "Observation Hub",
    portfolio: "Observation Hub",
    curriculum: "Lesson Plans",
    behavior: "Observation Hub",
    learningStory: "Observation Hub",
    parentMessage: "Forms Library",
    schedule: "Forms Library",
    classroomSetup: "Forms Library",
    emergency: "Forms Library",
    substitute: "Lesson Plans",
    grant: "Forms Library",
  };
  return categoryMap[toolId] || "Forms Library";
}

function saveGeneratedResultToLibrary(result) {
  const toolId = result.toolId || document.querySelector("#activeGeneratorForm")?.dataset.generator || "";
  const resource = {
    id: `ai-library-${Date.now()}`,
    category: categoryForGenerator(toolId),
    title: result.title,
    age: "All Ages",
    plan: "Pro",
    month: "AI Saved",
    tags: ["AI Generated", result.title, toolId].filter(Boolean),
    format: "In-App Preview",
    description: result.text.slice(0, 180),
    customContent: result.text,
  };
  saveUploadedResources([resource, ...uploadedResources()]);
  resources = loadResources();
  renderAdminDashboard();
  return resource;
}

function printTextDocument(title, text) {
  const printWindow = window.open("", "_blank");
  if (!printWindow) {
    window.print();
    return;
  }
  printWindow.document.write(`
    <html>
      <head>
        <title>${escapeHtml(title)}</title>
        <style>
          @page { margin: 0.55in; }
          body { font-family: Arial, sans-serif; line-height: 1.6; padding: 32px; color: #2f2a25; }
          .brand { color: #386062; font-size: 13px; text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }
          h1.doc-title { color: #386062; margin: 6px 0 24px; font-size: 28px; }
          h2 { color: #386062; font-size: 20px; margin: 22px 0 6px; border-bottom: 1px solid #d5e3f0; padding-bottom: 4px; }
          h3 { color: #386062; font-size: 17px; margin: 18px 0 5px; }
          h4 { color: #536280; font-size: 15px; margin: 14px 0 4px; }
          p { margin: 0 0 10px; font-size: 14px; }
          ul, ol { margin: 0 0 10px; padding-left: 22px; }
          li { margin-bottom: 4px; font-size: 14px; }
          strong { font-weight: 700; }
          em { font-style: italic; }
        </style>
      </head>
      <body>
        <div class="brand">Little Learner Hub</div>
        <h1 class="doc-title">${escapeHtml(title)}</h1>
        <div class="doc-body">${renderMarkdown(text)}</div>
      </body>
    </html>
  `);
  printWindow.document.close();
  printWindow.focus();
  printWindow.print();
}

function printGeneratedResult(result) {
  printTextDocument(result.title, result.text);
}

function renderGeneratedHistory() {
  const target = document.querySelector("#generatedHistory");
  if (!target) return;
  const items = generatedOutputs();
  target.innerHTML = items.length
    ? items.map((item) => `
      <div class="compact-item generated-item">
        <div>
          <strong>${escapeHtml(item.title)}</strong>
          <span>${escapeHtml(item.date)} · ${escapeHtml(item.text.slice(0, 92))}${item.text.length > 92 ? "..." : ""}</span>
        </div>
        <div class="goal-card-actions">
          <button class="ghost-button" data-load-output="${escapeHtml(item.id)}" type="button">Open</button>
          ${itemActionMenuHtml(`generated-${item.id}`, [
            { label: "Open", attr: `data-load-output="${escapeHtml(item.id)}"` },
            { divider: true },
            { label: "Delete Permanently", attr: `data-delete-generated-output="${escapeHtml(item.id)}"`, danger: true },
          ])}
        </div>
      </div>
    `).join("")
    : `<div class="empty-state">Generated AI results you save will show up here for quick reuse.</div>`;
}

function uploadedResourceFingerprint(resource) {
  const payload = JSON.stringify({
    category: String(resource?.category || "").trim(),
    title: String(resource?.title || "").trim(),
    age: String(resource?.age || "").trim(),
    plan: String(resource?.plan || "").trim(),
    month: String(resource?.month || "").trim(),
    tags: Array.isArray(resource?.tags) ? resource.tags.map((tag) => String(tag || "").trim()).filter(Boolean).slice(0, 25) : [],
    format: String(resource?.format || "").trim(),
    fileName: String(resource?.fileName || "").trim(),
    fileData: String(resource?.fileData || "").trim(),
    previewName: String(resource?.previewName || "").trim(),
    previewData: String(resource?.previewData || "").trim(),
    description: String(resource?.description || "").trim(),
    customContent: String(resource?.customContent || "").trim(),
    visible: resource?.visible !== false,
    archived: resource?.archived === true,
  });
  let hash = 0;
  for (let i = 0; i < payload.length; i += 1) {
    hash = ((hash << 5) - hash + payload.charCodeAt(i)) | 0;
  }
  return `fp-${Math.abs(hash).toString(36)}`;
}

function normalizeUploadedResource(resource) {
  if (!resource || typeof resource !== "object") return null;
  const id = String(resource.id || "").trim();
  if (!id) return null;
  const tags = Array.isArray(resource.tags)
    ? resource.tags.map((tag) => String(tag || "").trim()).filter(Boolean).slice(0, 25)
    : [];
  const normalized = {
    ...resource,
    id,
    category: String(resource.category || "Forms Library").trim(),
    title: String(resource.title || "Uploaded Resource").trim(),
    age: String(resource.age || "All Ages").trim(),
    plan: String(resource.plan || "Free").trim(),
    month: String(resource.month || "").trim(),
    tags,
    format: String(resource.format || "").trim(),
    fileName: String(resource.fileName || "").trim(),
    fileData: String(resource.fileData || "").trim(),
    previewName: String(resource.previewName || "").trim(),
    previewData: String(resource.previewData || "").trim(),
    description: String(resource.description || "").trim(),
    customContent: String(resource.customContent || "").trim(),
    visible: resource.visible !== false,
    archived: resource.archived === true,
    updatedAt: String(resource.updatedAt || "").trim(),
  };
  normalized.fingerprint = String(resource.fingerprint || uploadedResourceFingerprint(normalized)).trim();
  return normalized;
}

function dedupeUploadedResourcesList(items = [], limit = 3000) {
  const byId = new Set();
  const byFingerprint = new Set();
  const deduped = [];
  for (const item of items) {
    const normalized = normalizeUploadedResource(item);
    if (!normalized) continue;
    const fp = normalized.fingerprint || uploadedResourceFingerprint(normalized);
    if (byId.has(normalized.id) || (fp && byFingerprint.has(fp))) continue;
    byId.add(normalized.id);
    if (fp) byFingerprint.add(fp);
    deduped.push({ ...normalized, fingerprint: fp });
    if (deduped.length >= limit) break;
  }
  return deduped;
}

function uploadedResourcesDigest(items = []) {
  return dedupeUploadedResourcesList(items).map((item) => `${item.id}:${item.fingerprint}`).join("|");
}

function uploadedResources() {
  return dedupeUploadedResourcesList(readSavedJson(uploadedResourcesConfig.storageKey, []));
}

function saveUploadedResources(items) {
  const deduped = dedupeUploadedResourcesList(items);
  localStorage.setItem(uploadedResourcesConfig.storageKey, JSON.stringify(deduped));
  resources = loadResources();
  return deduped;
}

function mergeUploadedResources(remoteUploads = []) {
  const merged = dedupeUploadedResourcesList([...remoteUploads, ...uploadedResources()]);
  return saveUploadedResources(merged);
}

async function loadUploadedResourcesFromBackend({ admin = false, migrateLocal = false } = {}) {
  if (!canUseLaunchBackend()) return uploadedResources();
  const params = new URLSearchParams({ t: String(Date.now()) });
  const token = adminSession()?.token || "";
  const requestHeaders = admin && token ? { Authorization: `Bearer ${token}` } : {};
  try {
    const response = await fetch(`${uploadedResourcesConfig.listEndpoint}?${params.toString()}`, { cache: "no-store", headers: requestHeaders });
    const data = await response.json();
    if (!response.ok) throw new Error(data?.error || "Could not load uploaded resources.");
    const remoteUploads = dedupeUploadedResourcesList(data.uploads || []);
    saveUploadedResources(remoteUploads);
    if (admin && migrateLocal && token) {
      await migrateUploadedResourcesFromLocalStorage();
    }
    return uploadedResources();
  } catch (error) {
    console.warn("Uploaded resources backend sync failed", error);
    return uploadedResources();
  }
}

async function migrateUploadedResourcesFromLocalStorage() {
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !token) return { migrated: false };
  const localUploads = uploadedResources();
  if (!localUploads.length) return { migrated: false };
  const localDigest = uploadedResourcesDigest(localUploads);
  const marker = readSavedJson(uploadedResourcesConfig.migrationKey, null);
  if (marker?.completed === true && marker?.digest === localDigest) {
    return { migrated: false, reason: "already-migrated" };
  }
  try {
    const response = await fetch(uploadedResourcesConfig.migrateEndpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ uploads: localUploads }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data?.error || "Could not migrate uploads.");
    const merged = dedupeUploadedResourcesList(data.uploads || []);
    saveUploadedResources(merged);
    localStorage.setItem(uploadedResourcesConfig.migrationKey, JSON.stringify({
      completed: true,
      digest: localDigest,
      migratedAt: new Date().toISOString(),
      count: localUploads.length,
      remoteCount: merged.length,
    }));
    return { migrated: true, migration: data.migration || null };
  } catch (error) {
    console.warn("Uploaded resource migration failed", error);
    return { migrated: false, error: error.message || "migration-failed" };
  }
}

async function saveUploadedResourceToBackend(upload) {
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !isAdminUnlocked() || !token) {
    throw new Error("Backend server and admin login are required to save uploads.");
  }
  const response = await fetch(uploadedResourcesConfig.upsertEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({ upload }),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error || "Could not save uploaded resource.");
  saveUploadedResources(data.uploads || []);
  return data.upload;
}

async function deleteUploadedResourceFromBackend(id) {
  const token = adminSession()?.token || "";
  if (!canUseLaunchBackend() || !isAdminUnlocked() || !token) {
    throw new Error("Backend server and admin login are required to delete uploads.");
  }
  const response = await fetch(uploadedResourcesConfig.deleteEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({ id }),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error || "Could not delete uploaded resource.");
  saveUploadedResources(data.uploads || []);
  return true;
}

function supportTickets() {
  return readSavedJson("llhSupportTickets", []);
}

function saveSupportTickets(items) {
  localStorage.setItem("llhSupportTickets", JSON.stringify(items));
}

function mergeSupportTickets(remoteTickets = []) {
  const merged = [...remoteTickets, ...supportTickets()];
  const seen = new Set();
  const unique = merged.filter((ticket) => {
    if (!ticket?.id || seen.has(ticket.id)) return false;
    seen.add(ticket.id);
    return true;
  });
  saveSupportTickets(unique.slice(0, 100));
  return unique;
}

async function loadSupportTicketsFromBackend({ admin = false } = {}) {
  if (!canUseLaunchBackend()) return supportTickets();
  const params = new URLSearchParams();
  const headers = { Accept: "application/json" };
  if (admin && adminSession()?.token) {
    headers.Authorization = `Bearer ${adminSession().token}`;
  } else if (currentUser) {
    // List endpoint requires authenticated identity — do not rely on ?email= alone.
    const auth = await firebaseAuthHeaders().catch(() => null);
    if (auth) Object.assign(headers, auth);
    else {
      headers["X-LLH-User-Email"] = String(currentUser).trim().toLowerCase();
      headers.Authorization = `Bearer test:${String(currentUser).trim().toLowerCase()}`;
    }
  } else {
    return supportTickets();
  }
  try {
    const response = await fetch(`/api/support-tickets?${params.toString()}`, { headers, cache: "no-store" });
    const data = await response.json();
    if (!response.ok) throw new Error(data?.error || "Could not load support tickets.");
    return mergeSupportTickets(data.tickets || []);
  } catch (error) {
    console.warn("Support ticket sync failed", error);
    return supportTickets();
  }
}

function ticketStatusClass(status) {
  return `ticket-status-${String(status || "New").toLowerCase().replace(/\s+/g, "-")}`;
}

function supportFormMessage(form) {
  let message = form.querySelector(".form-message");
  if (!message) {
    message = document.createElement("span");
    message.className = "form-message";
    form.appendChild(message);
  }
  return message;
}

async function submitSupportTicket(form) {
  const data = collectFormData(form);
  const messageTarget = supportFormMessage(form);
  setFormMessage(messageTarget, "Submitting...", true);
  let ticket = {
    id: `ticket-${Date.now()}`,
    kind: form.dataset.ticketKind || "Support Request",
    name: data.name || "Provider",
    email: data.email || currentUser || "",
    createdBy: currentUser || data.email || "",
    topic: data.topic || "General Questions",
    message: data.message || "",
    status: "New",
    reply: "",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  let submitMessage = "Submitted and saved.";
  if (canUseLaunchBackend()) {
    try {
      const response = await fetch("/api/support-ticket", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...ticket,
          sourceUrl: window.location.href,
          userAgent: navigator.userAgent,
        }),
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result?.error || "Could not submit support ticket.");
      ticket = result.ticket || ticket;
      if (result.emailNotification?.sent) {
        submitMessage = "Submitted. An email notification was sent to support.";
      } else if (result.emailNotification?.configured) {
        submitMessage = "Submitted and saved in Admin. The email notification did not send, so support should check Admin tickets.";
      } else {
        submitMessage = "Submitted and saved in Admin. Email notifications still need an email provider key.";
      }
    } catch (error) {
      console.warn("Support ticket backend submit failed", error);
      submitMessage = "Saved in this browser. If this is urgent, please also email support.";
    }
  } else {
    submitMessage = "Saved in this browser. Connect the backend to save tickets in Admin.";
  }
  saveSupportTickets([ticket, ...supportTickets()]);
  form.reset();
  setFormMessage(messageTarget, submitMessage, true);
  renderContactPage();
  renderAdminTickets();
}

function feedbackDraftStorageKey(type = "General Feedback") {
  const email = String(currentUser || "guest").trim().toLowerCase() || "guest";
  return `llh-feedback-draft:${email}:${String(type || "General Feedback")}`;
}

function readFeedbackDraft(type = "General Feedback") {
  try {
    const raw = sessionStorage.getItem(feedbackDraftStorageKey(type));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function writeFeedbackDraft(type = "General Feedback") {
  try {
    const subject = document.querySelector("#feedbackSubjectInput")?.value || "";
    const message = document.querySelector("#feedbackMessageInput")?.value || "";
    if (!String(subject).trim() && !String(message).trim()) {
      sessionStorage.removeItem(feedbackDraftStorageKey(type));
      return;
    }
    sessionStorage.setItem(feedbackDraftStorageKey(type), JSON.stringify({
      subject,
      message,
      savedAt: new Date().toISOString(),
    }));
  } catch {
    /* ignore quota / private mode */
  }
}

function clearFeedbackDraft(type = "General Feedback") {
  try {
    sessionStorage.removeItem(feedbackDraftStorageKey(type));
  } catch {
    /* ignore */
  }
}

const HOME_SHAPE_FEEDBACK_TYPES = new Set([
  "New Feature",
  "Lesson Plan Request",
  "Activity Request",
  "Bug Report",
  "General Feedback",
]);

function setHomeShapeFeedbackStatus(message = "", { ok = false, error = false } = {}) {
  const status = document.querySelector("#homeShapeFeedbackStatus");
  if (!status) return;
  status.textContent = message;
  status.classList.toggle("is-success", Boolean(ok && message));
  status.classList.toggle("is-error", Boolean(error && message));
}

function prefillHomeShapeFeedbackEmail() {
  const emailInput = document.querySelector("#homeShapeFeedbackEmail");
  if (!emailInput || emailInput.value.trim()) return;
  const account = typeof currentAccount === "function" ? (currentAccount() || {}) : {};
  const email = currentUser || account.email || "";
  if (email) emailInput.value = email;
}

function bindHomeShapeFeedbackForm() {
  const form = document.querySelector("#homeShapeFeedbackForm");
  if (!form || form.dataset.bound === "1") return;
  form.dataset.bound = "1";
  form.addEventListener("submit", submitHomeShapeFeedbackForm);
  prefillHomeShapeFeedbackEmail();
}

async function submitHomeShapeFeedbackForm(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const type = String(document.querySelector("#homeShapeFeedbackType")?.value || "").trim();
  const message = String(document.querySelector("#homeShapeFeedbackMessage")?.value || "").trim();
  const email = String(document.querySelector("#homeShapeFeedbackEmail")?.value || "").trim()
    || currentUser
    || "";
  const submitBtn = document.querySelector("#homeShapeFeedbackSubmit");
  if (!HOME_SHAPE_FEEDBACK_TYPES.has(type)) {
    setHomeShapeFeedbackStatus("Please choose a category.", { error: true });
    document.querySelector("#homeShapeFeedbackType")?.focus();
    return;
  }
  if (!message) {
    setHomeShapeFeedbackStatus("Tell us a little about your idea or request.", { error: true });
    document.querySelector("#homeShapeFeedbackMessage")?.focus();
    return;
  }
  const account = typeof currentAccount === "function" ? (currentAccount() || {}) : {};
  const name = (typeof displayUserName === "function" ? displayUserName(account) : "")
    || [account.firstName, account.lastName].filter(Boolean).join(" ")
    || "Provider";
  const payload = {
    type,
    name,
    email,
    subject: type,
    message,
    sourceUrl: window.location.href,
    page: "#homeShapeFeedback",
    accountType: account.accountType || (typeof getAccountType === "function" ? getAccountType(account) : ""),
    role: account.role || (typeof getUserRole === "function" ? getUserRole(account) : ""),
  };
  setHomeShapeFeedbackStatus("Sending…");
  if (submitBtn) submitBtn.disabled = true;
  try {
    if (!canUseLaunchBackend()) throw new Error("We couldn’t send that just now. Check your connection and try again.");
    const response = await fetch("/api/feedback", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error || "Could not send feedback.");
    trackEvent("feedback_submitted", { type, subject: type, source: "homepage_shape" });
    setHomeShapeFeedbackStatus("Thank you — Leah got your note. It stays private with the team.", { ok: true });
    form.reset();
    prefillHomeShapeFeedbackEmail();
    if (typeof isAdminUnlocked === "function" && isAdminUnlocked()) {
      adminAnalyticsCache = null;
      loadAdminAnalyticsFromBackend();
    }
  } catch (error) {
    setHomeShapeFeedbackStatus(error?.message || "Could not send feedback. Please try again.", { error: true });
  } finally {
    if (submitBtn) submitBtn.disabled = false;
  }
}

const IDEA_REQUEST_TYPES = new Set(["Lesson Plan", "Activity", "Feature", "Other"]);
const IDEA_REQUEST_AGE_GROUPS = new Set(["Infant", "Toddler", "Preschool", "School Age", "Not Applicable"]);

function setIdeaRequestMessage(text, { ok = false, error = false } = {}) {
  const el = document.querySelector("#ideaRequestMessage");
  if (!el) return;
  el.textContent = text || "";
  el.classList.toggle("is-success", Boolean(ok));
  el.classList.toggle("is-error", Boolean(error));
}

function ideaRequestSavedContact() {
  const account = typeof currentAccount === "function" ? (currentAccount() || {}) : {};
  const email = String(currentUser || account.email || "").trim();
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return { name: "", email: "" };
  }
  const fromParts = [account.firstName, account.lastName].filter(Boolean).join(" ").trim();
  const candidates = [
    fromParts,
    String(account.name || "").trim(),
    String(account.displayName || "").trim(),
    String(account.fullName || "").trim(),
  ].filter(Boolean);
  // Only use a real saved name — never invent "Provider" or email-local fallbacks.
  const name = candidates.find((value) => (
    value
    && !/^provider$/i.test(value)
    && !/^undefined(\s+undefined)?$/i.test(value)
  )) || "";
  return { name, email };
}

function prefillIdeaRequestForm({ force = false } = {}) {
  const { name, email } = ideaRequestSavedContact();
  const nameInput = document.querySelector("#ideaRequestName");
  const emailInput = document.querySelector("#ideaRequestEmail");
  if (!nameInput || !emailInput) return;
  if (force || !nameInput.value) nameInput.value = name;
  if (force || !emailInput.value) emailInput.value = email;
}

function openIdeaRequestModal() {
  const modal = document.querySelector("#ideaRequestModal");
  if (!modal) return;
  setIdeaRequestMessage("");
  // Always start from saved contact state so guests never see leftover/fake names.
  prefillIdeaRequestForm({ force: true });
  document.body.classList.add("auth-modal-open");
  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
  const focusTarget = document.querySelector("#ideaRequestName")
    || document.querySelector("#ideaRequestType")
    || document.querySelector("#ideaRequestDetails");
  focusTarget?.focus?.();
}

function closeIdeaRequestModal() {
  const modal = document.querySelector("#ideaRequestModal");
  if (!modal) return;
  modal.classList.remove("open");
  modal.setAttribute("aria-hidden", "true");
  if (!document.querySelector(".modal.open, .llh-confirm-dialog:not([hidden]), #scheduleEventModal.open")) {
    document.body.classList.remove("auth-modal-open");
  }
}

function bindIdeaRequestForm() {
  const form = document.querySelector("#ideaRequestForm");
  if (!form || form.dataset.bound === "1") return;
  form.dataset.bound = "1";
  form.addEventListener("submit", submitIdeaRequestForm);
}

async function submitIdeaRequestForm(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const name = String(document.querySelector("#ideaRequestName")?.value || "").trim();
  const email = String(document.querySelector("#ideaRequestEmail")?.value || "").trim();
  const requestType = String(document.querySelector("#ideaRequestType")?.value || "").trim();
  const ageGroup = String(document.querySelector("#ideaRequestAgeGroup")?.value || "").trim();
  const details = String(document.querySelector("#ideaRequestDetails")?.value || "").trim();
  const submitBtn = document.querySelector("#ideaRequestSubmit");

  if (!name) {
    setIdeaRequestMessage("Please enter your name.", { error: true });
    document.querySelector("#ideaRequestName")?.focus();
    return;
  }
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    setIdeaRequestMessage("Please enter a valid email.", { error: true });
    document.querySelector("#ideaRequestEmail")?.focus();
    return;
  }
  if (!IDEA_REQUEST_TYPES.has(requestType)) {
    setIdeaRequestMessage("Please choose a request type.", { error: true });
    document.querySelector("#ideaRequestType")?.focus();
    return;
  }
  if (!IDEA_REQUEST_AGE_GROUPS.has(ageGroup)) {
    setIdeaRequestMessage("Please choose an age group.", { error: true });
    document.querySelector("#ideaRequestAgeGroup")?.focus();
    return;
  }
  if (!details) {
    setIdeaRequestMessage("Please share a few details about your request.", { error: true });
    document.querySelector("#ideaRequestDetails")?.focus();
    return;
  }

  const title = `${requestType} request: ${details}`.slice(0, 120);
  const description = [
    details,
    "",
    `Request type: ${requestType}`,
    `Age group: ${ageGroup}`,
  ].join("\n");

  setIdeaRequestMessage("Sending…");
  if (submitBtn) submitBtn.disabled = true;
  try {
    if (!canUseLaunchBackend()) throw new Error("We couldn’t send that just now. Check your connection and try again.");
    const response = await fetch("/api/feature-request", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title,
        description,
        category: requestType,
        ageGroup,
        name,
        email,
        source: "homepage_idea_request",
        sourceUrl: window.location.href,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error || "Could not send your request.");
    trackEvent("idea_request_submitted", { requestType, ageGroup, source: "homepage_idea_request" });
    setIdeaRequestMessage("Thank you! Your request has been sent for review.", { ok: true });
    form.reset();
    prefillIdeaRequestForm({ force: true });
    if (typeof isAdminUnlocked === "function" && isAdminUnlocked()) {
      try {
        if (typeof window.renderAdminFeatureRequests === "function") {
          const host = document.querySelector("#adminFeatureRequestsApp");
          if (host) window.renderAdminFeatureRequests(host);
        }
      } catch { /* ignore */ }
    }
  } catch (error) {
    setIdeaRequestMessage(error?.message || "Could not send your request. Please try again.", { error: true });
  } finally {
    if (submitBtn) submitBtn.disabled = false;
  }
}

function openFeedbackModal(type = "General Feedback") {
  const modal = document.querySelector("#feedbackModal");
  if (!modal) return;
  const account = currentAccount() || {};
  const name = displayUserName(account) || [account.firstName, account.lastName].filter(Boolean).join(" ") || "";
  const email = currentUser || account.email || "";
  const typeInput = document.querySelector("#feedbackTypeInput");
  const nameInput = document.querySelector("#feedbackNameInput");
  const emailInput = document.querySelector("#feedbackEmailInput");
  const subjectInput = document.querySelector("#feedbackSubjectInput");
  const messageInput = document.querySelector("#feedbackMessageInput");
  const previousType = String(typeInput?.value || "").trim();
  const nextType = String(type || "General Feedback");
  const alreadyOpen = modal.classList.contains("open");
  // Preserve in-progress typing when reopening the same modal; only swap drafts
  // when the feedback type changes (bug vs feature vs general).
  if (alreadyOpen && previousType && previousType !== nextType) {
    writeFeedbackDraft(previousType);
  }
  if (typeInput) typeInput.value = nextType;
  if (nameInput && !nameInput.value) nameInput.value = name;
  if (emailInput && !emailInput.value) emailInput.value = email;
  const liveSubject = String(subjectInput?.value || "").trim();
  const liveMessage = String(messageInput?.value || "").trim();
  if (!(alreadyOpen && previousType === nextType && (liveSubject || liveMessage))) {
    const draft = readFeedbackDraft(nextType);
    if (subjectInput) subjectInput.value = draft?.subject || "";
    if (messageInput) messageInput.value = draft?.message || "";
  }
  setFormMessage("#feedbackMessage", "");
  document.body.classList.add("auth-modal-open");
  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
  if (!alreadyOpen) {
    (messageInput?.value ? messageInput : nameInput)?.focus();
  }
}

function closeFeedbackModal({ discardDraft = false } = {}) {
  const modal = document.querySelector("#feedbackModal");
  if (!modal) return;
  const type = document.querySelector("#feedbackTypeInput")?.value || "General Feedback";
  if (discardDraft) clearFeedbackDraft(type);
  else writeFeedbackDraft(type);
  modal.classList.remove("open");
  modal.setAttribute("aria-hidden", "true");
  if (!document.querySelector(".modal.open, .llh-confirm-dialog:not([hidden]), #scheduleEventModal.open")) {
    document.body.classList.remove("auth-modal-open");
  }
}

async function submitFeedbackForm(event) {
  event.preventDefault();
  const form = event.currentTarget;
  if (form?.dataset?.submitting === "1") return;
  const type = document.querySelector("#feedbackTypeInput")?.value || "General Feedback";
  const name = document.querySelector("#feedbackNameInput")?.value?.trim() || "Provider";
  const email = document.querySelector("#feedbackEmailInput")?.value?.trim() || currentUser || "";
  const subject = document.querySelector("#feedbackSubjectInput")?.value?.trim() || type;
  const message = document.querySelector("#feedbackMessageInput")?.value?.trim() || "";
  if (!email || !message) {
    setFormMessage("#feedbackMessage", "Email and message are required.");
    return;
  }
  form.dataset.submitting = "1";
  const submitBtn = form.querySelector('[type="submit"]');
  if (submitBtn) submitBtn.disabled = true;
  setFormMessage("#feedbackMessage", "Sending…", true);
  const account = currentAccount() || {};
  const payload = {
    type,
    name,
    email,
    subject,
    message,
    sourceUrl: window.location.href,
    page: window.location.hash || window.location.pathname || "app",
    accountType: account.accountType || getAccountType(account),
    role: account.role || getUserRole(account),
  };
  try {
    if (!canUseLaunchBackend()) throw new Error("We couldn’t send that just now. Check your connection and try again.");
    const response = await fetch("/api/feedback", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error || "Could not send feedback.");
    trackEvent("feedback_submitted", { type, subject });
    // Lesson-plan / activity improvement feedback also lands in the support ticket inbox.
    if (type === "Lesson Plan Feedback" || type === "Activity Feedback") {
      await fetch("/api/support-ticket", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          kind: type,
          name,
          email,
          topic: subject,
          message,
          sourceUrl: window.location.href,
          userAgent: navigator.userAgent,
        }),
      }).catch(() => null);
    }
    setFormMessage("#feedbackMessage", "Thank you — your feedback was sent to Leah and saved in Admin.", true);
    clearFeedbackDraft(type);
    form.reset();
    setTimeout(() => closeFeedbackModal({ discardDraft: true }), 1200);
    if (isAdminUnlocked()) {
      adminAnalyticsCache = null;
      loadAdminAnalyticsFromBackend();
    }
  } catch (error) {
    // Fallback: also create a support ticket so Admin still sees it.
    try {
      await fetch("/api/support-ticket", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          kind: type === "Bug" || type === "Problem" ? "Bug Report" : type === "Feature Request" || type === "Missing Feature" ? "Feature Request" : "Support Request",
          name,
          email,
          topic: subject,
          message,
          sourceUrl: window.location.href,
          userAgent: navigator.userAgent,
        }),
      });
      setFormMessage("#feedbackMessage", "Saved to support inbox. If urgent, also email little.learners.hub.customer@gmail.com.", true);
      setTimeout(closeFeedbackModal, 1400);
    } catch {
      setFormMessage("#feedbackMessage", error.message || "Could not send feedback. Please email support.");
    }
  } finally {
    if (form) {
      delete form.dataset.submitting;
      const btn = form.querySelector('[type="submit"]');
      if (btn) btn.disabled = false;
    }
  }
}

function formatAdminFeedbackSentiment(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  return raw.replace(/[-_]/g, " ").replace(/\b\w/g, (ch) => ch.toUpperCase());
}

function syncAdminFeedbackTypeFilterOptions(items = []) {
  const select = document.querySelector("#feedbackTypeFilter");
  if (!select) return;
  const selected = String(select.value || "");
  const types = [...new Set(items.map((item) => String(item.type || "").trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  select.innerHTML = [`<option value="">All Types</option>`]
    .concat(types.map((type) => `<option value="${escapeHtml(type)}">${escapeHtml(type)}</option>`))
    .join("");
  if (selected && types.includes(selected)) select.value = selected;
}

function renderAdminFeedbackCenter() {
  const target = document.querySelector("#adminFeedbackApp");
  if (!target || !isAdminUnlocked()) return;
  const statusFilter = document.querySelector("#feedbackStatusFilter")?.value || "All Statuses";
  const typeFilter = String(document.querySelector("#feedbackTypeFilter")?.value || "").trim();
  const search = String(document.querySelector("#feedbackSearchInput")?.value || "").trim().toLowerCase();
  const items = (adminAnalyticsCache?.feedback || []).slice();
  syncAdminFeedbackTypeFilterOptions(items);

  if (!adminAnalyticsCache && adminAnalyticsLoading) {
    target.innerHTML = `<div class="empty-state">Loading private feedback…</div>`;
    return;
  }

  const filtered = items.filter((item) => {
    if (statusFilter === "Resolved") {
      if (!["Resolved", "Completed"].includes(item.status)) return false;
    } else if (statusFilter !== "All Statuses" && item.status !== statusFilter) {
      return false;
    }
    if (typeFilter && String(item.type || "") !== typeFilter) return false;
    if (search) {
      const haystack = [
        item.subject,
        item.message,
        item.email,
        item.name,
        item.type,
        item.page,
        item.sourceUrl,
        item.lessonId,
        item.activityId,
        item.sentiment,
        item.stars,
      ].map((value) => String(value || "").toLowerCase()).join(" ");
      if (!haystack.includes(search)) return false;
    }
    return true;
  });

  const counts = {
    total: items.length,
    new: items.filter((i) => i.status === "New").length,
    progress: items.filter((i) => i.status === "In Progress" || i.status === "Reviewed" || i.status === "Planned").length,
    resolved: items.filter((i) => ["Resolved", "Completed"].includes(i.status)).length,
    archived: items.filter((i) => i.status === "Archived").length,
  };
  const typeCounts = items.reduce((acc, item) => {
    const key = String(item.type || "Feedback");
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  const topTypes = Object.entries(typeCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 4);
  const rated = items.filter((item) => {
    const stars = Number(item.stars);
    return Number.isFinite(stars) && stars >= 1 && stars <= 5;
  });
  const avgStars = rated.length
    ? (rated.reduce((sum, item) => sum + Number(item.stars), 0) / rated.length)
    : null;

  target.innerHTML = `
    <div class="aup-insight-grid admin-feedback-stats">
      <div class="aup-insight-card"><strong>${counts.total}</strong><span>Total</span></div>
      <div class="aup-insight-card"><strong>${counts.new}</strong><span>New</span></div>
      <div class="aup-insight-card aup-insight--trial"><strong>${counts.progress}</strong><span>In Progress</span></div>
      <div class="aup-insight-card aup-insight--pro"><strong>${counts.resolved}</strong><span>Resolved</span></div>
      <div class="aup-insight-card"><strong>${counts.archived}</strong><span>Archived</span></div>
      ${avgStars != null ? `<div class="aup-insight-card"><strong>${avgStars.toFixed(1)}</strong><span>Avg stars (${rated.length})</span></div>` : ""}
    </div>
    ${topTypes.length ? `
      <div class="admin-feedback-type-stats" aria-label="Feedback by type">
        ${topTypes.map(([type, count]) => `<span class="admin-feedback-type-chip"><strong>${escapeHtml(String(count))}</strong> ${escapeHtml(type)}</span>`).join("")}
      </div>
    ` : ""}
    <div class="ticket-list admin-feedback-list">
      ${filtered.length ? filtered.map((item) => {
        const stars = Number(item.stars);
        const hasStars = Number.isFinite(stars) && stars >= 1 && stars <= 5;
        const starLabel = hasStars ? `${"★".repeat(stars)}${"☆".repeat(5 - stars)} (${stars}/5)` : "";
        const sentimentLabel = formatAdminFeedbackSentiment(item.sentiment);
        const focused = adminFeedbackFocusId && item.id === adminFeedbackFocusId;
        return `
        <article class="ticket-card${focused ? " is-highlighted" : ""}" data-feedback-id="${escapeHtml(item.id)}" id="admin-feedback-${escapeHtml(item.id)}">
          <div class="ticket-card-header">
            <div>
              <p class="eyebrow">${escapeHtml(item.type || "Feedback")} · ${escapeHtml(item.status || "New")}${sentimentLabel ? ` · ${escapeHtml(sentimentLabel)}` : ""}${hasStars ? ` · ${escapeHtml(String(stars))}/5 stars` : ""}</p>
              <h3>${escapeHtml(item.subject || item.type || "Feedback")}</h3>
              <p>${escapeHtml(item.name || "Provider")} · ${escapeHtml(item.email || "No email")}</p>
              <small>${escapeHtml(item.createdAt ? new Date(item.createdAt).toLocaleString() : "")}${item.page || item.sourceUrl ? ` · ${escapeHtml(item.page || item.sourceUrl)}` : ""}${item.activityId ? ` · activity:${escapeHtml(item.activityId)}` : ""}${item.lessonId ? ` · lesson:${escapeHtml(item.lessonId)}` : ""}</small>
              ${hasStars ? `<p class="admin-feedback-stars" aria-label="${escapeHtml(String(stars))} of 5 stars">${escapeHtml(starLabel)}</p>` : ""}
            </div>
          </div>
          <p>${escapeHtml(item.message || "")}</p>
          ${(item.adminNotes || []).length ? `<div class="muted-copy">${(item.adminNotes || []).map((n) => `<p><strong>Note:</strong> ${escapeHtml(n.note || n)}</p>`).join("")}</div>` : ""}
          <div class="account-actions-row">
            <button class="ghost-button" type="button" data-feedback-status="In Progress" data-feedback-id="${escapeHtml(item.id)}">In Progress</button>
            <button class="primary-button" type="button" data-feedback-status="Resolved" data-feedback-id="${escapeHtml(item.id)}">Mark Resolved</button>
            <button class="ghost-button" type="button" data-feedback-status="Archived" data-feedback-id="${escapeHtml(item.id)}">Archive</button>
            <button class="ghost-button" type="button" data-feedback-note="${escapeHtml(item.id)}">Add Note</button>
          </div>
        </article>
      `;
      }).join("") : `<div class="empty-state">${items.length ? "No feedback matches these filters." : "No private feedback yet."}</div>`}
    </div>
  `;
}

async function updateAdminFeedbackItem(id, updates = {}) {
  const token = adminSession()?.token;
  if (!token || !canUseLaunchBackend()) return { ok: false, error: "Admin token required." };
  const response = await fetch("/api/admin/feedback-update", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({ id, ...updates }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) return { ok: false, error: data?.error || "Update failed." };
  adminAnalyticsCache = null;
  await loadAdminAnalyticsFromBackend();
  renderAdminFeedbackCenter();
  return { ok: true, feedback: data.feedback };
}

let adminEmailEngagementCache = null;

async function loadAdminEmailEngagement(force = false) {
  const token = adminSession()?.token;
  if (!token || !canUseLaunchBackend()) return null;
  if (adminEmailEngagementCache && !force) return adminEmailEngagementCache;
  const response = await fetch(`/api/admin/email-engagement`, { headers: { Authorization: `Bearer ${token}` } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data?.error || "Could not load email engagement.");
  adminEmailEngagementCache = data;
  return data;
}

