async function adminEmailEngagementPost(path, body = {}) {
  const token = adminSession()?.token;
  if (!token) throw new Error("Admin login required.");
  const response = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({ ...body }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data?.error || "Request failed.");
  return data;
}

async function renderContactPage() {
  const target = document.querySelector("#userTicketList");
  if (!target) return;
  await loadSupportTicketsFromBackend();
  const currentEmail = currentUser || "";
  const tickets = supportTickets()
    .filter((ticket) => !currentEmail || ticket.email === currentEmail || ticket.createdBy === currentEmail)
    .slice(0, 8);
  target.innerHTML = tickets.length ? tickets.map(ticketCard).join("") : `<div class="empty-state">No support tickets submitted yet.</div>`;
}

function ticketReplyEmailStatusHtml(ticket) {
  const info = ticket?.replyEmail;
  if (!info) {
    return `<p class="form-note ticket-reply-email-status" data-ticket-email-status="${escapeHtml(ticket.id)}">No reply email sent yet. Use <strong>Send Reply Email</strong> to email this person and track delivery here.</p>`;
  }
  const when = info.sentAt ? new Date(info.sentAt).toLocaleString() : "";
  if (info.sent) {
    const event = info.lastEvent && info.lastEvent !== "accepted"
      ? ` · Resend status: <strong>${escapeHtml(info.lastEvent)}</strong>`
      : " · Accepted by email provider";
    return `<p class="form-note ticket-reply-email-status is-sent" data-ticket-email-status="${escapeHtml(ticket.id)}">Email sent to <strong>${escapeHtml(info.to || ticket.email || "")}</strong>${when ? ` at ${escapeHtml(when)}` : ""}${event}${info.messageId ? ` · ID ${escapeHtml(info.messageId)}` : ""}. Use <strong>Check Delivery</strong> to refresh Delivered/Bounced.</p>`;
  }
  return `<p class="form-note ticket-reply-email-status is-failed" data-ticket-email-status="${escapeHtml(ticket.id)}">Reply email did <strong>not</strong> send${info.to ? ` to ${escapeHtml(info.to)}` : ""}${when ? ` (${escapeHtml(when)})` : ""}. ${escapeHtml(info.error || "Unknown email error.")}</p>`;
}

function ticketCard(ticket, admin = false) {
  return `
    <article class="ticket-card" data-ticket-card="${escapeHtml(ticket.id)}">
      <div class="ticket-card-header">
        <div>
          <p class="eyebrow">${escapeHtml(ticket.kind)}</p>
          <h3>${escapeHtml(ticket.topic)}</h3>
          <p>${escapeHtml(ticket.name)} · ${escapeHtml(ticket.email || "No email")}</p>
        </div>
        <span class="ticket-status ${ticketStatusClass(ticket.status)}">${escapeHtml(ticket.status)}</span>
      </div>
      <p>${escapeHtml(ticket.message)}</p>
      ${ticket.reply ? `<div class="ticket-reply"><strong>Admin Reply</strong><p>${escapeHtml(ticket.reply)}</p></div>` : ""}
      ${admin ? ticketReplyEmailStatusHtml(ticket) : ""}
      <small>Submitted ${new Date(ticket.createdAt).toLocaleString()}</small>
      ${admin ? adminTicketActions(ticket) : ""}
    </article>
  `;
}

function adminTicketActions(ticket) {
  const hasPriorSend = Boolean(ticket.replyEmail?.sentAt);
  return `
    <div class="ticket-admin-actions">
      <label>Status
        <select data-ticket-status="${ticket.id}">
          ${["New", "In Progress", "Complete"].map((status) => `<option ${ticket.status === status ? "selected" : ""}>${status}</option>`).join("")}
        </select>
      </label>
      <label>Reply email to customer
        <textarea data-ticket-reply="${ticket.id}" rows="4" placeholder="Write what you want them to receive by email">${escapeHtml(ticket.reply || "")}</textarea>
      </label>
      <div class="table-actions">
        <button class="primary-button" data-save-ticket-reply="${ticket.id}" type="button">${hasPriorSend ? "Resend Reply Email" : "Send Reply Email"}</button>
        <button class="ghost-button" data-refresh-ticket-reply-email="${ticket.id}" type="button" ${ticket.replyEmail?.messageId ? "" : "disabled"}>Check Delivery</button>
        <button class="ghost-button" data-complete-ticket="${ticket.id}" type="button">Mark Complete</button>
      </div>
    </div>
  `;
}

function setAdminTicketMessage(message, ok = true) {
  const el = document.querySelector("#adminTicketMessage");
  if (!el) return;
  el.textContent = message || "";
  el.classList.toggle("ok", Boolean(ok && message));
  el.classList.toggle("error", Boolean(!ok && message));
  el.hidden = !message;
}

async function renderAdminTickets() {
  const target = document.querySelector("#adminTicketList");
  if (!target) return;
  await loadSupportTicketsFromBackend({ admin: isAdminUnlocked() });
  const filter = document.querySelector("#ticketStatusFilter")?.value || "All Statuses";
  const tickets = supportTickets().filter((ticket) => filter === "All Statuses" || ticket.status === filter);
  target.innerHTML = tickets.length ? tickets.map((ticket) => ticketCard(ticket, true)).join("") : `<div class="empty-state">No support tickets match this status.</div>`;
}

async function updateTicket(id, updates = {}) {
  const statusSelect = document.querySelector(`[data-ticket-status="${id}"]`);
  const payload = {
    ...updates,
    status: updates.status || statusSelect?.value || undefined,
  };
  if (canUseLaunchBackend() && isAdminUnlocked() && adminSession()?.token) {
    try {
      const response = await fetch("/api/support-ticket-update", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${adminSession().token}` },
        body: JSON.stringify({ id, ...payload }),
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result?.error || "Could not update support ticket.");
      if (result.ticket) {
        mergeSupportTickets([result.ticket]);
      }
      const emailInfo = result.ticket?.replyEmail || result.emailResult || null;
      if (payload.refreshReplyEmail) {
        const event = emailInfo?.lastEvent || emailInfo?.status || "unknown";
        setAdminTicketMessage(
          emailInfo?.messageId
            ? `Delivery refresh for ${emailInfo.to || "customer"}: ${event}.`
            : "No Resend message ID to check yet. Send the reply email first.",
          Boolean(emailInfo?.messageId),
        );
      } else if (payload.reply !== undefined || payload.forceResend) {
        if (emailInfo?.sent) {
          setAdminTicketMessage(
            `Reply email sent to ${emailInfo.to || "customer"}. Status: ${emailInfo.lastEvent || emailInfo.status || "accepted"}. You can press Check Delivery in a minute to confirm Delivered.`,
            true,
          );
        } else if (emailInfo) {
          setAdminTicketMessage(
            `Reply saved, but email did not send${emailInfo.to ? ` to ${emailInfo.to}` : ""}. ${emailInfo.error || "Check Email diagnostics / Resend."}`,
            false,
          );
        } else {
          setAdminTicketMessage("Ticket updated.", true);
        }
      } else {
        setAdminTicketMessage("Ticket updated.", true);
      }
      renderContactPage();
      renderAdminTickets();
      return result;
    } catch (error) {
      console.warn("Support ticket backend update failed", error);
      setAdminTicketMessage(error.message || "Could not update support ticket.", false);
      throw error;
    }
  }
  const updated = supportTickets().map((ticket) => ticket.id === id ? { ...ticket, ...payload, updatedAt: new Date().toISOString() } : ticket);
  saveSupportTickets(updated);
  setAdminTicketMessage("Ticket updated locally (server email send unavailable in this session).", false);
  renderContactPage();
  renderAdminTickets();
  return { ticket: updated.find((ticket) => ticket.id === id) || null };
}

function isAdminUnlocked() {
  // Unlock flag alone is not enough — a corrupt/missing token left the UI
  // "unlocked" while every /api/admin call returned 401 (felt like random logout).
  const session = adminSession();
  return localStorage.getItem("llhAdminUnlocked") === "true" && Boolean(session?.token);
}

function adminPreviewMode() {
  if (!isAdminUnlocked()) return "";
  return localStorage.getItem("llhAdminPreviewMode") || "Admin";
}

function hasAdminFullAccess() {
  // Admin unlock on a shared browser must not elevate a different Free member's
  // plan/features. Full admin access applies when browsing as admin (no member
  // session) or when the signed-in user is the platform owner.
  if (!(isAdminUnlocked() && adminPreviewMode() === "Admin")) return false;
  try {
    if (!currentUser) return true;
    return isSignedInPlatformOwner();
  } catch (_error) {
    // app.js still initializing currentUser — treat as admin-only browse.
    return true;
  }
}

function adminAccessOverridesMemberPlan() {
  return hasAdminFullAccess();
}

function effectiveAccessPlan() {
  const preview = adminPreviewMode();
  if (preview === "Free") return "Free";
  if (preview === "Trial" || preview === "Pro") return "Pro";
  if (
    preview === "Founding"
    || preview === "Director"
    || preview === "Teacher"
    || preview === "Owner"
    || preview === "Assistant"
    || preview === "Parent"
  ) return "Founding";
  if (adminAccessOverridesMemberPlan()) return "Founding";
  // Platform owner aliases (e.g. leahivie@icloud.com) always get full Pro/Founding
  // app access so every lesson plan is viewable — even when the membership row is
  // still marked Free for billing/upgrade testing. Admin Free preview above still
  // lets Leah simulate a Free member when needed.
  if (isSignedInPlatformOwner()) return "Founding";
  if (currentUser) {
    const account = currentAccount();
    if (account?.programAccessViaOwner) {
      return normalizeBillingPlan(account?.plan || "Pro", account) === "Free" ? "Pro" : normalizeBillingPlan(account?.plan || "Pro", account);
    }
    const resolved = accountHasPaidBilling(account) ? normalizeBillingPlan(account?.plan || currentPlan, account) : "Free";
    // Testing Pro unlocks premium features on the testing site without changing role permissions.
    if (resolved === "Free" && hasTestingProEntitlement()) {
      console.debug(`[access] effectiveAccessPlan email=${currentUser} Testing Pro entitlement`);
      return "Pro";
    }
    console.debug(`[access] effectiveAccessPlan email=${currentUser} plan=${account?.plan || "none"} status="${account?.subscriptionStatus || "none"}" resolved=${resolved}`);
    return resolved;
  }
  return "Free";
}

/** Plan label shown in UI while Admin preview is active. */
function previewAwarePlanLabel() {
  const preview = adminPreviewMode();
  if (preview === "Free") return "Free";
  if (preview === "Trial") return "Trial";
  if (preview === "Pro") return "Pro";
  if (preview === "Founding") return "Founding Member";
  if (preview === "Owner") return "Owner (View As)";
  if (preview === "Director") return "Director (View As)";
  if (preview === "Teacher") return "Teacher (View As)";
  if (preview === "Assistant") return "Assistant (View As)";
  if (preview === "Parent") return "Parent (View As)";
  if (preview === "Admin") return "Admin";
  return billingPlanLabel();
}

const ADMIN_VIEW_AS_ROLES = Object.freeze(["Owner", "Director", "Teacher", "Assistant", "Parent"]);
const ADMIN_PREVIEW_MODES = Object.freeze([
  "Admin", "Free", "Trial", "Pro", "Founding", ...ADMIN_VIEW_AS_ROLES,
]);

/** Map Admin View As mode → platform user role (never changes billing entitlements alone). */
function adminPreviewUserRole() {
  if (!isAdminUnlocked()) return "";
  const preview = adminPreviewMode();
  if (preview === "Owner") return USER_ROLES.OWNER;
  if (preview === "Director") return USER_ROLES.DIRECTOR;
  if (preview === "Teacher") return USER_ROLES.TEACHER;
  if (preview === "Assistant") return USER_ROLES.ASSISTANT;
  return "";
}

function previewAwarePriceLabel() {
  const preview = adminPreviewMode();
  if (preview === "Free") return "$0/month";
  if (preview === "Pro") return "$19.99/month";
  if (preview === "Founding") return "$9.99/month";
  if (preview === "Admin") return "Full access";
  return billingPriceLabel();
}

function isAdminPreviewSimulating() {
  const preview = adminPreviewMode();
  return Boolean(preview && preview !== "Admin");
}

function setAdminPreviewMode(mode) {
  if (!isAdminUnlocked()) return false;
  let allowedModes = ["Admin", "Free", "Trial", "Pro", "Founding", "Owner", "Director", "Teacher", "Assistant", "Parent"];
  try {
    if (Array.isArray(ADMIN_PREVIEW_MODES)) allowedModes = ADMIN_PREVIEW_MODES;
  } catch (_error) { /* const still initializing */ }
  const next = allowedModes.includes(mode) ? mode : "Admin";
  localStorage.setItem("llhAdminPreviewMode", next);
  // Keep HDH persona in sync for Parent View As; restore teacher persona otherwise.
  try {
    if (isHomeDaycareHubTestingEnabled() && typeof setHdhTesterPersona === "function") {
      if (next === "Parent") {
        setHdhTesterPersona({ role: "parent" });
      } else if (getHdhTesterPersona().role === "parent" && next !== "Parent") {
        setHdhTesterPersona({ role: "teacher" });
      }
    }
  } catch (_error) { /* boot / persona race */ }
  applyAdminPreviewToPlatform();
  if (next === "Parent" && isHomeDaycareHubTestingEnabled() && typeof switchHdhTesterRole === "function") {
    switchHdhTesterRole("parent").catch((error) => {
      showActionFeedback(error?.message || "Could not open Parent View As.");
    });
  }
  return true;
}

function applyAdminPreviewToPlatform() {
  updateAuthButtons();
  updatePlanLabel();
  syncPlatformNavVisibility();
  updateAdminNavVisibility();
  refreshAdminPreviewBadge();
  document.body.classList.toggle("admin-preview-simulating", isAdminPreviewSimulating());
  document.body.dataset.adminPreview = adminPreviewMode() || "";

  // Close open viewers so lock/unlock chrome rebuilds for the simulated plan.
  if (typeof dismissResourceViewerForNavigation === "function") {
    dismissResourceViewerForNavigation();
  }

  const activeView = document.querySelector(".active-view")?.id.replace("view-", "") || "";
  if (activeView === "home") {
    renderHome();
  } else if (activeView === "admin") {
    renderAdminDashboard();
  } else if (activeView === "generators") {
    const tool = document.querySelector("#generatorWorkspace")?.dataset.activeTool || "lesson";
    renderGeneratorWorkspace(tool);
  } else if (activeView === "ai") {
    renderAiPage();
  } else if (activeView === "children" || childToolTabFromView(activeView)) {
    renderChildManagement();
  } else if (activeView === "calendar") {
    renderMainCalendar();
  } else if (activeView === "planner") {
    renderWeeklyPlanner();
  } else if (activeView === "account") {
    renderAccountPage();
  } else if (activeView === "favorites") {
    renderFavoritesPage();
  } else if (activeView === "billing" || activeView === "subscription" || activeView === "membership") {
    renderBillingPage();
  } else if (activeView === "plans") {
    renderPricingPage();
  } else if (activeView === "settings") {
    renderSettingsHubPage();
  } else if (activeView === "staff") {
    renderStaffManagementPage();
  } else if (activeView === "classrooms") {
    renderClassroomsPage();
  } else if (activeView === "families") {
    if (isWorkModeNavEnabled()) renderFamiliesHubPage();
    else renderFamiliesPage();
  } else if (activeView === "enrollment") {
    renderEnrollmentPage();
  } else if (activeView === "today") {
    renderTeacherTodayPage();
  } else if (activeView === "classroom") {
    renderClassroomHubPage();
  } else if (activeView === "business") {
    renderBusinessHubPage();
  } else if (activeView === "more") {
    renderMoreHubPage();
  } else if (activeView === "support-center") {
    renderSupportCenterPage();
  } else if (activeView === "resources") {
    renderResourcesHubPage();
  } else if (activeView === "reports") {
    renderReportsPage();
  } else if (activeView === "tools") {
    renderFutureTools();
  } else if (viewMap[activeView]) {
    renderCategoryPage(activeView);
  }

  // After View As, jump to that role's natural home (Owner≠Teacher≠Parent).
  if (isWorkModeNavEnabled() && isAdminPreviewSimulating()) {
    const role = workModeRole();
    const landing = workModeLandingView(role);
    if (activeView === "admin" || activeView === "home" || activeView === "today" || activeView === "calendar") {
      if (adminPreviewMode() !== "Parent") {
        setView(landing, { allowDashboard: true, skipAccessRedirect: true, fromAdminPreview: true });
      }
    }
  }

  showActionFeedback(`Preview mode: ${previewAwarePlanLabel()}`);
  document.dispatchEvent(new CustomEvent("llh:admin-preview-changed", {
    detail: { mode: adminPreviewMode(), plan: effectiveAccessPlan() },
  }));
}

function refreshAdminPreviewBadge() {
  let badge = document.querySelector("[data-admin-preview-badge]");
  if (!isAdminUnlocked()) {
    badge?.remove();
    document.body.classList.remove("admin-preview-simulating");
    delete document.body.dataset.adminPreview;
    return;
  }
  const mode = adminPreviewMode() || "Admin";
  if (!badge) {
    document.body.insertAdjacentHTML("beforeend", `
      <div class="admin-preview-badge" data-admin-preview-badge role="status" aria-live="polite">
        <span data-admin-preview-badge-label></span>
        <button type="button" class="ghost-button" data-admin-preview="Admin" data-admin-return-admin>Return to Admin</button>
      </div>
    `);
    badge = document.querySelector("[data-admin-preview-badge]");
  }
  const label = badge.querySelector("[data-admin-preview-badge-label]");
  const returnBtn = badge.querySelector("[data-admin-return-admin]");
  if (label) {
    label.textContent = mode === "Admin"
      ? "Admin mode"
      : `Previewing as ${mode}`;
  }
  if (returnBtn) returnBtn.hidden = mode === "Admin" && !isAdminImpersonating();
  badge.classList.toggle("is-simulating", mode !== "Admin" || isAdminImpersonating());
  badge.hidden = false;
  if (isAdminImpersonating()) {
    if (label) {
      label.textContent = `Viewing as ${adminImpersonationState.account?.name || adminImpersonationState.email} (read-only)`;
    }
    if (returnBtn) {
      returnBtn.hidden = false;
      returnBtn.textContent = "Exit user view";
      returnBtn.setAttribute("data-admin-exit-impersonation", "1");
    }
  } else if (returnBtn) {
    returnBtn.textContent = "Return to Admin";
    returnBtn.removeAttribute("data-admin-exit-impersonation");
  }
}

function isAdminImpersonating() {
  return Boolean(isAdminUnlocked() && adminImpersonationState?.email);
}

function stopAdminImpersonation({ refresh = true } = {}) {
  adminImpersonationState = null;
  document.body.classList.remove("admin-impersonating");
  delete document.body.dataset.adminImpersonation;
  setAdminPreviewMode("Admin");
  if (refresh) {
    refreshAdminPreviewBadge();
    showActionFeedback("Exited user view.");
  }
}

async function fetchAdminUserDetail(email) {
  const token = adminSession()?.token || "";
  const clean = String(email || "").trim().toLowerCase();
  if (!token || !clean || !canUseLaunchBackend()) return null;
  if (adminUserDetailCache[clean]?.fetchedAt && Date.now() - adminUserDetailCache[clean].fetchedAt < 15000) {
    return adminUserDetailCache[clean].data;
  }
  const res = await fetch(`/api/admin/user-detail?email=${encodeURIComponent(clean)}`, { cache: "no-store", headers: { Authorization: `Bearer ${token}` } });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data?.error || "Could not load user detail.");
  adminUserDetailCache[clean] = { fetchedAt: Date.now(), data };
  return data;
}

async function startAdminImpersonation(email) {
  if (!isAdminUnlocked()) return;
  try {
    const detail = await fetchAdminUserDetail(email);
    if (!detail?.user) throw new Error("User detail unavailable.");
    const planPreview = detail.impersonation?.planPreview || "Free";
    adminImpersonationState = {
      email: detail.user.email,
      account: detail.user,
      activity: detail.activity || {},
      planPreview,
      startedAt: new Date().toISOString(),
      readOnly: true,
    };
    document.body.classList.add("admin-impersonating");
    document.body.dataset.adminImpersonation = detail.user.email;
    setAdminPreviewMode(["Free", "Trial", "Pro", "Founding"].includes(planPreview) ? planPreview : "Free");
    refreshAdminPreviewBadge();
    showActionFeedback(`Viewing as ${detail.user.name || detail.user.email} (read-only sandbox).`);
    setView("home");
  } catch (error) {
    showActionFeedback(error?.message || "Could not start user view.");
  }
}

