function eventCount(name) {
  return analyticsEvents().filter((event) => event.name === name).length;
}

function dateKey(value) {
  const date = new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) return "Unknown";
  return date.toISOString().slice(0, 10);
}

function monthKey(value) {
  const key = dateKey(value);
  return key === "Unknown" ? key : key.slice(0, 7);
}

function weekKey(value) {
  const date = new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) return "Unknown";
  const first = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const dayNumber = Math.floor((date - first) / 86400000) + 1;
  const week = Math.ceil((dayNumber + first.getUTCDay()) / 7);
  return `${date.getUTCFullYear()}-W${String(week).padStart(2, "0")}`;
}

function groupCounts(items, getter) {
  return items.reduce((counts, item) => {
    const key = getter(item) || "Unknown";
    counts[key] = (counts[key] || 0) + 1;
    return counts;
  }, {});
}

function countListHtml(counts, emptyText = "No data yet.") {
  const entries = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  if (!entries.length) return `<div class="empty-state">${emptyText}</div>`;
  return entries.map(([label, count]) => `
    <div class="analytics-row">
      <span>${escapeHtml(label)}</span>
      <strong>${count}</strong>
    </div>
  `).join("");
}

function topEntries(counts, limit = 8) {
  return Object.entries(counts || {}).sort((a, b) => b[1] - a[1]).slice(0, limit);
}

function percentage(part, whole) {
  return whole ? `${Math.round((part / whole) * 100)}%` : "0%";
}

function moneyValue(value) {
  const amount = Number(String(value || "").replace(/[^0-9.]/g, ""));
  return Number.isFinite(amount) ? amount : 0;
}

function groupMoney(events, keyGetter) {
  return events.reduce((totals, event) => {
    const key = keyGetter(event);
    totals[key] = (totals[key] || 0) + moneyValue(event.detail?.monthlyPrice || event.detail?.amount || event.amount);
    return totals;
  }, {});
}

function lineChartHtml(points = [], emptyText = "No trend data yet.") {
  const entries = Array.isArray(points) ? points : Object.entries(points).map(([label, value]) => ({ label, value }));
  const trimmed = entries.slice(-14);
  if (!trimmed.length) return `<div class="empty-state">${emptyText}</div>`;
  const max = Math.max(...trimmed.map((point) => Number(point.value || 0)), 1);
  return `
    <div class="analytics-chart">
      ${trimmed.map((point) => {
        const height = Math.max(8, Math.round((Number(point.value || 0) / max) * 100));
        return `
          <div class="analytics-bar" title="${escapeHtml(point.label)}: ${escapeHtml(point.value)}">
            <span style="height:${height}%"></span>
            <small>${escapeHtml(String(point.label).replace(/^2026-/, ""))}</small>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function mapCountsToPoints(counts = {}) {
  return Object.entries(counts)
    .sort(([a], [b]) => String(a).localeCompare(String(b)))
    .map(([label, value]) => ({ label, value }));
}

/** Count people who try Pro checkout vs who leave without buying. */
function summarizeProUpgradeFunnel(events = []) {
  const actorId = (event) => event.user || event.visitorId || event.sessionId || "";
  const isProCheckoutStart = (event) => {
    if (event.name !== "checkout_start") return false;
    const type = String(event.detail?.type || "").toLowerCase();
    return type === "monthly" || type === "annual" || Boolean(event.detail?.trial7day);
  };
  const isProCheckoutSuccess = (event) => {
    if (event.name !== "checkout_success") return false;
    const plan = String(event.detail?.plan || "").toLowerCase();
    return !plan || plan.includes("pro") || plan === "monthly" || plan === "annual";
  };
  const intentEvents = events.filter((event) => event.name === "pro_upgrade_intent");
  const startEvents = events.filter(isProCheckoutStart);
  const successEvents = events.filter(isProCheckoutSuccess);
  const abandonEvents = events.filter((event) => event.name === "pro_checkout_abandoned");
  const dismissEvents = events.filter((event) => event.name === "pro_upgrade_dismissed");
  const tried = new Set();
  const succeeded = new Set();
  for (const event of [...intentEvents, ...startEvents, ...abandonEvents]) {
    const id = actorId(event);
    if (id) tried.add(id);
  }
  for (const event of successEvents) {
    const id = actorId(event);
    if (id) succeeded.add(id);
  }
  let triedNoBuy = 0;
  tried.forEach((id) => {
    if (!succeeded.has(id)) triedNoBuy += 1;
  });
  return {
    proUpgradeIntents: intentEvents.length,
    proCheckoutsStarted: startEvents.length,
    proCheckoutsCompleted: successEvents.length,
    proCheckoutsAbandoned: abandonEvents.length,
    proUpgradeDismissals: dismissEvents.length,
    proTriedNoBuy: triedNoBuy,
  };
}

function localAnalyticsSummary() {
  const events = analyticsEvents();
  const accountRows = allAccountsList();
  const leadRows = leads();
  const pageViews = events.filter((event) => event.name === "page_view");
  const sessionVisits = events.filter((event) => event.name === "website_visit");
  const trafficEvents = events.filter((event) => event.name === "website_visit" || event.name === "page_view");
  const signups = events.filter((event) => event.name === "account_signup_complete");
  const paidEvents = events.filter((event) => event.name === "checkout_success");
  const paidUsers = accountRows.filter((account) => adminMembershipHasProAccess(account));
  const visitorIds = new Set(trafficEvents.map((event) => event.visitorId || event.user || event.sessionId).filter(Boolean));
  const visitorDays = {};
  trafficEvents.forEach((event) => {
    const id = event.visitorId || event.user || event.sessionId || "unknown";
    visitorDays[id] = visitorDays[id] || new Set();
    visitorDays[id].add(dateKey(event.createdAt));
  });
  const returningVisitors = Object.values(visitorDays).filter((days) => days.size > 1).length;
  const revenueEvents = paidEvents;
  const featureEvents = events.filter((event) => ["button_click", "ai_generation_success", "resource_view", "resource_print", "generated_pdf", "generated_print", "provider_tool_pdf", "checkout_start", "checkout_success", "pro_upgrade_intent", "pro_checkout_abandoned", "pro_upgrade_dismissed", "schedule_assign_lesson", "lesson_plan_added_to_calendar", "observation_created", "parent_message_generated"].includes(event.name));
  const activeMonth = accountRows.filter((account) => adminIsWithinDays(account.lastSeenAt || account.lastLoginAt, 30)).length;
  const proFunnel = summarizeProUpgradeFunnel(events);
  return {
    mode: "Local browser history",
    updatedAt: new Date().toISOString(),
    totals: {
      visitors: sessionVisits.length,
      sessionVisits: sessionVisits.length,
      pageViewCount: pageViews.length,
      uniqueVisitors: visitorIds.size,
      signups: signups.length,
      totalRegisteredUsers: accountRows.length,
      freeUsers: accountRows.filter((account) => adminCurrentAccessKey(account) === "free").length,
      trialUsers: accountRows.filter((account) => adminCurrentAccessKey(account) === "trial").length,
      proUsers: accountRows.filter((account) => adminCurrentAccessKey(account) === "pro").length,
      foundingMembers: accountRows.filter((account) => adminCurrentAccessKey(account) === "founding").length,
      paidUsers: paidUsers.length,
      activeSubscriptions: accountRows.filter((account) => adminBillingStatusKey(account) === "active").length,
      activeUsersMonth: activeMonth,
      cancelingSubscriptions: accountRows.filter((account) => adminBillingStatusKey(account) === "canceling").length,
      canceledSubscriptions: accountRows.filter((account) => ["canceled", "ended"].includes(adminBillingStatusKey(account))).length,
      pastDueUsers: accountRows.filter((account) => adminCurrentAccessKey(account) === "past_due").length,
      failedPayments: accountRows.filter((account) => adminBillingStatusKey(account) === "payment_failed").length,
      returningVisitors,
      visitorToSignupRate: percentage(accountRows.length, Math.max(visitorIds.size, 1)),
      signupToPaidRate: percentage(paidUsers.length, Math.max(accountRows.length, 1)),
      visitorToPaidRate: percentage(paidUsers.length, Math.max(visitorIds.size, 1)),
      totalRevenue: revenueEvents.reduce((total, event) => total + moneyValue(event.detail?.monthlyPrice || event.detail?.amount), 0),
      ...proFunnel,
    },
    periods: {
      dailyVisitors: groupCounts(sessionVisits, (event) => dateKey(event.createdAt)),
      weeklyVisitors: groupCounts(sessionVisits, (event) => weekKey(event.createdAt)),
      monthlyVisitors: groupCounts(sessionVisits, (event) => monthKey(event.createdAt)),
      dailyRevenue: groupMoney(revenueEvents, (event) => dateKey(event.createdAt)),
      weeklyRevenue: groupMoney(revenueEvents, (event) => weekKey(event.createdAt)),
      monthlyRevenue: groupMoney(revenueEvents, (event) => monthKey(event.createdAt)),
      yearlyRevenue: groupMoney(revenueEvents, (event) => String(new Date(event.createdAt).getFullYear())),
    },
    counts: {
      pageViews: groupCounts(pageViews, (event) => event.detail?.view || event.path || event.hash || "Home"),
      sources: groupCounts(sessionVisits.length ? sessionVisits : trafficEvents, (event) => event.source || event.attribution?.source || "Direct"),
      buttonClicks: groupCounts(events.filter((event) => event.name === "button_click"), (event) => event.detail?.label || event.detail?.action || "Button"),
      aiUsage: groupCounts(events.filter((event) => event.name === "ai_generation_success"), (event) => event.detail?.tool || "Document Helper"),
      resourceViews: groupCounts(events.filter((event) => event.name === "resource_view"), (event) => event.detail?.category || "Resource"),
      resourcePrints: groupCounts(events.filter((event) => ["resource_print", "generated_pdf", "generated_print", "provider_tool_pdf"].includes(event.name)), (event) => event.detail?.category || event.detail?.tool || "Printable/PDF"),
      featureUsage: groupCounts(featureEvents, (event) => event.name),
    },
    users: accountRows.map((account) => {
      const userEvents = events.filter((event) => event.user === account.email);
      const lastEvent = userEvents.slice().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))[0];
      return {
        email: account.email,
        plan: account.plan || "Free",
        subscriptionStatus: account.subscriptionStatus || "Free Plan",
        signupAt: account.createdAt || "",
        lastLoginAt: account.lastLoginAt || "",
        lastSeenAt: account.lastSeenAt || lastEvent?.createdAt || account.lastLoginAt || "",
        featureUseCount: userEvents.length,
        topFeatures: topEntries(groupCounts(userEvents, (event) => event.name), 3),
      };
    }),
    recentEvents: events.slice(0, 12),
    leads: leadRows,
  };
}

async function loadAdminAnalyticsFromBackend(options = {}) {
  const token = adminSession()?.token;
  if (!analyticsConfig.adminEndpoint || !canUseLaunchBackend() || !token) {
    adminAnalyticsLoading = false;
    if (!token) {
      adminAnalyticsLastError = "Admin session token missing. Unlock Admin again.";
    } else if (!canUseLaunchBackend()) {
      adminAnalyticsLastError = "Live analytics require the production backend.";
    }
    if (options.renderLoading !== false) {
      renderAdminOwnerOverview();
      renderAdminAnalytics();
    }
    return null;
  }

  if (LOCAL_ADMIN_TOKENS.has(String(token))) {
    adminAnalyticsLoading = false;
    adminAnalyticsLastError = "Local preview tokens cannot load live production analytics. Use the production Admin unlock.";
    if (options.renderLoading !== false) {
      renderAdminOwnerOverview();
      renderAdminAnalytics();
    }
    return null;
  }

  if (adminAnalyticsLoadPromise && !options.force) {
    return adminAnalyticsLoadPromise;
  }

  if (!options.force && adminAnalyticsCacheFresh()) {
    if (options.renderLoading !== false) {
      renderAdminOwnerOverview();
      renderAdminAnalytics();
    }
    return adminAnalyticsCache;
  }

  // Force refresh: abort any hung in-flight request instead of waiting forever.
  if (options.force && adminAnalyticsAbortController) {
    try { adminAnalyticsAbortController.abort(); } catch { /* ignore */ }
    adminAnalyticsAbortController = null;
    adminAnalyticsLoadPromise = null;
  }

  adminAnalyticsLoading = true;
  adminAnalyticsLastError = "";
  if (options.renderLoading !== false) {
    renderAdminOwnerOverview();
    renderAdminAnalytics();
  }

  const controller = new AbortController();
  adminAnalyticsAbortController = controller;
  const timeoutId = setTimeout(() => {
    try { controller.abort(); } catch { /* ignore */ }
  }, ADMIN_ANALYTICS_TIMEOUT_MS);

  adminAnalyticsLoadPromise = (async () => {
    const session = adminSession() || {};
    const requestUrl = `${analyticsConfig.adminEndpoint}?t=${Date.now()}`;
    console.info("[admin-analytics:client] request", {
      url: analyticsConfig.adminEndpoint,
      email: session.email || "",
      mode: session.mode || "",
      unlocked: isAdminUnlocked(),
      tokenPrefix: token ? `${String(token).slice(0, 12)}…` : "",
    });
    try {
      const response = await fetch(requestUrl, { cache: "no-store", signal: controller.signal, headers: { Authorization: `Bearer ${token}` } });
      const rawText = await response.text();
      let data = {};
      try {
        data = rawText ? JSON.parse(rawText) : {};
      } catch (parseError) {
        console.error("[admin-analytics:client] non-JSON response", {
          status: response.status,
          bodyPreview: String(rawText || "").slice(0, 300),
          parseError: parseError?.message,
        });
        throw new Error(
          `Admin analytics returned HTTP ${response.status} with non-JSON body (often a Render crash/OOM).`,
        );
      }
      console.info("[admin-analytics:client] response", {
        status: response.status,
        ok: response.ok,
        code: data?.code || "",
        error: data?.error || "",
        hasAnalytics: Boolean(data?.analytics),
        bodyKeys: Object.keys(data || {}),
      });
      if (!response.ok) {
        if (!assertAdminApiResponse(response, data, { render: false })) {
          // Session invalid — re-unlock shell will appear on next admin paint.
        }
        const detail = data?.error || data?.hint || `HTTP ${response.status}`;
        throw new Error(
          isAdminSessionAuthError(data, response)
            ? (data?.hint || "Admin session expired on the server. Unlock Admin again.")
            : detail,
        );
      }
      adminAnalyticsCache = data.analytics || data;
      adminAnalyticsFetchedAt = Date.now();
      adminAnalyticsLastError = "";
      adminSessionInvalidOnServer = false;
      renderAdminAnalytics();
      renderAdminMarketingAnalytics();
      renderAdminOwnerOverview();
      renderAdminUsersDashboard();
      renderAdminFeedbackCenter();
      return adminAnalyticsCache;
    } catch (error) {
      const aborted = error?.name === "AbortError";
      adminAnalyticsLastError = aborted
        ? `Analytics timed out after ${Math.round(ADMIN_ANALYTICS_TIMEOUT_MS / 1000)}s. Tap Retry.`
        : (error?.message || "Could not load admin analytics.");
      console.error("[admin-analytics:client] failed", {
        aborted,
        message: adminAnalyticsLastError,
        email: session.email || "",
      });
      renderAdminOwnerOverview();
      renderAdminAnalytics();
      renderAdminMarketingAnalytics();
      return null;
    } finally {
      clearTimeout(timeoutId);
      if (adminAnalyticsAbortController === controller) {
        adminAnalyticsAbortController = null;
      }
      adminAnalyticsLoading = false;
      adminAnalyticsLoadPromise = null;
    }
  })();

  return adminAnalyticsLoadPromise;
}

