// ── Free Plan Access (grandfathering + soft limits) ──

function adminResolvedFreePlanAccessConfig() {
  const api = freePlanGrandfatheringApi();
  const fromSite = effectiveSiteContent().freePlanAccess || {};
  const resolved = api?.resolveConfig?.({ siteContent: effectiveSiteContent() }) || {};
  return {
    enabled: typeof fromSite.enabled === "boolean" ? fromSite.enabled : (resolved.enabled !== false),
    curatedCutoffAt: fromSite.curatedCutoffAt || resolved.curatedCutoffAt || "2026-07-18T00:00:00.000Z",
    missingDateMeansLegacy: typeof fromSite.missingDateMeansLegacy === "boolean"
      ? fromSite.missingDateMeansLegacy
      : (resolved.missingDateMeansLegacy !== false),
    earlySupporterTitle: fromSite.earlySupporterTitle || resolved.earlySupporterTitle || "Early supporter Free access",
    earlySupporterBody: fromSite.earlySupporterBody || resolved.earlySupporterBody || "",
    freeCalendarPlanningDays: Math.max(1, Number(fromSite.freeCalendarPlanningDays) || freeCalendarPlanningDays || 30),
    freeFavoriteLimit: Math.max(1, Number(fromSite.freeFavoriteLimit) || freeFavoriteLimit || 20),
    freeChildProfileLimit: Math.max(1, Number(fromSite.freeChildProfileLimit) || freeChildProfileLimit || 5),
  };
}

function adminFreeLessonAccessLabel(account = {}) {
  if (adminMembershipHasProAccess(account)) return "Paid (full Pro library)";
  const api = freePlanGrandfatheringApi();
  const mode = api?.resolveFreeLessonAccessMode?.(account, { siteContent: effectiveSiteContent() }) || "curated";
  if (mode === "legacy") return "Legacy Free (grandfathered)";
  return "Curated Free sample";
}

function renderAdminFreePlanAccessSection() {
  const target = document.querySelector("#adminFreePlanAccessApp");
  if (!target || !isAdminUnlocked()) return;
  const cfg = adminResolvedFreePlanAccessConfig();
  const cutoffLocal = (() => {
    const ms = Date.parse(cfg.curatedCutoffAt);
    if (!Number.isFinite(ms)) return "";
    const d = new Date(ms);
    const pad = (n) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  })();
  target.innerHTML = `
    <div class="section-heading">
      <div><p class="eyebrow">Site Editor</p><h3>Free Plan Access <span class="se-status-badge se-live">🟢 Live</span></h3></div>
    </div>
    <p class="muted-copy">Control what new Free users get vs grandfathered Free users. Pro / Founding / Trial always keep full access.</p>
    <form id="adminFreePlanAccessForm" class="panel-form admin-stacked-form">
      <details class="se-accordion" open>
        <summary class="se-accordion-summary">Grandfathering</summary>
        <div class="se-accordion-body">
          <label class="se-draft-toggle"><input type="checkbox" name="enabled"${cfg.enabled ? " checked" : ""} /> Grandfather existing Free users before the cutoff</label>
          <label>Curated Free cutoff (local time)<input name="curatedCutoffAt" type="datetime-local" value="${escapeHtml(cutoffLocal)}" /></label>
          <p class="form-note">Accounts created <strong>before</strong> this date keep the original Free library. New Free signups after it get the curated sample.</p>
          <label class="se-draft-toggle"><input type="checkbox" name="missingDateMeansLegacy"${cfg.missingDateMeansLegacy ? " checked" : ""} /> Treat Free accounts with no signup date as grandfathered</label>
          <label>Early supporter title<input name="earlySupporterTitle" value="${escapeHtml(cfg.earlySupporterTitle)}" /></label>
          <label>Early supporter message<textarea name="earlySupporterBody" rows="4">${escapeHtml(cfg.earlySupporterBody)}</textarea></label>
        </div>
      </details>
      <details class="se-accordion" open>
        <summary class="se-accordion-summary">New Free Soft Limits</summary>
        <div class="se-accordion-body">
          <div class="form-grid-two">
            <label>Calendar planning days<input name="freeCalendarPlanningDays" type="number" min="1" max="365" value="${escapeHtml(String(cfg.freeCalendarPlanningDays))}" /></label>
            <label>Favorites limit<input name="freeFavoriteLimit" type="number" min="1" max="500" value="${escapeHtml(String(cfg.freeFavoriteLimit))}" /></label>
          </div>
          <label>Child profiles limit<input name="freeChildProfileLimit" type="number" min="1" max="200" value="${escapeHtml(String(cfg.freeChildProfileLimit))}" /></label>
          <p class="form-note">These apply to <strong>new curated Free</strong> users. Grandfathered Free and paid plans are not limited by these caps.</p>
          <div class="access-notice" style="margin-top:10px;">
            <p><strong>Current live defaults</strong></p>
            <ul>
              <li>Calendar horizon: ${escapeHtml(String(cfg.freeCalendarPlanningDays))} days</li>
              <li>Favorites: up to ${escapeHtml(String(cfg.freeFavoriteLimit))}</li>
              <li>Child profiles: up to ${escapeHtml(String(cfg.freeChildProfileLimit))}</li>
              <li>Lesson library: curated Free sample for new Free · full Free-tier catalog for grandfathered Free · full library for Pro/Founding/Trial</li>
            </ul>
          </div>
        </div>
      </details>
      <div class="se-form-actions">
        <div class="se-action-buttons">
          <button class="ghost-button" type="button" data-se-restore="free-plan">Restore Defaults</button>
          <button class="primary-button" type="submit">Save Free Plan Access</button>
        </div>
      </div>
      <span class="form-message" id="adminFreePlanAccessMessage"></span>
    </form>
  `;
}

function adminFeaturedThisWeekEditorHtml() {
  const cfg = effectiveSiteContent()?.onboardingRecommendations || {};
  const titles = Array.isArray(cfg.featuredLessonTitles) ? cfg.featuredLessonTitles : ["Farm Animals", "All About Me", "Colors Everywhere"];
  const ids = Array.isArray(cfg.featuredLessonIds) ? cfg.featuredLessonIds : [];
  return `
    <section class="panel-form" style="margin-top:28px;" aria-label="Featured This Week">
      <div class="section-heading">
        <div><p class="eyebrow">Onboarding</p><h3>Featured This Week</h3></div>
      </div>
      <p class="muted-copy">Shown at the top of Lesson Plans for new users. Titles are matched first; optional IDs win when present. Source stays <code>manual</code> until AI/analytics providers are wired.</p>
      <form id="adminFeaturedThisWeekForm">
        <label>Featured titles (one per line)
          <textarea name="featuredTitles" rows="4">${escapeHtml(titles.join("\n"))}</textarea>
        </label>
        <label>Optional lesson plan IDs (one per line)
          <textarea name="featuredIds" rows="4">${escapeHtml(ids.join("\n"))}</textarea>
        </label>
        <label>Recommendation source
          <select name="source">
            <option value="manual" ${cfg.source !== "analytics" && cfg.source !== "ai" ? "selected" : ""}>manual</option>
            <option value="analytics" ${cfg.source === "analytics" ? "selected" : ""} disabled>analytics (coming soon)</option>
            <option value="ai" ${cfg.source === "ai" ? "selected" : ""} disabled>ai (coming soon)</option>
          </select>
        </label>
        <div class="se-action-buttons">
          <button class="primary-button" type="submit">Save Featured This Week</button>
        </div>
        <span class="form-message" id="adminFeaturedThisWeekMessage"></span>
      </form>
    </section>
  `;
}

function bindAdminFeaturedThisWeekEditor(root) {
  const form = root?.querySelector("#adminFeaturedThisWeekForm");
  if (!form) return;
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const msg = root.querySelector("#adminFeaturedThisWeekMessage");
    const data = new FormData(form);
    const titles = String(data.get("featuredTitles") || "").split(/\n+/).map((s) => s.trim()).filter(Boolean);
    const ids = String(data.get("featuredIds") || "").split(/\n+/).map((s) => s.trim()).filter(Boolean);
    if (msg) msg.textContent = "Saving…";
    try {
      const next = cloneJson(effectiveSiteContent(), emptySiteContent());
      next.onboardingRecommendations = {
        ...(next.onboardingRecommendations || {}),
        source: "manual",
        featuredLessonTitles: titles.length ? titles : ["Farm Animals", "All About Me", "Colors Everywhere"],
        featuredLessonIds: ids,
        aiContext: next.onboardingRecommendations?.aiContext || null,
      };
      await saveAdminSiteContent(next);
      if (msg) msg.textContent = "Featured This Week saved.";
    } catch (error) {
      if (msg) msg.textContent = error.message || "Could not save.";
    }
  });
}

async function renderAdminFreeStarterLibrarySection() {
  const target = document.querySelector("#adminFreeStarterLibraryApp");
  if (!target || !isAdminUnlocked()) return;
  target.hidden = false;
  target.innerHTML = `<p class="messages-loading">Loading Free Starter Library…</p>`;
  try {
    const token = adminSession()?.token || localStorage.getItem("llhAdminToken") || "";
    const res = await fetch(`/api/admin/free-starter-library?adminToken=${encodeURIComponent(token)}`);
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || "Could not load Free Starter Library.");
    const lib = data.freeStarterLibrary || {};
    const plans = Array.isArray(lib.plans) ? lib.plans : [];
    const ages = plans.reduce((acc, p) => {
      const age = String(p.age || "Other");
      acc[age] = (acc[age] || 0) + 1;
      return acc;
    }, {});
    const errors = lib.validation?.errors || [];
    target.innerHTML = `
      <div class="section-heading">
        <div><p class="eyebrow">Content</p><h3>Free Starter Library</h3></div>
      </div>
      <p class="muted-copy">Exactly 10 published lesson plans (3 Infant, 3 Toddler, 4 Preschool). Preview before saving. Unrelated lesson edits never change this list.</p>
      <p><strong>Source:</strong> ${escapeHtml(lib.source || "default")} · <strong>Distribution:</strong> Infant ${ages.Infant || 0} · Toddler ${ages.Toddler || 0} · Preschool ${ages.Preschool || 0}</p>
      ${errors.length ? `<div class="access-notice"><strong>Validation</strong><ul>${errors.map((e) => `<li>${escapeHtml(e)}</li>`).join("")}</ul></div>` : `<p class="form-note">Current set meets the required distribution.</p>`}
      <div class="admin-summary" style="margin:12px 0;">
        <table class="admin-table"><thead><tr><th>Age</th><th>Title</th><th>Status</th><th>ID</th></tr></thead>
        <tbody>
          ${plans.map((p) => `<tr><td>${escapeHtml(p.age || "—")}</td><td>${escapeHtml(p.title || "(missing)")}</td><td>${p.missing ? "Missing" : escapeHtml(p.status || "")}</td><td><code>${escapeHtml(p.id)}</code></td></tr>`).join("")}
        </tbody></table>
      </div>
      <form id="adminFreeStarterLibraryForm" class="panel-form">
        <label>Lesson plan IDs (one per line, exactly 10)
          <textarea name="lessonPlanIds" rows="12">${escapeHtml((lib.lessonPlanIds || []).join("\n"))}</textarea>
        </label>
        <div class="se-action-buttons">
          <button class="ghost-button" type="submit" name="mode" value="preview">Preview changes</button>
          <button class="primary-button" type="submit" name="mode" value="save">Save Free Starter Library</button>
        </div>
        <span class="form-message" id="adminFreeStarterLibraryMessage"></span>
      </form>
      ${adminFeaturedThisWeekEditorHtml()}
    `;
    const form = target.querySelector("#adminFreeStarterLibraryForm");
    bindAdminFeaturedThisWeekEditor(target);
    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      const mode = event.submitter?.value || "preview";
      const ids = String(new FormData(form).get("lessonPlanIds") || "")
        .split(/\n+/)
        .map((s) => s.trim())
        .filter(Boolean);
      const msg = target.querySelector("#adminFreeStarterLibraryMessage");
      if (msg) msg.textContent = mode === "save" ? "Saving…" : "Previewing…";
      try {
        const saveRes = await fetch("/api/admin/free-starter-library", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            adminToken: token,
            lessonPlanIds: ids,
            confirm: mode === "save",
            adminEmail: adminSession()?.email || "",
          }),
        });
        const saveData = await saveRes.json();
        if (!saveRes.ok) {
          if (msg) msg.textContent = (saveData.errors || [saveData.error]).join(" ");
          return;
        }
        if (msg) {
          msg.textContent = saveData.saved
            ? "Free Starter Library saved."
            : (saveData.message || "Preview ready — confirm to save.");
        }
        if (saveData.saved || saveData.preview) await renderAdminFreeStarterLibrarySection();
      } catch (error) {
        if (msg) msg.textContent = error.message || "Save failed.";
      }
    });
  } catch (error) {
    target.innerHTML = `<div class="empty-state">${escapeHtml(error.message || "Failed to load.")}</div>`;
  }
}

