async function saveAdminAiGuideKillSwitch(killOn) {
  const token = adminSession()?.token || "";
  if (!token || !isAdminUnlocked()) return;
  adminAiGuideState.saving = true;
  adminAiGuideState.success = "";
  adminAiGuideState.error = "";
  renderAdminAiGuideControls();
  try {
    const res = await fetch("/api/admin/ai-guide/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ emergencyKillSwitch: Boolean(killOn) }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "Could not update AI Guide kill switch.");
    if (adminAiGuideState.overview) {
      adminAiGuideState.overview.settings = data.settings || adminAiGuideState.overview.settings;
    }
    adminAiGuideState.success = killOn
      ? "AI Guide emergency kill switch is ON — user generate/revise is blocked."
      : "AI Guide emergency kill switch is OFF.";
  } catch (error) {
    adminAiGuideState.error = error.message || "Could not update kill switch.";
  }
  adminAiGuideState.saving = false;
  renderAdminAiGuideControls();
}

function renderAdminAiGuideControls() {
  const host = document.querySelector("#adminAiGuideControls");
  if (!host) return;
  if (!isAiGuideEnabled()) {
    host.innerHTML = `
      <div class="section-heading">
        <div>
          <p class="eyebrow">Testing only</p>
          <h3>AI Guide</h3>
          <p>AI Guide env fence is off on this server. Set AI_GUIDE_ENABLED=true only on the testing service.</p>
        </div>
      </div>
    `;
    return;
  }
  if (adminAiGuideState.loading) {
    host.innerHTML = `<p class="ai-pm-loading">Loading AI Guide controls…</p>`;
    return;
  }
  const overview = adminAiGuideState.overview;
  const settings = overview?.settings || {};
  const totals = overview?.totals || {};
  const killed = Boolean(settings.emergencyKillSwitch);
  host.innerHTML = `
    <div class="section-heading">
      <div>
        <p class="eyebrow">Testing only</p>
        <h3>AI Guide controls</h3>
        <p>Phase 1 helpers never auto-send or auto-publish. Use the kill switch if drafts look unsafe.</p>
      </div>
    </div>
    ${adminAiGuideState.error ? `<p class="form-error">${escapeHtml(adminAiGuideState.error)}</p>` : ""}
    ${adminAiGuideState.success ? `<p class="form-success">${escapeHtml(adminAiGuideState.success)}</p>` : ""}
    <p class="form-note">Generations: ${escapeHtml(String(totals.generations ?? "—"))} · Drafts: ${escapeHtml(String(totals.drafts ?? "—"))} · Feedback: ${escapeHtml(String(totals.feedback ?? "—"))} · Templates: ${escapeHtml(String(totals.templates ?? "—"))} · Ask queries: ${escapeHtml(String(totals.askQueries ?? "—"))}</p>
    <p class="form-note">Status: <strong>${killed ? "Blocked by admin" : "Available on testing"}</strong></p>
    <div class="account-actions-row">
      <button class="primary-button" type="button" data-ai-guide-kill="on" ${adminAiGuideState.saving || killed ? "disabled" : ""}>Turn kill switch ON</button>
      <button class="ghost-button" type="button" data-ai-guide-kill="off" ${adminAiGuideState.saving || !killed ? "disabled" : ""}>Turn kill switch OFF</button>
      <button class="ghost-button" type="button" id="aiGuideAdminRefreshBtn">Refresh</button>
    </div>
  `;
  document.querySelector("#aiGuideAdminRefreshBtn")?.addEventListener("click", () => loadAdminAiGuideOverview());
}

function renderAdminAiSettingsTab() {
  const target = document.querySelector("#adminAiSettingsApp");
  if (!target || !isAdminUnlocked()) return;
  const state = adminAiSettingsState;
  const settings = state.aiSettings;

  if (state.loading) {
    target.innerHTML = `<p class="ai-pm-loading">Loading AI settings…</p>`;
    return;
  }
  if (!settings) {
    target.innerHTML = `
      <div class="section-heading"><div><p class="eyebrow">Admin Only</p><h3>AI Settings</h3></div></div>
      ${state.error ? `<p class="form-error">${escapeHtml(state.error)}</p>` : ""}
      <p>Could not load AI settings. <button class="ghost-button" type="button" id="aiSettingsRetryBtn">Retry</button></p>
      <div id="adminAiGuideControls" class="section-block" style="margin-top:24px;"></div>
    `;
    renderAdminAiGuideControls();
    loadAdminAiGuideOverview();
    return;
  }

  target.innerHTML = `
    <div class="section-heading">
      <div>
        <p class="eyebrow">Admin Only</p>
        <h3>AI Settings &amp; Safety Controls</h3>
        <p>Enable or disable individual AI tools, set per-tool generation limits, and configure fallback messages shown to users when a tool is unavailable.</p>
      </div>
    </div>
    ${state.error ? `<p class="form-error" style="margin-bottom:12px;">${escapeHtml(state.error)}</p>` : ""}
    ${state.success ? `<p class="form-success" style="margin-bottom:12px;">${escapeHtml(state.success)}</p>` : ""}
    <form id="adminAiSettingsForm" class="panel-form">
      <div class="ai-settings-master">
        <label class="admin-inline-toggle">
          <input type="checkbox" id="aiSettingsMasterEnabled" ${settings.masterEnabled !== false ? "checked" : ""} />
          <strong>AI Document Creation Master Switch</strong>
        </label>
        <p class="form-note">Turn off to disable all AI generations across the entire app. Individual tool settings below are ignored when the master switch is off.</p>
      </div>
      <p class="eyebrow" style="margin:20px 0 8px;">Per-Tool Settings</p>
      <div class="ai-settings-grid">
        ${Object.entries(AI_TOOL_LABELS).map(([toolId, label]) => {
          const tool = settings.tools?.[toolId] || {};
          return `
            <div class="ai-settings-tool-card">
              <div class="ai-settings-tool-header">
                <label class="admin-inline-toggle">
                  <input type="checkbox" name="tool_enabled_${toolId}" ${tool.enabled !== false ? "checked" : ""} />
                  <strong>${escapeHtml(label)}</strong>
                </label>
                <span class="ai-tool-status-badge ${tool.enabled !== false ? "badge-on" : "badge-off"}">${tool.enabled !== false ? "Active" : "Disabled"}</span>
              </div>
              <div class="ai-settings-tool-fields">
                <label class="form-field-small">
                  Monthly Limit (blank = no limit)
                  <input type="number" name="tool_limit_${toolId}" min="1" max="9999" value="${tool.generationLimit != null ? tool.generationLimit : ""}" placeholder="No limit" />
                </label>
                <label class="form-field-small">
                  Fallback Message (shown to users when tool is disabled)
                  <input type="text" name="tool_fallback_${toolId}" maxlength="500" value="${escapeHtml(tool.fallbackMessage || "")}" placeholder="This AI tool is currently unavailable." />
                </label>
              </div>
            </div>
          `;
        }).join("")}
      </div>
      <div class="form-actions" style="margin-top:20px;">
        <button class="primary-button" type="submit" id="aiSettingsSaveBtn" ${state.saving ? "disabled" : ""}>
          ${state.saving ? "Saving…" : "Save AI Settings"}
        </button>
      </div>
    </form>
    <div id="adminAiGuideControls" class="section-block" style="margin-top:28px;"></div>
  `;
  renderAdminAiGuideControls();
  loadAdminAiGuideOverview();
}

// ─── AI Usage Monitor ─────────────────────────────────────────────────────────

let adminAiUsageState = {
  loading: false,
  error: "",
  data: null,
};

let adminAiHealthState = {
  loading: false,
  testing: false,
  error: "",
  data: null,
  testResult: "",
};

async function loadAdminAiHealth() {
  const token = adminSession()?.token || "";
  if (!token || !canUseLaunchBackend()) return;
  adminAiHealthState.loading = true;
  renderAdminAiHealthTab();
  try {
    const res = await fetch(`${adminAiHealthConfig.endpoint}?t=${Date.now()}`, { cache: "no-store", headers: { Authorization: `Bearer ${token}` } });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "Failed to load AI health.");
    adminAiHealthState.data = data.aiHealth || null;
    adminAiHealthState.error = "";
  } catch (error) {
    adminAiHealthState.error = error.message || "Could not load AI health.";
    adminAiHealthState.data = null;
  }
  adminAiHealthState.loading = false;
  renderAdminAiHealthTab();
}

async function runAdminAiHealthTest() {
  const token = adminSession()?.token || "";
  if (!token || !canUseLaunchBackend()) return;
  adminAiHealthState.testing = true;
  adminAiHealthState.testResult = "";
  renderAdminAiHealthTab();
  try {
    const res = await fetch(adminAiHealthConfig.testEndpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ adminEmail: adminSession()?.email || "" }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "AI health test failed.");
    adminAiHealthState.testResult = `OK — ${data.output || "Test passed."} (Ref: ${data.requestId || "n/a"})`;
  } catch (error) {
    adminAiHealthState.testResult = error.message || "AI health test failed.";
  }
  adminAiHealthState.testing = false;
  renderAdminAiHealthTab();
}

function renderAdminAiHealthTab() {
  const target = document.querySelector("#adminAiHealthApp");
  if (!target) return;
  const state = adminAiHealthState;
  if (state.loading) {
    target.innerHTML = `<p class="ai-pm-loading">Loading AI health…</p>`;
    return;
  }
  const d = state.data;
  if (!d) {
    target.innerHTML = `
      <div class="section-heading"><div><p class="eyebrow">Admin Only</p><h3>AI Health</h3></div></div>
      ${state.error ? `<p class="form-error">${escapeHtml(state.error)}</p>` : ""}
      <p>Could not load AI health. <button class="ghost-button" type="button" id="aiHealthRetryBtn">Retry</button></p>
    `;
    return;
  }
  const formatMs = (ms) => ms == null ? "—" : ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`;
  const statusClass = d.operational ? "ai-stat-success" : "ai-stat-failed";
  const toolRows = Object.entries(d.toolSettings || {}).map(([toolId, cfg]) => `
    <div class="ai-health-tool-row">
      <div>
        <strong>${escapeHtml(AI_TOOL_LABELS[toolId] || toolId)}</strong>
        <p class="muted-copy">${cfg.enabled === false ? "Disabled" : "Enabled"}${cfg.generationLimit ? ` · limit ${cfg.generationLimit}/month` : ""}</p>
      </div>
      <span class="ai-health-pill ${cfg.enabled === false ? "is-off" : "is-on"}">${cfg.enabled === false ? "Off" : "On"}</span>
    </div>
  `).join("");
  const errorRows = (d.recentErrors || []).map((row) => `
    <tr>
      <td>${escapeHtml(row.createdAt ? new Date(row.createdAt).toLocaleString() : "—")}</td>
      <td>${escapeHtml(AI_TOOL_LABELS[row.tool] || row.tool || "—")}</td>
      <td><code>${escapeHtml(row.requestId || "—")}</code></td>
      <td>${escapeHtml(row.errorMessage || "—")}</td>
    </tr>
  `).join("") || `<tr><td colspan="4">No failures logged today.</td></tr>`;

  target.innerHTML = `
    <div class="section-heading">
      <div>
        <p class="eyebrow">Admin Only</p>
        <h3>AI Health</h3>
        <p>Operational status, today's traffic, sanitized errors, and per-tool controls.</p>
      </div>
      <div class="output-actions">
        <button class="ghost-button" type="button" id="aiHealthRefreshBtn">Refresh</button>
        <button class="primary-button" type="button" id="aiHealthTestBtn" ${state.testing ? "disabled" : ""}>${state.testing ? "Testing…" : "Run Safe Test"}</button>
      </div>
    </div>
    <div class="ai-usage-stats-grid">
      <div class="ai-usage-stat-card ${statusClass}">
        <p class="ai-stat-label">Status</p>
        <p class="ai-stat-value">${d.operational ? "Operational" : "Unavailable"}</p>
      </div>
      <div class="ai-usage-stat-card">
        <p class="ai-stat-label">Provider / Model</p>
        <p class="ai-stat-value" style="font-size:1rem;">${escapeHtml(d.provider)} · ${escapeHtml(d.model)}</p>
      </div>
      <div class="ai-usage-stat-card">
        <p class="ai-stat-label">Requests Today</p>
        <p class="ai-stat-value">${Number(d.requestsToday || 0).toLocaleString()}</p>
      </div>
      <div class="ai-usage-stat-card ai-stat-success">
        <p class="ai-stat-label">Successful Today</p>
        <p class="ai-stat-value">${Number(d.successfulToday || 0).toLocaleString()}</p>
      </div>
      <div class="ai-usage-stat-card ai-stat-failed">
        <p class="ai-stat-label">Failed Today</p>
        <p class="ai-stat-value">${Number(d.failedToday || 0).toLocaleString()}</p>
      </div>
      <div class="ai-usage-stat-card">
        <p class="ai-stat-label">Avg Response Today</p>
        <p class="ai-stat-value">${formatMs(d.avgResponseMs)}</p>
      </div>
      <div class="ai-usage-stat-card">
        <p class="ai-stat-label">Est. Cost Today</p>
        <p class="ai-stat-value">$${Number(d.estimatedCostUsdToday || 0).toFixed(4)}</p>
      </div>
      <div class="ai-usage-stat-card">
        <p class="ai-stat-label">Top Failing Tool</p>
        <p class="ai-stat-value" style="font-size:1rem;">${escapeHtml(AI_TOOL_LABELS[d.topFailingTool] || d.topFailingTool || "—")}</p>
      </div>
    </div>
    ${state.testResult ? `<p class="form-note">${escapeHtml(state.testResult)}</p>` : ""}
    <div class="ai-health-tools section-block">
      <p class="eyebrow">Per-tool switches</p>
      <p class="muted-copy">Disable one tool without turning off all AI. Manage limits in AI Settings.</p>
      ${toolRows}
    </div>
    <div class="ai-usage-log-section section-block">
      <p class="eyebrow">Recent sanitized errors (today)</p>
      <div class="ai-usage-log-table-wrap">
        <table class="ai-usage-log-table">
          <thead><tr><th>Time</th><th>Tool</th><th>Request ID</th><th>Error</th></tr></thead>
          <tbody>${errorRows}</tbody>
        </table>
      </div>
    </div>
  `;
}

