async function loadAdminStoreBackups() {
  const token = adminSession()?.token || "";
  if (!token || !canUseLaunchBackend()) return [];
  adminStoreHealthState.backupsLoading = true;
  adminStoreHealthState.backupError = "";
  try {
    const res = await fetch(`/api/admin/store-backups`, { cache: "no-store", headers: { Authorization: `Bearer ${token}` } });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "Could not load store backups.");
    adminStoreHealthState.backups = Array.isArray(data.backups) ? data.backups : [];
  } catch (error) {
    adminStoreHealthState.backupError = error.message || "Store backups unavailable.";
    adminStoreHealthState.backups = [];
  }
  adminStoreHealthState.backupsLoading = false;
  return adminStoreHealthState.backups;
}

async function createAdminStoreBackup() {
  const token = adminSession()?.token || "";
  if (!token || !canUseLaunchBackend()) return null;
  adminStoreHealthState.backingUp = true;
  adminStoreHealthState.backupError = "";
  try {
    const res = await fetch("/api/admin/store-backups", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ source: "manual-admin" }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "Could not create store backup.");
    await loadAdminStoreBackups();
    return data.result || null;
  } catch (error) {
    adminStoreHealthState.backupError = error.message || "Could not create store backup.";
    return null;
  } finally {
    adminStoreHealthState.backingUp = false;
  }
}

async function downloadAdminStoreBackup(backupId) {
  const token = adminSession()?.token || "";
  const id = String(backupId || "").trim();
  if (!token || !id || !canUseLaunchBackend()) return;
  adminStoreHealthState.backupError = "";
  try {
    const res = await fetch(
      `/api/admin/store-backups/download?id=${encodeURIComponent(id)}`,
      { cache: "no-store", headers: { Authorization: `Bearer ${token}` } },
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "Could not download backup.");
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const href = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = href;
    a.download = `${id}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(href);
  } catch (error) {
    adminStoreHealthState.backupError = error.message || "Backup download failed.";
    renderAdminStripeBackfillTab();
  }
}

async function runAdminSparseStoreRecovery({ force = false } = {}) {
  const token = adminSession()?.token || "";
  if (!token || !canUseLaunchBackend()) return;
  adminStoreHealthState.recovering = true;
  adminStoreHealthState.recoverResult = null;
  adminStoreHealthState.error = "";
  renderAdminStripeBackfillTab();
  try {
    const res = await fetch("/api/admin/recover-sparse-store", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        force: force === true,
        confirm: "RECOVER_SPARSE_STORE",
      }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error || "Recovery failed.");
    adminStoreHealthState.recoverResult = data.result || null;
    adminStoreHealthState.health = data.health || adminStoreHealthState.health;
    await loadAdminAnalytics(true).catch(() => {});
    renderAdminUsersDashboard();
  } catch (error) {
    adminStoreHealthState.error = error.message || "Recovery failed.";
  }
  adminStoreHealthState.recovering = false;
  renderAdminStripeBackfillTab();
}

function renderAdminStripeBackfillTab() {
  const target = document.querySelector("#adminStripeBackfillApp");
  if (!target || !isAdminUnlocked()) return;
  const s = stripeBackfillState;
  const health = adminStoreHealthState.health;
  const sparse = Boolean(health?.sparseStoreSuspected);

  if (!adminStoreHealthState.loading && !health && !adminStoreHealthState.error) {
    loadAdminStoreHealth().then(() => {
      loadAdminStoreBackups().finally(() => renderAdminStripeBackfillTab());
    });
  }

  target.innerHTML = `
    <div class="section-heading">
      <div>
        <p class="eyebrow">Admin Only</p>
        <h3>Stripe Backfill / Store Recovery</h3>
        <p>Rebuild missing users from Stripe after a sparse-store wipe, or reconcile legacy Stripe customers with backend accounts.</p>
      </div>
    </div>

    ${adminStoreHealthState.error ? `<p class="form-error">${escapeHtml(adminStoreHealthState.error)}</p>` : ""}
    ${health ? `
      <div class="aup-insight-grid" style="margin-bottom:16px;">
        <div class="aup-insight-card"><strong>${health.counts?.users ?? "—"}</strong><span>Users in store</span></div>
        <div class="aup-insight-card"><strong>${health.counts?.messages ?? "—"}</strong><span>Messages</span></div>
        <div class="aup-insight-card"><strong>${health.counts?.conversations ?? "—"}</strong><span>Conversations</span></div>
        <div class="aup-insight-card ${sparse ? "aup-insight--canceled" : "aup-insight--pro"}"><strong>${sparse ? "SPARSE" : "OK"}</strong><span>Store health</span></div>
      </div>
      <p class="form-note">${escapeHtml(health.note || "")}${health.recovery?.sparseStripeBackfillAt ? ` · Last auto-recovery: ${escapeHtml(health.recovery.sparseStripeBackfillAt)} (${Number(health.recovery.userCountBefore) || 0} → ${Number(health.recovery.userCountAfter) || 0} users)` : ""}${health.recovery?.firebaseHybridRecoveredAt ? ` · Firebase hybrid recovery: ${escapeHtml(health.recovery.firebaseHybridRecoveredAt)} (${Number(health.recovery.firebaseHybridCreatedCount) || 0} created)` : ""}</p>
      <div class="account-actions-row" style="margin-bottom:18px;">
        <button class="primary-button" type="button" id="adminRecoverSparseStoreBtn" ${adminStoreHealthState.recovering ? "disabled" : ""}>
          ${adminStoreHealthState.recovering ? "Recovering from Stripe…" : (sparse ? "Recover users from Stripe now" : "Re-run Stripe recovery (force)")}
        </button>
        <button class="ghost-button" type="button" id="adminRefreshStoreHealthBtn">Refresh store health</button>
        <button class="ghost-button" type="button" id="adminCreateStoreBackupBtn" ${adminStoreHealthState.backingUp ? "disabled" : ""}>
          ${adminStoreHealthState.backingUp ? "Creating backup…" : "Create store backup now"}
        </button>
        <button class="ghost-button" type="button" id="adminRefreshStoreBackupsBtn">Refresh backups</button>
      </div>
      ${adminStoreHealthState.recoverResult ? `<p class="form-note">Recovery result: ${escapeHtml(adminStoreHealthState.recoverResult.reason || "")}${adminStoreHealthState.recoverResult.userCountAfter != null ? ` · users now ${adminStoreHealthState.recoverResult.userCountAfter}` : ""}</p>` : ""}
      <div class="panel-card" style="margin-bottom:18px;">
        <h4 style="margin:0 0 8px;">Logical store backups</h4>
        <p class="form-note">Daily Postgres snapshots (retained on the server). Download weekly/offsite copies from here and store them somewhere safe.</p>
        ${adminStoreHealthState.backupError ? `<p class="form-error">${escapeHtml(adminStoreHealthState.backupError)}</p>` : ""}
        ${Array.isArray(adminStoreHealthState.backups) && adminStoreHealthState.backups.length ? `
          <div class="table-wrap"><table class="data-table"><thead><tr>
            <th>Created</th><th>Source</th><th>Users</th><th>Messages</th><th>Founding</th><th>Verified</th><th></th>
          </tr></thead><tbody>
            ${adminStoreHealthState.backups.map((b) => `
              <tr>
                <td>${escapeHtml(b.created_at ? new Date(b.created_at).toLocaleString() : "")}</td>
                <td>${escapeHtml(b.source || "")}</td>
                <td>${Number(b.user_count) || 0}</td>
                <td>${Number(b.message_count) || 0}</td>
                <td>${Number(b.founding_count) || 0}</td>
                <td>${b.verified ? "Yes" : "No"}</td>
                <td><button class="ghost-button" type="button" data-download-backup="${escapeHtml(b.id)}">Download</button></td>
              </tr>
            `).join("")}
          </tbody></table></div>
        ` : `<p class="form-note">${adminStoreHealthState.backupsLoading ? "Loading backups…" : "No backups yet. Create one now, or wait for the daily scheduler after deploy."}</p>`}
      </div>
    ` : (adminStoreHealthState.loading ? `<p class="ai-pm-loading">Checking store health…</p>` : "")}

    ${s.error ? `<p class="form-error">${escapeHtml(s.error)}</p>` : ""}

    ${s.loading ? `<p class="ai-pm-loading">Running preview…</p>` : ""}

    ${!s.loading && !s.preview && !s.runResult ? `
      <button class="primary-button" type="button" id="stripeBackfillPreviewBtn" ${s.loading ? "disabled" : ""}>
        Run Dry-Run Preview
      </button>
    ` : ""}

    ${s.preview && !s.runResult ? `
      ${renderStripeBackfillReport(s.preview, "Dry-Run Preview Results")}
      <div class="backfill-confirm-row">
        <button class="ghost-button" type="button" id="stripeBackfillResetBtn">Start Over</button>
        <button class="primary-button" type="button" id="stripeBackfillRunBtn" ${s.running ? "disabled" : ""}>
          ${s.running ? "Applying changes…" : "Confirm &amp; Run Backfill"}
        </button>
      </div>
      ${s.runError ? `<p class="form-error">${escapeHtml(s.runError)}</p>` : ""}
    ` : ""}

    ${s.runResult ? `
      ${renderStripeBackfillReport(s.runResult, "Backfill Complete")}
      <button class="ghost-button" type="button" id="stripeBackfillResetBtn" style="margin-top:16px;">Run Again</button>
    ` : ""}
  `;

  document.querySelector("#adminRecoverSparseStoreBtn")?.addEventListener("click", () => {
    const force = !sparse;
    const label = force
      ? "Force re-run Stripe recovery even if the store no longer looks sparse?"
      : "Rebuild missing users from Stripe into the production store now?";
    if (!window.confirm(label)) return;
    runAdminSparseStoreRecovery({ force });
  });
  document.querySelector("#adminRefreshStoreHealthBtn")?.addEventListener("click", async () => {
    await loadAdminStoreHealth();
    renderAdminStripeBackfillTab();
  });
  document.querySelector("#adminCreateStoreBackupBtn")?.addEventListener("click", async () => {
    if (!window.confirm("Create a logical Postgres store backup now? This does not change user data.")) return;
    renderAdminStripeBackfillTab();
    await createAdminStoreBackup();
    renderAdminStripeBackfillTab();
  });
  document.querySelector("#adminRefreshStoreBackupsBtn")?.addEventListener("click", async () => {
    await loadAdminStoreBackups();
    renderAdminStripeBackfillTab();
  });
  document.querySelectorAll("[data-download-backup]").forEach((btn) => {
    btn.addEventListener("click", () => downloadAdminStoreBackup(btn.getAttribute("data-download-backup")));
  });
  document.querySelector("#stripeBackfillPreviewBtn")?.addEventListener("click", loadStripeBackfillPreview);
  document.querySelector("#stripeBackfillRunBtn")?.addEventListener("click", runStripeBackfillConfirm);
  document.querySelector("#stripeBackfillResetBtn")?.addEventListener("click", () => {
    stripeBackfillState.preview = null;
    stripeBackfillState.runResult = null;
    stripeBackfillState.error = "";
    stripeBackfillState.runError = "";
    renderAdminStripeBackfillTab();
  });
}

function fillAdminLessonPlanFormFields(fields, mode) {
  const form = document.querySelector("#adminLessonPlanForm");
  if (!form) return;
  const fieldMap = [
    ["weeklyOverview", "weeklyOverview"],
    ["materials", "materials"],
    ["objectives", "objectives"],
    ["teacherLanguage", "teacherLanguage"],
    ["monday", "monday"],
    ["tuesday", "tuesday"],
    ["wednesday", "wednesday"],
    ["thursday", "thursday"],
    ["friday", "friday"],
    ["elgConnections", "elgConnections"],
    ["familyConnection", "familyConnection"],
    ["reflectionNotes", "reflectionNotes"],
  ];
  const titleValue = String(fields.title || "").trim();
  const titleEl = form.querySelector('[name="title"]');
  if (titleEl && titleValue && !titleEl.value.trim()) titleEl.value = titleValue;
  fieldMap.forEach(([fieldKey, formName]) => {
    const value = String(fields[fieldKey] || "").trim();
    if (!value) return;
    const el = form.querySelector(`[name="${formName}"]`);
    if (!el) return;
    if (mode === "empty" && el.value.trim()) return;
    el.value = value;
  });
  const thumbUrl = form.querySelector('[name="thumbnailUrl"]');
  if (thumbUrl && !thumbUrl.value.trim() && fields.thumbnailPrompt) {
    const prompt = String(fields.thumbnailPrompt).trim();
    thumbUrl.setAttribute("data-thumbnail-prompt", prompt);
    thumbUrl.placeholder = `Generated prompt: ${prompt.slice(0, 100)}${prompt.length > 100 ? "…" : ""}`;
  }
  updateAdminLessonEditorHeading();
}

async function triggerAdminLessonGenerate(fillMode) {
  const form = document.querySelector("#adminLessonPlanForm");
  if (!form) return;
  const age = (form.querySelector('[name="age"]')?.value || "").trim();
  const theme = (form.querySelector('[name="theme"]')?.value || "").trim();
  const lessonNumber = (form.querySelector('[name="generatorLessonNumber"]')?.value || "").trim();
  const generateBtn = document.querySelector("#adminLessonGenerateBtn");
  const confirmEl = document.querySelector("#adminLessonOverwriteConfirm");

  if (!age || !theme) {
    setFormMessage("#adminLessonGenerateMessage", "Please enter the Age Group and Theme before generating.");
    return;
  }

  if (fillMode === "check") {
    const hasContent = adminLessonContentFields.some(
      (name) => (form.querySelector(`[name="${name}"]`)?.value || "").trim() !== ""
    );
    if (hasContent) {
      if (confirmEl) confirmEl.hidden = false;
      setFormMessage("#adminLessonGenerateMessage", "");
      return;
    }
    fillMode = "all";
  }

  if (confirmEl) confirmEl.hidden = true;
  if (generateBtn) { generateBtn.disabled = true; generateBtn.textContent = "Creating…"; }
  setFormMessage("#adminLessonGenerateMessage", "Generating lesson plan — this may take up to 30 seconds…", true);

  try {
    const fields = await callAdminGenerateLessonPlan(age, theme, lessonNumber);
    fillAdminLessonPlanFormFields(fields, fillMode);
    setFormMessage("#adminLessonGenerateMessage", "✅ Lesson plan generated. Review all fields below and click Save Lesson Plan when ready.", true);
  } catch (error) {
    setFormMessage("#adminLessonGenerateMessage", error.message || "Lesson plan could not be generated. Please try again.");
  } finally {
    if (generateBtn) { generateBtn.disabled = false; generateBtn.textContent = "✨ Generate Lesson Plan"; }
  }
}

function previewAdminLessonPlan() {
  if (adminLessonEditorId) openResourceViewer(adminLessonEditorId);
}



