function generateBehaviorDocumentation(data) {
  const hasChild = Boolean(data.childExplicitlySelected && (data.childName || data.child));
  const childName = hasChild ? String(data.childName || data.child || "").trim() : "";
  const childRef = childName || "the child";
  const rawAge = data.age ? normalizeAiAgeGroup(data.age) : "";
  const programName = String(data.programName || data.program || "").trim();
  const tone = data.tone || "Warm and professional";
  const ageContext = data.childAge && rawAge
    ? ` (${data.childAge} · ${rawAge})`
    : data.childAge
      ? ` (${data.childAge})`
      : rawAge
        ? ` (${rawAge})`
        : "";
  const domain = String(data.developmentalDomain || "").trim();
  const concern = String(data.concern || data.note || data.details || "").trim();
  const missing = "Not enough detail provided";
  const parentMessage = toneCopy(tone, [
    ["brief", `Today${programName ? ` at ${programName}` : ""}, ${childRef} needed support${concern ? ` with ${concern}` : ""}. We will keep you updated.`],
    ["supportive", `Today${programName ? ` at ${programName}` : ""}, ${childRef} needed extra support${concern ? ` with ${concern}` : ""}. We can share strategies that may help at home too.`],
    ["warm", `Today${programName ? ` at ${programName}` : ""}, ${childRef} needed some extra guidance${concern ? ` with ${concern}` : ""}. I am happy to talk more about what helped.`],
    ["professional", `Today${programName ? ` at ${programName}` : ""}, ${childRef} needed support${concern ? ` with ${concern}` : ""}. We will continue using consistent strategies and keep you updated as needed.`],
  ]);
  return `Behavior Support Documentation
${programName ? `Program: ${programName}\n` : ""}${childName ? `Child: ${childName}${ageContext}\n` : ""}${domain ? `Developmental Domain: ${domain}\n` : ""}Concern: ${concern || missing}

What Happened
${data.incident && String(data.incident).trim() ? String(data.incident).trim() : (concern || missing)}

Possible Trigger or Antecedent
${data.trigger && String(data.trigger).trim() ? String(data.trigger).trim() : missing}

Support Given
${data.support && String(data.support).trim() ? String(data.support).trim() : missing}

What This Behavior May Communicate
${missing}. Add only what you observed — do not invent causes.

Support Strategies
- Stay calm and close
- Use short words
- Offer a safe choice
(Edit these to match what you actually used.)

Developmental Goal
${data.goal && String(data.goal).trim() ? String(data.goal).trim() : missing}

Follow-Up Plan
${data.plan && String(data.plan).trim() ? String(data.plan).trim() : missing}

Parent Communication
Tone: ${tone}
${parentMessage}

Provider Note
${data.providerNotes ? `Provider Notes: ${data.providerNotes}\n` : ""}Review your program policy and state licensing requirements for behavior documentation, incident reporting, and parent notification.`;
}

function generateIncidentReport(data) {
  const childName = data.childName || data.child || "Child";
  const childAge = data.childAge || "";
  const age = normalizeAiAgeGroup(data.age || "");
  const programName = data.programName || data.program || "Your Daycare Name";
  const date = data.date || "Date of incident";
  const time = data.time || "Time not entered";
  const ageLabel = childAge && age ? ` (${childAge} · ${age})` : childAge ? ` (${childAge})` : age ? ` (${age})` : "";
  const tone = data.tone || "Factual and professional";
  const parentNotification = toneCopy(tone, [
    ["warm", `Today at ${programName}, I am sharing an incident report involving ${childName}. ${withSentencePeriod(data.incident || "An incident occurred during care today.")} ${data.response ? `Immediate response provided: ${withSentencePeriod(data.response)}` : "Immediate support and supervision were provided right away."} Please let me know if you would like to review the report together.`],
    ["detailed", `This is a written incident report from ${programName} regarding ${childName}. ${withSentencePeriod(data.incident || "An incident occurred during care today.")} ${data.trigger ? `Before the incident: ${withSentencePeriod(data.trigger)}` : ""} ${data.response ? `Immediate response: ${withSentencePeriod(data.response)}` : "Immediate support and supervision were provided right away."} ${data.nextSteps ? `Follow-up: ${withSentencePeriod(data.nextSteps)}` : ""} Please contact me if you have any questions about this documentation.`],
    ["factual", `Today at ${programName}, an incident involving ${childName} was documented. ${withSentencePeriod(data.incident || "An incident occurred during care today.")} ${data.response ? `Immediate response: ${withSentencePeriod(data.response)}` : "Immediate support and supervision were provided right away."} Please contact me with any questions.`],
    ["professional", `Today at ${programName}, an incident involving ${childName} was documented. ${withSentencePeriod(data.incident || "An incident occurred during care today.")} ${data.response ? `Immediate response: ${withSentencePeriod(data.response)}` : "Immediate support and supervision were provided right away."} Please contact me with any questions.`],
  ]);
  return `Incident Report
Program: ${programName}
Date: ${date}
Time: ${time}
Child Name: ${childName}${ageLabel}

Description of Incident
${data.incident || "Describe what happened using factual, objective language."}

What Occurred Before the Incident
${data.trigger || "Describe any known triggers, antecedents, or events that occurred just before the incident."}

Immediate Response Given
${data.response || "Describe the steps taken immediately after the incident, including first aid, comfort, and supervision."}

Witnesses / Others Present
${data.witnesses || "List any witnesses or children who were present."}

Next Steps and Follow-Up
${data.nextSteps || "Document any planned follow-up steps, safety changes, or monitoring needed."}

Parent Notification
Tone: ${tone}
${parentNotification}

Provider Note
${data.providerNotes ? `Provider Notes: ${data.providerNotes}\n` : ""}Review your state licensing requirements for incident documentation, parent notification timelines, and required forms. Keep a copy in the child's file.`;
}


