function subscriptionSummaryHtml() {
  const account = currentAccount();
  const paidBilling = currentUser ? accountHasPaidBilling(account) : false;
  const status = currentUser ? accountProductStatus(account) : null;
  const planLabel = currentUser ? (status?.planLabel || billingPlanLabel(currentPlan, account)) : "Guest";
  const statusLabel = currentUser ? `${status.emoji} ${status.label}` : "No account";
  return `
    <div class="billing-summary-grid">
      <div><span>Current Plan</span><strong>${escapeHtml(planLabel)}</strong></div>
      <div><span>Monthly Price</span><strong>${escapeHtml(billingPriceLabel(account))}</strong></div>
      <div><span>Price Lock</span><strong>${paidBilling ? (account?.foundingMemberActive || normalizeBillingPlan(account?.plan, account) === "Founding" || account?.foundingMember ? escapeHtml(FOUNDING_PRICE_LOCK_COPY) : "Regular Pro pricing") : "None"}</strong></div>
      <div><span>Account Status</span><strong class="llh-billing-status-value llh-billing-status-value--${escapeHtml(status?.tone || "neutral")}">${escapeHtml(statusLabel)}</strong></div>
      <div><span>AI Usage</span><strong>${serverAiUsed !== null ? serverAiUsed : aiUsageCount()} / ${serverAiLimit !== null ? serverAiLimit : aiMonthlyLimit()}</strong></div>
      <div><span>AI Reset</span><strong>${escapeHtml(aiResetLabel())}</strong></div>
    </div>
    ${status?.detail ? `<p class="muted-copy llh-billing-status-detail">${escapeHtml(status.detail)}</p>` : ""}
  `;
}

function renderBillingPage() {
  const target = document.querySelector("#billingApp");
  if (!target) return;
  const account = currentAccount();
  const paidBilling = currentUser ? accountHasPaidBilling(account) : false;
  const productStatus = currentUser ? accountProductStatus(account) : null;
  const accessBanner = subscriptionAccessBannerHtml({ variant: "billing" });
  const billingUpgradeBanner = !paidBilling && !productStatus?.banner
    ? foundingUpgradeBannerHtml({ variant: "billing", dismissible: false, force: true })
    : "";
  const showUpdatePayment = paidBilling || productStatus?.cta === "update_payment" || productStatus?.cta === "reactivate";
  const primaryCta = productStatus?.cta === "reactivate"
    ? `<button class="primary-button" data-view="upgrade" type="button">Reactivate Subscription</button>`
    : productStatus?.cta === "update_payment"
      ? `<button class="primary-button" data-update-payment type="button">Update Payment Method</button>`
      : `<button class="primary-button" data-view="upgrade" type="button">${paidBilling ? "Change Plan" : (canSeePaidUpgradeOffer() ? preferredPaidCheckoutButtonLabel() : "Upgrade to Pro")}</button>`;
  const cancelScheduled = Boolean(account?.cancelAtPeriodEnd);
  const accessEndLabel = account?.accessEndsAt || account?.currentPeriodEnd || account?.trialEnd
    ? new Date(account.accessEndsAt || account.currentPeriodEnd || account.trialEnd).toLocaleDateString()
    : "";
  const showPromoEntry = !paidBilling && !account?.promoCodeUsed && canSeePaidUpgradeOffer();
  target.innerHTML = `
    ${accessBanner}
    ${billingUpgradeBanner}
    ${showPromoEntry ? promoCodePanel({
      context: "billing",
      heading: "Have a promo code? Apply it here before upgrading.",
      hideWhenRedeemed: true,
    }) : ""}
    <section class="account-layout">
      <div class="account-panel">
        <p class="eyebrow">Billing &amp; Subscription</p>
        <h3>${escapeHtml(currentUser || "Guest")}</h3>
        <p class="llh-billing-status-line">${accountStatusBadgeHtml(account)}</p>
        ${subscriptionSummaryHtml()}
        ${accountIsInTrial(account) ? `<p class="muted-copy"><strong>Trial curriculum exports:</strong> ${escapeHtml(MEMBERSHIP_COPY.trialCore)} Your own records are never limited by this allowance.</p>` : ""}
        ${!paidBilling && !accountIsInTrial(account) ? `<p class="muted-copy">${escapeHtml(MEMBERSHIP_COPY.freeCore)} ${escapeHtml(MEMBERSHIP_COPY.freeBrowse)}</p>` : ""}
        ${account?.promoCodeUsed ? `<p class="muted-copy">Promo code used: <strong>${escapeHtml(account.promoCodeUsed)}</strong>${account.promoLabelUsed ? ` — ${escapeHtml(account.promoLabelUsed)}` : ""}</p>` : ""}
        <div class="account-actions-row">
          <button class="ghost-button back-button" data-view="settings" type="button">← Back to Settings</button>
          ${primaryCta}
          ${showUpdatePayment && productStatus?.cta !== "update_payment" ? `<button class="ghost-button" data-update-payment type="button">Update Payment Method</button>` : ""}
          <button class="ghost-button" data-view="billing-history" type="button">View Billing History</button>
        </div>
      </div>
      <div class="account-panel">
        <p class="eyebrow">Payment Method</p>
        <h3>${escapeHtml(paidBilling ? account?.paymentMethod || "Managed in Stripe" : "No payment method on file")}</h3>
        <p>Stripe Customer: ${escapeHtml(paidBilling ? account?.stripeCustomerId || "Created after live checkout" : "Created after checkout")}</p>
        <p>Subscription: ${escapeHtml(paidBilling ? account?.stripeSubscriptionId || "Created after live checkout" : "No active subscription")}</p>
      </div>
    </section>
    ${paidBilling ? `
    <section class="section-block llh-billing-cancel-panel" id="billingCancelPanel">
      <p class="eyebrow">Manage Subscription</p>
      <h3>${cancelScheduled ? "Cancellation scheduled" : "Cancel subscription"}</h3>
      ${cancelScheduled
        ? `<p class="muted-copy">Status: <strong>${escapeHtml(account.subscriptionStatus || `Canceled — Access Ends ${accessEndLabel}`)}</strong>. You keep access until that date.</p>`
        : `<p class="muted-copy">Need to cancel? You can do that here. Access continues until the end of your current billing period (or free month), and you will see a clear confirmation before anything changes.</p>
          <div class="account-actions-row">
            <button class="danger-button" data-view="cancel-subscription" type="button">Cancel Subscription</button>
          </div>`}
    </section>
    ` : ""}
  `;
}

