let featurePreviewTrigger = null;

function isFeaturePreviewOpen() {
  return featurePreviewModal?.getAttribute("aria-hidden") === "false";
}

function featurePreviewFocusableElements() {
  if (!featurePreviewModal) return [];
  return [...featurePreviewModal.querySelectorAll(FEATURE_PREVIEW_FOCUSABLE_SELECTOR)]
    .filter((element) => !element.disabled && !element.hidden && element.getAttribute("aria-hidden") !== "true");
}

function openFeaturePreview(previewId, triggerEl = null) {
  const content = featurePreviewContent[previewId];
  if (!content || !featurePreviewModal || !featurePreviewTitle || !featurePreviewEyebrow || !featurePreviewBody || !closeFeaturePreviewButton) return;
  featurePreviewTrigger = triggerEl || document.activeElement || null;
  featurePreviewEyebrow.textContent = content.eyebrow;
  featurePreviewTitle.textContent = content.title;
  featurePreviewBody.innerHTML = content.html;
  featurePreviewModal.classList.add("open");
  featurePreviewModal.setAttribute("aria-hidden", "false");
  document.body.classList.add("auth-modal-open");
  featurePreviewTitle.focus();
}

function closeFeaturePreview() {
  if (!featurePreviewModal) return;
  const wasOpen = featurePreviewModal.classList.contains("open");
  featurePreviewModal.classList.remove("open", "fp-has-sticky-upgrade");
  featurePreviewModal.setAttribute("aria-hidden", "true");
  document.body.classList.remove("auth-modal-open");
  featurePreviewBody.innerHTML = "";
  const stickyBar = featurePreviewModal.querySelector("[data-fp-sticky-upgrade]");
  if (stickyBar) {
    stickyBar.hidden = true;
    stickyBar.innerHTML = "";
  }
  if (featurePreviewTrigger && typeof featurePreviewTrigger.focus === "function") {
    featurePreviewTrigger.focus();
  }
  featurePreviewTrigger = null;
  if (wasOpen) restoreLessonLibraryBrowseState();
}

closeFeaturePreviewButton?.addEventListener("click", closeFeaturePreview);

featurePreviewModal?.addEventListener("click", (event) => {
  if (event.target === featurePreviewModal) closeFeaturePreview();
});

document.querySelector("#closeInstallAppModal")?.addEventListener("click", closeInstallAppModal);
document.querySelector("#accountInstallAppButton")?.addEventListener("click", () => {
  promptInstallFlow({ source: "settings" });
});
document.querySelector("#accountInstallInstructionsButton")?.addEventListener("click", () => {
  openInstallAppModal({ source: "settings", forceInstructions: true });
});
document.querySelector("#installAppPrimaryButton")?.addEventListener("click", () => {
  const mode = document.querySelector("#installAppPrimaryButton")?.dataset.installMode || "prompt";
  if (mode === "close") {
    closeInstallAppModal();
    return;
  }
  promptInstallFlow({ source: installModalSource });
});
document.querySelector("#installAppSecondaryButton")?.addEventListener("click", () => {
  const mode = document.querySelector("#installAppSecondaryButton")?.dataset.installMode || "close";
  if (mode === "later") {
    deferInstallPrompt();
    return;
  }
  closeInstallAppModal();
});
document.querySelector("#installAppModal")?.addEventListener("click", (event) => {
  if (event.target === document.querySelector("#installAppModal")) closeInstallAppModal();
});

document.addEventListener("click", (event) => {
  const card = event.target.closest("[data-preview]");
  if (card) {
    event.preventDefault();
    openFeaturePreview(card.dataset.preview, card);
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && isFeaturePreviewOpen()) {
    closeFeaturePreview();
    return;
  }
  if (event.key === "Escape" && document.querySelector("#installAppModal.open")) {
    closeInstallAppModal();
    return;
  }
  if (event.key === "Tab" && isFeaturePreviewOpen()) {
    const focusable = featurePreviewFocusableElements();
    if (!focusable.length) {
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (!focusable.includes(document.activeElement)) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
      return;
    }
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
      return;
    }
    if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
    return;
  }
  if ((event.key === "Enter" || event.key === " ") && event.target.closest("[data-preview]")) {
    event.preventDefault();
    const card = event.target.closest("[data-preview]");
    openFeaturePreview(card.dataset.preview, card);
  }
});

document.querySelector("#proModalUpgrade")?.addEventListener("click", () => {
  const upgradeBtn = document.querySelector("#proModalUpgrade");
  const mode = upgradeBtn?.dataset.upgradeMode || "trial";
  const promptId = upgradeBtn?.dataset.upgradePromptId || "pro_modal";
  trackUpgradePromptClick(promptId, { mode });
  if (mode === "monthly" || mode === "trial") {
    trackProUpgradeIntent("pro_feature_modal", { mode, plan: mode === "trial" ? "monthly" : mode });
  }
  closeProFeatureModal({ completed: true });
  if (mode === "dismiss") {
    return;
  }
  if (mode === "founding") {
    startCheckoutWithFoundingGuard("founding", "pro_feature_modal");
    return;
  }
  if (mode === "monthly") {
    startCheckoutWithFoundingGuard("monthly", "pro_feature_modal");
    return;
  }
  startProTrial();
});

document.querySelector("#proModalDismiss")?.addEventListener("click", () => closeProFeatureModal({ source: "maybe_later" }));
document.querySelector("#closeProModal")?.addEventListener("click", () => closeProFeatureModal({ source: "close" }));

document.querySelector("#authForm")?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const email = document.querySelector("#emailInput").value;
  const password = document.querySelector("#passwordInput").value;
  const phone = document.querySelector("#phoneInput")?.value || "";
  const submitButton = document.querySelector("#authSubmitButton");
  submitButton.disabled = true;
  setFormMessage("#authMessage", currentAuthMode === "forgot" ? "Sending your reset link…" : (currentAuthMode === "signup" ? "Creating your account…" : "Signing you in…"), true);
  try {
    if (currentAuthMode === "forgot") {
      const message = await sendPasswordReset(email);
      setFormMessage("#authMessage", message, true);
      trackEvent("password_reset_requested");
      closeAuthModal();
      setView("reset-password");
      return;
    }
    if (currentAuthMode === "signup") {
      if (signupWizardStep === 1) {
        const { firstName, lastName } = syncNameHiddenFieldsFromFullName();
        if (!firstName) throw new Error("Please enter your name.");
        const result = await signUpWithProvider(email, password, phone, firstName, lastName);
        loadAccountState(result.email);
        const preferredPlan = preferredSignupPlanFromStorage();
        const selectedAtSignup = preferredPlan === "founding"
          ? "Founding"
          : preferredPlan === "monthly"
            ? "Pro"
            : "Free";
        updateAccount(result.email, {
          signupAt: new Date().toISOString(),
          lastLoginAt: new Date().toISOString(),
          selectedPlanAtSignup: selectedAtSignup,
          preferredCheckoutPlan: preferredPlan || "",
          firstName,
          lastName,
          name: [firstName, lastName].filter(Boolean).join(" "),
        });
        // Advance the wizard immediately so Create Account never freezes behind
        // slow profile/welcome sync and blocks every other button on the page.
        signupWizardStep = 2;
        setFormMessage("#authMessage", "");
        renderSignupWizardStep();
        submitButton.disabled = false;
        const registrationEventId = makeMetaEventId("reg");
        // Profile sync first — analytics/welcome/admin alerts must not race ahead of
        // a successful account create. Fire analytics only after sync succeeds.
        runAuthSyncWithTimeout("signup profile sync", () => syncAccountProfileToBackend(result.email, {
          firstName,
          lastName,
          businessName: "",
          accountType: "",
          role: "",
          phone,
        }, { signup: true, lastLogin: true, metaEventId: registrationEventId })).then((syncedUser) => {
          if (syncedUser) {
            trackEvent("account_signup_complete", {
              email: result.email,
              plan: selectedAtSignup,
              preferredPlan: preferredPlan || "free",
              source: trafficSource(),
              firstName,
              lastName,
              signupFlow: "wizard-step-1",
              metaEventId: registrationEventId,
            });
            // Browser mirror; server CAPI is authoritative and dedupes via event_id.
            trackMetaPixel("CompleteRegistration", {
              content_name: "account_signup",
              status: true,
              currency: "USD",
              value: 0,
            }, registrationEventId);
          }
          return Promise.all([
            runAuthSyncWithTimeout("signup membership sync", () => syncSubscriptionFromBackend(result.email)),
            runAuthSyncWithTimeout("signup child sync", () => syncChildDataFromBackend()),
            loadUserAiUsage(result.email).catch(() => {}),
          ]);
        }).catch(() => {});
        return;
      }
      if (signupWizardStep === 2) {
        await completeSignupProgramStep({ allowSkip: false });
        return;
      }
      return;
    }
    const result = await loginWithProvider(email, password);
    loadAccountState(result.email);
    markAccountLogin(result.email);
    // Forced password change must win immediately. Do not let profile/subscription
    // sync failures surface as "login failed" after a successful temp-password auth.
    if (result.mustChangePassword || accountRequiresPasswordChange()) {
      updateAccount(result.email, { mustChangePassword: true });
      closeAuthModal();
      enforceForcedPasswordChangeGate();
      syncAccountProfileToBackend(result.email, {
        firstName: currentAccount()?.firstName || "",
        lastName: currentAccount()?.lastName || "",
        businessName: currentAccount()?.businessName || currentAccount()?.programSettings?.programName || "",
        accountType: currentAccount()?.accountType || "",
        role: currentAccount()?.role || "",
        phone: currentAccount()?.phone || "",
      }, { lastLogin: true }).catch(() => {});
      syncSubscriptionFromBackend(result.email, { forceRefresh: true }).catch(() => {});
      return;
    }
    const loginNavGeneration = viewNavigationGeneration;
    // Close auth UI first so login never leaves a "Working..." overlay trapping clicks.
    setFormMessage("#authMessage", "");
    closeAuthModal();
    markAppBootReady();
    trackEvent("account_login_complete", { email: result.email, plan: currentPlan });
    if (loginNavGeneration === viewNavigationGeneration) {
      const returnView = pendingAuthReturnView
        && canOpenViewForCurrentAccess(pendingAuthReturnView)
        ? pendingAuthReturnView
        : "calendar";
      pendingAuthReturnView = "";
      setView(returnView, { fromAuthLanding: true });
    } else {
      pendingAuthReturnView = "";
    }
    runAuthSyncWithTimeout("login profile sync", () => syncAccountProfileToBackend(result.email, {
      firstName: currentAccount()?.firstName || "",
      lastName: currentAccount()?.lastName || "",
      businessName: currentAccount()?.businessName || currentAccount()?.programSettings?.programName || "",
      accountType: currentAccount()?.accountType || "",
      role: currentAccount()?.role || "",
      phone: currentAccount()?.phone || "",
    }, { lastLogin: true })).then(() => Promise.all([
      runAuthSyncWithTimeout("login membership sync", () => syncSubscriptionFromBackend(result.email, { forceRefresh: true })),
      runAuthSyncWithTimeout("login child sync", () => syncChildDataFromBackend()),
      loadUserAiUsage(result.email).catch(() => {}),
    ])).catch(() => {});
  } catch (error) {
    setFormMessage("#authMessage", friendlyAuthError(error));
  } finally {
    submitButton.disabled = false;
  }
});

