document.querySelector("#aiChatForm")?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const promptBox = document.querySelector("#aiPrompt");
  const submitBtn = event.target.querySelector("[type='submit']");
  const prompt = promptBox.value.trim();
  if (!prompt) return;
  if (submitBtn?.disabled) return;
  if (!canUseAi()) {
    addAiMessage("assistant", aiLimitMessage());
    return;
  }
  addAiMessage("user", prompt);
  promptBox.value = "";
  if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Creating…"; }
  addAiMessage("assistant", "Creating your document…");
  const assistantPlaceholder = document.querySelector("#aiChatMessages .ai-message.assistant:last-child");
  const lower = prompt.toLowerCase();
  const age = detectAgeFromPrompt(lower);
  let toolId = "lesson";
  if (lower.includes("observation") || lower.includes("developmental")) toolId = "observation";
  else if (lower.includes("newsletter")) toolId = "newsletter";
  else if (lower.includes("daily report")) toolId = "daily";
  else if (lower.includes("incident") || lower.includes("injury")) toolId = "incidentReport";
  else if (lower.includes("behavior")) toolId = "behaviorNote";
  else if (lower.includes("activity") || lower.includes("sensory") || lower.includes("art")) toolId = "activity";
  else if (lower.includes("parent message") || lower.includes("parent note")) toolId = "parentMessage";
  else if (lower.includes("menu")) toolId = "menu";
  else if (lower.includes("handbook")) toolId = "handbook";
  else if (lower.includes("contract")) toolId = "contract";
  else if (lower.includes("curriculum unit")) toolId = "curriculum";
  const settings = getProgramSettings();
  try {
    const result = await generateToolOutputWithBackend(toolId, {
      age,
      note: prompt,
      details: prompt,
      programName: settings.programName || "",
    });
    if (assistantPlaceholder) {
      assistantPlaceholder.textContent = result.output;
    } else {
      addAiMessage("assistant", result.output);
    }
    recordAiUse(result.used, result.limit);
    trackEvent("ai_generation_success", { tool: "chat", promptLength: prompt.length, plan: currentPlan, backendUsed: result.backendUsed });
  } catch (error) {
    const message = error.message || "We couldn't create your document right now. Please try again.";
    if (assistantPlaceholder) {
      assistantPlaceholder.textContent = message;
    } else {
      addAiMessage("assistant", message);
    }
  } finally {
    if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = "Send"; }
  }
});

document.addEventListener("change", (event) => {
  if (event.target.matches("#docHelperType")) {
    // Changing document type must not silently change the selected child.
    updateDocHelperComposeHint();
    return;
  }
  if (!event.target.matches("#docHelperChild")) return;
  const childId = event.target.value || "";
  if (childId) event.target.dataset.explicitChildId = childId;
  else delete event.target.dataset.explicitChildId;
  // Do not rewrite global selectedChildId from Documentation Helpers — that caused silent preselection.
  updateDocHelperComposeHint();
  const reviewChild = document.querySelector("#docHelperSelectedChildLabel");
  if (reviewChild) {
    const name = event.target.selectedOptions?.[0]?.textContent?.trim() || "No child selected";
    reviewChild.textContent = childId ? `Selected child: ${name}` : "Selected child: none";
  }
});

function setDocHelperDraftActionsVisible(visible) {
  const actions = document.querySelector("#docHelperDraftActions");
  if (actions) actions.hidden = !visible;
}

function restoreDocHelperOriginalNote() {
  const note = document.querySelector("#docHelperNote");
  if (!note || !docHelperDraftState.originalNote) return;
  note.value = docHelperDraftState.originalNote;
}

let docHelperGenerating = false;

function sanitizeDocHelperDraftText(text) {
  return String(text || "")
    .replace(/^\s{0,3}#{1,6}\s+/gm, "")
    .replace(/[!]{2,}/g, "!")
    .replace(/[?]{2,}/g, "?")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

async function runDocHelperGeneration({ docType, note, childId, draftAction = "" } = {}) {
  const form = document.querySelector("#docHelperForm");
  const submitBtn = form?.querySelector("[type='submit']");
  const resultsEl = document.querySelector("#docHelperResults");
  const outputEl = document.querySelector("#docHelperOutput");
  const titleEl = document.querySelector("#docHelperResultTitle");
  const labelEl = document.querySelector("#docHelperResultLabel");
  const saveBtn = document.querySelector("#docHelperSaveBtn");
  if (!outputEl || !resultsEl || !note) return;
  if (docHelperGenerating || submitBtn?.disabled) return;

  if (!canUseAi() || (!isProUser() && aiUsageRemaining() <= 0 && serverAiUsed !== null)) {
    resultsEl.hidden = false;
    outputEl.textContent = aiLimitMessage();
    delete outputEl.dataset.rawMarkdown;
    if (titleEl) titleEl.textContent = "Limit Reached";
    if (labelEl) labelEl.textContent = "Notice";
    setDocHelperDraftActionsVisible(false);
    updateDocHelperComposeHint();
    return;
  }

  const records = childRecords();
  const child = (childId && records.children.find((c) => c.id === childId)) || null;
  const settings = getProgramSettings();
  // Never send a real child name to AI unless the provider explicitly selected that child.
  const childName = child?.name || "";
  // Do not invent an age group when none is on the child profile.
  const ageFromChild = child ? (normalizeAgeGroup(child.ageGroup) || "") : "";
  const ageFromForm = normalizeAiAgeGroup(document.querySelector("#docHelperAge")?.value || "");
  const ageGroup = ageFromChild || ageFromForm || "";
  if (!ageGroup && ["lesson-plan", "activity-idea", "behavior-note", "daily-log"].includes(docType)) {
    syncDocHelperAgeField();
    resultsEl.hidden = false;
    outputEl.textContent = "Choose an age group before generating this document, or select a child profile that already has an age.";
    delete outputEl.dataset.rawMarkdown;
    if (titleEl) titleEl.textContent = "Age needed";
    if (labelEl) labelEl.textContent = "Notice";
    setDocHelperDraftActionsVisible(false);
    document.querySelector("#docHelperAge")?.focus();
    return;
  }
  const programName = settings.programName || "";
  const today = new Date().toISOString().slice(0, 10);
  const toolId = docHelperToolMap[docType] || "observation";
  const label = docTypeLabels[docType] || "Documentation";
  docHelperGenerating = true;

  const missingFactWarnings = [];
  if (/incident/i.test(docType) && !/\b(when|where|time|date|location|happened)\b/i.test(note)) {
    missingFactWarnings.push("Incident drafts work best with when/where details. Missing facts will stay blank — AI will not invent them.");
  }
  if (/\b(medication|medicine|dose|dosage|epipen|inhaler)\b/i.test(note) && !/\b(mg|ml|dose|given|administered|time)\b/i.test(note)) {
    missingFactWarnings.push("Medication details look incomplete. Confirm dose/time yourself — AI will not invent medication facts.");
  }

  const data = {
    childName: childName || "",
    age: ageGroup,
    programName,
    note,
    highlights: note,
    details: note,
    concern: note,
    incident: note,
    theme: cleanPromptTheme(note) || "",
    skill: "",
    topic: label,
    date: today,
    // Explicit flag so prompts/backends can avoid treating a placeholder as a real child.
    childExplicitlySelected: Boolean(childId && child),
  };

  if (draftAction === "shorten" && docHelperDraftState.lastOutput) {
    data.note = `Shorten this draft while keeping every fact accurate. Do not add new details.\n\n${docHelperDraftState.lastOutput}`;
    data.details = data.note;
  } else if (draftAction === "friendlier" && docHelperDraftState.lastOutput) {
    data.note = `Rewrite this draft in a warmer, friendlier tone while keeping every fact accurate. Do not add new details.\n\n${docHelperDraftState.lastOutput}`;
    data.details = data.note;
  } else if (draftAction === "professional" && docHelperDraftState.lastOutput) {
    data.note = `Rewrite this draft in a more professional tone while keeping every fact accurate. Do not add new details.\n\n${docHelperDraftState.lastOutput}`;
    data.details = data.note;
  }

  const previousOutput = (outputEl.dataset.rawMarkdown || outputEl.textContent || "").trim();
  if (!docHelperDraftState.originalNote) {
    docHelperDraftState.originalNote = note;
  }
  docHelperDraftState.lastData = data;
  docHelperDraftState.toolId = toolId;
  docHelperDraftState.docType = docType;

  resultsEl.hidden = false;
  outputEl.textContent = "Creating your document…";
  delete outputEl.dataset.rawMarkdown;
  outputEl.contentEditable = "false";
  if (titleEl) titleEl.textContent = `${label} Ready`;
  if (labelEl) labelEl.textContent = "Creating";
  const postSave = document.querySelector("#docHelperPostSavePanel");
  if (postSave) postSave.hidden = true;
  let warnHost = resultsEl.querySelector("[data-doc-helper-fact-warnings]");
  if (!warnHost) {
    warnHost = document.createElement("div");
    warnHost.dataset.docHelperFactWarnings = "";
    warnHost.className = "form-note doc-helper-fact-warnings";
    resultsEl.insertBefore(warnHost, resultsEl.firstChild);
  }
  warnHost.innerHTML = missingFactWarnings.length
    ? missingFactWarnings.map((w) => `<p role="status">${escapeHtml(w)}</p>`).join("")
    : "";
  const selectedChildLabel = resultsEl.querySelector("#docHelperSelectedChildLabel")
    || (() => {
      const el = document.createElement("p");
      el.id = "docHelperSelectedChildLabel";
      el.className = "form-note";
      resultsEl.insertBefore(el, warnHost.nextSibling);
      return el;
    })();
  selectedChildLabel.textContent = child
    ? `Selected child: ${child.name}`
    : "Selected child: none — choose a child above before saving to a profile.";
  const hint = document.querySelector("#docHelperNextStepHint");
  if (hint) {
    hint.textContent = childId
      ? "Writing your draft… When it is ready, edit, copy, or confirm the child before saving."
      : "Writing your draft… Choose a child before saving to a profile, or copy the text when ready.";
  }
  if (saveBtn) {
    saveBtn.dataset.docType = docType;
    saveBtn.dataset.childId = childId;
    saveBtn.disabled = false;
    saveBtn.textContent = childId ? "Save to Child Profile" : "Save";
  }
  const editBtn = document.querySelector("#docHelperEditBtn");
  if (editBtn) editBtn.textContent = "Edit Generated Content";
  setDocHelperDraftActionsVisible(false);
  if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Creating…"; }
  document.querySelectorAll("[data-doc-draft-action]").forEach((btn) => { btn.disabled = true; });

  try {
    const result = await generateToolOutputWithBackend(toolId, data);
    const cleaned = sanitizeDocHelperDraftText(result.output);
    outputEl.innerHTML = renderMarkdown(cleaned);
    outputEl.dataset.rawMarkdown = cleaned;
    docHelperDraftState.lastOutput = cleaned;
    renderAiDebugPanel("#docHelperDebugPanel", result.debug, cleaned);
    if (labelEl) labelEl.textContent = "Draft";
    if (hint) {
      hint.textContent = childId
        ? "Review this draft before saving. Use Regenerate or tone options, or edit the text directly."
        : "Review this draft. Pick a child above before saving, or copy to use elsewhere.";
    }
    recordAiUse(result.used, result.limit);
    renderAiUsagePanel();
    updateDocHelperComposeHint();
    setDocHelperDraftActionsVisible(true);
    trackEvent("ai_generation_success", { tool: "doc-helper", docType, plan: currentPlan, backendUsed: Boolean(result.backendUsed), draftAction: draftAction || "create" });
    if (docType === "observation") trackEvent("observation_created", { source: "doc-helper" });
    if (docType === "parent-message") trackEvent("parent_message_generated", { source: "doc-helper" });
    if (docType === "incident-report") trackEvent("incident_report_created", { source: "doc-helper" });
    if (docType === "daily-log") trackEvent("daily_report_saved", { source: "doc-helper", docType });
  } catch (error) {
    renderAiDebugPanel("#docHelperDebugPanel");
    if (previousOutput) {
      outputEl.innerHTML = renderMarkdown(previousOutput);
      outputEl.dataset.rawMarkdown = previousOutput;
      docHelperDraftState.lastOutput = previousOutput;
      setDocHelperDraftActionsVisible(true);
      if (labelEl) labelEl.textContent = "Draft";
      if (hint) hint.textContent = "Generation failed. Your previous draft is still here. Edit your note or try again.";
    } else {
      outputEl.textContent = error.message || "We couldn't create your document right now. Please try again.";
      delete outputEl.dataset.rawMarkdown;
      if (labelEl) labelEl.textContent = "Error";
      if (hint) hint.textContent = "Generation failed. Your note is unchanged — edit it and try Create Documentation again.";
      setDocHelperDraftActionsVisible(false);
    }
  } finally {
    docHelperGenerating = false;
    if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = "Create Documentation"; }
    document.querySelectorAll("[data-doc-draft-action]").forEach((btn) => { btn.disabled = false; });
  }
}

document.addEventListener("submit", async (event) => {
  if (event.target.matches("#hdhAiDraftForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const submitBtn = event.target.querySelector("[type='submit']");
    if (submitBtn && submitBtn.disabled) return;
    hdhAiDraftState.lastOutput = "";
    await runHomeDaycareAiFormDraft({ draftAction: "create" });
    return;
  }

  if (event.target.matches("#hdhFamilyHubInviteForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const submitBtn = form.querySelector("[type='submit']");
    const message = document.querySelector("#hdhFamilyHubInviteMessage");
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "Creating…";
    }
    try {
      const result = await createFamilyHubHouseholdInvite(form);
      if (message) message.textContent = result.message || "Family Hub invite created.";
      renderHomeDaycareHubPage({ refreshHouseholds: false });
      showActionFeedback("Family Hub household invite ready.");
    } catch (error) {
      if (message) message.textContent = error.message || "Could not create invite.";
      showActionFeedback(error.message || "Could not create Family Hub invite.");
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = "Create household invite";
      }
    }
    return;
  }

  if (event.target.matches("#familyHubLoginForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const message = document.querySelector("#familyHubLoginMessage");
    const data = collectFormData(form);
    const submitBtn = form.querySelector("[type='submit']");
    if (submitBtn) submitBtn.disabled = true;
    try {
      const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
      const timer = controller ? setTimeout(() => controller.abort(), 12000) : null;
      let response;
      let result = {};
      try {
        response = await fetch("/api/family-hub/login", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ email: data.email, code: data.code }),
          signal: controller?.signal,
        });
        result = await response.json().catch(() => ({}));
      } finally {
        if (timer) clearTimeout(timer);
      }
      if (!response.ok) {
        if (response.status === 410) throw new Error(result?.error || "This invite has expired.");
        if (response.status === 404) throw new Error(result?.error || "This invite was revoked or is invalid.");
        throw new Error(result?.error || "Could not sign in to Family Hub.");
      }
      if (!result.sessionToken) throw new Error("Family Hub session was not created.");
      setFamilyHubSessionToken(result.sessionToken);
      familyHubParentState = { panel: "today", childId: "", data: null, loadId: "" };
      renderFamilyHubPage();
      familyHubParentToast("Signed in");
    } catch (error) {
      if (error?.name === "AbortError") {
        if (message) message.textContent = "Sign-in timed out. Check your connection and try again.";
      } else if (message) {
        message.textContent = error.message || "Could not sign in.";
      }
    } finally {
      if (submitBtn) submitBtn.disabled = false;
    }
    return;
  }

  if (event.target.matches("#familyHubMessageForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const status = document.querySelector("#familyHubMessageStatus");
    const submitBtn = form.querySelector("[type='submit']");
    const data = collectFormData(form);
    if (submitBtn) submitBtn.disabled = true;
    try {
      const headers = familyHubAuthHeaders();
      if (!headers) throw new Error("Sign in again to send a message.");
      const response = await fetch("/api/family-hub/messages", {
        method: "POST",
        headers,
        body: JSON.stringify({ body: data.body }),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result?.error || "Could not send message.");
      if (familyHubParentState.data) {
        familyHubParentState.data.messages = Array.isArray(result.messages) ? result.messages : familyHubParentState.data.messages;
      }
      form.reset();
      paintFamilyHubParentPanel("messages");
      if (status) status.textContent = "Message sent.";
      familyHubParentToast("Message sent");
      document.querySelector("#familyHubMessageInput")?.focus();
    } catch (error) {
      if (status) status.textContent = error.message || "Could not send message.";
    } finally {
      if (submitBtn) submitBtn.disabled = false;
    }
    return;
  }

  if (event.target.matches("#familyHubSettingsForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const status = document.querySelector("#familyHubSettingsMessage");
    const submitBtn = form.querySelector("[type='submit']");
    if (submitBtn) submitBtn.disabled = true;
    try {
      const headers = familyHubAuthHeaders();
      if (!headers) throw new Error("Sign in again to save settings.");
      const preferredName = String(form.querySelector("[name='preferredName']")?.value || "").trim();
      const payload = {
        preferredName,
        notifyMessages: Boolean(form.querySelector("[name='notifyMessages']")?.checked),
        notifyPhotos: Boolean(form.querySelector("[name='notifyPhotos']")?.checked),
        notifyDailyReports: Boolean(form.querySelector("[name='notifyDailyReports']")?.checked),
        notifyEvents: Boolean(form.querySelector("[name='notifyEvents']")?.checked),
      };
      const response = await fetch("/api/family-hub/settings", {
        method: "PATCH",
        headers,
        body: JSON.stringify(payload),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result?.error || "Could not save settings.");
      if (familyHubParentState.data) {
        familyHubParentState.data.settings = result.settings || payload;
        if (familyHubParentState.data.household) {
          familyHubParentState.data.household.settings = result.settings || payload;
        }
      }
      if (status) status.textContent = "Saved.";
      familyHubParentToast("Settings saved");
      showActionFeedback("Settings saved.");
    } catch (error) {
      if (status) status.textContent = error.message || "Could not save settings.";
    } finally {
      if (submitBtn) submitBtn.disabled = false;
    }
    return;
  }

  if (event.target.matches("#familyHubRequestForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const status = document.querySelector("#familyHubRequestMessage");
    const submitBtn = form.querySelector("[type='submit']");
    if (submitBtn) submitBtn.disabled = true;
    try {
      const headers = familyHubAuthHeaders();
      if (!headers) throw new Error("Sign in again to send a request.");
      const data = collectFormData(form);
      const child = (familyHubParentState.data?.children || []).find((item) => String(item.id) === String(data.childId || ""));
      const response = await fetch("/api/family-hub/requests", {
        method: "POST",
        headers,
        body: JSON.stringify({
          type: data.type,
          childId: data.childId || "",
          childName: child?.name || "",
          date: data.date || "",
          time: data.time || "",
          details: data.details || "",
        }),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result?.error || "Could not send request.");
      if (familyHubParentState.data) {
        const next = [result.request, ...(Array.isArray(familyHubParentState.data.requests) ? familyHubParentState.data.requests : [])]
          .filter(Boolean)
          .slice(0, 40);
        familyHubParentState.data.requests = next;
        if (Array.isArray(familyHubParentState.data.notifications) && result.request) {
          familyHubParentState.data.notifications = [
            {
              id: `local-${result.request.id}`,
              title: "Request sent",
              body: result.request.details || result.request.type,
              createdAt: result.request.createdAt,
              read: false,
              href: "more",
            },
            ...familyHubParentState.data.notifications,
          ];
        }
      }
      form.querySelector("[name='details']") && (form.querySelector("[name='details']").value = "");
      paintFamilyHubParentPanel("more");
      if (status) status.textContent = result.message || "Request sent.";
      familyHubParentToast("Request sent to your provider");
    } catch (error) {
      if (status) status.textContent = error.message || "Could not send request.";
    } finally {
      if (submitBtn) submitBtn.disabled = false;
    }
    return;
  }

  if (event.target.matches("#hdhFullAccessInviteForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const message = document.querySelector("#hdhFullAccessInviteMessage");
    const data = collectFormData(form);
    const email = String(data.email || "").trim().toLowerCase();
    const childName = String(data.childName || "Demo Child").trim() || "Demo Child";
    const submitBtn = form.querySelector("[type='submit']");
    if (!email) return;
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "Sending…";
    }
    try {
      const result = await createHdhIndependentTesterInviteRequest({ email, childName });
      hdhTesterInviteResult = {
        email,
        childName: result.invite?.childName || childName,
        acceptUrl: result.acceptUrl || result.invite?.acceptUrl || "",
      };
      if (message) {
        message.textContent = result.email?.sent
          ? "Invite emailed. They can also use the copyable accept link below."
          : (result.error || "Invite ready — copy the accept link and send it (email delivery may be off on testing).");
      }
      showActionFeedback("Tester invite ready — their own account + own kid. No Admin. They Message Leah in Messages.");
      renderHomeDaycareHubPage({ refreshHouseholds: false });
    } catch (error) {
      if (message) message.textContent = error.message || "Could not send invite.";
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = "Invite tester";
      }
    }
    return;
  }

  if (event.target.matches("#hdhStaffInviteForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const message = document.querySelector("#hdhStaffInviteMessage");
    const data = collectFormData(form);
    const email = String(data.email || "").trim().toLowerCase();
    const submitBtn = form.querySelector("[type='submit']");
    if (!email) return;
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "Sending…";
    }
    try {
      const visibility = collectHdhStaffVisibilityFromForm(form);
      const result = await createHdhStaffInviteRequest({
        email,
        role: String(data.role || "assistant").trim() || "assistant",
        visibilityPreset: visibility.visibilityPreset,
        hdhVisibility: visibility.hdhVisibility,
      });
      hdhStaffInviteResult = {
        email,
        role: String(data.role || "assistant").trim() || "assistant",
        visibilityPreset: visibility.visibilityPreset,
        acceptUrl: result.acceptUrl || "",
      };
      if (message) message.textContent = result.message || "Invite sent.";
      showActionFeedback(result.acceptUrl && !result.email?.sent ? `Invite ready: ${result.acceptUrl}` : "Staff invite created.");
      renderHomeDaycareHubPage({ refreshHouseholds: false });
    } catch (error) {
      if (message) message.textContent = error.message || "Could not send invite.";
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = "Send staff invite";
      }
    }
    return;
  }

  if (event.target.matches("#hdhTrainingForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const message = document.querySelector("#hdhTrainingMessage");
    const data = collectFormData(form);
    const submitBtn = form.querySelector("[type='submit']");
    if (submitBtn) submitBtn.disabled = true;
    try {
      const headers = await staffAuthHeaders();
      if (!headers || !canUseLaunchBackend()) throw new Error("Training tracker needs the testing server backend.");
      const response = await fetch("/api/home-daycare-hub/staff-trainings", {
        method: "POST",
        headers,
        body: JSON.stringify(data),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result?.error || "Could not save training.");
      await refreshHdhStaffTrainings();
      form.reset();
      if (message) message.textContent = "Training saved.";
      renderHomeDaycareHubPage({ refreshHouseholds: false });
      showActionFeedback("Training saved.");
    } catch (error) {
      if (message) message.textContent = error.message || "Could not save training.";
    } finally {
      if (submitBtn) submitBtn.disabled = false;
    }
    return;
  }

  if (event.target.matches("#hdhPacketForm")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const form = event.target;
    const message = document.querySelector("#hdhPacketMessage");
    const data = collectFormData(form);
    const childId = String(data.childId || "").trim();
    const child = (childRecords().children || []).find((item) => item.id === childId);
    if (!child) return;
    const submitBtn = form.querySelector("[type='submit']");
    if (submitBtn) submitBtn.disabled = true;
    try {
      addAllHomeDaycarePackFormsToChild(childId);
      const household = (familyHubHouseholdCache.households || []).find((item) => item.id === data.householdId);
      const headers = await staffAuthHeaders();
      if (!headers || !canUseLaunchBackend()) throw new Error("Packets need the testing server backend.");
      const response = await fetch("/api/home-daycare-hub/packets", {
        method: "POST",
        headers,
        body: JSON.stringify({
          title: String(data.title || "").trim() || `${child.name} enrollment packet`,
          childId: child.id,
          childName: child.name,
          householdId: household?.id || "",
          householdLabel: household?.label || "",
          items: HOME_DAYCARE_FORMS_PACK.map((formItem, index) => ({
            id: `item-${index + 1}`,
            packFormId: formItem.id,
            title: formItem.title,
            category: formItem.category,
            status: "needed",
            statusLabel: "Needed",
          })),
        }),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result?.error || "Could not create packet.");
      await refreshHdhPackets();
      form.reset();
      if (message) message.textContent = "Packet created.";
      renderHomeDaycareHubPage({ refreshHouseholds: false });
      showActionFeedback("Packet created and child file updated.");
    } catch (error) {
      if (message) message.textContent = error.message || "Could not create packet.";
    } finally {
      if (submitBtn) submitBtn.disabled = false;
    }
    return;
  }

  if (!event.target.matches("#docHelperForm")) return;
  event.preventDefault();
  const form = event.target;
  const submitBtn = form.querySelector("[type='submit']");
  if (submitBtn && submitBtn.disabled) return;

  const childId = form.querySelector("#docHelperChild")?.value || document.querySelector("#docHelperChild")?.value || "";
  const docType = form.querySelector("#docHelperType")?.value || "observation";
  const note = form.querySelector("#docHelperNote")?.value.trim() || "";
  if (!note) return;

  docHelperDraftState.originalNote = note;
  docHelperDraftState.lastOutput = "";
  await runDocHelperGeneration({ docType, note, childId });
});

