document.addEventListener("submit", async (event) => {
  if (!event.target.matches("#childProfileForm")) return;
  event.preventDefault();
  const form = event.target;
  const data = collectFormData(form);
  const editId = data.childId || activeChildProfileEditId || "";
  if (isPlaceholderChildName(data.name)) {
    alert("Please enter the child’s real first name before saving. Placeholder names like “Your Name” or “New Child” cannot be saved.");
    form.querySelector("[name='name']")?.focus();
    return;
  }
  if (!editId && !isProUser() && childStore("Profiles").length >= effectiveFreeChildProfileLimit()) {
    showProFeatureModal(freeChildProfileLimitMessage, "limit");
    return;
  }
  const formData = new FormData(form);
  const photoFile = formData.get("photo");
  const goalAreas = Array.from(new Set(formData.getAll("goalAreas").map((area) => String(area || "").trim()).filter(Boolean)));
  const supportAreas = Array.from(new Set(formData.getAll("supportAreas").map((area) => String(area || "").trim()).filter(Boolean)));
  const existing = editId ? childStore("Profiles").find((item) => item.id === editId) : null;
  const photo = photoFile?.name ? await fileToDataUrl(photoFile) : "";
  const monthlyGoal = data.monthlyObservationGoal === "custom" ? data.customMonthlyObservationGoal : data.monthlyObservationGoal;
  const age = calculateAgeFromDob(data.dob) || data.age;
  const rooms = activeScheduleClassrooms();
  let classroomId = String(data.classroomId || "").trim();
  let classroomName = String(data.classroom || "").trim();
  if (classroomId === "__other__") {
    classroomId = "";
  } else if (classroomId) {
    const room = rooms.find((item) => String(item.id) === classroomId);
    if (room) classroomName = String(room.name || classroomName || "").trim();
  }
  const child = {
    ...(existing || {}),
    id: editId || `child-${Date.now()}`,
    name: data.name,
    ageGroup: normalizeAgeGroup(data.ageGroup) || ageGroupFromDob(data.dob) || data.ageGroup,
    age,
    dob: data.dob,
    enrollmentDate: data.enrollmentDate,
    classroom: classroomName,
    classroomId,
    monthlyObservationGoal: monthlyGoal || "4",
    observationsRequiredPerMonth: monthlyGoal || "4",
    parentInfo: data.parentInfo,
    emergency: data.emergencyContact || data.emergency || "",
    emergencyContact: data.emergencyContact || data.emergency || "",
    pickupContacts: data.pickupContacts || "",
    allergies: data.allergies,
    medical: data.medical,
    photo: photo || existing?.photo || "",
    goalAreas,
    supportAreas,
    activeGoals: data.activeGoals,
    notes: data.notes,
    createdAt: existing?.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  const children = childStore("Profiles");
  saveChildStore("Profiles", editId ? children.map((item) => item.id === editId ? child : item) : [...children, child]);
  selectedChildId = child.id;
  localStorage.setItem("llhSelectedChild", selectedChildId);
  childManagementMode = "profile";
  childProfileTab = "overview";
  activeChildProfileEditId = "";
  form.reset();
  renderChildManagement();
  const createdNew = !editId;
  if (createdNew && typeof runChildCreatedAutomation === "function") {
    const auto = runChildCreatedAutomation(child, { isNew: true }) || {};
    if (auto.formsAdded > 0) {
      showActionFeedback(`${child.name} is ready — Daily Logs, timeline, and ${auto.formsAdded} forms are set up automatically.`);
    } else {
      showActionFeedback(`${child.name} is ready — they’re available in Daily Logs, Attendance, and Documentation Helpers.`);
    }
  } else {
    showActionFeedback(`${child.name} is ready — they’re available in Daily Logs, Attendance, and Documentation Helpers.`);
  }
  maybeLinkChildToFamilyHubHouseholds(child).then((linked) => {
    if (linked > 0) {
      showActionFeedback(`${child.name} is also linked for Family Hub — parents can see shared updates.`);
    }
  }).catch(() => {});
});

document.addEventListener("submit", (event) => {
  if (!event.target.matches("#childObservationForm")) return;
  event.preventDefault();
  const form = event.target;
  const data = collectFormData(form);
  const formData = new FormData(form);
  const selectedAreas = formData.getAll("areas").map((area) => normalizeObservationArea(area) || area).filter(Boolean);
  const child = childRecords().children.find((item) => item.id === data.childId);
  if (!child) {
    childManagementMode = "list";
    renderChildManagement();
    return;
  }
  const shareWithFamily = form.querySelector("[name='shareWithFamily']")?.checked === true;
  const record = enrichObservationRecord({
    ...data,
    childId: child.id,
    childName: child.name,
    area: selectedAreas[0] || data.area || "Approaches to Learning",
    categories: selectedAreas.length ? Array.from(new Set(selectedAreas)) : undefined,
    shareWithFamily,
  }, child);
  const observations = childStore("Observations");
  if (data.observationId || activeChildObservationEditId) {
    const editId = data.observationId || activeChildObservationEditId;
    const updated = observations.map((item) => item.id === editId ? {
      ...item,
      ...record,
      id: editId,
      updatedAt: new Date().toISOString(),
    } : item);
    saveChildStore("Observations", updated);
    const saved = updated.find((item) => item.id === editId);
    if (saved && typeof runObservationAutomation === "function") runObservationAutomation(saved);
    if (saved?.shareWithFamily && typeof maybeNotifyFamilyHubSharedRecord === "function") {
      maybeNotifyFamilyHubSharedRecord("Observations", saved).catch(() => {});
    }
  } else {
    if (!isProUser() && observations.length >= freeObservationRecordLimit) {
      trackUpgradePrompt("observations_limit", { limit: freeObservationRecordLimit });
      showProFeatureModal(`${freeDocumentationLimitMessage}

You've used all ${freeObservationRecordLimit} Free observations for now — upgrade for unlimited documentation that saves time every day.`, "limit");
      return;
    }
    appendChildRecord("Observations", record);
  }
  selectedChildId = child.id;
  localStorage.setItem("llhSelectedChild", selectedChildId);
  activeChildObservationEditId = "";
  activeObservationChildLock = "";
  pendingObservationArea = "";
  childProfileTab = "observations";
  childManagementMode = "profile";
  renderChildManagement();
  showAfterActionPrompt("observation", child.id);
});

