document.querySelector("#programSettingsForm")?.addEventListener("submit", (event) => {
  event.preventDefault();
  const form = event.target;
  const messageEl = document.querySelector("#programSettingsMessage");

  if (!currentUser) {
    if (messageEl) {
      messageEl.textContent = "Please log in to save Program Settings.";
      messageEl.classList.remove("success");
    }
    return;
  }

  // Collect plain text/select/url/tel fields
  const settings = collectFormData(form);
  if (settings.curriculumUsed !== CUSTOM_CURRICULUM_OPTION) settings.customCurriculumName = "";

  // Override checkbox groups with arrays (collectFormData only keeps last checked value)
  ["agesServed", "dailyReportSections", "familyHubSettings"].forEach((groupName) => {
    settings[groupName] = Array.from(form.querySelectorAll(`[name="${groupName}"]:checked`)).map((cb) => cb.value);
  });

  // Remove file input entry (handled separately)
  delete settings.logoUpload;

  // Handle logo upload (read as base64, keep existing if no new file selected)
  const existing = getProgramSettings();
  const logoInput = document.querySelector("#programLogoInput");
  const logoFile = logoInput?.files?.[0];

  function finalize(logoDataUrl) {
    if (logoDataUrl !== undefined) settings.logoDataUrl = logoDataUrl;
    else if (existing.logoDataUrl) settings.logoDataUrl = existing.logoDataUrl;

    saveProgramSettings(settings);

    if (messageEl) {
      messageEl.textContent = "Settings saved.";
      messageEl.classList.add("success");
      setTimeout(() => { if (messageEl) messageEl.textContent = ""; }, PROGRAM_SETTINGS_MESSAGE_TIMEOUT_MS);
    }

    // Update live signature preview
    updateSignaturePreview(settings.signatureName || "", settings.signatureTitle || "");

    syncProgramLogoPreview(settings.logoDataUrl || "");

    trackEvent("program_settings_saved", { plan: currentPlan, hasLogo: Boolean(settings.logoDataUrl), hasProgramName: Boolean(settings.programName) });
  }

  if (logoFile) {
    if (logoFile.size > MAX_LOGO_SIZE_BYTES) {
      if (messageEl) {
        messageEl.textContent = "Logo file is too large. Please use an image under 512 KB.";
        messageEl.classList.remove("success");
      }
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => finalize(e.target.result);
    reader.onerror = () => finalize(undefined);
    reader.readAsDataURL(logoFile);
  } else {
    finalize(undefined);
  }
});

document.addEventListener("submit", async (event) => {
  if (event.target?.id === "classroomCreateForm") {
    event.preventDefault();
    const form = event.target;
    const data = collectFormData(form);
    const api = getScheduleApi();
    try {
      await ensureScheduleLoaded();
      const doc = scheduleDocCache || api.readCache(scheduleApiEmail()) || api.emptyDoc();
      const nextRoom = {
        id: api.randomId ? api.randomId("classroom") : `classroom-${Date.now().toString(36)}`,
        name: String(data.name || "").trim() || "Classroom",
        ageGroupDefault: String(data.ageGroupDefault || "").trim(),
        notes: String(data.notes || "").trim(),
        organizationId: null,
        centerId: null,
        archived: false,
      };
      await persistScheduleClassrooms([...(doc.classrooms || []), nextRoom]);
      form.reset();
      paintClassroomsManageApp();
      showActionFeedback(`${nextRoom.name} added.`);
    } catch (error) {
      window.alert(error.message || "Could not add classroom.");
    }
    return;
  }

  if (event.target?.id === "staffInviteForm") {
    event.preventDefault();
    if (!canAccessPlatformFeature("staff_management")) return;
    const form = event.target;
    const message = document.querySelector("#staffInviteMessage");
    const data = collectFormData(form);
    const email = String(data.email || "").trim().toLowerCase();
    if (!email) return;
    const classroomId = String(data.classroomId || "").trim();
    const classroomName = activeScheduleClassrooms().find((room) => room.id === classroomId)?.name || "";
    const submitBtn = form.querySelector("button[type='submit']");
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "Sending…";
    }
    (async () => {
      try {
        const headers = await staffAuthHeaders();
        if (!headers || !canUseLaunchBackend()) {
          // Offline/local fallback
          const current = centerProgramData();
          if (current.staffInvites.some((invite) => String(invite.email || "").toLowerCase() === email && invite.status !== "revoked")) {
            throw new Error("That email already has a pending invite.");
          }
          saveCenterProgramData({
            staffInvites: [
              ...current.staffInvites,
              {
                id: `invite-${Date.now().toString(36)}`,
                email,
                role: String(data.role || "teacher").trim() || "teacher",
                classroomId,
                classroomName,
                status: "pending",
                invitedAt: new Date().toISOString(),
              },
            ],
          });
          form.reset();
          renderStaffManagementPage({ refresh: false });
          showActionFeedback("Staff invite saved locally.");
          return;
        }
        const settings = getProgramSettings();
        const visibility = isHomeDaycareHubTestingEnabled()
          ? collectHdhStaffVisibilityFromForm(form)
          : { visibilityPreset: "", hdhVisibility: null };
        const response = await fetch("/api/staff/invites", {
          method: "POST",
          headers,
          body: JSON.stringify({
            email,
            role: String(data.role || "teacher").trim() || "teacher",
            classroomId,
            classroomName,
            programName: settings.programName || "",
            appOrigin: window.location.origin,
            ...visibility,
          }),
        });
        const result = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(result?.error || "Could not send invite.");
        await refreshStaffInvitesFromBackend();
        form.reset();
        renderStaffManagementPage({ refresh: false });
        if (message) message.textContent = result.message || "Invite sent.";
        if (result.acceptUrl) {
          showActionFeedback(result.email?.sent ? "Invite email sent." : `Invite ready: ${result.acceptUrl}`);
        } else {
          showActionFeedback("Staff invite created.");
        }
      } catch (error) {
        if (message) {
          message.textContent = error.message || "Could not send invite.";
          message.classList.remove("success");
        } else {
          window.alert(error.message || "Could not send invite.");
        }
      } finally {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.textContent = "Send Invite";
        }
      }
    })();
    return;
  }

  if (event.target?.matches?.("[data-child-document-form]")) {
    event.preventDefault();
    const childId = event.target.getAttribute("data-child-document-form") || selectedChildId;
    if (!childId) return;
    const data = collectFormData(event.target);
    const title = String(data.title || "").trim();
    if (!title) return;
    const status = String(data.status || "needed").trim();
    const category = String(data.category || "Other").trim() || "Other";
    const shareWithFamily = String(data.shareWithFamily || "") === "true"
      || event.target.querySelector('[name="shareWithFamily"]')?.checked === true;
    const saved = appendChildRecord("Documents", {
      childId,
      title,
      category,
      status,
      statusLabel: homeDaycarePackDocumentStatusLabel(status),
      notes: String(data.notes || "").trim(),
      dueDate: String(data.dueDate || "").trim(),
      date: new Date().toISOString().slice(0, 10),
      updatedAt: new Date().toISOString(),
      shareWithFamily,
      providerReviewed: false,
    });
    childProfileTab = isHomeDaycareHubTestingEnabled() ? "forms-records" : "documents";
    childManagementMode = "profile";
    event.target.reset();
    showActionFeedback("Form saved to child file.");
    renderChildManagement();
    if (shareWithFamily && saved?.id) {
      shareChildDocumentWithFamily(saved.id)
        .then(() => showActionFeedback("Form shared with Family Hub — parents can sign it there."))
        .catch((error) => showActionFeedback(error.message || "Saved locally — Family Hub notify failed."));
    }
    return;
  }

  if (event.target?.matches?.("[data-assign-template-form]")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const templateId = event.target.getAttribute("data-assign-template-form");
    const template = formsProgramTemplates().find((item) => String(item.id) === String(templateId));
    if (!template) {
      showActionFeedback("Template not found.");
      return;
    }
    const data = collectFormData(event.target);
    const childIds = Array.from(event.target.querySelectorAll('input[name="childIds"]:checked')).map((input) => input.value);
    assignAndNotifyForm({
      title: template.title,
      category: template.category,
      body: template.body,
      draftText: template.body,
      packFormId: template.packFormId || "",
      resourceId: template.resourceId || "",
      templateId: template.id,
      dueDate: data.dueDate || "",
      shareWithFamily: event.target.querySelector('[name="shareWithFamily"]')?.checked !== false,
      notes: "Assigned from program template.",
    }, childIds)
      .then((saved) => {
        const refreshed = Number(saved.refreshedCount || 0);
        const message = refreshed
          ? `Updated existing assignment for “${template.title}” (${refreshed} already open — no duplicate created).`
          : `Assigned “${template.title}” to ${saved.length} child${saved.length === 1 ? "" : "ren"}.`;
        showActionFeedback(message);
        renderHomeDaycareHubPage({ refreshHouseholds: false });
      })
      .catch((error) => showActionFeedback(error.message || "Could not assign template."));
    return;
  }

  if (event.target?.matches?.("[data-edit-template-form]")) {
    event.preventDefault();
    if (!isHomeDaycareHubTestingEnabled()) return;
    const templateId = event.target.getAttribute("data-edit-template-form");
    const data = collectFormData(event.target);
    const next = formsProgramTemplates().map((template) => (
      String(template.id) === String(templateId)
        ? {
          ...template,
          title: String(data.title || template.title || "Custom form").trim() || "Custom form",
          category: String(data.category || template.category || "Other").trim() || "Other",
          body: String(data.body || "").trim(),
          updatedAt: new Date().toISOString(),
        }
        : template
    ));
    if (!String(data.body || "").trim()) {
      showActionFeedback("Template body can’t be empty.");
      return;
    }
    saveFormsProgramTemplates(next);
    showActionFeedback("Template updated. Forms already assigned to children keep their original copy.");
    renderHomeDaycareHubPage({ refreshHouseholds: false });
    return;
  }

  if (event.target?.id === "enrollmentLeadForm") {
    event.preventDefault();
    if (!canAccessPlatformFeature("enrollment")) return;
    const data = collectFormData(event.target);
    const current = centerProgramData();
    saveCenterProgramData({
      enrollmentLeads: [
        ...current.enrollmentLeads,
        {
          id: `lead-${Date.now().toString(36)}`,
          childName: String(data.childName || "").trim(),
          parentName: String(data.parentName || "").trim(),
          desiredRoom: String(data.desiredRoom || "").trim(),
          notes: String(data.notes || "").trim(),
          status: "inquiry",
          createdAt: new Date().toISOString(),
        },
      ],
    });
    event.target.reset();
    renderEnrollmentPage();
    showActionFeedback("Inquiry added.");
    return;
  }

  if (event.target?.matches?.("[data-family-parent-form]")) {
    event.preventDefault();
    if (!canAccessPlatformFeature("families")) return;
    const form = event.target;
    const data = collectFormData(form);
    const parentInfo = String(data.parentInfo || "").trim();
    const childIds = String(data.childIds || "").split(",").map((id) => id.trim()).filter(Boolean);
    const children = childStore("Profiles");
    saveChildStore("Profiles", children.map((child) => (
      childIds.includes(child.id)
        ? { ...child, parentInfo, updatedAt: new Date().toISOString() }
        : child
    )));
    renderFamiliesPage();
    showActionFeedback("Household contact saved.");
  }
});

