// Password-reset email links use ?view=reset-password&resetToken=... (server-generated,
// see appBaseUrl() resetUrl) or Firebase's ?mode=resetPassword&oobCode=.... Recognize both —
// a guest clicking their email link must land on the reset screen, not the homepage/Dashboard.
function resetPasswordLinkRequestedFromLocation() {
  const params = new URLSearchParams(window.location.search);
  if (params.get("resetToken") || readPendingUrlSecret("resetToken")) return true;
  if (params.get("view") === "reset-password") return true;
  if (params.get("mode") === "resetPassword") return true;
  return false;
}

// Guests get the marketing homepage. Logged-in users never paint the retired Dashboard.
// Admin-only unlock (no provider login) restores Admin immediately to avoid Home flash / "kicked out" feel.
// Signed-in providers do NOT auto-open Admin — they land on Calendar / last workspace section.
// Open Admin only via Admin nav, /admin, or ?view=admin.
if (!currentUser) {
  if (resetPasswordLinkRequestedFromLocation()) {
    setView("reset-password", { fromBoot: true, replaceHistory: true });
  } else if (isAdminUnlocked() && localStorage.getItem("llhAdminLastView") === "admin") {
    setView("admin", { fromBoot: true, replaceHistory: true });
  } else {
    renderHome();
  }
} else {
  // Synchronously open Calendar (or last remembered section) before async sync work.
  // This prevents the old Dashboard from flashing or lingering behind Calendar.
  const earlyLanding = (() => {
    const fromLocation = (() => {
      if (resetPasswordLinkRequestedFromLocation()) return "reset-password";
      if (lessonPlanEditRouteIdFromLocation()) return "lesson-editor";
      return adRouteMap[window.location.pathname] || adRouteMap[window.location.hash] || "";
    })();
    if (fromLocation && fromLocation !== "home") return fromLocation;
    return defaultLoggedInLandingView();
  })();
  if (earlyLanding !== "lesson-editor") {
    setView(earlyLanding, { fromBoot: true, replaceHistory: true });
  }
}
loadSiteContentFromBackend().catch(() => {});
loadUploadedResourcesFromBackend({ admin: isAdminUnlocked(), migrateLocal: false }).catch(() => {});

function initialViewFromLocation() {
  const params = new URLSearchParams(window.location.search);
  if (resetPasswordLinkRequestedFromLocation()) return "reset-password";
  if (lessonPlanEditRouteIdFromLocation()) return "lesson-editor";
  // Deep link used by push notification taps (see service-worker.js
  // notificationclick) and by "Open Little Learner Hub" copy — routes
  // straight to the right conversation/tab instead of the default landing.
  if (params.get("view") === "messages" && (isLoggedIn() || hasAdminFullAccess())) return "messages";
  if (params.get("view") === "admin" && (canSeeAdminNav() || isAdminUnlocked() || hasAdminFullAccess())) return "admin";
  // Parent magic links must land in Family Hub even when the visitor is not a provider account.
  if (params.get("familyHub") && typeof isHomeDaycareHubTestingEnabled === "function" && isHomeDaycareHubTestingEnabled()) {
    return "family-hub";
  }
  if (params.get("view") === "family-hub" && typeof isHomeDaycareHubTestingEnabled === "function" && isHomeDaycareHubTestingEnabled()) {
    return "family-hub";
  }
  const pathView = adRouteMap[window.location.pathname];
  const hashView = adRouteMap[window.location.hash];
  return pathView || hashView || "home";
}

async function initializeAppView(options = {}) {
  const runId = ++appBootRunId;
  if (!options.retry && viewNavigationGeneration === 0) {
    suppressBootLanding = false;
  }
  const bootNavGeneration = viewNavigationGeneration;
  const needsVerification = requiresVerifiedAppBoot();
  if (needsVerification) {
    appBootState = "pending";
    setAppBootGateMode("loading");
  }
  try {
    const handledCheckoutReturn = await verifyStripeReturnIfNeeded();
    if (handledCheckoutReturn) {
      if (runId !== appBootRunId) return;
      markAppBootReady();
      return;
    }
    if (needsVerification) {
      await runSignedInBootVerification();
      if (runId !== appBootRunId) return;
      markAppBootReady();
    } else {
      // Parents open Family Hub via magic link without a provider login — still show the accept panel.
      await withBootVerificationTimeout("Family Hub invite", () => maybeHandleFamilyHubInviteFromUrl()).catch(() => {});
      if (runId !== appBootRunId) return;
      if (!document.body.classList.contains("app-boot-ready")) {
        markAppBootReady();
      }
    }
    if (suppressBootLanding || bootNavGeneration !== viewNavigationGeneration) {
      return;
    }
    const initialView = initialViewFromLocation();
    const lessonEditId = lessonPlanEditRouteIdFromLocation();
    if (!currentAttribution()?.firstSeenAt) {
      saveAttribution({ route: window.location.pathname || window.location.hash || "home", view: initialView, source: trafficSource() });
    }
    // Reuse the head Pixel PageView eventID so browser + CAPI PageView dedupe.
    const pageViewEventId = window.__llhMetaPageViewEventId || makeMetaEventId("pv");
    trackEvent("website_visit", {
      view: initialView,
      source: trafficSource(),
      metaEventId: pageViewEventId,
    });
    if (lessonEditId) {
      const route = window.location.pathname || window.location.hash;
      saveAttribution({ route, view: "lesson-editor" });
      trackEvent("ad_route_visit", { route, view: "lesson-editor" });
      if (isLoggedIn() || hasAdminFullAccess()) {
        await openLessonPlanEditor(lessonEditId, { returnView: "lessons", skipEditorRoute: true });
      } else {
        pendingAuthReturnView = "lessons";
        openAuthModal("login");
      }
      return;
    }
    if (initialView !== "home") {
      const route = window.location.pathname || window.location.hash;
      saveAttribution({ route, view: initialView });
      trackEvent("ad_route_visit", { route, view: initialView });
      const viewOptions = { fromBoot: true, replaceHistory: true };
      if (initialView === "messages") {
        const conversationParam = new URLSearchParams(window.location.search).get("conversation") || "";
        if (conversationParam) viewOptions.conversation = conversationParam;
      }
      setView(initialView, viewOptions);
      if (initialView === "admin") {
        window.setTimeout(() => applyAdminLocationDeepLink(), 0);
      }
      return;
    }
    // Admin-only unlock (no provider login): stay in Admin after refresh.
    // Providers with an unlocked admin session still land on Calendar / workspace.
    if (!currentUser && isAdminUnlocked() && localStorage.getItem("llhAdminLastView") === "admin") {
      setView("admin", { fromBoot: true, replaceHistory: true });
      loadAdminAnalyticsFromBackend({ force: true }).catch(() => {});
      window.setTimeout(() => applyAdminLocationDeepLink(), 0);
      return;
    }
    if (currentUser && !suppressBootLanding) {
      setView(defaultLoggedInLandingView(), { fromBoot: true, replaceHistory: true });
      return;
    }
    if (!currentUser) {
      setView("home", { fromBoot: true, allowDashboard: true, replaceHistory: true });
      const bootParams = new URLSearchParams(window.location.search || "");
      const lessonDeepLink = String(bootParams.get("lesson") || "").trim();
      const wantsSignup = bootParams.get("signup") === "1" || bootParams.get("signup") === "true";
      if (lessonDeepLink) {
        window.setTimeout(() => {
          Promise.resolve(loadSiteContentFromBackend?.()).catch(() => {}).finally(() => {
            openHomePublicPreview(lessonDeepLink, "homeLessonPlans");
          });
        }, 250);
      } else if (wantsSignup) {
        window.setTimeout(() => {
          setPreferredSignupPlan("free");
          openAuthModal("signup");
        }, 200);
      }
    }
  } catch (error) {
    if (runId !== appBootRunId) return;
    if (needsVerification) {
      markAppBootFailed(error);
    } else {
      console.warn("App boot failed", error);
      markAppBootReady();
    }
  } finally {
    document.body.classList.add("app-booted");
    if (!needsVerification && !document.body.classList.contains("app-boot-ready")) {
      markAppBootReady();
    }
  }
}

initializeAppView();

