// ─── Admin AI Testing Center Event Handlers ───────────────────────────────────

document.addEventListener("click", (event) => {
  // Slot selection
  const slotTab = event.target.closest("[data-aitc-slot]");
  if (slotTab && slotTab.closest("#adminAiTestCenter")) {
    adminTestCenterState.activeSlot = slotTab.dataset.aitcSlot;
    renderAdminAiTestCenter();
    return;
  }

  // Generate button
  if (event.target.matches("#aitcGenerateBtn")) {
    handleAdminAiTestGenerate();
    return;
  }

  // Show/hide combined prompt preview
  if (event.target.matches("#aitcShowCombinedPrompt")) {
    adminTestCenterState.showPromptPreview = !adminTestCenterState.showPromptPreview;
    const preview = document.querySelector("#aitcCombinedPromptPreview");
    if (preview) preview.hidden = !adminTestCenterState.showPromptPreview;
    event.target.textContent = (adminTestCenterState.showPromptPreview ? "Hide" : "Preview") + " Combined Prompt";
    updateAdminTestCombinedPromptPreview();
    return;
  }

  // Show/hide request viewer
  if (event.target.matches("#aitcShowRequestViewer")) {
    adminTestCenterState.showRequestViewer = !adminTestCenterState.showRequestViewer;
    const viewer = document.querySelector("#aitcRequestViewer");
    if (viewer) viewer.hidden = !adminTestCenterState.showRequestViewer;
    event.target.textContent = (adminTestCenterState.showRequestViewer ? "Hide" : "Show") + " Request Preview";
    updateAdminTestCombinedPromptPreview();
    return;
  }

  // Copy combined prompt
  if (event.target.matches("#aitcCopyPrompt")) {
    const text = document.querySelector("#aitcCombinedPromptText")?.textContent || "";
    navigator.clipboard.writeText(text).catch(() => {});
    return;
  }

  // Layer prompt preview
  const layerPreviewBtn = event.target.closest("[data-aitc-preview-layer]");
  if (layerPreviewBtn) {
    const layerId = layerPreviewBtn.dataset.aitcPreviewLayer;
    const layer = adminPromptLayers.find((l) => l.id === layerId);
    const previewEl = document.querySelector("#aitcLayerPreview");
    if (!layer || !previewEl) return;
    const isShowing = !previewEl.hidden && previewEl.dataset.showing === layerId;
    previewEl.hidden = isShowing;
    previewEl.dataset.showing = layerId;
    previewEl.innerHTML = isShowing ? "" : `<strong>${layer.label}</strong><pre class="aitc-prompt-pre">${escapeHtml(layer.text)}</pre>`;
    return;
  }

  // Quick-fill sample note
  const sampleBtn = event.target.closest("[data-aitc-sample]");
  if (sampleBtn) {
    const noteField = document.querySelector('#adminAiTestForm [name="quickNote"]');
    if (noteField) {
      noteField.value = sampleBtn.dataset.aitcSample;
      updateAdminTestCombinedPromptPreview();
    }
    return;
  }

  // Copy slot output
  const copySlotBtn = event.target.closest("[data-aitc-copy-slot]");
  if (copySlotBtn) {
    adminAiTestExport(copySlotBtn.dataset.aitcCopySlot, "copy");
    return;
  }

  // Download slot output
  const downloadSlotBtn = event.target.closest("[data-aitc-download-slot]");
  if (downloadSlotBtn) {
    adminAiTestExport(downloadSlotBtn.dataset.aitcDownloadSlot, "download");
    return;
  }

  // Clear slot
  const clearSlotBtn = event.target.closest("[data-aitc-clear-slot]");
  if (clearSlotBtn) {
    adminTestCenterState.slots[clearSlotBtn.dataset.aitcClearSlot] = null;
    renderAdminAiTestCenter();
    return;
  }

  // Result view tab (formatted / raw / prompt)
  const resultTab = event.target.closest("[data-aitc-view-tab]");
  if (resultTab) {
    const slot = resultTab.dataset.aitcSlotTab;
    const view = resultTab.dataset.aitcViewTab;
    const container = resultTab.closest(".aitc-card");
    if (!container) return;
    container.querySelectorAll(".aitc-result-tab").forEach((btn) => btn.classList.remove("active"));
    resultTab.classList.add("active");
    const formattedEl = document.querySelector(`#aitcSlotOutput${slot}`);
    const rawEl = document.querySelector(`#aitcSlotRaw${slot}`);
    const promptEl = document.querySelector(`#aitcSlotPrompt${slot}`);
    if (formattedEl) formattedEl.hidden = view !== "formatted";
    if (rawEl) rawEl.hidden = view !== "raw";
    if (promptEl) promptEl.hidden = view !== "prompt";
    return;
  }

  // Save prompt version
  if (event.target.matches("#aitcSaveVersion")) {
    const name = document.querySelector("#aitcVersionName")?.value?.trim();
    if (!name) return;
    const form = document.querySelector("#adminAiTestForm");
    const docType = form?.querySelector('[name="docType"]')?.value || "Observation";
    const customText = document.querySelector("#aitcCustomPromptText")?.value || "";
    const state = adminTestCenterState;
    const versions = adminPromptVersions();
    versions.unshift({
      name,
      docType,
      savedAt: new Date().toISOString(),
      layers: { ...state.layers },
      useCustomPrompt: state.useCustomPrompt,
      customPromptText: customText,
      layersEnabled: adminPromptLayers.filter((l) => state.layers[l.id]).map((l) => l.label),
      systemPrompt: buildAdminTestCombinedPrompt(state.layers, customText, state.useCustomPrompt),
    });
    saveAdminPromptVersions(versions.slice(0, 20));
    const nameInput = document.querySelector("#aitcVersionName");
    if (nameInput) nameInput.value = "";
    renderAdminAiTestCenter();
    return;
  }

  // Restore prompt version
  const restoreBtn = event.target.closest("[data-aitc-restore-version]");
  if (restoreBtn) {
    const versions = adminPromptVersions();
    const version = versions[Number(restoreBtn.dataset.aitcRestoreVersion)];
    if (!version) return;
    adminTestCenterState.layers = { ...version.layers };
    adminTestCenterState.useCustomPrompt = version.useCustomPrompt;
    renderAdminAiTestCenter();
    if (version.customPromptText) {
      const ta = document.querySelector("#aitcCustomPromptText");
      if (ta) ta.value = version.customPromptText;
    }
    updateAdminTestCombinedPromptPreview();
    return;
  }

  // Delete prompt version
  const deleteBtn = event.target.closest("[data-aitc-delete-version]");
  if (deleteBtn) {
    const versions = adminPromptVersions();
    const idx = Number(deleteBtn.dataset.aitcDeleteVersion);
    versions.splice(idx, 1);
    saveAdminPromptVersions(versions);
    renderAdminAiTestCenter();
    return;
  }
});

document.addEventListener("change", (event) => {
  // Layer toggle checkboxes
  const layerToggle = event.target.closest("[data-aitc-layer]");
  if (layerToggle) {
    adminTestCenterState.layers[layerToggle.dataset.aitcLayer] = layerToggle.checked;
    updateAdminTestCombinedPromptPreview();
    return;
  }

  // Custom prompt override toggle
  if (event.target.matches("#aitcUseCustomPrompt")) {
    adminTestCenterState.useCustomPrompt = event.target.checked;
    const area = document.querySelector("#aitcCustomPromptArea");
    if (area) area.hidden = !event.target.checked;
    updateAdminTestCombinedPromptPreview();
    return;
  }
});

document.addEventListener("input", (event) => {
  if (event.target.matches("#aitcCustomPromptText") || event.target.closest("#adminAiTestForm")) {
    updateAdminTestCombinedPromptPreview();
  }
});

async function handleAdminAiTestGenerate() {
  const form = document.querySelector("#adminAiTestForm");
  const errEl = document.querySelector("#aitcGenerateError");
  if (!form) return;
  const quickNote = form.querySelector('[name="quickNote"]')?.value?.trim();
  if (!quickNote) {
    if (errEl) errEl.textContent = "Teacher Quick Note is required.";
    return;
  }
  if (errEl) errEl.textContent = "";
  const state = adminTestCenterState;
  const customText = document.querySelector("#aitcCustomPromptText")?.value || "";
  const systemPrompt = buildAdminTestCombinedPrompt(state.layers, customText, state.useCustomPrompt);
  const userPrompt = buildAdminTestUserPrompt(form);
  const wantScore = document.querySelector("#aitcWantScore")?.checked !== false;
  const slot = state.activeSlot;

  state.generating = true;
  const btn = document.querySelector("#aitcGenerateBtn");
  if (btn) { btn.disabled = true; btn.textContent = "Creating…"; }

  try {
    const result = await callAdminAiTest(systemPrompt, userPrompt, wantScore);
    state.slots[slot] = {
      output: result.output || "",
      scores: result.scores || null,
      model: result.model || "unknown",
      systemPrompt,
      userPrompt,
      layersEnabled: adminPromptLayers.filter((l) => state.layers[l.id]).map((l) => l.label),
      generatedAt: new Date().toISOString(),
    };
  } catch (error) {
    if (errEl) errEl.textContent = error.message || "Generation failed.";
  }

  state.generating = false;
  renderAdminAiTestCenter();
}

// ─── AI Prompt Manager Event Handlers ────────────────────────────────────────

document.addEventListener("click", (event) => {
  // Tool selector
  const toolBtn = event.target.closest("[data-ai-pm-tool]");
  if (toolBtn) {
    adminAiPromptsState.activeTool = toolBtn.dataset.aiPmTool;
    adminAiPromptsState.success = "";
    adminAiPromptsState.error = "";
    renderAdminAiPromptsTab();
    return;
  }
  // Restore version
  const restoreBtn = event.target.closest("[data-ai-pm-restore]");
  if (restoreBtn) {
    if (confirm("Restore this prompt version? The current version will be saved in history.")) {
      restoreAdminAiPromptVersion(restoreBtn.dataset.aiPmRestore);
    }
    return;
  }
  // Toggle version history
  if (event.target.matches("#aiPmToggleHistory")) {
    adminAiPromptsState.showVersionHistory = !adminAiPromptsState.showVersionHistory;
    renderAdminAiPromptsTab();
    return;
  }
  // Reset to default
  if (event.target.matches("#aiPmResetBtn")) {
    const tool = adminAiPromptsState.activeTool;
    const defaultText = adminAiPromptsState.hardcodedDefaults[tool] || "";
    const form = document.querySelector("#adminAiPromptsForm");
    if (!form) return;
    if (confirm("Reset all prompt layers for this tool to the built-in defaults? This will clear all custom text in the editor (not yet saved to the server).")) {
      for (const layer of AI_PROMPT_LAYERS_ORDERED) {
        const el = form.querySelector(`[name="${layer}"]`);
        if (el) el.value = "";
      }
      // Put the full default in masterPrompt as a convenient starting point
      const masterEl = form.querySelector('[name="masterPrompt"]');
      if (masterEl) masterEl.value = defaultText;
    }
    return;
  }
  // AI Settings retry
  if (event.target.matches("#aiSettingsRetryBtn")) {
    loadAdminAiSettings();
    return;
  }
  // AI Usage retry/refresh
  if (event.target.matches("#aiUsageRetryBtn") || event.target.matches("#aiUsageRefreshBtn")) {
    loadAdminAiUsage();
    return;
  }
  if (event.target.matches("#aiHealthRetryBtn") || event.target.matches("#aiHealthRefreshBtn")) {
    loadAdminAiHealth();
    return;
  }
  if (event.target.matches("#aiHealthTestBtn")) {
    runAdminAiHealthTest();
    return;
  }
});

document.addEventListener("submit", (event) => {
  // Prompt Manager save
  if (event.target.matches("#adminAiPromptsForm")) {
    event.preventDefault();
    saveAdminAiPrompts(adminAiPromptsState.activeTool);
    return;
  }
  // AI Settings save
  if (event.target.matches("#adminAiSettingsForm")) {
    event.preventDefault();
    saveAdminAiSettings();
    return;
  }
  if (event.target.matches("#aiGuideComposeForm")) {
    event.preventDefault();
    if (!isAiGuideEnabled()) return;
    generateAiGuideDraftFromForm(event.target);
  }
});

document.addEventListener("change", (event) => {
  if (event.target.matches("#aiGuideReviewAck")) {
    acknowledgeAiGuideReview(Boolean(event.target.checked));
    return;
  }
  if (event.target.matches("[data-ai-guide-template]")) {
    const templateId = String(event.target.value || "").trim();
    const template = (aiGuideState.config?.templates || []).find((item) => item.id === templateId);
    if (!template) return;
    aiGuideState.featureId = template.featureId || aiGuideState.featureId;
    aiGuideState.notes = template.notes || "";
    aiGuideState.length = template.length || "standard";
    aiGuideState.tone = template.tone || "";
    aiGuideState.ageGroup = template.ageGroup || "";
    aiGuideState.state = template.state || "";
    renderAiGuidePage();
    return;
  }
  if (event.target.matches("#aiGuideComposeForm [name='featureId']")) {
    aiGuideState.featureId = String(event.target.value || "").trim();
    const form = document.querySelector("#aiGuideComposeForm");
    if (form) {
      const data = new FormData(form);
      aiGuideState.notes = String(data.get("notes") || "");
      aiGuideState.childName = String(data.get("childName") || "");
      aiGuideState.ageGroup = String(data.get("ageGroup") || "");
      aiGuideState.length = String(data.get("length") || "standard");
      aiGuideState.tone = String(data.get("tone") || "");
      aiGuideState.state = String(data.get("state") || "");
      aiGuideState.sourceRecordIds = Array.from(form.querySelectorAll('input[name="sourceRecordIds"]:checked')).map((el) => el.value);
    }
    renderAiGuidePage();
  }
});

// ─── Messaging Center + Notification Bell — event wiring ───────────────────

document.addEventListener("click", async (event) => {
  const bellBtn = event.target.closest("#notificationBellBtn");
  if (bellBtn) {
    event.preventDefault();
    toggleNotificationBellPanel();
    return;
  }
  const closeBellBtn = event.target.closest("#notificationBellCloseBtn, #notificationBellBackdrop");
  if (closeBellBtn) {
    event.preventDefault();
    toggleNotificationBellPanel(false);
    return;
  }
  const markAllBtn = event.target.closest("#notificationMarkAllBtn");
  if (markAllBtn) {
    event.preventDefault();
    const unread = Number(notificationBellState.unreadCount || 0);
    const confirmed = window.confirm(
      unread > 0
        ? `Mark all ${unread} notification${unread === 1 ? "" : "s"} as read? Message history will not be deleted.`
        : "Mark all notifications as read? Message history will not be deleted.",
    );
    if (!confirmed) return;
    await markNotificationRead({ all: true });
    return;
  }
  const seeAllBtn = event.target.closest("#notificationSeeAllBtn");
  if (seeAllBtn) {
    toggleNotificationBellPanel(false);
  }
  const bellItem = event.target.closest(".notification-bell-item");
  if (bellItem) {
    event.preventDefault();
    const id = bellItem.dataset.notificationId;
    const conversationEmail = bellItem.dataset.notificationConversation || "";
    toggleNotificationBellPanel(false);
    await markNotificationRead(conversationEmail ? { conversationEmail } : { id });
    setView("messages", conversationEmail ? { conversation: conversationEmail } : {});
    return;
  }
  // Close the bell panel on any outside click (backdrop / page chrome).
  if (
    notificationBellState.open
    && !event.target.closest("#notificationBellWrap")
    && !event.target.closest("#notificationBellPanel")
  ) {
    toggleNotificationBellPanel(false);
  }
  const messagesTabBtn = event.target.closest("[data-messages-tab]");
  if (messagesTabBtn) {
    // Comms Center owns Messages tabs when mounted — do not remount the legacy 3-tab shell.
    if (typeof window.renderMyMessagesCenter === "function" && (
      messagesTabBtn.hasAttribute("data-messages-center-tab")
      || document.querySelector(".messages-center-tabs, [data-messages-center-tab]")
    )) {
      return;
    }
    event.preventDefault();
    messagesPageSetTab(messagesTabBtn.dataset.messagesTab);
    if (messagesTabBtn.dataset.messagesTab === "updates") {
      const unreadIds = messagesViewState.inbox.filter((i) => !i.notification.read).map((i) => i.notification.id);
      if (unreadIds.length) await markNotificationRead({ id: unreadIds[0] });
      if (unreadIds.length > 1) {
        for (const id of unreadIds.slice(1)) {
          // Best-effort sequential mark-read; small lists in practice.
          // eslint-disable-next-line no-await-in-loop
          await markNotificationRead({ id });
        }
      }
    }
    return;
  }
  const updateItem = event.target.closest(".messages-update-item");
  if (updateItem) {
    event.preventDefault();
    await markNotificationRead({ id: updateItem.dataset.notificationId });
    return;
  }
});

document.addEventListener("change", async (event) => {
  if (!event.target.matches("#pushNotificationToggle")) return;
  const checkbox = event.target;
  checkbox.disabled = true;
  if (checkbox.checked) {
    await enablePushNotifications();
  } else {
    await disablePushNotifications();
  }
  checkbox.disabled = false;
  if (typeof window.renderMyMessagesCenter === "function" && document.querySelector(".messages-center-tabs, [data-messages-center-tab]")) {
    window.renderMyMessagesCenter({ tab: "preferences" }).catch(() => {});
    return;
  }
  renderMessagesPageBody();
});

document.addEventListener("submit", async (event) => {
  if (!event.target.matches("#messagesReplyForm")) return;
  // Comms Center has its own submit handler — skip legacy path to prevent double-send.
  if (typeof window.renderMyMessagesCenter === "function" && (
    event.target.hasAttribute("data-draft-form")
    || document.querySelector(".messages-center-tabs, [data-messages-center-tab]")
  )) {
    return;
  }
  event.preventDefault();
  const textarea = document.querySelector("#messagesReplyInput");
  const body = String(textarea?.value || "").trim();
  if (!body) return;
  const submitBtn = event.target.querySelector("button[type='submit']");
  if (submitBtn) submitBtn.disabled = true;
  const result = await sendMemberReply(body);
  if (submitBtn) submitBtn.disabled = false;
  if (result.ok) {
    if (textarea) textarea.value = "";
    await refreshMessagesData();
    renderMessagesPageBody();
  } else {
    alert(result.error || "Could not send your message. Please try again.");
  }
});

// Refresh the bell when the tab regains focus/visibility (covers "app open,
// backgrounded, closed" — foreground refresh catches up on anything a push
// may have missed while backgrounded, with no push required at all).
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible" && isLoggedIn()) refreshNotificationBell();
});

window.addEventListener("resize", () => {
  if (notificationBellState.open) positionNotificationBellPanel();
  if (document.querySelector(".lesson-workspace-more-menu:not([hidden])")) {
    positionLessonWorkspaceMoreMenu();
  }
  const openItemMenu = document.querySelector("[data-llh-item-menu]:not([hidden])");
  if (openItemMenu) positionItemActionMenuPanel(openItemMenu);
});
window.addEventListener("scroll", () => {
  if (notificationBellState.open) positionNotificationBellPanel();
}, { passive: true });
document.addEventListener("keydown", (event) => {
  if (event.key === "Tab") {
    const confirmPanel = document.querySelector("[data-llh-confirm-dialog]:not([hidden]) .llh-confirm-panel");
    if (confirmPanel && trapLlhDialogFocus(event, confirmPanel)) return;
    const recordEditPanel = document.querySelector("[data-llh-record-edit-dialog]:not([hidden]) .llh-confirm-panel");
    if (recordEditPanel && trapLlhDialogFocus(event, recordEditPanel)) return;
    const scheduleCard = document.querySelector("#scheduleEventModal.open .modal-card");
    if (scheduleCard && trapLlhDialogFocus(event, scheduleCard)) return;
    const resourceCard = document.querySelector("#resourceViewerModal.open .resource-viewer-card, #resourceViewerModal.open .modal-card");
    if (resourceCard && trapLlhDialogFocus(event, resourceCard)) return;
  }
  if (event.key !== "Escape") return;
  const confirmDialog = document.querySelector("[data-llh-confirm-dialog]:not([hidden])");
  if (confirmDialog) {
    event.preventDefault();
    closeConfirmActionDialog(false);
    return;
  }
  const recordEditDialog = document.querySelector("[data-llh-record-edit-dialog]:not([hidden])");
  if (recordEditDialog) {
    event.preventDefault();
    closeChildRecordEditDialog(false);
    return;
  }
  if (document.querySelector("#scheduleEventModal.open")) {
    event.preventDefault();
    closeCalendarAddItemDialog();
    return;
  }
  if (notificationBellState.open) {
    toggleNotificationBellPanel(false);
    return;
  }
  if (document.querySelector(".lesson-workspace-more-menu:not([hidden])")) {
    toggleLessonWorkspaceMoreMenu(false);
  }
});

if (isLoggedIn()) {
  refreshNotificationBell();
  startNotificationBellPolling();
}

try {
  ensureMetaCookieNotice();
} catch {
  /* ignore */
}

